window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["RUT"]={"book":"RUT","editions":{"hbo-source":[[1,1,"וַ⁠יְהִ֗י בִּ⁠ימֵי֙ שְׁפֹ֣ט הַ⁠שֹּׁפְטִ֔ים וַ⁠יְהִ֥י רָעָ֖ב בָּ⁠אָ֑רֶץ וַ⁠יֵּ֨לֶךְ אִ֜ישׁ מִ⁠בֵּ֧ית לֶ֣חֶם יְהוּדָ֗ה לָ⁠גוּר֙ בִּ⁠שְׂדֵ֣י מוֹאָ֔ב ה֥וּא וְ⁠אִשְׁתּ֖⁠וֹ וּ⁠שְׁנֵ֥י בָנָֽי⁠ו׃","wa⁠yĕhi֗y bi̇⁠yméy֙ şĕ̌pò֣t ha⁠şò̇̌pĕti֔ym wa⁠yĕhi֥y ráʻá֖b bá̇⁠ʼá֑reẕ wa⁠yé̇֨lekĕ ʼi֜yş̌ mi⁠bé֧̇yţ le֣ẖem yĕhẇdá֗h lá⁠gẇr֙ bi̇⁠şĕ̂dé֣y mwòʼá֔b h֥ẇʼ wĕ⁠ʼişĕ̌ţ֖̇⁠wò ẇ⁠şĕ̌né֥y bánáֽy⁠w׃"],[1,2,"וְ⁠שֵׁ֣ם הָ⁠אִ֣ישׁ אֱֽלִימֶ֡לֶךְ וְ⁠שֵׁם֩ אִשְׁתּ֨⁠וֹ נָעֳמִ֜י וְ⁠שֵׁ֥ם שְׁנֵֽי־בָנָ֣י⁠ו ׀ מַחְל֤וֹן וְ⁠כִלְיוֹן֙ אֶפְרָתִ֔ים מִ⁠בֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וַ⁠יָּבֹ֥אוּ שְׂדֵי־מוֹאָ֖ב וַ⁠יִּֽהְיוּ־שָֽׁם׃","wĕ⁠şé֣̌m há⁠ʼi֣yş̌ ʼèֽliyme֡lekĕ wĕ⁠şé̌m֩ ʼişĕ̌ţ̇֨⁠wò náʻomi֜y wĕ⁠şé֥̌m şĕ̌néֽy-báná֣y⁠w ׀ maẖĕl֤wòn wĕ⁠kilĕywòn֙ ʼepĕráţi֔ym mi⁠bé֥̇yţ le֖ẖem yĕhẇdá֑h wa⁠yá̇bò֥ʼẇ şĕ̂déy-mwòʼá֖b wa⁠yiֽ̇hĕyẇ-şáֽ̌m׃"],[1,3,"וַ⁠יָּ֥מָת אֱלִימֶ֖לֶךְ אִ֣ישׁ נָעֳמִ֑י וַ⁠תִּשָּׁאֵ֥ר הִ֖יא וּ⁠שְׁנֵ֥י בָנֶֽי⁠הָ׃","wa⁠yá֥̇máţ ʼèliyme֖lekĕ ʼi֣yş̌ náʻomi֑y wa⁠ţi̇şá̇̌ʼé֥r hi֖yʼ ẇ⁠şĕ̌né֥y báneֽy⁠há׃"],[1,4,"וַ⁠יִּשְׂא֣וּ לָ⁠הֶ֗ם נָשִׁים֙ מֹֽאֲבִיּ֔וֹת שֵׁ֤ם הָֽ⁠אַחַת֙ עָרְפָּ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖ית ר֑וּת וַ⁠יֵּ֥שְׁבוּ שָׁ֖ם כְּ⁠עֶ֥שֶׂר שָׁנִֽים׃","wa⁠yi̇şĕ̂ʼ֣ẇ lá⁠he֗m náşǐym֙ mòֽʼàbiẏ֔wòţ şé֤̌m háֽ⁠ʼaẖaţ֙ ʻárĕpá̇֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖yţ r֑ẇţ wa⁠yé֥̇şĕ̌bẇ şá֖̌m kĕ̇⁠ʻe֥şêr şá̌niֽym׃"],[1,5,"וַ⁠יָּמ֥וּתוּ גַם־שְׁנֵי⁠הֶ֖ם מַחְל֣וֹן וְ⁠כִלְי֑וֹן וַ⁠תִּשָּׁאֵר֙ הָֽ⁠אִשָּׁ֔ה מִ⁠שְּׁנֵ֥י יְלָדֶ֖י⁠הָ וּ⁠מֵ⁠אִישָֽׁ⁠הּ׃","wa⁠yá̇m֥ẇţẇ gam-şĕ̌néy⁠he֖m maẖĕl֣wòn wĕ⁠kilĕy֑wòn wa⁠ţi̇şá̇̌ʼér֙ háֽ⁠ʼişá̇̌֔h mi⁠şĕ̇̌né֥y yĕláde֖y⁠há ẇ⁠mé⁠ʼiyşáֽ̌⁠ḣ׃"],[1,6,"וַ⁠תָּ֤קָם הִיא֙ וְ⁠כַלֹּתֶ֔י⁠הָ וַ⁠תָּ֖שָׁב מִ⁠שְּׂדֵ֣י מוֹאָ֑ב כִּ֤י שָֽׁמְעָה֙ בִּ⁠שְׂדֵ֣ה מוֹאָ֔ב כִּֽי־פָקַ֤ד יְהוָה֙ אֶת־עַמּ֔⁠וֹ לָ⁠תֵ֥ת לָ⁠הֶ֖ם לָֽחֶם׃","wa⁠ţá֤̇qám hiyʼ֙ wĕ⁠kalò̇ţe֔y⁠há wa⁠ţá֖̇şá̌b mi⁠şĕ̇̂dé֣y mwòʼá֑b ki֤̇y şáֽ̌mĕʻáh֙ bi̇⁠şĕ̂dé֣h mwòʼá֔b kiֽ̇y-páqa֤d yĕhwáh֙ ʼeţ-ʻaṁ֔⁠wò lá⁠ţé֥ţ lá⁠he֖m láֽẖem׃"],[1,7,"וַ⁠תֵּצֵ֗א מִן־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר הָיְתָה־שָׁ֔מָּ⁠ה וּ⁠שְׁתֵּ֥י כַלֹּתֶ֖י⁠הָ עִמָּ֑⁠הּ וַ⁠תֵּלַ֣כְנָה בַ⁠דֶּ֔רֶךְ לָ⁠שׁ֖וּב אֶל־אֶ֥רֶץ יְהוּדָֽה׃","wa⁠ţé̇ẕé֗ʼ min-ha⁠má̇qwòm֙ ʼàşě֣r háyĕţáh-şá̌֔má̇⁠h ẇ⁠şĕ̌ţé֥̇y kalò̇ţe֖y⁠há ʻimá֑̇⁠ḣ wa⁠ţé̇la֣kĕnáh ba⁠dė֔rekĕ lá⁠ş֖̌ẇb ʼel-ʼe֥reẕ yĕhẇdáֽh׃"],[1,8,"וַ⁠תֹּ֤אמֶר נָעֳמִי֙ לִ⁠שְׁתֵּ֣י כַלֹּתֶ֔י⁠הָ לֵ֣כְנָה שֹּׁ֔בְנָה אִשָּׁ֖ה לְ⁠בֵ֣ית אִמָּ֑⁠הּ יעשה יְהוָ֤ה עִמָּ⁠כֶם֙ חֶ֔סֶד כַּ⁠אֲשֶׁ֧ר עֲשִׂיתֶ֛ם עִם־הַ⁠מֵּתִ֖ים וְ⁠עִמָּדִֽ⁠י׃","wa⁠ţò֤̇ʼmer náʻomiy֙ li⁠şĕ̌ţé֣̇y kalò̇ţe֔y⁠há lé֣kĕnáh şò̇̌֔bĕnáh ʼişá֖̇̌h lĕ⁠bé֣yţ ʼimá֑̇⁠ḣ yʻşh yĕhwá֤h ʻimá̇⁠kem֙ ẖe֔sed kȧ⁠ʼàşě֧r ʻàşîyţe֛m ʻim-ha⁠mé̇ţi֖ym wĕ⁠ʻimá̇diֽ⁠y׃"],[1,9,"יִתֵּ֤ן יְהוָה֙ לָ⁠כֶ֔ם וּ⁠מְצֶ֣אןָ מְנוּחָ֔ה אִשָּׁ֖ה בֵּ֣ית אִישָׁ֑⁠הּ וַ⁠תִּשַּׁ֣ק לָ⁠הֶ֔ן וַ⁠תִּשֶּׂ֥אנָה קוֹלָ֖⁠ן וַ⁠תִּבְכֶּֽינָה׃","yiţé֤̇n yĕhwáh֙ lá⁠ke֔m ẇ⁠mĕẕe֣ʼná mĕnẇẖá֔h ʼişá֖̇̌h bé֣̇yţ ʼiyşá֑̌⁠ḣ wa⁠ţi̇şȧ֣̌q lá⁠he֔n wa⁠ţi̇şė֥̂ʼnáh qwòlá֖⁠n wa⁠ţi̇bĕkėֽynáh׃"],[1,10,"וַ⁠תֹּאמַ֖רְנָה־לָּ֑⁠הּ כִּי־אִתָּ֥⁠ךְ נָשׁ֖וּב לְ⁠עַמֵּֽ⁠ךְ׃","wa⁠ţò̇ʼma֖rĕnáh-lá֑̇⁠ḣ ki̇y-ʼiţá֥̇⁠kĕ náş֖̌ẇb lĕ⁠ʻaméֽ̇⁠kĕ׃"],[1,11,"וַ⁠תֹּ֤אמֶר נָעֳמִי֙ שֹׁ֣בְנָה בְנֹתַ֔⁠י לָ֥⁠מָּה תֵלַ֖כְנָה עִמִּ֑⁠י הַֽ⁠עֽוֹד־לִ֤⁠י בָנִים֙ בְּֽ⁠מֵעַ֔⁠י וְ⁠הָי֥וּ לָ⁠כֶ֖ם לַ⁠אֲנָשִֽׁים׃","wa⁠ţò֤̇ʼmer náʻomiy֙ şò֣̌bĕnáh bĕnòţa֔⁠y lá֥⁠má̇h ţéla֖kĕnáh ʻimi֑̇⁠y haֽ⁠ʻֽwòd-li֤⁠y bániym֙ bĕֽ̇⁠méʻa֔⁠y wĕ⁠háy֥ẇ lá⁠ke֖m la⁠ʼànáşǐֽym׃"],[1,12,"שֹׁ֤בְנָה בְנֹתַ⁠י֙ לֵ֔כְןָ כִּ֥י זָקַ֖נְתִּי מִ⁠הְי֣וֹת לְ⁠אִ֑ישׁ כִּ֤י אָמַ֨רְתִּי֙ יֶשׁ־לִ֣⁠י תִקְוָ֔ה גַּ֣ם הָיִ֤יתִי הַ⁠לַּ֨יְלָה֙ לְ⁠אִ֔ישׁ וְ⁠גַ֖ם יָלַ֥דְתִּי בָנִֽים׃","şò֤̌bĕnáh bĕnòţa⁠y֙ lé֔kĕná ki֥̇y záqa֖nĕţi̇y mi⁠hĕy֣wòţ lĕ⁠ʼi֑yş̌ ki֤̇y ʼáma֨rĕţi̇y֙ yeş̌-li֣⁠y ţiqĕwá֔h gȧ֣m háyi֤yţiy ha⁠lȧ֨yĕláh֙ lĕ⁠ʼi֔yş̌ wĕ⁠ga֖m yála֥dĕţi̇y bániֽym׃"],[1,13,"הֲ⁠לָהֵ֣ן ׀ תְּשַׂבֵּ֗רְנָה עַ֚ד אֲשֶׁ֣ר יִגְדָּ֔לוּ הֲ⁠לָהֵן֙ תֵּֽעָגֵ֔נָה לְ⁠בִלְתִּ֖י הֱי֣וֹת לְ⁠אִ֑ישׁ אַ֣ל בְּנֹתַ֗⁠י כִּֽי־מַר־לִ֤⁠י מְאֹד֙ מִ⁠כֶּ֔ם כִּֽי־יָצְאָ֥ה בִ֖⁠י יַד־יְהוָֽה׃","hà⁠láhé֣n ׀ ţĕ̇şâbé̇֗rĕnáh ʻa֚d ʼàşě֣r yigĕdá̇֔lẇ hà⁠láhén֙ ţéֽ̇ʻágé֔náh lĕ⁠bilĕţi֖̇y hèy֣wòţ lĕ⁠ʼi֑yş̌ ʼa֣l bĕ̇nòţa֗⁠y kiֽ̇y-mar-li֤⁠y mĕʼòd֙ mi⁠kė֔m kiֽ̇y-yáẕĕʼá֥h bi֖⁠y yad-yĕhwáֽh׃"],[1,14,"וַ⁠תִּשֶּׂ֣נָה קוֹלָ֔⁠ן וַ⁠תִּבְכֶּ֖ינָה ע֑וֹד וַ⁠תִּשַּׁ֤ק עָרְפָּה֙ לַ⁠חֲמוֹתָ֔⁠הּ וְ⁠ר֖וּת דָּ֥בְקָה בָּֽ⁠הּ׃","wa⁠ţi̇şė֣̂náh qwòlá֔⁠n wa⁠ţi̇bĕkė֖ynáh ʻ֑wòd wa⁠ţi̇şȧ֤̌q ʻárĕpá̇h֙ la⁠ẖàmwòţá֔⁠ḣ wĕ⁠r֖ẇţ dá֥̇bĕqáh báֽ̇⁠ḣ׃"],[1,15,"וַ⁠תֹּ֗אמֶר הִנֵּה֙ שָׁ֣בָה יְבִמְתֵּ֔⁠ךְ אֶל־עַמָּ֖⁠הּ וְ⁠אֶל־אֱלֹהֶ֑י⁠הָ שׁ֖וּבִי אַחֲרֵ֥י יְבִמְתֵּֽ⁠ךְ׃","wa⁠ţò̇֗ʼmer hiné̇h֙ şá֣̌báh yĕbimĕţé̇֔⁠kĕ ʼel-ʻamá֖̇⁠ḣ wĕ⁠ʼel-ʼèlòhe֑y⁠há ş֖̌ẇbiy ʼaẖàré֥y yĕbimĕţéֽ̇⁠kĕ׃"],[1,16,"וַ⁠תֹּ֤אמֶר רוּת֙ אַל־תִּפְגְּעִי־בִ֔⁠י לְ⁠עָזְבֵ֖⁠ךְ לָ⁠שׁ֣וּב מֵ⁠אַחֲרָ֑יִ⁠ךְ כִּ֠י אֶל־אֲשֶׁ֨ר תֵּלְכִ֜י אֵלֵ֗ךְ וּ⁠בַ⁠אֲשֶׁ֤ר תָּלִ֨ינִי֙ אָלִ֔ין עַמֵּ֣⁠ךְ עַמִּ֔⁠י וֵ⁠אלֹהַ֖יִ⁠ךְ אֱלֹהָֽ⁠י׃","wa⁠ţò֤̇ʼmer rẇţ֙ ʼal-ţi̇pĕgĕ̇ʻiy-bi֔⁠y lĕ⁠ʻázĕbé֖⁠kĕ lá⁠ş֣̌ẇb mé⁠ʼaẖàrá֑yi⁠kĕ ki̇֠y ʼel-ʼàşě֨r ţé̇lĕki֜y ʼélé֗kĕ ẇ⁠ba⁠ʼàşě֤r ţá̇li֨yniy֙ ʼáli֔yn ʻamé֣̇⁠kĕ ʻami̇֔⁠y wé⁠ʼlòha֖yi⁠kĕ ʼèlòháֽ⁠y׃"],[1,17,"בַּ⁠אֲשֶׁ֤ר תָּמ֨וּתִי֙ אָמ֔וּת וְ⁠שָׁ֖ם אֶקָּבֵ֑ר כֹּה֩ יַעֲשֶׂ֨ה יְהוָ֥ה לִ⁠י֙ וְ⁠כֹ֣ה יֹסִ֔יף כִּ֣י הַ⁠מָּ֔וֶת יַפְרִ֖יד בֵּינִ֥⁠י וּ⁠בֵינֵֽ⁠ךְ׃","bȧ⁠ʼàşě֤r ţá̇m֨ẇţiy֙ ʼám֔ẇţ wĕ⁠şá֖̌m ʼeqá̇bé֑r kò̇h֩ yaʻàşê֨h yĕhwá֥h li⁠y֙ wĕ⁠kò֣h yòsi֔yp ki֣̇y ha⁠má̇֔weţ yapĕri֖yd bé̇yni֥⁠y ẇ⁠béynéֽ⁠kĕ׃"],[1,18,"וַ⁠תֵּ֕רֶא כִּֽי־מִתְאַמֶּ֥צֶת הִ֖יא לָ⁠לֶ֣כֶת אִתָּ֑⁠הּ וַ⁠תֶּחְדַּ֖ל לְ⁠דַבֵּ֥ר אֵלֶֽי⁠הָ׃","wa⁠ţé̇֕reʼ kiֽ̇y-miţĕʼamė֥ẕeţ hi֖yʼ lá⁠le֣keţ ʼiţá֑̇⁠ḣ wa⁠ţėẖĕdȧ֖l lĕ⁠dabé֥̇r ʼéleֽy⁠há׃"],[1,19,"וַ⁠תֵּלַ֣כְנָה שְׁתֵּי⁠הֶ֔ם עַד־בֹּאָ֖⁠נָה בֵּ֣ית לָ֑חֶם וַ⁠יְהִ֗י כְּ⁠בֹאָ֨⁠נָה֙ בֵּ֣ית לֶ֔חֶם וַ⁠תֵּהֹ֤ם כָּל־הָ⁠עִיר֙ עֲלֵי⁠הֶ֔ן וַ⁠תֹּאמַ֖רְנָה הֲ⁠זֹ֥את נָעֳמִֽי׃","wa⁠ţé̇la֣kĕnáh şĕ̌ţé̇y⁠he֔m ʻad-bò̇ʼá֖⁠náh bé֣̇yţ lá֑ẖem wa⁠yĕhi֗y kĕ̇⁠bòʼá֨⁠náh֙ bé֣̇yţ le֔ẖem wa⁠ţé̇hò֤m ká̇l-há⁠ʻiyr֙ ʻàléy⁠he֔n wa⁠ţò̇ʼma֖rĕnáh hà⁠zò֥ʼţ náʻomiֽy׃"],[1,20,"וַ⁠תֹּ֣אמֶר אֲלֵי⁠הֶ֔ן אַל־תִּקְרֶ֥אנָה לִ֖⁠י נָעֳמִ֑י קְרֶ֤אןָ לִ⁠י֙ מָרָ֔א כִּי־הֵמַ֥ר שַׁדַּ֛י לִ֖⁠י מְאֹֽד׃","wa⁠ţò֣̇ʼmer ʼàléy⁠he֔n ʼal-ţi̇qĕre֥ʼnáh li֖⁠y náʻomi֑y qĕre֤ʼná li⁠y֙ márá֔ʼ ki̇y-héma֥r şǎdȧ֛y li֖⁠y mĕʼòֽd׃"],[1,21,"אֲנִי֙ מְלֵאָ֣ה הָלַ֔כְתִּי וְ⁠רֵיקָ֖ם הֱשִׁיבַ֣⁠נִי יְהוָ֑ה לָ֣⁠מָּה תִקְרֶ֤אנָה לִ⁠י֙ נָעֳמִ֔י וַֽ⁠יהוָה֙ עָ֣נָה בִ֔⁠י וְ⁠שַׁדַּ֖י הֵ֥רַֽע לִֽ⁠י׃","ʼàniy֙ mĕléʼá֣h hála֔kĕţi̇y wĕ⁠réyqá֖m hèşǐyba֣⁠niy yĕhwá֑h lá֣⁠má̇h ţiqĕre֤ʼnáh li⁠y֙ náʻomi֔y waֽ⁠yhwáh֙ ʻá֣náh bi֔⁠y wĕ⁠şǎdȧ֖y hé֥raֽʻ liֽ⁠y׃"],[1,22,"וַ⁠תָּ֣שָׁב נָעֳמִ֗י וְ⁠ר֨וּת הַ⁠מּוֹאֲבִיָּ֤ה כַלָּתָ⁠הּ֙ עִמָּ֔⁠הּ הַ⁠שָּׁ֖בָה מִ⁠שְּׂדֵ֣י מוֹאָ֑ב וְ⁠הֵ֗מָּה בָּ֚אוּ בֵּ֣ית לֶ֔חֶם בִּ⁠תְחִלַּ֖ת קְצִ֥יר שְׂעֹרִֽים׃","wa⁠ţá֣̇şá̌b náʻomi֗y wĕ⁠r֨ẇţ ha⁠ṁwòʼàbiyá֤̇h kalá̇ţá⁠ḣ֙ ʻimá̇֔⁠ḣ ha⁠şá֖̇̌báh mi⁠şĕ̇̂dé֣y mwòʼá֑b wĕ⁠hé֗má̇h bá֚̇ʼẇ bé֣̇yţ le֔ẖem bi̇⁠ţĕẖilȧ֖ţ qĕẕi֥yr şĕ̂ʻòriֽym׃"],[2,1,"וּֽ⁠לְ⁠נָעֳמִ֞י מידע לְ⁠אִישָׁ֗⁠הּ אִ֚ישׁ גִּבּ֣וֹר חַ֔יִל מִ⁠מִּשְׁפַּ֖חַת אֱלִימֶ֑לֶךְ וּ⁠שְׁמ֖⁠וֹ בֹּֽעַז׃","ẇֽ⁠lĕ⁠náʻomi֞y mydʻ lĕ⁠ʼiyşá̌֗⁠ḣ ʼi֚yş̌ gi̇ḃ֣wòr ẖa֔yil mi⁠mi̇şĕ̌pȧ֖ẖaţ ʼèliyme֑lekĕ ẇ⁠şĕ̌m֖⁠wò bòֽ̇ʻaz׃"],[2,2,"וַ⁠תֹּאמֶר֩ ר֨וּת הַ⁠מּוֹאֲבִיָּ֜ה אֶֽל־נָעֳמִ֗י אֵֽלְכָה־נָּ֤א הַ⁠שָּׂדֶה֙ וַ⁠אֲלַקֳטָּ֣ה בַ⁠שִׁבֳּלִ֔ים אַחַ֕ר אֲשֶׁ֥ר אֶמְצָא־חֵ֖ן בְּ⁠עֵינָ֑י⁠ו וַ⁠תֹּ֥אמֶר לָ֖⁠הּ לְכִ֥י בִתִּֽ⁠י׃","wa⁠ţò̇ʼmer֩ r֨ẇţ ha⁠ṁwòʼàbiyá̇֜h ʼeֽl-náʻomi֗y ʼéֽlĕkáh-ná֤̇ʼ ha⁠şá̇̂deh֙ wa⁠ʼàlaqotá֣̇h ba⁠şǐbȯli֔ym ʼaẖa֕r ʼàşě֥r ʼemĕẕáʼ-ẖé֖n bĕ̇⁠ʻéyná֑y⁠w wa⁠ţò֥̇ʼmer lá֖⁠ḣ lĕki֥y biţiֽ̇⁠y׃"],[2,3,"וַ⁠תֵּ֤לֶךְ וַ⁠תָּבוֹא֙ וַ⁠תְּלַקֵּ֣ט בַּ⁠שָּׂדֶ֔ה אַחֲרֵ֖י הַ⁠קֹּצְרִ֑ים וַ⁠יִּ֣קֶר מִקְרֶ֔⁠הָ חֶלְקַ֤ת הַ⁠שָּׂדֶה֙ לְ⁠בֹ֔עַז אֲשֶׁ֖ר מִ⁠מִּשְׁפַּ֥חַת אֱלִימֶֽלֶךְ׃","wa⁠ţé֤̇lekĕ wa⁠ţá̇bwòʼ֙ wa⁠ţĕ̇laqé֣̇t bȧ⁠şá̇̂de֔h ʼaẖàré֖y ha⁠qò̇ẕĕri֑ym wa⁠yi֣̇qer miqĕre֔⁠há ẖelĕqa֤ţ ha⁠şá̇̂deh֙ lĕ⁠bò֔ʻaz ʼàşě֖r mi⁠mi̇şĕ̌pȧ֥ẖaţ ʼèliymeֽlekĕ׃"],[2,4,"וְ⁠הִנֵּה־בֹ֗עַז בָּ֚א מִ⁠בֵּ֣ית לֶ֔חֶם וַ⁠יֹּ֥אמֶר לַ⁠קּוֹצְרִ֖ים יְהוָ֣ה עִמָּ⁠כֶ֑ם וַ⁠יֹּ֥אמְרוּ ל֖⁠וֹ יְבָרֶכְ⁠ךָ֥ יְהוָֽה׃","wĕ⁠hiné̇h-bò֗ʻaz bá֚̇ʼ mi⁠bé֣̇yţ le֔ẖem wa⁠yò֥̇ʼmer la⁠q̇wòẕĕri֖ym yĕhwá֣h ʻimá̇⁠ke֑m wa⁠yò֥̇ʼmĕrẇ l֖⁠wò yĕbárekĕ⁠ká֥ yĕhwáֽh׃"],[2,5,"וַ⁠יֹּ֤אמֶר בֹּ֨עַז֙ לְ⁠נַעֲר֔⁠וֹ הַ⁠נִּצָּ֖ב עַל־הַ⁠קּֽוֹצְרִ֑ים לְ⁠מִ֖י הַ⁠נַּעֲרָ֥ה הַ⁠זֹּֽאת׃","wa⁠yò֤̇ʼmer bò̇֨ʻaz֙ lĕ⁠naʻàr֔⁠wò ha⁠ni̇ẕá֖̇b ʻal-ha⁠qֽ̇wòẕĕri֑ym lĕ⁠mi֖y ha⁠nȧʻàrá֥h ha⁠zòֽ̇ʼţ׃"],[2,6,"וַ⁠יַּ֗עַן הַ⁠נַּ֛עַר הַ⁠נִּצָּ֥ב עַל־הַ⁠קּוֹצְרִ֖ים וַ⁠יֹּאמַ֑ר נַעֲרָ֤ה מֽוֹאֲבִיָּה֙ הִ֔יא הַ⁠שָּׁ֥בָה עִֽם־נָעֳמִ֖י מִ⁠שְּׂדֵ֥ה מוֹאָֽב׃","wa⁠yȧ֗ʻan ha⁠nȧ֛ʻar ha⁠ni̇ẕá֥̇b ʻal-ha⁠q̇wòẕĕri֖ym wa⁠yò̇ʼma֑r naʻàrá֤h mֽwòʼàbiyá̇h֙ hi֔yʼ ha⁠şá֥̇̌báh ʻiֽm-náʻomi֖y mi⁠şĕ̇̂dé֥h mwòʼáֽb׃"],[2,7,"וַ⁠תֹּ֗אמֶר אֲלַקֳטָה־נָּא֙ וְ⁠אָסַפְתִּ֣י בָֽ⁠עֳמָרִ֔ים אַחֲרֵ֖י הַ⁠קּוֹצְרִ֑ים וַ⁠תָּב֣וֹא וַֽ⁠תַּעֲמ֗וֹד מֵ⁠אָ֤ז הַ⁠בֹּ֨קֶר֙ וְ⁠עַד־עַ֔תָּה זֶ֛ה שִׁבְתָּ֥⁠הּ הַ⁠בַּ֖יִת מְעָֽט׃","wa⁠ţò̇֗ʼmer ʼàlaqotáh-ná̇ʼ֙ wĕ⁠ʼásapĕţi֣̇y báֽ⁠ʻomári֔ym ʼaẖàré֖y ha⁠q̇wòẕĕri֑ym wa⁠ţá̇b֣wòʼ waֽ⁠ţȧʻàm֗wòd mé⁠ʼá֤z ha⁠bò̇֨qer֙ wĕ⁠ʻad-ʻa֔ţá̇h ze֛h şǐbĕţá֥̇⁠ḣ ha⁠bȧ֖yiţ mĕʻáֽt׃"],[2,8,"וַ⁠יֹּאמֶר֩ בֹּ֨עַז אֶל־ר֜וּת הֲ⁠ל֧וֹא שָׁמַ֣עַתְּ בִּתִּ֗⁠י אַל־תֵּלְכִי֙ לִ⁠לְקֹט֙ בְּ⁠שָׂדֶ֣ה אַחֵ֔ר וְ⁠גַ֛ם לֹ֥א תַעֲבוּרִ֖י מִ⁠זֶּ֑ה וְ⁠כֹ֥ה תִדְבָּקִ֖י⁠ן עִם־נַעֲרֹתָֽ⁠י׃","wa⁠yò̇ʼmer֩ bò̇֨ʻaz ʼel-r֜ẇţ hà⁠l֧wòʼ şá̌ma֣ʻaţĕ̇ bi̇ţi̇֗⁠y ʼal-ţé̇lĕkiy֙ li⁠lĕqòt֙ bĕ̇⁠şá̂de֣h ʼaẖé֔r wĕ⁠ga֛m lò֥ʼ ţaʻàbẇri֖y mi⁠zė֑h wĕ⁠kò֥h ţidĕbá̇qi֖y⁠n ʻim-naʻàròţáֽ⁠y׃"],[2,9,"עֵינַ֜יִ⁠ךְ בַּ⁠שָּׂדֶ֤ה אֲשֶׁר־יִקְצֹרוּ⁠ן֙ וְ⁠הָלַ֣כְתִּ אַחֲרֵי⁠הֶ֔ן הֲ⁠ל֥וֹא צִוִּ֛יתִי אֶת־הַ⁠נְּעָרִ֖ים לְ⁠בִלְתִּ֣י נָגְעֵ֑⁠ךְ וְ⁠צָמִ֗ת וְ⁠הָלַכְתְּ֙ אֶל־הַ⁠כֵּלִ֔ים וְ⁠שָׁתִ֕ית מֵ⁠אֲשֶׁ֥ר יִשְׁאֲב֖וּ⁠ן הַ⁠נְּעָרִֽים׃","ʻéyna֜yi⁠kĕ bȧ⁠şá̇̂de֤h ʼàşěr-yiqĕẕòrẇ⁠n֙ wĕ⁠hála֣kĕţi̇ ʼaẖàréy⁠he֔n hà⁠l֥wòʼ ẕiwi֛̇yţiy ʼeţ-ha⁠nĕ̇ʻári֖ym lĕ⁠bilĕţi֣̇y nágĕʻé֑⁠kĕ wĕ⁠ẕámi֗ţ wĕ⁠hálakĕţĕ̇֙ ʼel-ha⁠ké̇li֔ym wĕ⁠şá̌ţi֕yţ mé⁠ʼàşě֥r yişĕ̌ʼàb֖ẇ⁠n ha⁠nĕ̇ʻáriֽym׃"],[2,10,"וַ⁠תִּפֹּל֙ עַל־פָּנֶ֔י⁠הָ וַ⁠תִּשְׁתַּ֖חוּ אָ֑רְצָ⁠ה וַ⁠תֹּ֣אמֶר אֵלָ֗י⁠ו מַדּוּעַ֩ מָצָ֨אתִי חֵ֤ן בְּ⁠עֵינֶ֨י⁠ךָ֙ לְ⁠הַכִּירֵ֔⁠נִי וְ⁠אָּנֹכִ֖י נָכְרִיָּֽה׃","wa⁠ţi̇pò̇l֙ ʻal-pá̇ne֔y⁠há wa⁠ţi̇şĕ̌ţȧ֖ẖẇ ʼá֑rĕẕá⁠h wa⁠ţò֣̇ʼmer ʼélá֗y⁠w maḋẇʻa֩ máẕá֨ʼţiy ẖé֤n bĕ̇⁠ʻéyne֨y⁠ká֙ lĕ⁠haki̇yré֔⁠niy wĕ⁠ʼá̇nòki֖y nákĕriyáֽ̇h׃"],[2,11,"וַ⁠יַּ֤עַן בֹּ֨עַז֙ וַ⁠יֹּ֣אמֶר לָ֔⁠הּ הֻגֵּ֨ד הֻגַּ֜ד לִ֗⁠י כֹּ֤ל אֲשֶׁר־עָשִׂית֙ אֶת־חֲמוֹתֵ֔⁠ךְ אַחֲרֵ֖י מ֣וֹת אִישֵׁ֑⁠ךְ וַ⁠תַּֽעַזְבִ֞י אָּבִ֣י⁠ךְ וְ⁠אִמֵּ֗⁠ךְ וְ⁠אֶ֨רֶץ֙ מֽוֹלַדְתֵּ֔⁠ךְ וַ⁠תֵּ֣לְכִ֔י אֶל־עַ֕ם אֲשֶׁ֥ר לֹא־יָדַ֖עַתְּ תְּמ֥וֹל שִׁלְשֽׁוֹם׃","wa⁠yȧ֤ʻan bò̇֨ʻaz֙ wa⁠yò֣̇ʼmer lá֔⁠ḣ hugé̇֨d hugȧ֜d li֗⁠y kò֤̇l ʼàşěr-ʻáşîyţ֙ ʼeţ-ẖàmwòţé֔⁠kĕ ʼaẖàré֖y m֣wòţ ʼiyşé֑̌⁠kĕ wa⁠ţȧֽʻazĕbi֞y ʼá̇bi֣y⁠kĕ wĕ⁠ʼimé̇֗⁠kĕ wĕ⁠ʼe֨reẕ֙ mֽwòladĕţé̇֔⁠kĕ wa⁠ţé֣̇lĕki֔y ʼel-ʻa֕m ʼàşě֥r lòʼ-yáda֖ʻaţĕ̇ ţĕ̇m֥wòl şǐlĕşֽ̌wòm׃"],[2,12,"יְשַׁלֵּ֥ם יְהוָ֖ה פָּעֳלֵ֑⁠ךְ וּ⁠תְהִ֨י מַשְׂכֻּרְתֵּ֜⁠ךְ שְׁלֵמָ֗ה מֵ⁠עִ֤ם יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר־בָּ֖את לַ⁠חֲס֥וֹת תַּֽחַת־כְּנָפָֽי⁠ו׃","yĕşǎlé֥̇m yĕhwá֖h pá̇ʻolé֑⁠kĕ ẇ⁠ţĕhi֨y maşĕ̂ku̇rĕţé̇֜⁠kĕ şĕ̌lémá֗h mé⁠ʻi֤m yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşěr-bá֖̇ʼţ la⁠ẖàs֥wòţ ţȧֽẖaţ-kĕ̇nápáֽy⁠w׃"],[2,13,"וַ֠⁠תֹּאמֶר אֶמְצָא־חֵ֨ן בְּ⁠עֵינֶ֤י⁠ךָ אֲדֹנִ⁠י֙ כִּ֣י נִֽחַמְתָּ֔⁠נִי וְ⁠כִ֥י דִבַּ֖רְתָּ עַל־לֵ֣ב שִׁפְחָתֶ֑⁠ךָ וְ⁠אָנֹכִי֙ לֹ֣א אֶֽהְיֶ֔ה כְּ⁠אַחַ֖ת שִׁפְחֹתֶֽי⁠ךָ׃","wa֠⁠ţò̇ʼmer ʼemĕẕáʼ-ẖé֨n bĕ̇⁠ʻéyne֤y⁠ká ʼàdòni⁠y֙ ki֣̇y niֽẖamĕţá̇֔⁠niy wĕ⁠ki֥y dibȧ֖rĕţá̇ ʻal-lé֣b şǐpĕẖáţe֑⁠ká wĕ⁠ʼánòkiy֙ lò֣ʼ ʼeֽhĕye֔h kĕ̇⁠ʼaẖa֖ţ şǐpĕẖòţeֽy⁠ká׃"],[2,14,"וַ⁠יֹּאמֶר֩ לָ֨⁠ה בֹ֜עַז לְ⁠עֵ֣ת הָ⁠אֹ֗כֶל גֹּ֤שִֽׁי הֲלֹם֙ וְ⁠אָכַ֣לְתְּ מִן־הַ⁠לֶּ֔חֶם וְ⁠טָבַ֥לְתְּ פִּתֵּ֖⁠ךְ בַּ⁠חֹ֑מֶץ וַ⁠תֵּ֨שֶׁב֙ מִ⁠צַּ֣ד הַ⁠קּֽוֹצְרִ֔ים וַ⁠יִּצְבָּט־לָ֣⁠הּ קָלִ֔י וַ⁠תֹּ֥אכַל וַ⁠תִּשְׂבַּ֖ע וַ⁠תֹּתַֽר׃","wa⁠yò̇ʼmer֩ lá֨⁠h bò֜ʻaz lĕ⁠ʻé֣ţ há⁠ʼò֗kel gò֤̇şǐֽy hàlòm֙ wĕ⁠ʼáka֣lĕţĕ̇ min-ha⁠lė֔ẖem wĕ⁠tába֥lĕţĕ̇ pi̇ţé֖̇⁠kĕ bȧ⁠ẖò֑meẕ wa⁠ţé̇֨şěb֙ mi⁠ẕȧ֣d ha⁠qֽ̇wòẕĕri֔ym wa⁠yi̇ẕĕbá̇t-lá֣⁠ḣ qáli֔y wa⁠ţò֥̇ʼkal wa⁠ţi̇şĕ̂bȧ֖ʻ wa⁠ţò̇ţaֽr׃"],[2,15,"וַ⁠תָּ֖קָם לְ⁠לַקֵּ֑ט וַ⁠יְצַו֩ בֹּ֨עַז אֶת־נְעָרָ֜י⁠ו לֵ⁠אמֹ֗ר גַּ֣ם בֵּ֧ין הָֽ⁠עֳמָרִ֛ים תְּלַקֵּ֖ט וְ⁠לֹ֥א תַכְלִימֽוּ⁠הָ׃","wa⁠ţá֖̇qám lĕ⁠laqé֑̇t wa⁠yĕẕaw֩ bò̇֨ʻaz ʼeţ-nĕʻárá֜y⁠w lé⁠ʼmò֗r gȧ֣m bé֧̇yn háֽ⁠ʻomári֛ym ţĕ̇laqé֖̇t wĕ⁠lò֥ʼ ţakĕliymֽẇ⁠há׃"],[2,16,"וְ⁠גַ֛ם שֹׁל־תָּשֹׁ֥לּוּ לָ֖⁠הּ מִן־הַ⁠צְּבָתִ֑ים וַ⁠עֲזַבְתֶּ֥ם וְ⁠לִקְּטָ֖ה וְ⁠לֹ֥א תִגְעֲרוּ־בָֽ⁠הּ׃","wĕ⁠ga֛m şò̌l-ţá̇şò֥̌l̇ẇ lá֖⁠ḣ min-ha⁠ẕĕ̇báţi֑ym wa⁠ʻàzabĕţė֥m wĕ⁠liqĕ̇tá֖h wĕ⁠lò֥ʼ ţigĕʻàrẇ-báֽ⁠ḣ׃"],[2,17,"וַ⁠תְּלַקֵּ֥ט בַּ⁠שָּׂדֶ֖ה עַד־הָ⁠עָ֑רֶב וַ⁠תַּחְבֹּט֙ אֵ֣ת אֲשֶׁר־לִקֵּ֔טָה וַ⁠יְהִ֖י כְּ⁠אֵיפָ֥ה שְׂעֹרִֽים׃","wa⁠ţĕ̇laqé֥̇t bȧ⁠şá̇̂de֖h ʻad-há⁠ʻá֑reb wa⁠ţȧẖĕbò̇t֙ ʼé֣ţ ʼàşěr-liqé̇֔táh wa⁠yĕhi֖y kĕ̇⁠ʼéypá֥h şĕ̂ʻòriֽym׃"],[2,18,"וַ⁠תִּשָּׂא֙ וַ⁠תָּב֣וֹא הָ⁠עִ֔יר וַ⁠תֵּ֥רֶא חֲמוֹתָ֖⁠הּ אֵ֣ת אֲשֶׁר־לִקֵּ֑טָה וַ⁠תּוֹצֵא֙ וַ⁠תִּתֶּן־לָ֔⁠הּ אֵ֥ת אֲשֶׁר־הוֹתִ֖רָה מִ⁠שָּׂבְעָֽ⁠הּ׃","wa⁠ţi̇şá̇̂ʼ֙ wa⁠ţá̇b֣wòʼ há⁠ʻi֔yr wa⁠ţé֥̇reʼ ẖàmwòţá֖⁠ḣ ʼé֣ţ ʼàşěr-liqé֑̇táh wa⁠ţ̇wòẕéʼ֙ wa⁠ţi̇ţėn-lá֔⁠ḣ ʼé֥ţ ʼàşěr-hwòţi֖ráh mi⁠şá̇̂bĕʻáֽ⁠ḣ׃"],[2,19,"וַ⁠תֹּאמֶר֩ לָ֨⁠הּ חֲמוֹתָ֜⁠הּ אֵיפֹ֨ה לִקַּ֤טְתְּ הַ⁠יּוֹם֙ וְ⁠אָ֣נָה עָשִׂ֔ית יְהִ֥י מַכִּירֵ֖⁠ךְ בָּר֑וּךְ וַ⁠תַּגֵּ֣ד לַ⁠חֲמוֹתָ֗⁠הּ אֵ֤ת אֲשֶׁר־עָשְׂתָה֙ עִמּ֔⁠וֹ וַ⁠תֹּ֗אמֶר שֵׁ֤ם הָ⁠אִישׁ֙ אֲשֶׁ֨ר עָשִׂ֧יתִי עִמּ֛⁠וֹ הַ⁠יּ֖וֹם בֹּֽעַז׃","wa⁠ţò̇ʼmer֩ lá֨⁠ḣ ẖàmwòţá֜⁠ḣ ʼéypò֨h liqȧ֤tĕţĕ̇ ha⁠ẏwòm֙ wĕ⁠ʼá֣náh ʻáşî֔yţ yĕhi֥y maki̇yré֖⁠kĕ bá̇r֑ẇkĕ wa⁠ţȧgé֣̇d la⁠ẖàmwòţá֗⁠ḣ ʼé֤ţ ʼàşěr-ʻáşĕ̂ţáh֙ ʻiṁ֔⁠wò wa⁠ţò̇֗ʼmer şé֤̌m há⁠ʼiyş̌֙ ʼàşě֨r ʻáşî֧yţiy ʻiṁ֛⁠wò ha⁠ẏ֖wòm bòֽ̇ʻaz׃"],[2,20,"וַ⁠תֹּ֨אמֶר נָעֳמִ֜י לְ⁠כַלָּתָ֗⁠הּ בָּר֥וּךְ הוּא֙ לַ⁠יהוָ֔ה אֲשֶׁר֙ לֹא־עָזַ֣ב חַסְדּ֔⁠וֹ אֶת־הַ⁠חַיִּ֖ים וְ⁠אֶת־הַ⁠מֵּתִ֑ים וַ⁠תֹּ֧אמֶר לָ֣⁠הּ נָעֳמִ֗י קָר֥וֹב לָ֨⁠נוּ֙ הָ⁠אִ֔ישׁ מִֽ⁠גֹּאֲלֵ֖⁠נוּ הֽוּא׃","wa⁠ţò̇֨ʼmer náʻomi֜y lĕ⁠kalá̇ţá֗⁠ḣ bá̇r֥ẇkĕ hẇʼ֙ la⁠yhwá֔h ʼàşěr֙ lòʼ-ʻáza֣b ẖasĕḋ֔⁠wò ʼeţ-ha⁠ẖayi֖̇ym wĕ⁠ʼeţ-ha⁠mé̇ţi֑ym wa⁠ţò֧̇ʼmer lá֣⁠ḣ náʻomi֗y qár֥wòb lá֨⁠nẇ֙ há⁠ʼi֔yş̌ miֽ⁠gò̇ʼàlé֖⁠nẇ hֽẇʼ׃"],[2,21,"וַ⁠תֹּ֖אמֶר ר֣וּת הַ⁠מּוֹאֲבִיָּ֑ה גַּ֣ם ׀ כִּי־אָמַ֣ר אֵלַ֗⁠י עִם־הַ⁠נְּעָרִ֤ים אֲשֶׁר־לִ⁠י֙ תִּדְבָּקִ֔י⁠ן עַ֣ד אִם־כִּלּ֔וּ אֵ֥ת כָּל־הַ⁠קָּצִ֖יר אֲשֶׁר־לִֽ⁠י׃","wa⁠ţò֖̇ʼmer r֣ẇţ ha⁠ṁwòʼàbiyá֑̇h gȧ֣m ׀ ki̇y-ʼáma֣r ʼéla֗⁠y ʻim-ha⁠nĕ̇ʻári֤ym ʼàşěr-li⁠y֙ ţi̇dĕbá̇qi֔y⁠n ʻa֣d ʼim-ki̇l̇֔ẇ ʼé֥ţ ká̇l-ha⁠qá̇ẕi֖yr ʼàşěr-liֽ⁠y׃"],[2,22,"וַ⁠תֹּ֥אמֶר נָעֳמִ֖י אֶל־ר֣וּת כַּלָּתָ֑⁠הּ ט֣וֹב בִּתִּ֗⁠י כִּ֤י תֵֽצְאִי֙ עִם־נַ֣עֲרוֹתָ֔י⁠ו וְ⁠לֹ֥א יִפְגְּעוּ־בָ֖⁠ךְ בְּ⁠שָׂדֶ֥ה אַחֵֽר׃","wa⁠ţò֥̇ʼmer náʻomi֖y ʼel-r֣ẇţ kȧlá̇ţá֑⁠ḣ t֣wòb bi̇ţi̇֗⁠y ki֤̇y ţéֽẕĕʼiy֙ ʻim-na֣ʻàrwòţá֔y⁠w wĕ⁠lò֥ʼ yipĕgĕ̇ʻẇ-bá֖⁠kĕ bĕ̇⁠şá̂de֥h ʼaẖéֽr׃"],[2,23,"וַ⁠תִּדְבַּ֞ק בְּ⁠נַעֲר֥וֹת בֹּ֨עַז֙ לְ⁠לַקֵּ֔ט עַד־כְּל֥וֹת קְצִֽיר־הַ⁠שְּׂעֹרִ֖ים וּ⁠קְצִ֣יר הַֽ⁠חִטִּ֑ים וַ⁠תֵּ֖שֶׁב אֶת־חֲמוֹתָֽ⁠הּ׃","wa⁠ţi̇dĕbȧ֞q bĕ̇⁠naʻàr֥wòţ bò̇֨ʻaz֙ lĕ⁠laqé̇֔t ʻad-kĕ̇l֥wòţ qĕẕiֽyr-ha⁠şĕ̇̂ʻòri֖ym ẇ⁠qĕẕi֣yr haֽ⁠ẖiti֑̇ym wa⁠ţé֖̇şěb ʼeţ-ẖàmwòţáֽ⁠ḣ׃"],[3,1,"וַ⁠תֹּ֥אמֶר לָ֖⁠הּ נָעֳמִ֣י חֲמוֹתָ֑⁠הּ בִּתִּ֞⁠י הֲ⁠לֹ֧א אֲבַקֶּשׁ־לָ֛⁠ךְ מָנ֖וֹחַ אֲשֶׁ֥ר יִֽיטַב־לָֽ⁠ךְ׃","wa⁠ţò֥̇ʼmer lá֖⁠ḣ náʻomi֣y ẖàmwòţá֑⁠ḣ bi̇ţi̇֞⁠y hà⁠lò֧ʼ ʼàbaqėş̌-lá֛⁠kĕ mán֖wòẖa ʼàşě֥r yiֽytab-láֽ⁠kĕ׃"],[3,2,"וְ⁠עַתָּ֗ה הֲ⁠לֹ֥א בֹ֨עַז֙ מֹֽדַעְתָּ֔⁠נוּ אֲשֶׁ֥ר הָיִ֖ית אֶת־נַעֲרוֹתָ֑י⁠ו הִנֵּה־ה֗וּא זֹרֶ֛ה אֶת־גֹּ֥רֶן הַ⁠שְּׂעֹרִ֖ים הַ⁠לָּֽיְלָה׃","wĕ⁠ʻaţá̇֗h hà⁠lò֥ʼ bò֨ʻaz֙ mòֽdaʻĕţá̇֔⁠nẇ ʼàşě֥r háyi֖yţ ʼeţ-naʻàrwòţá֑y⁠w hiné̇h-h֗ẇʼ zòre֛h ʼeţ-gò֥̇ren ha⁠şĕ̇̂ʻòri֖ym ha⁠láֽ̇yĕláh׃"],[3,3,"וְ⁠רָחַ֣צְתְּ ׀ וָ⁠סַ֗כְתְּ וְ⁠שַׂ֧מְתְּ שמלת⁠ך עָלַ֖יִ⁠ךְ ו⁠ירדתי הַ⁠גֹּ֑רֶן אַל־תִּוָּדְעִ֣י לָ⁠אִ֔ישׁ עַ֥ד כַּלֹּת֖⁠וֹ לֶ⁠אֱכֹ֥ל וְ⁠לִ⁠שְׁתּֽוֹת׃","wĕ⁠ráẖa֣ẕĕţĕ̇ ׀ wá⁠sa֗kĕţĕ̇ wĕ⁠şâ֧mĕţĕ̇ şmlţ⁠k ʻála֖yi⁠kĕ w⁠yrdţy ha⁠gò֑̇ren ʼal-ţi̇wá̇dĕʻi֣y lá⁠ʼi֔yş̌ ʻa֥d kȧlò̇ţ֖⁠wò le⁠ʼèkò֥l wĕ⁠li⁠şĕ̌ţֽ̇wòţ׃"],[3,4,"וִ⁠יהִ֣י בְ⁠שָׁכְב֗⁠וֹ וְ⁠יָדַ֨עַתְּ֙ אֶת־הַ⁠מָּקוֹם֙ אֲשֶׁ֣ר יִשְׁכַּב־שָׁ֔ם וּ⁠בָ֛את וְ⁠גִלִּ֥ית מַרְגְּלֹתָ֖י⁠ו ו⁠שכבתי וְ⁠הוּא֙ יַגִּ֣יד לָ֔⁠ךְ אֵ֖ת אֲשֶׁ֥ר תַּעַשִֽׂי⁠ן׃","wi⁠yhi֣y bĕ⁠şá̌kĕb֗⁠wò wĕ⁠yáda֨ʻaţĕ̇֙ ʼeţ-ha⁠má̇qwòm֙ ʼàşě֣r yişĕ̌kȧb-şá̌֔m ẇ⁠bá֛ʼţ wĕ⁠gili֥̇yţ marĕgĕ̇lòţá֖y⁠w w⁠şkbţy wĕ⁠hẇʼ֙ yagi֣̇yd lá֔⁠kĕ ʼé֖ţ ʼàşě֥r ţȧʻaşîֽy⁠n׃"],[3,5,"וַ⁠תֹּ֖אמֶר אֵלֶ֑י⁠הָ כֹּ֛ל אֲשֶׁר־תֹּאמְרִ֥י אֶֽעֱשֶֽׂה׃","wa⁠ţò֖̇ʼmer ʼéle֑y⁠há kò֛̇l ʼàşěr-ţò̇ʼmĕri֥y ʼeֽʻèşêֽh׃"],[3,6,"וַ⁠תֵּ֖רֶד הַ⁠גֹּ֑רֶן וַ⁠תַּ֕עַשׂ כְּ⁠כֹ֥ל אֲשֶׁר־צִוַּ֖תָּ⁠ה חֲמוֹתָֽ⁠הּ׃","wa⁠ţé֖̇red ha⁠gò֑̇ren wa⁠ţȧ֕ʻaş̂ kĕ̇⁠kò֥l ʼàşěr-ẕiwȧ֖ţá̇⁠h ẖàmwòţáֽ⁠ḣ׃"],[3,7,"וַ⁠יֹּ֨אכַל בֹּ֤עַז וַ⁠יֵּשְׁתְּ֙ וַ⁠יִּיטַ֣ב לִבּ֔⁠וֹ וַ⁠יָּבֹ֕א לִ⁠שְׁכַּ֖ב בִּ⁠קְצֵ֣ה הָ⁠עֲרֵמָ֑ה וַ⁠תָּבֹ֣א בַ⁠לָּ֔ט וַ⁠תְּגַ֥ל מַרְגְּלֹתָ֖י⁠ו וַ⁠תִּשְׁכָּֽב׃","wa⁠yò̇֨ʼkal bò֤̇ʻaz wa⁠yé̇şĕ̌ţĕ̇֙ wa⁠yi̇yta֣b liḃ֔⁠wò wa⁠yá̇bò֕ʼ li⁠şĕ̌kȧ֖b bi̇⁠qĕẕé֣h há⁠ʻàrémá֑h wa⁠ţá̇bò֣ʼ ba⁠lá̇֔t wa⁠ţĕ̇ga֥l marĕgĕ̇lòţá֖y⁠w wa⁠ţi̇şĕ̌káֽ̇b׃"],[3,8,"וַ⁠יְהִי֙ בַּ⁠חֲצִ֣י הַ⁠לַּ֔יְלָה וַ⁠יֶּחֱרַ֥ד הָ⁠אִ֖ישׁ וַ⁠יִּלָּפֵ֑ת וְ⁠הִנֵּ֣ה אִשָּׁ֔ה שֹׁכֶ֖בֶת מַרְגְּלֹתָֽי⁠ו׃","wa⁠yĕhiy֙ bȧ⁠ẖàẕi֣y ha⁠lȧ֔yĕláh wa⁠yėẖèra֥d há⁠ʼi֖yş̌ wa⁠yi̇lá̇pé֑ţ wĕ⁠hiné֣̇h ʼişá̇̌֔h şò̌ke֖beţ marĕgĕ̇lòţáֽy⁠w׃"],[3,9,"וַ⁠יֹּ֖אמֶר מִי־אָ֑תּ וַ⁠תֹּ֗אמֶר אָנֹכִי֙ ר֣וּת אֲמָתֶ֔⁠ךָ וּ⁠פָרַשְׂתָּ֤ כְנָפֶ֨⁠ךָ֙ עַל־אֲמָ֣תְ⁠ךָ֔ כִּ֥י גֹאֵ֖ל אָֽתָּה׃","wa⁠yò֖̇ʼmer miy-ʼá֑ţ̇ wa⁠ţò̇֗ʼmer ʼánòkiy֙ r֣ẇţ ʼàmáţe֔⁠ká ẇ⁠páraşĕ̂ţá֤̇ kĕnápe֨⁠ká֙ ʻal-ʼàmá֣ţĕ⁠ká֔ ki֥̇y gòʼé֖l ʼáֽţá̇h׃"],[3,10,"וַ⁠יֹּ֗אמֶר בְּרוּכָ֨ה אַ֤תְּ לַֽ⁠יהוָה֙ בִּתִּ֔⁠י הֵיטַ֛בְתְּ חַסְדֵּ֥⁠ךְ הָ⁠אַחֲר֖וֹן מִן־הָ⁠רִאשׁ֑וֹן לְ⁠בִלְתִּי־לֶ֗כֶת אַחֲרֵי֙ הַ⁠בַּ֣חוּרִ֔ים אִם־דַּ֖ל וְ⁠אִם־עָשִֽׁיר׃","wa⁠yò̇֗ʼmer bĕ̇rẇká֨h ʼa֤ţĕ̇ laֽ⁠yhwáh֙ bi̇ţi̇֔⁠y héyta֛bĕţĕ̇ ẖasĕdé֥̇⁠kĕ há⁠ʼaẖàr֖wòn min-há⁠riʼş֑̌wòn lĕ⁠bilĕţi̇y-le֗keţ ʼaẖàréy֙ ha⁠bȧ֣ẖẇri֔ym ʼim-dȧ֖l wĕ⁠ʼim-ʻáşǐֽyr׃"],[3,11,"וְ⁠עַתָּ֗ה בִּתִּ⁠י֙ אַל־תִּ֣ירְאִ֔י כֹּ֥ל אֲשֶׁר־תֹּאמְרִ֖י אֶֽעֱשֶׂה־לָּ֑⁠ךְ כִּ֤י יוֹדֵ֨עַ֙ כָּל־שַׁ֣עַר עַמִּ֔⁠י כִּ֛י אֵ֥שֶׁת חַ֖יִל אָֽתְּ׃","wĕ⁠ʻaţá̇֗h bi̇ţi̇⁠y֙ ʼal-ţi֣̇yrĕʼi֔y kò֥̇l ʼàşěr-ţò̇ʼmĕri֖y ʼeֽʻèşêh-lá֑̇⁠kĕ ki֤̇y ywòdé֨ʻa֙ ká̇l-şǎ֣ʻar ʻami̇֔⁠y ki֛̇y ʼé֥şěţ ẖa֖yil ʼáֽţĕ̇׃"],[3,12,"וְ⁠עַתָּה֙ כִּ֣י אָמְנָ֔ם כי אם גֹאֵ֖ל אָנֹ֑כִי וְ⁠גַ֛ם יֵ֥שׁ גֹּאֵ֖ל קָר֥וֹב מִמֶּֽ⁠נִּי׃","wĕ⁠ʻaţá̇h֙ ki֣̇y ʼámĕná֔m ky ʼm gòʼé֖l ʼánò֑kiy wĕ⁠ga֛m yé֥ş̌ gò̇ʼé֖l qár֥wòb mimėֽ⁠ni̇y׃"],[3,13,"לִ֣ינִי ׀ הַ⁠לַּ֗יְלָה וְ⁠הָיָ֤ה בַ⁠בֹּ֨קֶר֙ אִם־יִגְאָלֵ֥⁠ךְ טוֹב֙ יִגְאָ֔ל וְ⁠אִם־לֹ֨א יַחְפֹּ֧ץ לְ⁠גָֽאֳלֵ֛⁠ךְ וּ⁠גְאַלְתִּ֥י⁠ךְ אָנֹ֖כִי חַי־יְהוָ֑ה שִׁכְבִ֖י עַד־הַ⁠בֹּֽקֶר׃","li֣yniy ׀ ha⁠lȧ֗yĕláh wĕ⁠háyá֤h ba⁠bò̇֨qer֙ ʼim-yigĕʼálé֥⁠kĕ twòb֙ yigĕʼá֔l wĕ⁠ʼim-lò֨ʼ yaẖĕpò֧̇ẕ lĕ⁠gáֽʼolé֛⁠kĕ ẇ⁠gĕʼalĕţi֥̇y⁠kĕ ʼánò֖kiy ẖay-yĕhwá֑h şǐkĕbi֖y ʻad-ha⁠bòֽ̇qer׃"],[3,14,"וַ⁠תִּשְׁכַּ֤ב מרגלת⁠ו עַד־הַ⁠בֹּ֔קֶר וַ⁠תָּ֕קָם ב⁠טרום יַכִּ֥יר אִ֖ישׁ אֶת־רֵעֵ֑⁠הוּ וַ⁠יֹּ֨אמֶר֙ אַל־יִוָּדַ֔ע כִּי־בָ֥אָה הָ⁠אִשָּׁ֖ה הַ⁠גֹּֽרֶן׃","wa⁠ţi̇şĕ̌kȧ֤b mrglţ⁠w ʻad-ha⁠bò̇֔qer wa⁠ţá̇֕qám b⁠trwm yaki֥̇yr ʼi֖yş̌ ʼeţ-réʻé֑⁠hẇ wa⁠yò̇֨ʼmer֙ ʼal-yiwá̇da֔ʻ ki̇y-bá֥ʼáh há⁠ʼişá֖̇̌h ha⁠gòֽ̇ren׃"],[3,15,"וַ⁠יֹּ֗אמֶר הָ֠בִי הַ⁠מִּטְפַּ֧חַת אֲשֶׁר־עָלַ֛יִ⁠ךְ וְ⁠אֶֽחֳזִי־בָ֖⁠הּ וַ⁠תֹּ֣אחֶז בָּ֑⁠הּ וַ⁠יָּ֤מָד שֵׁשׁ־שְׂעֹרִים֙ וַ⁠יָּ֣שֶׁת עָלֶ֔י⁠הָ וַ⁠יָּבֹ֖א הָ⁠עִֽיר׃","wa⁠yò̇֗ʼmer há֠biy ha⁠mi̇tĕpȧ֧ẖaţ ʼàşěr-ʻála֛yi⁠kĕ wĕ⁠ʼeֽẖoziy-bá֖⁠ḣ wa⁠ţò֣̇ʼẖez bá֑̇⁠ḣ wa⁠yá֤̇mád şé̌ş̌-şĕ̂ʻòriym֙ wa⁠yá֣̇şěţ ʻále֔y⁠há wa⁠yá̇bò֖ʼ há⁠ʻiֽyr׃"],[3,16,"וַ⁠תָּבוֹא֙ אֶל־חֲמוֹתָ֔⁠הּ וַ⁠תֹּ֖אמֶר מִי־אַ֣תְּ בִּתִּ֑⁠י וַ⁠תַּ֨גֶּד־לָ֔⁠הּ אֵ֛ת כָּל־אֲשֶׁ֥ר עָֽשָׂה־לָ֖⁠הּ הָ⁠אִֽישׁ׃","wa⁠ţá̇bwòʼ֙ ʼel-ẖàmwòţá֔⁠ḣ wa⁠ţò֖̇ʼmer miy-ʼa֣ţĕ̇ bi̇ţi֑̇⁠y wa⁠ţȧ֨gėd-lá֔⁠ḣ ʼé֛ţ ká̇l-ʼàşě֥r ʻáֽşá̂h-lá֖⁠ḣ há⁠ʼiֽyş̌׃"],[3,17,"וַ⁠תֹּ֕אמֶר שֵׁשׁ־הַ⁠שְּׂעֹרִ֥ים הָ⁠אֵ֖לֶּה נָ֣תַן לִ֑⁠י כִּ֚י אָמַ֣ר אַל־תָּב֥וֹאִי רֵיקָ֖ם אֶל־חֲמוֹתֵֽ⁠ךְ׃","wa⁠ţò̇֕ʼmer şé̌ş̌-ha⁠şĕ̇̂ʻòri֥ym há⁠ʼé֖lėh ná֣ţan li֑⁠y ki֚̇y ʼáma֣r ʼal-ţá̇b֥wòʼiy réyqá֖m ʼel-ẖàmwòţéֽ⁠kĕ׃"],[3,18,"וַ⁠תֹּ֨אמֶר֙ שְׁבִ֣י בִתִּ֔⁠י עַ֚ד אֲשֶׁ֣ר תֵּֽדְעִ֔י⁠ן אֵ֖יךְ יִפֹּ֣ל דָּבָ֑ר כִּ֣י לֹ֤א יִשְׁקֹט֙ הָ⁠אִ֔ישׁ כִּֽי־אִם־כִּלָּ֥ה הַ⁠דָּבָ֖ר הַ⁠יּֽוֹם׃","wa⁠ţò̇֨ʼmer֙ şĕ̌bi֣y biţi̇֔⁠y ʻa֚d ʼàşě֣r ţéֽ̇dĕʻi֔y⁠n ʼé֖ykĕ yipò֣̇l dá̇bá֑r ki֣̇y lò֤ʼ yişĕ̌qòt֙ há⁠ʼi֔yş̌ kiֽ̇y-ʼim-ki̇lá֥̇h ha⁠dá̇bá֖r ha⁠ẏֽwòm׃"],[4,1,"וּ⁠בֹ֨עַז עָלָ֣ה הַ⁠שַּׁעַר֮ וַ⁠יֵּ֣שֶׁב שָׁם֒ וְ⁠הִנֵּ֨ה הַ⁠גֹּאֵ֤ל עֹבֵר֙ אֲשֶׁ֣ר דִּבֶּר־בֹּ֔עַז וַ⁠יֹּ֛אמֶר ס֥וּרָ⁠ה שְׁבָ⁠ה־פֹּ֖ה פְּלֹנִ֣י אַלְמֹנִ֑י וַ⁠יָּ֖סַר וַ⁠יֵּשֵֽׁב׃","ẇ⁠bò֨ʻaz ʻálá֣h ha⁠şȧ̌ʻar֮ wa⁠yé֣̇şěb şá̌m֒ wĕ⁠hiné̇֨h ha⁠gò̇ʼé֤l ʻòbér֙ ʼàşě֣r di̇bėr-bò̇֔ʻaz wa⁠yò֛̇ʼmer s֥ẇrá⁠h şĕ̌bá⁠h-pò֖̇h pĕ̇lòni֣y ʼalĕmòni֑y wa⁠yá֖̇sar wa⁠yé̇şéֽ̌b׃"],[4,2,"וַ⁠יִּקַּ֞ח עֲשָׂרָ֧ה אֲנָשִׁ֛ים מִ⁠זִּקְנֵ֥י הָ⁠עִ֖יר וַ⁠יֹּ֣אמֶר שְׁבוּ־פֹ֑ה וַ⁠יֵּשֵֽׁבוּ׃","wa⁠yi̇qȧ֞ẖ ʻàşá̂rá֧h ʼànáşǐ֛ym mi⁠zi̇qĕné֥y há⁠ʻi֖yr wa⁠yò֣̇ʼmer şĕ̌bẇ-pò֑h wa⁠yé̇şéֽ̌bẇ׃"],[4,3,"וַ⁠יֹּ֨אמֶר֙ לַ⁠גֹּאֵ֔ל חֶלְקַת֙ הַ⁠שָּׂדֶ֔ה אֲשֶׁ֥ר לְ⁠אָחִ֖י⁠נוּ לֶ⁠אֱלִימֶ֑לֶךְ מָכְרָ֣ה נָעֳמִ֔י הַ⁠שָּׁ֖בָה מִ⁠שְּׂדֵ֥ה מוֹאָֽב׃","wa⁠yò̇֨ʼmer֙ la⁠gò̇ʼé֔l ẖelĕqaţ֙ ha⁠şá̇̂de֔h ʼàşě֥r lĕ⁠ʼáẖi֖y⁠nẇ le⁠ʼèliyme֑lekĕ mákĕrá֣h náʻomi֔y ha⁠şá֖̇̌báh mi⁠şĕ̇̂dé֥h mwòʼáֽb׃"],[4,4,"וַ⁠אֲנִ֨י אָמַ֜רְתִּי אֶגְלֶ֧ה אָזְנְ⁠ךָ֣ לֵ⁠אמֹ֗ר קְ֠נֵה נֶ֥גֶד הַֽ⁠יֹּשְׁבִים֮ וְ⁠נֶ֣גֶד זִקְנֵ֣י עַמִּ⁠י֒ אִם־תִּגְאַל֙ גְּאָ֔ל וְ⁠אִם־לֹ֨א יִגְאַ֜ל הַגִּ֣ידָ⁠ה לִּ֗⁠י ו⁠אדע כִּ֣י אֵ֤ין זוּלָֽתְ⁠ךָ֙ לִ⁠גְא֔וֹל וְ⁠אָנֹכִ֖י אַחֲרֶ֑י⁠ךָ וַ⁠יֹּ֖אמֶר אָנֹכִ֥י אֶגְאָֽל׃","wa⁠ʼàni֨y ʼáma֜rĕţi̇y ʼegĕle֧h ʼázĕnĕ⁠ká֣ lé⁠ʼmò֗r qĕ֠néh ne֥ged haֽ⁠yò̇şĕ̌biym֮ wĕ⁠ne֣ged ziqĕné֣y ʻami̇⁠y֒ ʼim-ţi̇gĕʼal֙ gĕ̇ʼá֔l wĕ⁠ʼim-lò֨ʼ yigĕʼa֜l hagi֣̇ydá⁠h li̇֗⁠y w⁠ʼdʻ ki֣̇y ʼé֤yn zẇláֽţĕ⁠ká֙ li⁠gĕʼ֔wòl wĕ⁠ʼánòki֖y ʼaẖàre֑y⁠ká wa⁠yò֖̇ʼmer ʼánòki֥y ʼegĕʼáֽl׃"],[4,5,"וַ⁠יֹּ֣אמֶר בֹּ֔עַז בְּ⁠יוֹם־קְנוֹתְ⁠ךָ֥ הַ⁠שָּׂדֶ֖ה מִ⁠יַּ֣ד נָעֳמִ֑י וּ֠⁠מֵ⁠אֵת ר֣וּת הַ⁠מּוֹאֲבִיָּ֤ה אֵֽשֶׁת־הַ⁠מֵּת֙ קניתי לְ⁠הָקִ֥ים שֵׁם־הַ⁠מֵּ֖ת עַל־נַחֲלָתֽ⁠וֹ׃","wa⁠yò֣̇ʼmer bò̇֔ʻaz bĕ̇⁠ywòm-qĕnwòţĕ⁠ká֥ ha⁠şá̇̂de֖h mi⁠yȧ֣d náʻomi֑y ẇ֠⁠mé⁠ʼéţ r֣ẇţ ha⁠ṁwòʼàbiyá֤̇h ʼéֽşěţ-ha⁠mé̇ţ֙ qnyţy lĕ⁠háqi֥ym şé̌m-ha⁠mé֖̇ţ ʻal-naẖàláţֽ⁠wò׃"],[4,6,"וַ⁠יֹּ֣אמֶר הַ⁠גֹּאֵ֗ל לֹ֤א אוּכַל֙ ל⁠גאול־לִ֔⁠י פֶּן־אַשְׁחִ֖ית אֶת־נַחֲלָתִ֑⁠י גְּאַל־לְ⁠ךָ֤ אַתָּה֙ אֶת־גְּאֻלָּתִ֔⁠י כִּ֥י לֹא־אוּכַ֖ל לִ⁠גְאֹֽל׃","wa⁠yò֣̇ʼmer ha⁠gò̇ʼé֗l lò֤ʼ ʼẇkal֙ l⁠gʼwl-li֔⁠y pėn-ʼaşĕ̌ẖi֖yţ ʼeţ-naẖàláţi֑⁠y gĕ̇ʼal-lĕ⁠ká֤ ʼaţá̇h֙ ʼeţ-gĕ̇ʼulá̇ţi֔⁠y ki֥̇y lòʼ-ʼẇka֖l li⁠gĕʼòֽl׃"],[4,7,"וְ⁠זֹאת֩ לְ⁠פָנִ֨ים בְּ⁠יִשְׂרָאֵ֜ל עַל־הַ⁠גְּאוּלָּ֤ה וְ⁠עַל־הַ⁠תְּמוּרָה֙ לְ⁠קַיֵּ֣ם כָּל־דָּבָ֔ר שָׁלַ֥ף אִ֛ישׁ נַעֲל֖⁠וֹ וְ⁠נָתַ֣ן לְ⁠רֵעֵ֑⁠הוּ וְ⁠זֹ֥את הַ⁠תְּעוּדָ֖ה בְּ⁠יִשְׂרָאֵֽל׃","wĕ⁠zòʼţ֩ lĕ⁠páni֨ym bĕ̇⁠yişĕ̂ráʼé֜l ʻal-ha⁠gĕ̇ʼẇlá֤̇h wĕ⁠ʻal-ha⁠ţĕ̇mẇráh֙ lĕ⁠qayé֣̇m ká̇l-dá̇bá֔r şá̌la֥p ʼi֛yş̌ naʻàl֖⁠wò wĕ⁠náţa֣n lĕ⁠réʻé֑⁠hẇ wĕ⁠zò֥ʼţ ha⁠ţĕ̇ʻẇdá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃"],[4,8,"וַ⁠יֹּ֧אמֶר הַ⁠גֹּאֵ֛ל לְ⁠בֹ֖עַז קְנֵה־לָ֑⁠ךְ וַ⁠יִּשְׁלֹ֖ף נַעֲלֽ⁠וֹ׃","wa⁠yò֧̇ʼmer ha⁠gò̇ʼé֛l lĕ⁠bò֖ʻaz qĕnéh-lá֑⁠kĕ wa⁠yi̇şĕ̌lò֖p naʻàlֽ⁠wò׃"],[4,9,"וַ⁠יֹּאמֶר֩ בֹּ֨עַז לַ⁠זְּקֵנִ֜ים וְ⁠כָל־הָ⁠עָ֗ם עֵדִ֤ים אַתֶּם֙ הַ⁠יּ֔וֹם כִּ֤י קָנִ֨יתִי֙ אֶת־כָּל־אֲשֶׁ֣ר לֶֽ⁠אֱלִימֶ֔לֶךְ וְ⁠אֵ֛ת כָּל־אֲשֶׁ֥ר לְ⁠כִלְי֖וֹן וּ⁠מַחְל֑וֹן מִ⁠יַּ֖ד נָעֳמִֽי׃","wa⁠yò̇ʼmer֩ bò̇֨ʻaz la⁠zĕ̇qéni֜ym wĕ⁠kál-há⁠ʻá֗m ʻédi֤ym ʼaţėm֙ ha⁠ẏ֔wòm ki֤̇y qáni֨yţiy֙ ʼeţ-ká̇l-ʼàşě֣r leֽ⁠ʼèliyme֔lekĕ wĕ⁠ʼé֛ţ ká̇l-ʼàşě֥r lĕ⁠kilĕy֖wòn ẇ⁠maẖĕl֑wòn mi⁠yȧ֖d náʻomiֽy׃"],[4,10,"וְ⁠גַ֣ם אֶת־ר֣וּת הַ⁠מֹּאֲבִיָּה֩ אֵ֨שֶׁת מַחְל֜וֹן קָנִ֧יתִי לִ֣⁠י לְ⁠אִשָּׁ֗ה לְ⁠הָקִ֤ים שֵׁם־הַ⁠מֵּת֙ עַל־נַ֣חֲלָת֔⁠וֹ וְ⁠לֹא־יִכָּרֵ֧ת שֵׁם־הַ⁠מֵּ֛ת מֵ⁠עִ֥ם אֶחָ֖י⁠ו וּ⁠מִ⁠שַּׁ֣עַר מְקוֹמ֑⁠וֹ עֵדִ֥ים אַתֶּ֖ם הַ⁠יּֽוֹם׃","wĕ⁠ga֣m ʼeţ-r֣ẇţ ha⁠mò̇ʼàbiyá̇h֩ ʼé֨şěţ maẖĕl֜wòn qáni֧yţiy li֣⁠y lĕ⁠ʼişá̇̌֗h lĕ⁠háqi֤ym şé̌m-ha⁠mé̇ţ֙ ʻal-na֣ẖàláţ֔⁠wò wĕ⁠lòʼ-yiká̇ré֧ţ şé̌m-ha⁠mé֛̇ţ mé⁠ʻi֥m ʼeẖá֖y⁠w ẇ⁠mi⁠şȧ֣̌ʻar mĕqwòm֑⁠wò ʻédi֥ym ʼaţė֖m ha⁠ẏֽwòm׃"],[4,11,"וַ⁠יֹּ֨אמְר֜וּ כָּל־הָ⁠עָ֧ם אֲשֶׁר־בַּ⁠שַּׁ֛עַר וְ⁠הַ⁠זְּקֵנִ֖ים עֵדִ֑ים יִתֵּן֩ יְהוָ֨ה אֶֽת־הָ⁠אִשָּׁ֜ה הַ⁠בָּאָ֣ה אֶל־בֵּיתֶ֗⁠ךָ כְּ⁠רָחֵ֤ל ׀ וּ⁠כְ⁠לֵאָה֙ אֲשֶׁ֨ר בָּנ֤וּ שְׁתֵּי⁠הֶם֙ אֶת־בֵּ֣ית יִשְׂרָאֵ֔ל וַ⁠עֲשֵׂה־חַ֣יִל בְּ⁠אֶפְרָ֔תָה וּ⁠קְרָא־שֵׁ֖ם בְּ⁠בֵ֥ית לָֽחֶם׃","wa⁠yò̇֨ʼmĕr֜ẇ ká̇l-há⁠ʻá֧m ʼàşěr-bȧ⁠şȧ֛̌ʻar wĕ⁠ha⁠zĕ̇qéni֖ym ʻédi֑ym yiţé̇n֩ yĕhwá֨h ʼeֽţ-há⁠ʼişá̇̌֜h ha⁠bá̇ʼá֣h ʼel-bé̇yţe֗⁠ká kĕ̇⁠ráẖé֤l ׀ ẇ⁠kĕ⁠léʼáh֙ ʼàşě֨r bá̇n֤ẇ şĕ̌ţé̇y⁠hem֙ ʼeţ-bé֣̇yţ yişĕ̂ráʼé֔l wa⁠ʻàşé̂h-ẖa֣yil bĕ̇⁠ʼepĕrá֔ţáh ẇ⁠qĕráʼ-şé֖̌m bĕ̇⁠bé֥yţ láֽẖem׃"],[4,12,"וִ⁠יהִ֤י בֵֽיתְ⁠ךָ֙ כְּ⁠בֵ֣ית פֶּ֔רֶץ אֲשֶׁר־יָלְדָ֥ה תָמָ֖ר לִֽ⁠יהוּדָ֑ה מִן־הַ⁠זֶּ֗רַע אֲשֶׁ֨ר יִתֵּ֤ן יְהוָה֙ לְ⁠ךָ֔ מִן־הַֽ⁠נַּעֲרָ֖ה הַ⁠זֹּֽאת׃","wi⁠yhi֤y béֽyţĕ⁠ká֙ kĕ̇⁠bé֣yţ pė֔reẕ ʼàşěr-yálĕdá֥h ţámá֖r liֽ⁠yhẇdá֑h min-ha⁠zė֗raʻ ʼàşě֨r yiţé֤̇n yĕhwáh֙ lĕ⁠ká֔ min-haֽ⁠nȧʻàrá֖h ha⁠zòֽ̇ʼţ׃"],[4,13,"וַ⁠יִּקַּ֨ח בֹּ֤עַז אֶת־רוּת֙ וַ⁠תְּהִי־ל֣⁠וֹ לְ⁠אִשָּׁ֔ה וַ⁠יָּבֹ֖א אֵלֶ֑י⁠הָ וַ⁠יִּתֵּ֨ן יְהוָ֥ה לָ֛⁠הּ הֵרָי֖וֹן וַ⁠תֵּ֥לֶד בֵּֽן׃","wa⁠yi̇qȧ֨ẖ bò֤̇ʻaz ʼeţ-rẇţ֙ wa⁠ţĕ̇hiy-l֣⁠wò lĕ⁠ʼişá̇̌֔h wa⁠yá̇bò֖ʼ ʼéle֑y⁠há wa⁠yi̇ţé̇֨n yĕhwá֥h lá֛⁠ḣ héráy֖wòn wa⁠ţé֥̇led béֽ̇n׃"],[4,14,"וַ⁠תֹּאמַ֤רְנָה הַ⁠נָּשִׁים֙ אֶֽל־נָעֳמִ֔י בָּר֣וּךְ יְהוָ֔ה אֲ֠שֶׁר לֹ֣א הִשְׁבִּ֥ית לָ֛⁠ךְ גֹּאֵ֖ל הַ⁠יּ֑וֹם וְ⁠יִקָּרֵ֥א שְׁמ֖⁠וֹ בְּ⁠יִשְׂרָאֵֽל׃","wa⁠ţò̇ʼma֤rĕnáh ha⁠ná̇şǐym֙ ʼeֽl-náʻomi֔y bá̇r֣ẇkĕ yĕhwá֔h ʼà֠şěr lò֣ʼ hişĕ̌bi֥̇yţ lá֛⁠kĕ gò̇ʼé֖l ha⁠ẏ֑wòm wĕ⁠yiqá̇ré֥ʼ şĕ̌m֖⁠wò bĕ̇⁠yişĕ̂ráʼéֽl׃"],[4,15,"וְ⁠הָ֤יָה לָ⁠ךְ֙ לְ⁠מֵשִׁ֣יב נֶ֔פֶשׁ וּ⁠לְ⁠כַלְכֵּ֖ל אֶת־שֵׂיבָתֵ֑⁠ךְ כִּ֣י כַלָּתֵ֤⁠ךְ אֲֽשֶׁר־אֲהֵבַ֨תֶ⁠ךְ֙ יְלָדַ֔תּ⁠וּ אֲשֶׁר־הִיא֙ ט֣וֹבָה לָ֔⁠ךְ מִ⁠שִּׁבְעָ֖ה בָּנִֽים׃","wĕ⁠há֤yáh lá⁠kĕ֙ lĕ⁠méşǐ֣yb ne֔peş̌ ẇ⁠lĕ⁠kalĕké֖̇l ʼeţ-şé̂ybáţé֑⁠kĕ ki֣̇y kalá̇ţé֤⁠kĕ ʼàֽşěr-ʼàhéba֨ţe⁠kĕ֙ yĕláda֔ţ̇⁠ẇ ʼàşěr-hiyʼ֙ t֣wòbáh lá֔⁠kĕ mi⁠şi̇̌bĕʻá֖h bá̇niֽym׃"],[4,16,"וַ⁠תִּקַּ֨ח נָעֳמִ֤י אֶת־הַ⁠יֶּ֨לֶד֙ וַ⁠תְּשִׁתֵ֣⁠הוּ בְ⁠חֵיקָ֔⁠הּ וַ⁠תְּהִי־ל֖⁠וֹ לְ⁠אֹמֶֽנֶת׃","wa⁠ţi̇qȧ֨ẖ náʻomi֤y ʼeţ-ha⁠yė֨led֙ wa⁠ţĕ̇şǐţé֣⁠hẇ bĕ⁠ẖéyqá֔⁠ḣ wa⁠ţĕ̇hiy-l֖⁠wò lĕ⁠ʼòmeֽneţ׃"],[4,17,"וַ⁠תִּקְרֶאנָה֩ ל֨⁠וֹ הַ⁠שְּׁכֵנ֥וֹת שֵׁם֙ לֵ⁠אמֹ֔ר יֻלַּד־בֵּ֖ן לְ⁠נָעֳמִ֑י וַ⁠תִּקְרֶ֤אנָֽה שְׁמ⁠וֹ֙ עוֹבֵ֔ד ה֥וּא אֲבִי־יִשַׁ֖י אֲבִ֥י דָוִֽד׃פ","wa⁠ţi̇qĕreʼnáh֩ l֨⁠wò ha⁠şĕ̇̌kén֥wòţ şé̌m֙ lé⁠ʼmò֔r yulȧd-bé֖̇n lĕ⁠náʻomi֑y wa⁠ţi̇qĕre֤ʼnáֽh şĕ̌m⁠wò֙ ʻwòbé֔d h֥ẇʼ ʼàbiy-yişǎ֖y ʼàbi֥y dáwiֽd׃p"],[4,18,"וְ⁠אֵ֨לֶּה֙ תּוֹלְד֣וֹת פָּ֔רֶץ פֶּ֖רֶץ הוֹלִ֥יד אֶת־חֶצְרֽוֹן׃","wĕ⁠ʼé֨lėh֙ ţ̇wòlĕd֣wòţ pá̇֔reẕ pė֖reẕ hwòli֥yd ʼeţ-ẖeẕĕrֽwòn׃"],[4,19,"וְ⁠חֶצְרוֹן֙ הוֹלִ֣יד אֶת־רָ֔ם וְ⁠רָ֖ם הוֹלִ֥יד אֶת־עַמִּֽינָדָֽב׃","wĕ⁠ẖeẕĕrwòn֙ hwòli֣yd ʼeţ-rá֔m wĕ⁠rá֖m hwòli֥yd ʼeţ-ʻamiֽ̇ynádáֽb׃"],[4,20,"וְ⁠עַמִּֽינָדָב֙ הוֹלִ֣יד אֶת־נַחְשׁ֔וֹן וְ⁠נַחְשׁ֖וֹן הוֹלִ֥יד אֶת־שַׂלְמָֽה׃","wĕ⁠ʻamiֽ̇ynádáb֙ hwòli֣yd ʼeţ-naẖĕş̌֔wòn wĕ⁠naẖĕş֖̌wòn hwòli֥yd ʼeţ-şâlĕmáֽh׃"],[4,21,"וְ⁠שַׂלְמוֹן֙ הוֹלִ֣יד אֶת־בֹּ֔עַז וּ⁠בֹ֖עַז הוֹלִ֥יד אֶת־עוֹבֵֽד׃","wĕ⁠şâlĕmwòn֙ hwòli֣yd ʼeţ-bò̇֔ʻaz ẇ⁠bò֖ʻaz hwòli֥yd ʼeţ-ʻwòbéֽd׃"],[4,22,"וְ⁠עֹבֵד֙ הוֹלִ֣יד אֶת־יִשָׁ֔י וְ⁠יִשַׁ֖י הוֹלִ֥יד אֶת־דָּוִֽד׃","wĕ⁠ʻòbéd֙ hwòli֣yd ʼeţ-yişá̌֔y wĕ⁠yişǎ֖y hwòli֥yd ʼeţ-dá̇wiֽd׃"]],"fra-lsg1910":[[1,1,"Du temps des juges, il y eut une famine dans le pays. Un homme de Bethléhem de Juda partit, avec sa femme et ses deux fils, pour faire un séjour dans le pays de Moab.","Du temps des juges, il y eut une famine dans le pays. Un homme de Bethléhem de Juda partit, avec sa femme et ses deux fils, pour faire un séjour dans le pays de Moab."],[1,2,"Le nom de cet homme était Élimélec, celui de sa femme Naomi, et ses deux fils s'appelaient Machlon et Kiljon; ils étaient Éphratiens, de Bethléhem de Juda. Arrivés au pays de Moab, ils y fixèrent leur demeure.","Le nom de cet homme était Élimélec, celui de sa femme Naomi, et ses deux fils s'appelaient Machlon et Kiljon; ils étaient Éphratiens, de Bethléhem de Juda. Arrivés au pays de Moab, ils y fixèrent leur demeure."],[1,3,"Élimélec, mari de Naomi, mourut, et elle resta avec ses deux fils.","Élimélec, mari de Naomi, mourut, et elle resta avec ses deux fils."],[1,4,"Ils prirent des femmes Moabites, dont l'une se nommait Orpa, et l'autre Ruth, et ils habitèrent là environ dix ans.","Ils prirent des femmes Moabites, dont l'une se nommait Orpa, et l'autre Ruth, et ils habitèrent là environ dix ans."],[1,5,"Machlon et Kiljon moururent aussi tous les deux, et Naomi resta privée de ses deux fils et de son mari.","Machlon et Kiljon moururent aussi tous les deux, et Naomi resta privée de ses deux fils et de son mari."],[1,6,"Puis elle se leva, elle et ses belles-filles, afin de quitter le pays de Moab, car elle apprit au pays de Moab que l'Éternel avait visité son peuple et lui avait donné du pain.","Puis elle se leva, elle et ses belles-filles, afin de quitter le pays de Moab, car elle apprit au pays de Moab que l'Éternel avait visité son peuple et lui avait donné du pain."],[1,7,"Elle sortit du lieu qu'elle habitait, accompagnée de ses deux belles-filles, et elle se mit en route pour retourner dans le pays de Juda.","Elle sortit du lieu qu'elle habitait, accompagnée de ses deux belles-filles, et elle se mit en route pour retourner dans le pays de Juda."],[1,8,"Naomi dit alors à ses deux belles-filles: Allez, retournez chacune à la maison de sa mère! Que l'Éternel use de bonté envers vous, comme vous l'avez fait envers ceux qui sont morts et envers moi!","Naomi dit alors à ses deux belles-filles: Allez, retournez chacune à la maison de sa mère! Que l'Éternel use de bonté envers vous, comme vous l'avez fait envers ceux qui sont morts et envers moi!"],[1,9,"Que l'Éternel vous fasse trouver à chacune du repos dans la maison d'un mari! Et elle les baisa. Elles élevèrent la voix, et pleurèrent;","Que l'Éternel vous fasse trouver à chacune du repos dans la maison d'un mari! Et elle les baisa. Elles élevèrent la voix, et pleurèrent;"],[1,10,"et elles lui dirent: Non, nous irons avec toi vers ton peuple.","et elles lui dirent: Non, nous irons avec toi vers ton peuple."],[1,11,"Naomi, dit: Retournez, mes filles! Pourquoi viendriez-vous avec moi? Ai-je encore dans mon sein des fils qui puissent devenir vos maris?","Naomi, dit: Retournez, mes filles! Pourquoi viendriez-vous avec moi? Ai-je encore dans mon sein des fils qui puissent devenir vos maris?"],[1,12,"Retournez, mes filles, allez! Je suis trop vieille pour me remarier. Et quand je dirais: J'ai de l'espérance; quand cette nuit même je serais avec un mari, et que j'enfanterais des fils,","Retournez, mes filles, allez! Je suis trop vieille pour me remarier. Et quand je dirais: J'ai de l'espérance; quand cette nuit même je serais avec un mari, et que j'enfanterais des fils,"],[1,13,"attendriez-vous pour cela qu'ils eussent grandi, refuseriez-vous pour cela de vous marier? Non, mes filles! car à cause de vous je suis dans une grande affliction de ce que la main de l'Éternel s'est étendue contre moi.","attendriez-vous pour cela qu'ils eussent grandi, refuseriez-vous pour cela de vous marier? Non, mes filles! car à cause de vous je suis dans une grande affliction de ce que la main de l'Éternel s'est étendue contre moi."],[1,14,"Et elles élevèrent la voix, et pleurèrent encore. Orpa baisa sa belle-mère, mais Ruth s'attacha à elle.","Et elles élevèrent la voix, et pleurèrent encore. Orpa baisa sa belle-mère, mais Ruth s'attacha à elle."],[1,15,"Naomi dit à Ruth: Voici, ta belle-soeur est retournée vers son peuple et vers ses dieux; retourne, comme ta belle-soeur.","Naomi dit à Ruth: Voici, ta belle-soeur est retournée vers son peuple et vers ses dieux; retourne, comme ta belle-soeur."],[1,16,"Ruth répondit: Ne me presse pas de te laisser, de retourner loin de toi! Où tu iras j'irai, où tu demeureras je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu;","Ruth répondit: Ne me presse pas de te laisser, de retourner loin de toi! Où tu iras j'irai, où tu demeureras je demeurerai; ton peuple sera mon peuple, et ton Dieu sera mon Dieu;"],[1,17,"où tu mourras je mourrai, et j'y serai enterrée. Que l'Éternel me traite dans toute sa rigueur, si autre chose que la mort vient à me séparer de toi!","où tu mourras je mourrai, et j'y serai enterrée. Que l'Éternel me traite dans toute sa rigueur, si autre chose que la mort vient à me séparer de toi!"],[1,18,"Naomi, la voyant décidée à aller avec elle, cessa ses instances.","Naomi, la voyant décidée à aller avec elle, cessa ses instances."],[1,19,"Elles firent ensemble le voyage jusqu'à leur arrivée à Bethléhem. Et lorsqu'elles entrèrent dans Bethléhem, toute la ville fut émue à cause d'elles, et les femmes disaient: Est-ce là Naomi?","Elles firent ensemble le voyage jusqu'à leur arrivée à Bethléhem. Et lorsqu'elles entrèrent dans Bethléhem, toute la ville fut émue à cause d'elles, et les femmes disaient: Est-ce là Naomi?"],[1,20,"Elle leur dit: Ne m'appelez pas Naomi; appelez-moi Mara, car le Tout-Puissant m'a remplie d'amertume.","Elle leur dit: Ne m'appelez pas Naomi; appelez-moi Mara, car le Tout-Puissant m'a remplie d'amertume."],[1,21,"J'étais dans l'abondance à mon départ, et l'Éternel me ramène les mains vides. Pourquoi m'appelleriez-vous Naomi, après que l'Éternel s'est prononcé contre moi, et que le Tout-Puissant m'a affligée?","J'étais dans l'abondance à mon départ, et l'Éternel me ramène les mains vides. Pourquoi m'appelleriez-vous Naomi, après que l'Éternel s'est prononcé contre moi, et que le Tout-Puissant m'a affligée?"],[1,22,"Ainsi revinrent du pays de Moab Naomi et sa belle-fille, Ruth la Moabite. Elles arrivèrent à Bethléhem au commencement de la moisson des orges.","Ainsi revinrent du pays de Moab Naomi et sa belle-fille, Ruth la Moabite. Elles arrivèrent à Bethléhem au commencement de la moisson des orges."],[2,1,"Naomi avait un parent de son mari. C'était un homme puissant et riche, de la famille d'Élimélec, et qui se nommait Boaz.","Naomi avait un parent de son mari. C'était un homme puissant et riche, de la famille d'Élimélec, et qui se nommait Boaz."],[2,2,"Ruth la Moabite dit à Naomi: Laisse-moi, je te prie, aller glaner des épis dans le champ de celui aux yeux duquel je trouverai grâce. Elle lui répondit: Va, ma fille.","Ruth la Moabite dit à Naomi: Laisse-moi, je te prie, aller glaner des épis dans le champ de celui aux yeux duquel je trouverai grâce. Elle lui répondit: Va, ma fille."],[2,3,"Elle alla glaner dans un champ, derrière les moissonneurs. Et il se trouva par hasard que la pièce de terre appartenait à Boaz, qui était de la famille d'Élimélec.","Elle alla glaner dans un champ, derrière les moissonneurs. Et il se trouva par hasard que la pièce de terre appartenait à Boaz, qui était de la famille d'Élimélec."],[2,4,"Et voici, Boaz vint de Bethléhem, et il dit aux moissonneurs: Que l'Éternel soit avec vous! Ils lui répondirent: Que l'Éternel te bénisse!","Et voici, Boaz vint de Bethléhem, et il dit aux moissonneurs: Que l'Éternel soit avec vous! Ils lui répondirent: Que l'Éternel te bénisse!"],[2,5,"Et Boaz dit à son serviteur chargé de surveiller les moissonneurs: À qui est cette jeune femme?","Et Boaz dit à son serviteur chargé de surveiller les moissonneurs: À qui est cette jeune femme?"],[2,6,"Le serviteur chargé de surveiller les moissonneurs répondit: C'est une jeune femme Moabite, qui est revenue avec Naomi du pays de Moab.","Le serviteur chargé de surveiller les moissonneurs répondit: C'est une jeune femme Moabite, qui est revenue avec Naomi du pays de Moab."],[2,7,"Elle a dit: Permettez-moi de glaner et de ramasser des épis entre les gerbes, derrière les moissonneurs. Et depuis ce matin qu'elle est venue, elle a été debout jusqu'à présent, et ne s'est reposée qu'un moment dans la maison.","Elle a dit: Permettez-moi de glaner et de ramasser des épis entre les gerbes, derrière les moissonneurs. Et depuis ce matin qu'elle est venue, elle a été debout jusqu'à présent, et ne s'est reposée qu'un moment dans la maison."],[2,8,"Boaz dit à Ruth: Écoute, ma fille, ne va pas glaner dans un autre champ; ne t'éloigne pas d'ici, et reste avec mes servantes.","Boaz dit à Ruth: Écoute, ma fille, ne va pas glaner dans un autre champ; ne t'éloigne pas d'ici, et reste avec mes servantes."],[2,9,"Regarde où l'on moissonne dans le champ, et va après elles. J'ai défendu à mes serviteurs de te toucher. Et quand tu auras soif, tu iras aux vases, et tu boiras de ce que les serviteurs auront puisé.","Regarde où l'on moissonne dans le champ, et va après elles. J'ai défendu à mes serviteurs de te toucher. Et quand tu auras soif, tu iras aux vases, et tu boiras de ce que les serviteurs auront puisé."],[2,10,"Alors elle tomba sur sa face et se prosterna contre terre, et elle lui dit: Comment ai-je trouvé grâce à tes yeux, pour que tu t'intéresses à moi, à moi qui suis une étrangère?","Alors elle tomba sur sa face et se prosterna contre terre, et elle lui dit: Comment ai-je trouvé grâce à tes yeux, pour que tu t'intéresses à moi, à moi qui suis une étrangère?"],[2,11,"Boaz lui répondit: On m'a rapporté tout ce que tu as fait pour ta belle-mère depuis la mort de ton mari, et comment tu as quitté ton père et ta mère et le pays de ta naissance, pour aller vers un peuple que tu ne connaissais point auparavant.","Boaz lui répondit: On m'a rapporté tout ce que tu as fait pour ta belle-mère depuis la mort de ton mari, et comment tu as quitté ton père et ta mère et le pays de ta naissance, pour aller vers un peuple que tu ne connaissais point auparavant."],[2,12,"Que l'Éternel te rende ce que tu as fait, et que ta récompense soit entière de la part de l'Éternel, le Dieu d'Israël, sous les ailes duquel tu es venue te réfugier!","Que l'Éternel te rende ce que tu as fait, et que ta récompense soit entière de la part de l'Éternel, le Dieu d'Israël, sous les ailes duquel tu es venue te réfugier!"],[2,13,"Et elle dit: Oh! que je trouve grâce à tes yeux, mon seigneur! Car tu m'as consolée, et tu as parlé au coeur de ta servante. Et pourtant je ne suis pas, moi, comme l'une de tes servantes.","Et elle dit: Oh! que je trouve grâce à tes yeux, mon seigneur! Car tu m'as consolée, et tu as parlé au coeur de ta servante. Et pourtant je ne suis pas, moi, comme l'une de tes servantes."],[2,14,"Au moment du repas, Boaz dit à Ruth: Approche, mange du pain, et trempe ton morceau dans le vinaigre. Elle s'assit à côté des moissonneurs. On lui donna du grain rôti; elle mangea et se rassasia, et elle garda le reste.","Au moment du repas, Boaz dit à Ruth: Approche, mange du pain, et trempe ton morceau dans le vinaigre. Elle s'assit à côté des moissonneurs. On lui donna du grain rôti; elle mangea et se rassasia, et elle garda le reste."],[2,15,"Puis elle se leva pour glaner. Boaz donna cet ordre à ses serviteurs: Qu'elle glane aussi entre les gerbes, et ne l'inquiétez pas,","Puis elle se leva pour glaner. Boaz donna cet ordre à ses serviteurs: Qu'elle glane aussi entre les gerbes, et ne l'inquiétez pas,"],[2,16,"et même vous ôterez pour elle des gerbes quelques épis, que vous la laisserez glaner, sans lui faire de reproches.","et même vous ôterez pour elle des gerbes quelques épis, que vous la laisserez glaner, sans lui faire de reproches."],[2,17,"Elle glana dans le champ jusqu'au soir, et elle battit ce qu'elle avait glané. Il y eut environ un épha d'orge.","Elle glana dans le champ jusqu'au soir, et elle battit ce qu'elle avait glané. Il y eut environ un épha d'orge."],[2,18,"Elle l'emporta et rentra dans la ville, et sa belle-mère vit ce qu'elle avait glané. Elle sortit aussi les restes de son repas, et les lui donna.","Elle l'emporta et rentra dans la ville, et sa belle-mère vit ce qu'elle avait glané. Elle sortit aussi les restes de son repas, et les lui donna."],[2,19,"Sa belle-mère lui dit: Où as-tu glané aujourd'hui, et où as-tu travaillé? Béni soit celui qui s'est intéressé à toi! Et Ruth fit connaître à sa belle-mère chez qui elle avait travaillé: L'homme chez qui j'ai travaillé aujourd'hui, dit-elle, s'appelle Boaz.","Sa belle-mère lui dit: Où as-tu glané aujourd'hui, et où as-tu travaillé? Béni soit celui qui s'est intéressé à toi! Et Ruth fit connaître à sa belle-mère chez qui elle avait travaillé: L'homme chez qui j'ai travaillé aujourd'hui, dit-elle, s'appelle Boaz."],[2,20,"Naomi dit à sa belle-fille: Qu'il soit béni de l'Éternel, qui se montre miséricordieux pour les vivants comme il le fut pour ceux qui sont morts! Cet homme est notre parent, lui dit encore Naomi, il est de ceux qui ont sur nous droit de rachat.","Naomi dit à sa belle-fille: Qu'il soit béni de l'Éternel, qui se montre miséricordieux pour les vivants comme il le fut pour ceux qui sont morts! Cet homme est notre parent, lui dit encore Naomi, il est de ceux qui ont sur nous droit de rachat."],[2,21,"Ruth la Moabite ajouta: Il m'a dit aussi: Reste avec mes serviteurs, jusqu'à ce qu'ils aient achevé toute ma moisson.","Ruth la Moabite ajouta: Il m'a dit aussi: Reste avec mes serviteurs, jusqu'à ce qu'ils aient achevé toute ma moisson."],[2,22,"Et Naomi dit à Ruth, sa belle-fille: Il est bon, ma fille, que tu sortes avec ses servantes, et qu'on ne te rencontre pas dans un autre champ.","Et Naomi dit à Ruth, sa belle-fille: Il est bon, ma fille, que tu sortes avec ses servantes, et qu'on ne te rencontre pas dans un autre champ."],[2,23,"Elle resta donc avec les servantes de Boaz, pour glaner, jusqu'à la fin de la moisson des orges et de la moisson du froment. Et elle demeurait avec sa belle-mère.","Elle resta donc avec les servantes de Boaz, pour glaner, jusqu'à la fin de la moisson des orges et de la moisson du froment. Et elle demeurait avec sa belle-mère."],[3,1,"Naomi, sa belle-mère, lui dit: Ma fille, je voudrais assurer ton repos, afin que tu fusses heureuse.","Naomi, sa belle-mère, lui dit: Ma fille, je voudrais assurer ton repos, afin que tu fusses heureuse."],[3,2,"Et maintenant Boaz, avec les servantes duquel tu as été, n'est-il pas notre parent? Voici, il doit vanner cette nuit les orges qui sont dans l'aire.","Et maintenant Boaz, avec les servantes duquel tu as été, n'est-il pas notre parent? Voici, il doit vanner cette nuit les orges qui sont dans l'aire."],[3,3,"Lave-toi et oins-toi, puis remets tes habits, et descends à l'aire. Tu ne te feras pas connaître à lui, jusqu'à ce qu'il ait achevé de manger et de boire.","Lave-toi et oins-toi, puis remets tes habits, et descends à l'aire. Tu ne te feras pas connaître à lui, jusqu'à ce qu'il ait achevé de manger et de boire."],[3,4,"Et quand il ira se coucher, observe le lieu où il se couche. Ensuite va, découvre ses pieds, et couche-toi. Il te dira lui-même ce que tu as à faire.","Et quand il ira se coucher, observe le lieu où il se couche. Ensuite va, découvre ses pieds, et couche-toi. Il te dira lui-même ce que tu as à faire."],[3,5,"Elle lui répondit: Je ferai tout ce que tu as dit.","Elle lui répondit: Je ferai tout ce que tu as dit."],[3,6,"Elle descendit à l'aire, et fit tout ce qu'avait ordonné sa belle-mère.","Elle descendit à l'aire, et fit tout ce qu'avait ordonné sa belle-mère."],[3,7,"Boaz mangea et but, et son coeur était joyeux. Il alla se coucher à l'extrémité d'un tas de gerbes. Ruth vint alors tout doucement, découvrit ses pieds, et se coucha.","Boaz mangea et but, et son coeur était joyeux. Il alla se coucher à l'extrémité d'un tas de gerbes. Ruth vint alors tout doucement, découvrit ses pieds, et se coucha."],[3,8,"Au milieu de la nuit, cet homme eut une frayeur; il se pencha, et voici, une femme était couchée à ses pieds.","Au milieu de la nuit, cet homme eut une frayeur; il se pencha, et voici, une femme était couchée à ses pieds."],[3,9,"Il dit: Qui es-tu? Elle répondit: Je suis Ruth, ta servante; étends ton aile sur ta servante, car tu as droit de rachat.","Il dit: Qui es-tu? Elle répondit: Je suis Ruth, ta servante; étends ton aile sur ta servante, car tu as droit de rachat."],[3,10,"Et il dit: Sois bénie de l'Éternel, ma fille! Ce dernier trait témoigne encore plus en ta faveur que le premier, car tu n'as pas recherché des jeunes gens, pauvres ou riches.","Et il dit: Sois bénie de l'Éternel, ma fille! Ce dernier trait témoigne encore plus en ta faveur que le premier, car tu n'as pas recherché des jeunes gens, pauvres ou riches."],[3,11,"Maintenant, ma fille, ne crains point; je ferai pour toi tout ce que tu diras; car toute la porte de mon peuple sait que tu es une femme vertueuse.","Maintenant, ma fille, ne crains point; je ferai pour toi tout ce que tu diras; car toute la porte de mon peuple sait que tu es une femme vertueuse."],[3,12,"Il est bien vrai que j'ai droit de rachat, mais il en existe un autre plus proche que moi.","Il est bien vrai que j'ai droit de rachat, mais il en existe un autre plus proche que moi."],[3,13,"Passe ici la nuit. Et demain, s'il veut user envers toi du droit de rachat, à la bonne heure, qu'il le fasse; mais s'il ne lui plaît pas d'en user envers toi, j'en userai, moi, l'Éternel est vivant! Reste couchée jusqu'au matin.","Passe ici la nuit. Et demain, s'il veut user envers toi du droit de rachat, à la bonne heure, qu'il le fasse; mais s'il ne lui plaît pas d'en user envers toi, j'en userai, moi, l'Éternel est vivant! Reste couchée jusqu'au matin."],[3,14,"Elle resta couchée à ses pieds jusqu'au matin, et elle se leva avant qu'on pût se reconnaître l'un l'autre. Boaz dit: Qu'on ne sache pas qu'une femme est entrée dans l'aire.","Elle resta couchée à ses pieds jusqu'au matin, et elle se leva avant qu'on pût se reconnaître l'un l'autre. Boaz dit: Qu'on ne sache pas qu'une femme est entrée dans l'aire."],[3,15,"Et il ajouta: Donne le manteau qui est sur toi, et tiens-le. Elle le tint, et il mesura six mesures d'orge, qu'il chargea sur elle. Puis il rentra dans la ville.","Et il ajouta: Donne le manteau qui est sur toi, et tiens-le. Elle le tint, et il mesura six mesures d'orge, qu'il chargea sur elle. Puis il rentra dans la ville."],[3,16,"Ruth revint auprès de sa belle-mère, et Naomi dit: Est-ce toi, ma fille? Ruth lui raconta tout ce que cet homme avait fait pour elle.","Ruth revint auprès de sa belle-mère, et Naomi dit: Est-ce toi, ma fille? Ruth lui raconta tout ce que cet homme avait fait pour elle."],[3,17,"Elle dit: Il m'a donné ces six mesures d'orge, en disant: Tu ne retourneras pas à vide vers ta belle-mère.","Elle dit: Il m'a donné ces six mesures d'orge, en disant: Tu ne retourneras pas à vide vers ta belle-mère."],[3,18,"Et Naomi dit: Sois tranquille, ma fille, jusqu'à ce que tu saches comment finira la chose, car cet homme ne se donnera point de repos qu'il n'ait terminé cette affaire aujourd'hui.","Et Naomi dit: Sois tranquille, ma fille, jusqu'à ce que tu saches comment finira la chose, car cet homme ne se donnera point de repos qu'il n'ait terminé cette affaire aujourd'hui."],[4,1,"Boaz monta à la porte, et s'y arrêta. Or voici, celui qui avait droit de rachat, et dont Boaz avait parlé, vint à passer. Boaz lui dit: Approche, reste ici, toi un tel. Et il s'approcha, et s'arrêta.","Boaz monta à la porte, et s'y arrêta. Or voici, celui qui avait droit de rachat, et dont Boaz avait parlé, vint à passer. Boaz lui dit: Approche, reste ici, toi un tel. Et il s'approcha, et s'arrêta."],[4,2,"Boaz prit alors dix hommes parmi les anciens de la ville, et il dit: Asseyez-vous ici. Et ils s'assirent.","Boaz prit alors dix hommes parmi les anciens de la ville, et il dit: Asseyez-vous ici. Et ils s'assirent."],[4,3,"Puis il dit à celui qui avait le droit de rachat: Naomi, revenue du pays de Moab, a vendu la pièce de terre qui appartenait à notre frère Élimélec.","Puis il dit à celui qui avait le droit de rachat: Naomi, revenue du pays de Moab, a vendu la pièce de terre qui appartenait à notre frère Élimélec."],[4,4,"J'ai cru devoir t'en informer, et te dire: Acquiers-la, en présence des habitants et en présence des anciens de mon peuple. Si tu veux racheter, rachète; mais si tu ne veux pas, déclare-le-moi, afin que je le sache. Car il n'y a personne avant toi qui ait le droit de rachat, et je l'ai après toi. Et il répondit: je rachèterai.","J'ai cru devoir t'en informer, et te dire: Acquiers-la, en présence des habitants et en présence des anciens de mon peuple. Si tu veux racheter, rachète; mais si tu ne veux pas, déclare-le-moi, afin que je le sache. Car il n'y a personne avant toi qui ait le droit de rachat, et je l'ai après toi. Et il répondit: je rachèterai."],[4,5,"Boaz dit: Le jour où tu acquerras le champ de la main de Naomi, tu l'acquerras en même temps de Ruth la Moabite, femme du défunt, pour relever le nom du défunt dans son héritage.","Boaz dit: Le jour où tu acquerras le champ de la main de Naomi, tu l'acquerras en même temps de Ruth la Moabite, femme du défunt, pour relever le nom du défunt dans son héritage."],[4,6,"Et celui qui avait le droit de rachat répondit: Je ne puis pas racheter pour mon compte, crainte de détruire mon héritage; prends pour toi mon droit de rachat, car je ne puis pas racheter.","Et celui qui avait le droit de rachat répondit: Je ne puis pas racheter pour mon compte, crainte de détruire mon héritage; prends pour toi mon droit de rachat, car je ne puis pas racheter."],[4,7,"Autrefois en Israël, pour valider une affaire quelconque relative à un rachat ou à un échange, l'un ôtait son soulier et le donnait à l'autre: cela servait de témoignage en Israël.","Autrefois en Israël, pour valider une affaire quelconque relative à un rachat ou à un échange, l'un ôtait son soulier et le donnait à l'autre: cela servait de témoignage en Israël."],[4,8,"Celui qui avait le droit de rachat dit donc à Boaz: Acquiers pour ton compte! Et il ôta son soulier.","Celui qui avait le droit de rachat dit donc à Boaz: Acquiers pour ton compte! Et il ôta son soulier."],[4,9,"Alors Boaz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd'hui que j'ai acquis de la main de Naomi tout ce qui appartenait à Élimélec, à Kiljon et à Machlon,","Alors Boaz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd'hui que j'ai acquis de la main de Naomi tout ce qui appartenait à Élimélec, à Kiljon et à Machlon,"],[4,10,"et que je me suis également acquis pour femme Ruth la Moabite, femme de Machlon, pour relever le nom du défunt dans son héritage, et afin que le nom du défunt ne soit point retranché d'entre ses frères et de la porte de son lieu. Vous en êtes témoins aujourd'hui!","et que je me suis également acquis pour femme Ruth la Moabite, femme de Machlon, pour relever le nom du défunt dans son héritage, et afin que le nom du défunt ne soit point retranché d'entre ses frères et de la porte de son lieu. Vous en êtes témoins aujourd'hui!"],[4,11,"Tout le peuple qui était à la porte et les anciens dirent: Nous en sommes témoins! Que l'Éternel rende la femme qui entre dans ta maison semblable à Rachel et à Léa, qui toutes les deux ont bâti la maison d'Israël! Manifeste ta force dans Éphrata, et fais-toi un nom dans Bethléhem!","Tout le peuple qui était à la porte et les anciens dirent: Nous en sommes témoins! Que l'Éternel rende la femme qui entre dans ta maison semblable à Rachel et à Léa, qui toutes les deux ont bâti la maison d'Israël! Manifeste ta force dans Éphrata, et fais-toi un nom dans Bethléhem!"],[4,12,"Puisse la postérité que l'Éternel te donnera par cette jeune femme rendre ta maison semblable à la maison de Pérets, qui fut enfanté à Juda par Tamar!","Puisse la postérité que l'Éternel te donnera par cette jeune femme rendre ta maison semblable à la maison de Pérets, qui fut enfanté à Juda par Tamar!"],[4,13,"Boaz prit Ruth, qui devint sa femme, et il alla vers elle. L'Éternel permit à Ruth de concevoir, et elle enfanta un fils.","Boaz prit Ruth, qui devint sa femme, et il alla vers elle. L'Éternel permit à Ruth de concevoir, et elle enfanta un fils."],[4,14,"Les femmes dirent à Naomi: Béni soit l'Éternel, qui ne t'a point laissé manquer aujourd'hui d'un homme ayant droit de rachat, et dont le nom sera célébré en Israël!","Les femmes dirent à Naomi: Béni soit l'Éternel, qui ne t'a point laissé manquer aujourd'hui d'un homme ayant droit de rachat, et dont le nom sera célébré en Israël!"],[4,15,"Cet enfant restaurera ton âme, et sera le soutien de ta vieillesse; car ta belle-fille, qui t'aime, l'a enfanté, elle qui vaut mieux pour toi que sept fils.","Cet enfant restaurera ton âme, et sera le soutien de ta vieillesse; car ta belle-fille, qui t'aime, l'a enfanté, elle qui vaut mieux pour toi que sept fils."],[4,16,"Naomi prit l'enfant et le mit sur son sein, et elle fut sa garde.","Naomi prit l'enfant et le mit sur son sein, et elle fut sa garde."],[4,17,"Les voisines lui donnèrent un nom, en disant: Un fils est né à Naomi! Et elles l'appelèrent Obed. Ce fut le père d'Isaï père de David.","Les voisines lui donnèrent un nom, en disant: Un fils est né à Naomi! Et elles l'appelèrent Obed. Ce fut le père d'Isaï père de David."],[4,18,"Voici la postérité de Pérets. Pérets engendra Hetsron;","Voici la postérité de Pérets. Pérets engendra Hetsron;"],[4,19,"Hetsron engendra Ram; Ram engendra Amminadab;","Hetsron engendra Ram; Ram engendra Amminadab;"],[4,20,"Amminadab engendra Nachschon; Nachschon engendra Salmon;","Amminadab engendra Nachschon; Nachschon engendra Salmon;"],[4,21,"Salmon engendra Boaz; Boaz engendra Obed;","Salmon engendra Boaz; Boaz engendra Obed;"],[4,22,"Obed engendra Isaï; et Isaï engendra David.","Obed engendra Isaï; et Isaï engendra David."]],"spa-rv1909":[[1,1,"Y ACONTECIÓen los díasque gobernabanlos jueces, que hubohambreen la tierra. Y un varónde Beth-lehemde Judá, fuéá peregrinaren los camposde Moab, ély sumujer, y doshijossuyos.","Y ACONTECIÓen los díasque gobernabanlos jueces, que hubohambreen la tierra. Y un varónde Beth-lehemde Judá, fuéá peregrinaren los camposde Moab, ély sumujer, y doshijossuyos."],[1,2,"El nombrede aquel varónera Elimelech, y el de su mujerNoemi; y los nombresde sus dos hijoseran, Mahalóny Chelión, Ephrateosde Beth-lehemde Judá. Llegaronpues á los camposde Moab, y asentaron allí.","El nombrede aquel varónera Elimelech, y el de su mujerNoemi; y los nombresde sus dos hijoseran, Mahalóny Chelión, Ephrateosde Beth-lehemde Judá. Llegaronpues á los camposde Moab, y asentaron allí."],[1,3,"Y murióElimelech, maridode Noemi, y quedóellacon susdoshijos;","Y murióElimelech, maridode Noemi, y quedóellacon susdoshijos;"],[1,4,"Los cuales tomaronpara sí mujeresde Moab, el nombrede la una Orpha, y el nombrede la otraRuth; y habitaronallíunos diezaños.","Los cuales tomaronpara sí mujeresde Moab, el nombrede la una Orpha, y el nombrede la otraRuth; y habitaronallíunos diezaños."],[1,5,"Y murierontambiénlos dos, Mahalóny Chelión, quedandoasí la mujerdesamparadade sus doshijosy de su marido.","Y murierontambiénlos dos, Mahalóny Chelión, quedandoasí la mujerdesamparadade sus doshijosy de su marido."],[1,6,"Entonces se levantócon susnueras, y volviósede los camposde Moab: porqueoyóen el campode MoabqueJehováhabía visitadoá supueblopara darlespan.","Entonces se levantócon susnueras, y volviósede los camposde Moab: porqueoyóen el campode MoabqueJehováhabía visitadoá supueblopara darlespan."],[1,7,"Saliópues dellugardondehabía estado, y conella sus dosnueras, y comenzaron á caminarpara volverseá la tierrade Judá.","Saliópues dellugardondehabía estado, y conella sus dosnueras, y comenzaron á caminarpara volverseá la tierrade Judá."],[1,8,"Y Noemidijoá sus dosnueras: Andad, volveoscada unaá la casade su madre: Jehováhagaconvosotras misericordia, como la habéis hechoconlos muertosy conmigo.","Y Noemidijoá sus dosnueras: Andad, volveoscada unaá la casade su madre: Jehováhagaconvosotras misericordia, como la habéis hechoconlos muertosy conmigo."],[1,9,"Déos Jehováque halléisdescanso, cada unaen casade su marido: besólasluego, y ellas lloraroná vozen grito.","Déos Jehováque halléisdescanso, cada unaen casade su marido: besólasluego, y ellas lloraroná vozen grito."],[1,10,"Y dijéronle: Ciertamentenosotras volveremos contigoá tupueblo.","Y dijéronle: Ciertamentenosotras volveremos contigoá tupueblo."],[1,11,"Y Noemirespondió: Volveos, hijasmías: ¿para quéhabéis de irconmigo? ¿tengo yo máshijosen el vientre, que puedan servuestros maridos?","Y Noemirespondió: Volveos, hijasmías: ¿para quéhabéis de irconmigo? ¿tengo yo máshijosen el vientre, que puedan servuestros maridos?"],[1,12,"Volveos, hijasmías, éidos; queyo ya soy viejapara ser para varón. Y aunquedijese: Esperanzatengo; y estanochefuese con varón, y aunpariese hijos;","Volveos, hijasmías, éidos; queyo ya soy viejapara ser para varón. Y aunquedijese: Esperanzatengo; y estanochefuese con varón, y aunpariese hijos;"],[1,13,"¿Habíais vosotrasde esperarloshastaquefuesen grandes? ¿habías vosotras de quedarossin casarpor amor de ellos? No, hijasmías; quemayoramarguratengo yo quevosotras, puesla manode Jehováha salidocontra mí.","¿Habíais vosotrasde esperarloshastaquefuesen grandes? ¿habías vosotras de quedarossin casarpor amor de ellos? No, hijasmías; quemayoramarguratengo yo quevosotras, puesla manode Jehováha salidocontra mí."],[1,14,"Mas ellas alzando otravez su voz, lloraron: y Orphabesóá su suegra, mas Ruthse quedócon ella.","Mas ellas alzando otravez su voz, lloraron: y Orphabesóá su suegra, mas Ruthse quedócon ella."],[1,15,"Y Noemidijo: He aquítu cuñadase ha vueltoá su puebloy á sus dioses; vuélvetetú trasella.","Y Noemidijo: He aquítu cuñadase ha vueltoá su puebloy á sus dioses; vuélvetetú trasella."],[1,16,"Y Ruthrespondió: Nome rueguesque te deje, y me apartede ti: porquedonde quiera que tú fueres, iréyo; y donde quiera quevivieres, viviré. Tu puebloserá mi pueblo, y tu Diosmi Dios.","Y Ruthrespondió: Nome rueguesque te deje, y me apartede ti: porquedonde quiera que tú fueres, iréyo; y donde quiera quevivieres, viviré. Tu puebloserá mi pueblo, y tu Diosmi Dios."],[1,17,"Dondetú murieres, moriréyo, y allíseré sepultada: asíme hagaJehová, y asíme dé, quesólo la muertehará separaciónentremí y ti.","Dondetú murieres, moriréyo, y allíseré sepultada: asíme hagaJehová, y asíme dé, quesólo la muertehará separaciónentremí y ti."],[1,18,"Y viendoNoemiqueestaba tan resueltaá irconella, dejó de hablarle.","Y viendoNoemiqueestaba tan resueltaá irconella, dejó de hablarle."],[1,19,"Anduvieronpues ellas doshastaque llegaroná Beth-lehem: y acontecióque entrando en Beth-lehem, todala ciudadse conmovióporrazón de ellas, y decían: ¿No es éstaNoemi?","Anduvieronpues ellas doshastaque llegaroná Beth-lehem: y acontecióque entrando en Beth-lehem, todala ciudadse conmovióporrazón de ellas, y decían: ¿No es éstaNoemi?"],[1,20,"Y ella lesrespondía: Nome llaméisNoemi, sino llamadmeMara: porqueen grandeamargurame ha puesto el Todopoderoso.","Y ella lesrespondía: Nome llaméisNoemi, sino llamadmeMara: porqueen grandeamargurame ha puesto el Todopoderoso."],[1,21,"Yome fuíllena, mas vacía meha vueltoJehová. ¿Por quémellamaréisNoemi, ya que Jehováha dado testimoniocontra mí, y el Todopoderosomeha afligido?","Yome fuíllena, mas vacía meha vueltoJehová. ¿Por quémellamaréisNoemi, ya que Jehováha dado testimoniocontra mí, y el Todopoderosomeha afligido?"],[1,22,"Así volvióNoemiy RuthMoabitasu nueraconella; volvióde los camposde Moab, y llegaroná Beth-lehemen el principiode la siegade las cebadas.","Así volvióNoemiy RuthMoabitasu nueraconella; volvióde los camposde Moab, y llegaroná Beth-lehemen el principiode la siegade las cebadas."],[2,1,"Y TENÍA Noemiun parientede su marido, varónpoderoso y de hecho, de la familiade Elimelech, el cual se llamabaBooz.","Y TENÍA Noemiun parientede su marido, varónpoderoso y de hecho, de la familiade Elimelech, el cual se llamabaBooz."],[2,2,"Y Ruthla Moabitadijoá Noemi: Ruégoteque me dejes iral campo, y cogeréespigasen posde aquelá cuyos ojoshallaregracia. Y ella le respondió: Ve, hijamía.","Y Ruthla Moabitadijoá Noemi: Ruégoteque me dejes iral campo, y cogeréespigasen posde aquelá cuyos ojoshallaregracia. Y ella le respondió: Ve, hijamía."],[2,3,"Fuépues, y llegando, espigóen el campoen posde los segadores: y aconteciópor ventura, que la suertedel campoera de Booz, el cualera de la parentelade Elimelech.","Fuépues, y llegando, espigóen el campoen posde los segadores: y aconteciópor ventura, que la suertedel campoera de Booz, el cualera de la parentelade Elimelech."],[2,4,"Y he aquíque Boozvinode Beth-lehem, y dijoá los segadores: Jehovásea convosotros. Y ellos respondieron: Jehováte bendiga.","Y he aquíque Boozvinode Beth-lehem, y dijoá los segadores: Jehovásea convosotros. Y ellos respondieron: Jehováte bendiga."],[2,5,"Y Boozdijoá su criadoel sobrestantedelos segadores: ¿Cúyaes esta moza?","Y Boozdijoá su criadoel sobrestantedelos segadores: ¿Cúyaes esta moza?"],[2,6,"Y el criado, sobrestantedelos segadores, respondióy dijo: Es la mozade Moab, que volvióconNoemide los camposde Moab;","Y el criado, sobrestantedelos segadores, respondióy dijo: Es la mozade Moab, que volvióconNoemide los camposde Moab;"],[2,7,"Y ha dicho: Ruégoteque me dejes cogery juntartraslos segadoresentre las gavillas: entrópues, y estádesdepor la mañanahastaahora, menos un pocoque se detuvoen casa.","Y ha dicho: Ruégoteque me dejes cogery juntartraslos segadoresentre las gavillas: entrópues, y estádesdepor la mañanahastaahora, menos un pocoque se detuvoen casa."],[2,8,"Entonces Boozdijoá Ruth: Oye, hijamía, novayasá espigará otrocampo, nipasesde aquí: y aquíestarásconmis mozas.","Entonces Boozdijoá Ruth: Oye, hijamía, novayasá espigará otrocampo, nipasesde aquí: y aquíestarásconmis mozas."],[2,9,"Mirabien al campoquesegaren, y síguelas: porque yo he mandadoá los mozosquenotetoquen. Y si tuvieres sed, veá los vasos, y bebedel aguaquesacarenlos mozos.","Mirabien al campoquesegaren, y síguelas: porque yo he mandadoá los mozosquenotetoquen. Y si tuvieres sed, veá los vasos, y bebedel aguaquesacarenlos mozos."],[2,10,"Ella entonces bajandosu rostroinclinóseá tierra, y díjole: ¿Por quéhe halladograciaen tus ojospara que tú me reconozcas, siendo yo extranjera?","Ella entonces bajandosu rostroinclinóseá tierra, y díjole: ¿Por quéhe halladograciaen tus ojospara que tú me reconozcas, siendo yo extranjera?"],[2,11,"Y respondiendoBooz, díjole: Por cierto se me ha declaradotodolo quehas hechocontusuegradespuésde la muertede tumarido, y quedejandoá tupadrey á tumadrey la tierradonde naciste, has venidoá puebloquenoconocisteantes.","Y respondiendoBooz, díjole: Por cierto se me ha declaradotodolo quehas hechocontusuegradespuésde la muertede tumarido, y quedejandoá tupadrey á tumadrey la tierradonde naciste, has venidoá puebloquenoconocisteantes."],[2,12,"Jehovágalardone tu obra, y tu remuneraciónseallenapor JehováDiosde Israel, que has venidopara cubrirte debajo de sus alas.","Jehovágalardone tu obra, y tu remuneraciónseallenapor JehováDiosde Israel, que has venidopara cubrirte debajo de sus alas."],[2,13,"Y ella dijo: Señormío, halleyo graciadelante de tus ojos; porqueme has consolado, y porquehas habladoalcorazónde tu sierva, nosiendo yo como unade tus criadas.","Y ella dijo: Señormío, halleyo graciadelante de tus ojos; porqueme has consolado, y porquehas habladoalcorazónde tu sierva, nosiendo yo como unade tus criadas."],[2,14,"Y Boozle dijoá la horade comer: Allégate aquí, y comedelpan, y mojatu bocadoen el vinagre. Y sentóseella juntoá los segadores, y él le diódelpotaje, y comióhasta que se hartó y le sobró.","Y Boozle dijoá la horade comer: Allégate aquí, y comedelpan, y mojatu bocadoen el vinagre. Y sentóseella juntoá los segadores, y él le diódelpotaje, y comióhasta que se hartó y le sobró."],[2,15,"Levantóseluego para espigar. Y Boozmandóá sus criados, diciendo: Coja tambiénespigas entrelas gavillas, y nola avergoncéis;","Levantóseluego para espigar. Y Boozmandóá sus criados, diciendo: Coja tambiénespigas entrelas gavillas, y nola avergoncéis;"],[2,16,"Antes echaréisá sabiendasdelos manojos, y la dejaréisque coja, y nola reprendáis.","Antes echaréisá sabiendasdelos manojos, y la dejaréisque coja, y nola reprendáis."],[2,17,"Y espigóen el campohastala tarde, y desgranólo quehabía cogido, y fuécomo un ephade cebada.","Y espigóen el campohastala tarde, y desgranólo quehabía cogido, y fuécomo un ephade cebada."],[2,18,"Y tomólo, y vínoseá la ciudad; y su suegraviólo quehabía cogido. Sacótambién luego lo quele había sobradodespués de harta, y dióselo.","Y tomólo, y vínoseá la ciudad; y su suegraviólo quehabía cogido. Sacótambién luego lo quele había sobradodespués de harta, y dióselo."],[2,19,"Y díjolesu suegra: ¿Dóndehas espigadohoy? ¿y dóndehas trabajado? benditoseael que teha reconocido. Y ella declaróá su suegralo que le había acontecidocon aquél, y dijo: El nombredel varónconquien hoyhe trabajadoes Booz.","Y díjolesu suegra: ¿Dóndehas espigadohoy? ¿y dóndehas trabajado? benditoseael que teha reconocido. Y ella declaróá su suegralo que le había acontecidocon aquél, y dijo: El nombredel varónconquien hoyhe trabajadoes Booz."],[2,20,"Y dijoNoemiá sunuera: Sea élbenditode Jehová, pues quenoha rehusadoá los vivosla benevolenciaque tuvo para con los finados. Díjoledespués Noemi: Nuestro parientees aquel varón, y de nuestros redentoreses.","Y dijoNoemiá sunuera: Sea élbenditode Jehová, pues quenoha rehusadoá los vivosla benevolenciaque tuvo para con los finados. Díjoledespués Noemi: Nuestro parientees aquel varón, y de nuestros redentoreses."],[2,21,"Y RuthMoabitadijo: A másde esto meha dicho: Júntateconmis criados, hastaquehayan acabadotodami siega.","Y RuthMoabitadijo: A másde esto meha dicho: Júntateconmis criados, hastaquehayan acabadotodami siega."],[2,22,"Y Noemirespondióá Ruthsu nuera: Mejores, hijamía, quesalgasconsus criadas, que noquete encuentrenen otrocampo.","Y Noemirespondióá Ruthsu nuera: Mejores, hijamía, quesalgasconsus criadas, que noquete encuentrenen otrocampo."],[2,23,"Estuvo pues juntacon las mozasde Boozespigando, hastaque la siegade las cebadasy la de los trigosfué acabada; mas con susuegrahabitó.","Estuvo pues juntacon las mozasde Boozespigando, hastaque la siegade las cebadasy la de los trigosfué acabada; mas con susuegrahabitó."],[3,1,"Y DÍJOLEsu suegraNoemi: Hijamía, ¿note tengo de buscardescanso, quete sea bueno?","Y DÍJOLEsu suegraNoemi: Hijamía, ¿note tengo de buscardescanso, quete sea bueno?"],[3,2,"¿Noes Booznuestropariente, concuyasmozastú has estado? He aquíque élavientaesta nochela parvade las cebadas.","¿Noes Booznuestropariente, concuyasmozastú has estado? He aquíque élavientaesta nochela parvade las cebadas."],[3,3,"Te lavaráspues, y te ungirás, y vistiéndotetus vestidos, pasarásá la era; mas note darás á conoceral varónhastaque él haya acabadode comery de beber.","Te lavaráspues, y te ungirás, y vistiéndotetus vestidos, pasarásá la era; mas note darás á conoceral varónhastaque él haya acabadode comery de beber."],[3,4,"Y cuando él se acostare, reparatú el lugardondeél se acostará, é irás, y descubriráslospies, y te acostarásallí; y élte dirálo quehayas de hacer.","Y cuando él se acostare, reparatú el lugardondeél se acostará, é irás, y descubriráslospies, y te acostarásallí; y élte dirálo quehayas de hacer."],[3,5,"Y le respondió: Harétodolo quetú me mandares.","Y le respondió: Harétodolo quetú me mandares."],[3,6,"Descendiópues á la era, é hizotodolo quesu suegrale había mandado.","Descendiópues á la era, é hizotodolo quesu suegrale había mandado."],[3,7,"Y como Boozhubo comidoy bebido, y su corazónestuvo contento, retiróse á dormirá un ladodel montón. Entonces ella vinocalladamente, y descubriólos pies, y acostóse.","Y como Boozhubo comidoy bebido, y su corazónestuvo contento, retiróse á dormirá un ladodel montón. Entonces ella vinocalladamente, y descubriólos pies, y acostóse."],[3,8,"Y aconteció, que á la media noche se estremecióaquel hombre, y palpó: y he aquí, la mujerque estaba acostadaá sus pies.","Y aconteció, que á la media noche se estremecióaquel hombre, y palpó: y he aquí, la mujerque estaba acostadaá sus pies."],[3,9,"Entonces él dijo: ¿Quiéneres? Y ella respondió: Yosoy Ruthtusierva: extiendeel bordede tu capasobretusierva, por cuantoeres pariente cercano.","Entonces él dijo: ¿Quiéneres? Y ella respondió: Yosoy Ruthtusierva: extiendeel bordede tu capasobretusierva, por cuantoeres pariente cercano."],[3,10,"Y él dijo: Benditaseas túde Jehová, hijamía; quehas hecho mejortupostreragracia quela primera, no yendotraslos mancebos, sean pobresó ricos.","Y él dijo: Benditaseas túde Jehová, hijamía; quehas hecho mejortupostreragracia quela primera, no yendotraslos mancebos, sean pobresó ricos."],[3,11,"Ahorapues, notemas, hijamía: yo harécontigo lo quetú dijeres, puesquetodala puerta de mi pueblosabequeeres mujervirtuosa.","Ahorapues, notemas, hijamía: yo harécontigo lo quetú dijeres, puesquetodala puerta de mi pueblosabequeeres mujervirtuosa."],[3,12,"Y ahora, aunquees ciertoque yosoy parientecercano, con todo esohayparientemás cercanoqueyo.","Y ahora, aunquees ciertoque yosoy parientecercano, con todo esohayparientemás cercanoqueyo."],[3,13,"Reposaesta noche, y cuando seade día, siél te redimiere, bien, redímate; mas siél note quisiereredimir, yote redimiré, viveJehová. Descansapues hastala mañana.","Reposaesta noche, y cuando seade día, siél te redimiere, bien, redímate; mas siél note quisiereredimir, yote redimiré, viveJehová. Descansapues hastala mañana."],[3,14,"Y después que reposóá sus pieshastala mañana, levantóse, antes que nadiepudiese conocerá otro. Y él dijo: Nose sepaquehaya venido mujerá la era.","Y después que reposóá sus pieshastala mañana, levantóse, antes que nadiepudiese conocerá otro. Y él dijo: Nose sepaquehaya venido mujerá la era."],[3,15,"Después le dijo: Llega el lienzo quetraes sobreti, y tende él. Y teniéndoloella, él midióseismedidasde cebada, y púsoselasá cuestas: y vínoseella á la ciudad.","Después le dijo: Llega el lienzo quetraes sobreti, y tende él. Y teniéndoloella, él midióseismedidasde cebada, y púsoselasá cuestas: y vínoseella á la ciudad."],[3,16,"Así quevino á su suegra, ésta le dijo: ¿Quépues, hijamía? Y declaróleella todolo quecon aquel varónle había acontecido.","Así quevino á su suegra, ésta le dijo: ¿Quépues, hijamía? Y declaróleella todolo quecon aquel varónle había acontecido."],[3,17,"Y dijo: Estasseismedidasde cebadame dió, diciéndome: Porque novayasvacía á tu suegra.","Y dijo: Estasseismedidasde cebadame dió, diciéndome: Porque novayasvacía á tu suegra."],[3,18,"Entonces Noemidijo: Reposa, hijamía, hastaquesepascómocae la cosa: porqueaquel hombrenopararáhastaquehoyconcluyael negocio.","Entonces Noemidijo: Reposa, hijamía, hastaquesepascómocae la cosa: porqueaquel hombrenopararáhastaquehoyconcluyael negocio."],[4,1,"Y BOOZsubióá la puertay sentóseallí: y he aquípasabaaquel parientedel cual había Boozhablado, y díjole: Eh, fulano, venacáy siéntate. Y él vino, y sentóse.","Y BOOZsubióá la puertay sentóseallí: y he aquípasabaaquel parientedel cual había Boozhablado, y díjole: Eh, fulano, venacáy siéntate. Y él vino, y sentóse."],[4,2,"Entonces él tomódiezvaronesde los ancianosde la ciudad, y dijo: Sentaosaquí. Y ellos se sentaron.","Entonces él tomódiezvaronesde los ancianosde la ciudad, y dijo: Sentaosaquí. Y ellos se sentaron."],[4,3,"Luego dijoal pariente: Noemi, que ha vueltodel campode Moab, vendeuna partede las tierrasquetuvo nuestrohermanoElimelech;","Luego dijoal pariente: Noemi, que ha vueltodel campode Moab, vendeuna partede las tierrasquetuvo nuestrohermanoElimelech;"],[4,4,"Y yodecidíhacértelo saber, y decirteque la tomesdelantede los que están aquí sentados, y delantedelos ancianosde mipueblo. Si hubieres de redimir, redime; y si noquisieresredimir, decláramelopara que yolo sepa: porque nohay otroque redimasinotú, y yodespuésde ti. Y él respondió: Yoredimiré.","Y yodecidíhacértelo saber, y decirteque la tomesdelantede los que están aquí sentados, y delantedelos ancianosde mipueblo. Si hubieres de redimir, redime; y si noquisieresredimir, decláramelopara que yolo sepa: porque nohay otroque redimasinotú, y yodespuésde ti. Y él respondió: Yoredimiré."],[4,5,"Entonces replicóBooz: El mismo díaque tomareslas tierrasde manode Noemi, has de tomar también á RuthMoabita, mujerdel difunto, para que suscites el nombredel muertosobresu posesión.","Entonces replicóBooz: El mismo díaque tomareslas tierrasde manode Noemi, has de tomar también á RuthMoabita, mujerdel difunto, para que suscites el nombredel muertosobresu posesión."],[4,6,"Y respondióel pariente: Nopuedoredimir por mi parte, porqueecharía á perder mi heredad: redimetúusando demi derecho, porqueyo nopodréredimir.","Y respondióel pariente: Nopuedoredimir por mi parte, porqueecharía á perder mi heredad: redimetúusando demi derecho, porqueyo nopodréredimir."],[4,7,"Había ya de largo tiempoesta costumbreen Israelen la redenciónó contrato, que para la confirmaciónde cualquiernegocio, el unose quitabael zapatoy lo dabaá su compañero: y este era el testimonioen Israel.","Había ya de largo tiempoesta costumbreen Israelen la redenciónó contrato, que para la confirmaciónde cualquiernegocio, el unose quitabael zapatoy lo dabaá su compañero: y este era el testimonioen Israel."],[4,8,"Entonces el parientedijoá Booz: Tómalotú. Y descalzó su zapato.","Entonces el parientedijoá Booz: Tómalotú. Y descalzó su zapato."],[4,9,"Y Boozdijoá los ancianosy á todoel pueblo: Vosotrossois hoytestigosde quetomo todas las cosas quefueron de Elimelech, y todolo quefué de Chelióny de Mahalón, de manode Noemi;","Y Boozdijoá los ancianosy á todoel pueblo: Vosotrossois hoytestigosde quetomo todas las cosas quefueron de Elimelech, y todolo quefué de Chelióny de Mahalón, de manode Noemi;"],[4,10,"Y que tambiéntomopor mi mujerá RuthMoabita, mujerde Mahalón, para suscitarel nombredel difuntosobresu heredad, para que el nombredel muerto nose borrede entresus hermanosy de la puertade su lugar. Vosotrossois hoytestigos.","Y que tambiéntomopor mi mujerá RuthMoabita, mujerde Mahalón, para suscitarel nombredel difuntosobresu heredad, para que el nombredel muerto nose borrede entresus hermanosy de la puertade su lugar. Vosotrossois hoytestigos."],[4,11,"Y dijerontodoslos del puebloqueestaban á la puertacon los ancianos: Testigossomos. Jehováhagaá la mujerqueentraentu casacomo á Rachêly á Lea, las cualesdos edificaronla casade Israel; y tú seas ilustreenEphrata, y tengas nombradíaenBeth-lehem;","Y dijerontodoslos del puebloqueestaban á la puertacon los ancianos: Testigossomos. Jehováhagaá la mujerqueentraentu casacomo á Rachêly á Lea, las cualesdos edificaronla casade Israel; y tú seas ilustreenEphrata, y tengas nombradíaenBeth-lehem;"],[4,12,"Y de la simientequeJehováte dieredeaquesta moza, seatu casacomo la casade Phares, al queparióThamará Judá.","Y de la simientequeJehováte dieredeaquesta moza, seatu casacomo la casade Phares, al queparióThamará Judá."],[4,13,"Boozpues tomóá Ruth, y ella fuésu mujer; y luego que entró á ella, Jehovále dióque concibiesey pariese un hijo.","Boozpues tomóá Ruth, y ella fuésu mujer; y luego que entró á ella, Jehovále dióque concibiesey pariese un hijo."],[4,14,"Y las mujeresdecíaná Noemi: Loadosea Jehová, quehizo quenote faltasehoypariente, cuyo nombreserá nombrado en Israel.","Y las mujeresdecíaná Noemi: Loadosea Jehová, quehizo quenote faltasehoypariente, cuyo nombreserá nombrado en Israel."],[4,15,"El cual serárestauradorde tu alma, y el que sustentarátuvejez; puesquetunuera, la cual teamay tevalemás que sietehijos, le ha parido.","El cual serárestauradorde tu alma, y el que sustentarátuvejez; puesquetunuera, la cual teamay tevalemás que sietehijos, le ha parido."],[4,16,"Y tomandoNoemiel hijo, púsoloen su regazo, y fuélesu ama.","Y tomandoNoemiel hijo, púsoloen su regazo, y fuélesu ama."],[4,17,"Y las vecinasdiciendo, A Noemiha nacidoun hijo, le pusieron nombre; y llamáronleObed. Este es padrede Isaí, padrede David.","Y las vecinasdiciendo, A Noemiha nacidoun hijo, le pusieron nombre; y llamáronleObed. Este es padrede Isaí, padrede David."],[4,18,"Y estasson las generacionesde Phares: Pharesengendróá Hesrón;","Y estasson las generacionesde Phares: Pharesengendróá Hesrón;"],[4,19,"Y Hesrónengendróá Ram, y Ramengendróá Aminadab;","Y Hesrónengendróá Ram, y Ramengendróá Aminadab;"],[4,20,"Y Aminadabengendróá Nahasón, y Nahasónengendróá Salmón;","Y Aminadabengendróá Nahasón, y Nahasónengendróá Salmón;"],[4,21,"Y Salmónengendróá Booz, y Boozengendróá Obed;","Y Salmónengendróá Booz, y Boozengendróá Obed;"],[4,22,"Y Obedengendróá Isaí, é Isaíengendróá David.","Y Obedengendróá Isaí, é Isaíengendróá David."]],"rus-synodal":[[1,1,"В те дни, когда управляли судьи, случился голод на земле. И пошел один человек из Вифлеема Иудейского со своею женою и двумя сыновьями своими жить на полях Моавитских.","V te dni, kogda upravlâli sudʹi, slučilsâ golod na zemle. I pošel odin čelovek iz Vifleema Iudejskogo so svoeû ženoû i dvumâ synovʹâmi svoimi žitʹ na polâh Moavitskih."],[1,2,"Имя человека того Елимелех, имя жены его Ноеминь, а имена двух сынов его Махлон и Хилеон; они были Ефрафяне из Вифлеема Иудейского. И пришли они на поля Моавитские и остались там.","Imâ čeloveka togo Elimeleh, imâ ženy ego Noeminʹ, a imena dvuh synov ego Mahlon i Hileon; oni byli Efrafâne iz Vifleema Iudejskogo. I prišli oni na polâ Moavitskie i ostalisʹ tam."],[1,3,"И умер Елимелех, муж Ноемини, и осталась она с двумя сыновьями своими.","I umer Elimeleh, muž Noemini, i ostalasʹ ona s dvumâ synovʹâmi svoimi."],[1,4,"Они взяли себе жен из Моавитянок, имя одной Орфа, а имя другой Руфь, и жили там около десяти лет.","Oni vzâli sebe žen iz Moavitânok, imâ odnoj Orfa, a imâ drugoj Rufʹ, i žili tam okolo desâti let."],[1,5,"Но потом и оба [сына ее], Махлон и Хилеон, умерли, и осталась та женщина после обоих своих сыновей и после мужа своего.","No potom i oba [syna ee], Mahlon i Hileon, umerli, i ostalasʹ ta ženŝina posle oboih svoih synovej i posle muža svoego."],[1,6,"И встала она со снохами своими и пошла обратно с полей Моавитских, ибо услышала на полях Моавитских, что Бог посетил народ Свой и дал им хлеб.","I vstala ona so snohami svoimi i pošla obratno s polej Moavitskih, ibo uslyšala na polâh Moavitskih, čto Bog posetil narod Svoj i dal im hleb."],[1,7,"И вышла она из того места, в котором жила, и обе снохи ее с нею. Когда они шли по дороге, возвращаясь в землю Иудейскую,","I vyšla ona iz togo mesta, v kotorom žila, i obe snohi ee s neû. Kogda oni šli po doroge, vozvraŝaâsʹ v zemlû Iudejskuû,"],[1,8,"Ноеминь сказала двум снохам своим: пойдите, возвратитесь каждая в дом матери своей; да сотворит Господь с вами милость, как вы поступали с умершими и со мною!","Noeminʹ skazala dvum snoham svoim: pojdite, vozvratitesʹ každaâ v dom materi svoej; da sotvorit Gospodʹ s vami milostʹ, kak vy postupali s umeršimi i so mnoû!"],[1,9,"Да даст вам Господь, чтобы вы нашли пристанище каждая в доме своего мужа! И поцеловала их. Но они подняли вопль и плакали","Da dast vam Gospodʹ, čtoby vy našli pristaniŝe každaâ v dome svoego muža! I pocelovala ih. No oni podnâli voplʹ i plakali"],[1,10,"и сказали: нет, мы с тобою возвратимся к народу твоему.","i skazali: net, my s toboû vozvratimsâ k narodu tvoemu."],[1,11,"Ноеминь же сказала: возвратитесь, дочери мои; зачем вам идти со мною? Разве еще есть у меня сыновья в моем чреве, которые были бы вам мужьями?","Noeminʹ že skazala: vozvratitesʹ, dočeri moi; začem vam idti so mnoû? Razve eŝe estʹ u menâ synovʹâ v moem čreve, kotorye byli by vam mužʹâmi?"],[1,12,"Возвратитесь, дочери мои, пойдите, ибо я уже стара, чтоб быть замужем. Да если б я и сказала: «есть мне еще надежда», и даже если бы я сию же ночь была с мужем и потом родила сыновей, –","Vozvratitesʹ, dočeri moi, pojdite, ibo â uže stara, čtob bytʹ zamužem. Da esli b â i skazala: «estʹ mne eŝe nadežda», i daže esli by â siû že nočʹ byla s mužem i potom rodila synovej, –"],[1,13,"то можно ли вам ждать, пока они выросли бы? можно ли вам медлить и не выходить замуж? Нет, дочери мои, я весьма сокрушаюсь о вас, ибо рука Господня постигла меня.","to možno li vam ždatʹ, poka oni vyrosli by? možno li vam medlitʹ i ne vyhoditʹ zamuž? Net, dočeri moi, â vesʹma sokrušaûsʹ o vas, ibo ruka Gospodnâ postigla menâ."],[1,14,"Они подняли вопль и опять стали плакать. И Орфа простилась со свекровью своею [и возвратилась к народу своему], а Руфь осталась с нею.","Oni podnâli voplʹ i opâtʹ stali plakatʹ. I Orfa prostilasʹ so svekrovʹû svoeû [i vozvratilasʹ k narodu svoemu], a Rufʹ ostalasʹ s neû."],[1,15,"[Ноеминь] сказала [Руфи]: вот, невестка твоя возвратилась к народу своему и к своим богам; возвратись и ты вслед за невесткою твоею.","[Noeminʹ] skazala [Rufi]: vot, nevestka tvoâ vozvratilasʹ k narodu svoemu i k svoim bogam; vozvratisʹ i ty vsled za nevestkoû tvoeû."],[1,16,"Но Руфь сказала: не принуждай меня оставить тебя и возвратиться от тебя; но куда ты пойдешь, туда и я пойду, и где ты жить будешь, там и я буду жить; народ твой будет моим народом, и твой Бог – моим Богом;","No Rufʹ skazala: ne prinuždaj menâ ostavitʹ tebâ i vozvratitʹsâ ot tebâ; no kuda ty pojdešʹ, tuda i â pojdu, i gde ty žitʹ budešʹ, tam i â budu žitʹ; narod tvoj budet moim narodom, i tvoj Bog – moim Bogom;"],[1,17,"и где ты умрешь, там и я умру и погребена буду; пусть то и то сделает мне Господь, и еще больше сделает; смерть одна разлучит меня с тобою.","i gde ty umrešʹ, tam i â umru i pogrebena budu; pustʹ to i to sdelaet mne Gospodʹ, i eŝe bolʹše sdelaet; smertʹ odna razlučit menâ s toboû."],[1,18,"[Ноеминь,] видя, что она твердо решилась идти с нею, перестала уговаривать ее.","[Noeminʹ,] vidâ, čto ona tverdo rešilasʹ idti s neû, perestala ugovarivatʹ ee."],[1,19,"И шли обе они, доколе не пришли в Вифлеем. Когда пришли они в Вифлеем, весь город пришел в движение от них, и говорили: это Ноеминь?","I šli obe oni, dokole ne prišli v Vifleem. Kogda prišli oni v Vifleem, vesʹ gorod prišel v dviženie ot nih, i govorili: éto Noeminʹ?"],[1,20,"Она сказала им: не называйте меня Ноеминью, а называйте меня Марою, потому что Вседержитель послал мне великую горесть;","Ona skazala im: ne nazyvajte menâ Noeminʹû, a nazyvajte menâ Maroû, potomu čto Vsederžitelʹ poslal mne velikuû gorestʹ;"],[1,21,"я вышла отсюда с достатком, а возвратил меня Господь с пустыми руками; зачем называть меня Ноеминью, когда Господь заставил меня страдать, и Вседержитель послал мне несчастье?","â vyšla otsûda s dostatkom, a vozvratil menâ Gospodʹ s pustymi rukami; začem nazyvatʹ menâ Noeminʹû, kogda Gospodʹ zastavil menâ stradatʹ, i Vsederžitelʹ poslal mne nesčastʹe?"],[1,22,"И возвратилась Ноеминь, и с нею сноха ее Руфь Моавитянка, пришедшая с полей Моавитских, и пришли они в Вифлеем в начале жатвы ячменя.","I vozvratilasʹ Noeminʹ, i s neû snoha ee Rufʹ Moavitânka, prišedšaâ s polej Moavitskih, i prišli oni v Vifleem v načale žatvy âčmenâ."],[2,1,"У Ноемини был родственник по мужу ее, человек весьма знатный, из племени Елимелехова, имя ему Вооз.","U Noemini byl rodstvennik po mužu ee, čelovek vesʹma znatnyj, iz plemeni Elimelehova, imâ emu Vooz."],[2,2,"И сказала Руфь Моавитянка Ноемини: пойду я на поле и буду подбирать колосья по следам того, у кого найду благоволение. Она сказала ей: пойди, дочь моя.","I skazala Rufʹ Moavitânka Noemini: pojdu â na pole i budu podbiratʹ kolosʹâ po sledam togo, u kogo najdu blagovolenie. Ona skazala ej: pojdi, dočʹ moâ."],[2,3,"Она пошла, и пришла, и подбирала в поле колосья позади жнецов. И случилось, что та часть поля принадлежала Воозу, который из племени Елимелехова.","Ona pošla, i prišla, i podbirala v pole kolosʹâ pozadi žnecov. I slučilosʹ, čto ta častʹ polâ prinadležala Voozu, kotoryj iz plemeni Elimelehova."],[2,4,"И вот, Вооз пришел из Вифлеема и сказал жнецам: Господь с вами! Они сказали ему: да благословит тебя Господь!","I vot, Vooz prišel iz Vifleema i skazal žnecam: Gospodʹ s vami! Oni skazali emu: da blagoslovit tebâ Gospodʹ!"],[2,5,"И сказал Вооз слуге своему, приставленному к жнецам: чья это молодая женщина?","I skazal Vooz sluge svoemu, pristavlennomu k žnecam: čʹâ éto molodaâ ženŝina?"],[2,6,"Слуга, приставленный к жнецам, отвечал и сказал: эта молодая женщина – Моавитянка, пришедшая с Ноеминью с полей Моавитских;","Sluga, pristavlennyj k žnecam, otvečal i skazal: éta molodaâ ženŝina – Moavitânka, prišedšaâ s Noeminʹû s polej Moavitskih;"],[2,7,"она сказала: «буду я подбирать и собирать между снопами позади жнецов»; и пришла, и находится здесь с самого утра доселе; мало бывает она дома.","ona skazala: «budu â podbiratʹ i sobiratʹ meždu snopami pozadi žnecov»; i prišla, i nahoditsâ zdesʹ s samogo utra dosele; malo byvaet ona doma."],[2,8,"И сказал Вооз Руфи: послушай, дочь моя, не ходи подбирать на другом поле и не переходи отсюда, но будь здесь с моими служанками;","I skazal Vooz Rufi: poslušaj, dočʹ moâ, ne hodi podbiratʹ na drugom pole i ne perehodi otsûda, no budʹ zdesʹ s moimi služankami;"],[2,9,"пусть в глазах твоих будет то поле, где они жнут, и ходи за ними; вот, я приказал слугам моим не трогать тебя; когда захочешь пить, иди к сосудам и пей, откуда черпают слуги мои.","pustʹ v glazah tvoih budet to pole, gde oni žnut, i hodi za nimi; vot, â prikazal slugam moim ne trogatʹ tebâ; kogda zahočešʹ pitʹ, idi k sosudam i pej, otkuda čerpaût slugi moi."],[2,10,"Она пала на лицо свое и поклонилась до земли и сказала ему: чем снискала я в глазах твоих милость, что ты принимаешь меня, хотя я и чужеземка?","Ona pala na lico svoe i poklonilasʹ do zemli i skazala emu: čem sniskala â v glazah tvoih milostʹ, čto ty prinimaešʹ menâ, hotâ â i čužezemka?"],[2,11,"Вооз отвечал и сказал ей: мне сказано все, что сделала ты для свекрови своей по смерти мужа твоего, что ты оставила твоего отца и твою мать и твою родину и пришла к народу, которого ты не знала вчера и третьего дня;","Vooz otvečal i skazal ej: mne skazano vse, čto sdelala ty dlâ svekrovi svoej po smerti muža tvoego, čto ty ostavila tvoego otca i tvoû matʹ i tvoû rodinu i prišla k narodu, kotorogo ty ne znala včera i tretʹego dnâ;"],[2,12,"да воздаст Господь за это дело твое, и да будет тебе полная награда от Господа, Бога Израилева, к Которому ты пришла, чтоб успокоиться под Его крылами!","da vozdast Gospodʹ za éto delo tvoe, i da budet tebe polnaâ nagrada ot Gospoda, Boga Izraileva, k Kotoromu ty prišla, čtob uspokoitʹsâ pod Ego krylami!"],[2,13,"Она сказала: да буду я в милости пред очами твоими, господин мой! Ты утешил меня и говорил по сердцу рабы твоей, между тем как я не стою ни одной из рабынь твоих.","Ona skazala: da budu â v milosti pred očami tvoimi, gospodin moj! Ty utešil menâ i govoril po serdcu raby tvoej, meždu tem kak â ne stoû ni odnoj iz rabynʹ tvoih."],[2,14,"И сказал ей Вооз: время обеда; приди сюда и ешь хлеб и обмакивай кусок твой в уксус. И села она возле жнецов. Он подал ей хлеба; она ела, наелась, и еще осталось.","I skazal ej Vooz: vremâ obeda; pridi sûda i ešʹ hleb i obmakivaj kusok tvoj v uksus. I sela ona vozle žnecov. On podal ej hleba; ona ela, naelasʹ, i eŝe ostalosʹ."],[2,15,"И встала, чтобы подбирать. Вооз дал приказ слугам своим, сказав: пусть подбирает она и между снопами, и не обижайте ее;","I vstala, čtoby podbiratʹ. Vooz dal prikaz slugam svoim, skazav: pustʹ podbiraet ona i meždu snopami, i ne obižajte ee;"],[2,16,"да и от снопов откидывайте ей и оставляйте, пусть она подбирает [и ест], и не браните ее.","da i ot snopov otkidyvajte ej i ostavlâjte, pustʹ ona podbiraet [i est], i ne branite ee."],[2,17,"Так подбирала она на поле до вечера и вымолотила собранное, и вышло около ефы ячменя.","Tak podbirala ona na pole do večera i vymolotila sobrannoe, i vyšlo okolo efy âčmenâ."],[2,18,"Взяв это, она пошла в город, и свекровь ее увидела, что она набрала. И вынула [Руфь из пазухи своей] и дала ей то, что оставила, наевшись сама.","Vzâv éto, ona pošla v gorod, i svekrovʹ ee uvidela, čto ona nabrala. I vynula [Rufʹ iz pazuhi svoej] i dala ej to, čto ostavila, naevšisʹ sama."],[2,19,"И сказала ей свекровь ее: где ты собирала сегодня и где работала? да будет благословен принявший тебя! [Руфь] объявила свекрови своей, у кого она работала, и сказала: человеку тому, у которого я сегодня работала, имя Вооз.","I skazala ej svekrovʹ ee: gde ty sobirala segodnâ i gde rabotala? da budet blagosloven prinâvšij tebâ! [Rufʹ] obʺâvila svekrovi svoej, u kogo ona rabotala, i skazala: čeloveku tomu, u kotorogo â segodnâ rabotala, imâ Vooz."],[2,20,"И сказала Ноеминь снохе своей: благословен он от Господа за то, что не лишил милости своей ни живых, ни мертвых! И сказала ей Ноеминь: человек этот близок к нам; он из наших родственников.","I skazala Noeminʹ snohe svoej: blagosloven on ot Gospoda za to, čto ne lišil milosti svoej ni živyh, ni mertvyh! I skazala ej Noeminʹ: čelovek étot blizok k nam; on iz naših rodstvennikov."],[2,21,"Руфь Моавитянка сказала [свекрови своей]: он даже сказал мне: «будь с моими служанками, доколе не докончат они жатвы моей».","Rufʹ Moavitânka skazala [svekrovi svoej]: on daže skazal mne: «budʹ s moimi služankami, dokole ne dokončat oni žatvy moej»."],[2,22,"И сказала Ноеминь снохе своей Руфи: хорошо, дочь моя, что ты будешь ходить со служанками его, и не будут оскорблять тебя на другом поле.","I skazala Noeminʹ snohe svoej Rufi: horošo, dočʹ moâ, čto ty budešʹ hoditʹ so služankami ego, i ne budut oskorblâtʹ tebâ na drugom pole."],[2,23,"Так была она со служанками Воозовыми и подбирала [колосья], доколе не кончилась жатва ячменя и жатва пшеницы, и жила у свекрови своей.","Tak byla ona so služankami Voozovymi i podbirala [kolosʹâ], dokole ne končilasʹ žatva âčmenâ i žatva pšenicy, i žila u svekrovi svoej."],[3,1,"И сказала ей Ноеминь, свекровь ее: дочь моя, не поискать ли тебе пристанища, чтобы тебе хорошо было?","I skazala ej Noeminʹ, svekrovʹ ee: dočʹ moâ, ne poiskatʹ li tebe pristaniŝa, čtoby tebe horošo bylo?"],[3,2,"Вот, Вооз, со служанками которого ты была, родственник наш; вот, он в эту ночь веет на гумне ячмень;","Vot, Vooz, so služankami kotorogo ty byla, rodstvennik naš; vot, on v étu nočʹ veet na gumne âčmenʹ;"],[3,3,"умойся, помажься, надень на себя [нарядные] одежды твои и пойди на гумно, но не показывайся ему, доколе не кончит есть и пить;","umojsâ, pomažʹsâ, nadenʹ na sebâ [narâdnye] odeždy tvoi i pojdi na gumno, no ne pokazyvajsâ emu, dokole ne končit estʹ i pitʹ;"],[3,4,"когда же он ляжет спать, узнай место, где он ляжет; тогда придешь и откроешь у ног его и ляжешь; он скажет тебе, что тебе делать.","kogda že on lâžet spatʹ, uznaj mesto, gde on lâžet; togda pridešʹ i otkroešʹ u nog ego i lâžešʹ; on skažet tebe, čto tebe delatʹ."],[3,5,"[Руфь] сказала ей: сделаю все, что ты сказала мне.","[Rufʹ] skazala ej: sdelaû vse, čto ty skazala mne."],[3,6,"И пошла на гумно и сделала все так, как приказывала ей свекровь ее.","I pošla na gumno i sdelala vse tak, kak prikazyvala ej svekrovʹ ee."],[3,7,"Вооз наелся и напился, и развеселил сердце свое, и пошел и лег спать подле скирда. И она пришла тихонько, открыла у ног его и легла.","Vooz naelsâ i napilsâ, i razveselil serdce svoe, i pošel i leg spatʹ podle skirda. I ona prišla tihonʹko, otkryla u nog ego i legla."],[3,8,"В полночь он содрогнулся, приподнялся, и вот, у ног его лежит женщина.","V polnočʹ on sodrognulsâ, pripodnâlsâ, i vot, u nog ego ležit ženŝina."],[3,9,"И сказал [ей Вооз]: кто ты? Она сказала: я Руфь, раба твоя, простри крыло твое на рабу твою, ибо ты родственник.","I skazal [ej Vooz]: kto ty? Ona skazala: â Rufʹ, raba tvoâ, prostri krylo tvoe na rabu tvoû, ibo ty rodstvennik."],[3,10,"[Вооз] сказал: благословенна ты от Господа [Бога], дочь моя! это последнее твое доброе дело сделала ты еще лучше прежнего, что ты не пошла искать молодых людей, ни бедных, ни богатых;","[Vooz] skazal: blagoslovenna ty ot Gospoda [Boga], dočʹ moâ! éto poslednee tvoe dobroe delo sdelala ty eŝe lučše prežnego, čto ty ne pošla iskatʹ molodyh lûdej, ni bednyh, ni bogatyh;"],[3,11,"итак, дочь моя, не бойся, я сделаю тебе все, что ты сказала; ибо у всех ворот народа моего знают, что ты женщина добродетельная;","itak, dočʹ moâ, ne bojsâ, â sdelaû tebe vse, čto ty skazala; ibo u vseh vorot naroda moego znaût, čto ty ženŝina dobrodetelʹnaâ;"],[3,12,"хотя и правда, что я родственник, но есть еще родственник ближе меня;","hotâ i pravda, čto â rodstvennik, no estʹ eŝe rodstvennik bliže menâ;"],[3,13,"переночуй эту ночь; завтра же, если он примет тебя, то хорошо, пусть примет; а если он не захочет принять тебя, то я приму; жив Господь! Спи до утра.","perenočuj étu nočʹ; zavtra že, esli on primet tebâ, to horošo, pustʹ primet; a esli on ne zahočet prinâtʹ tebâ, to â primu; živ Gospodʹ! Spi do utra."],[3,14,"И спала она у ног его до утра и встала прежде, нежели могли они распознать друг друга. И сказал Вооз: пусть не знают, что женщина приходила на гумно.","I spala ona u nog ego do utra i vstala prežde, neželi mogli oni raspoznatʹ drug druga. I skazal Vooz: pustʹ ne znaût, čto ženŝina prihodila na gumno."],[3,15,"И сказал ей: подай верхнюю одежду, которая на тебе, подержи ее. Она держала, и он отмерил [ей] шесть мер ячменя, и положил на нее, и пошел в город.","I skazal ej: podaj verhnûû odeždu, kotoraâ na tebe, poderži ee. Ona deržala, i on otmeril [ej] šestʹ mer âčmenâ, i položil na nee, i pošel v gorod."],[3,16,"А [Руфь] пришла к свекрови своей. Та сказала [ей]: что, дочь моя? Она пересказала ей все, что сделал ей человек тот.","A [Rufʹ] prišla k svekrovi svoej. Ta skazala [ej]: čto, dočʹ moâ? Ona pereskazala ej vse, čto sdelal ej čelovek tot."],[3,17,"И сказала [ей]: эти шесть мер ячменя он дал мне и сказал мне: «не ходи к свекрови своей с пустыми руками».","I skazala [ej]: éti šestʹ mer âčmenâ on dal mne i skazal mne: «ne hodi k svekrovi svoej s pustymi rukami»."],[3,18,"Та сказала: подожди, дочь моя, доколе не узнаешь, чем кончится дело; ибо человек тот не останется в покое, не кончив сегодня дела.","Ta skazala: podoždi, dočʹ moâ, dokole ne uznaešʹ, čem končitsâ delo; ibo čelovek tot ne ostanetsâ v pokoe, ne končiv segodnâ dela."],[4,1,"Вооз вышел к воротам и сидел там. И вот, идет мимо родственник, о котором говорил Вооз. И сказал ему [Вооз]: зайди сюда и сядь здесь. Тот зашел и сел.","Vooz vyšel k vorotam i sidel tam. I vot, idet mimo rodstvennik, o kotorom govoril Vooz. I skazal emu [Vooz]: zajdi sûda i sâdʹ zdesʹ. Tot zašel i sel."],[4,2,"[Вооз] взял десять человек из старейшин города и сказал: сядьте здесь. И они сели.","[Vooz] vzâl desâtʹ čelovek iz starejšin goroda i skazal: sâdʹte zdesʹ. I oni seli."],[4,3,"И сказал [Вооз] родственнику: Ноеминь, возвратившаяся с полей Моавитских, продает часть поля, принадлежащую брату нашему Елимелеху;","I skazal [Vooz] rodstvenniku: Noeminʹ, vozvrativšaâsâ s polej Moavitskih, prodaet častʹ polâ, prinadležaŝuû bratu našemu Elimelehu;"],[4,4,"я решился довести до ушей твоих и сказать: купи при сидящих здесь и при старейшинах народа моего; если хочешь выкупить, выкупай; а если не хочешь выкупить, скажи мне, и я буду знать; ибо кроме тебя некому выкупить; а по тебе я. Тот сказал: я выкупаю.","â rešilsâ dovesti do ušej tvoih i skazatʹ: kupi pri sidâŝih zdesʹ i pri starejšinah naroda moego; esli hočešʹ vykupitʹ, vykupaj; a esli ne hočešʹ vykupitʹ, skaži mne, i â budu znatʹ; ibo krome tebâ nekomu vykupitʹ; a po tebe â. Tot skazal: â vykupaû."],[4,5,"Вооз сказал: когда ты купишь поле у Ноемини, то должен купить и у Руфи Моавитянки, жены умершего, и должен взять ее в замужество, чтобы восстановить имя умершего в уделе его.","Vooz skazal: kogda ty kupišʹ pole u Noemini, to dolžen kupitʹ i u Rufi Moavitânki, ženy umeršego, i dolžen vzâtʹ ee v zamužestvo, čtoby vosstanovitʹ imâ umeršego v udele ego."],[4,6,"И сказал тот родственник: не могу я взять ее себе, чтобы не расстроить своего удела; прими ее ты, ибо я не могу принять.","I skazal tot rodstvennik: ne mogu â vzâtʹ ee sebe, čtoby ne rasstroitʹ svoego udela; primi ee ty, ibo â ne mogu prinâtʹ."],[4,7,"Прежде такой был обычай у Израиля при выкупе и при мене для подтверждения какого-либо дела: один снимал сапог свой и давал другому, [который принимал право родственника,] и это было свидетельством у Израиля.","Prežde takoj byl obyčaj u Izrailâ pri vykupe i pri mene dlâ podtverždeniâ kakogo-libo dela: odin snimal sapog svoj i daval drugomu, [kotoryj prinimal pravo rodstvennika,] i éto bylo svidetelʹstvom u Izrailâ."],[4,8,"И сказал тот родственник Воозу: купи себе. И снял сапог свой [и дал ему].","I skazal tot rodstvennik Voozu: kupi sebe. I snâl sapog svoj [i dal emu]."],[4,9,"И сказал Вооз старейшинам и всему народу: вы теперь свидетели тому, что я покупаю у Ноемини все Елимелехово и все Хилеоново и Махлоново;","I skazal Vooz starejšinam i vsemu narodu: vy teperʹ svideteli tomu, čto â pokupaû u Noemini vse Elimelehovo i vse Hileonovo i Mahlonovo;"],[4,10,"также и Руфь Моавитянку, жену Махлонову, беру себе в жену, чтоб оставить имя умершего в уделе его, и чтобы не исчезло имя умершего между братьями его и у ворот местопребывания его: вы сегодня свидетели тому.","takže i Rufʹ Moavitânku, ženu Mahlonovu, beru sebe v ženu, čtob ostavitʹ imâ umeršego v udele ego, i čtoby ne isčezlo imâ umeršego meždu bratʹâmi ego i u vorot mestoprebyvaniâ ego: vy segodnâ svideteli tomu."],[4,11,"И сказал весь народ, который при воротах, и старейшины: мы свидетели; да соделает Господь жену, входящую в дом твой, как Рахиль и как Лию, которые обе устроили дом Израилев; приобретай богатство в Ефрафе, и да славится имя твое в Вифлееме;","I skazal vesʹ narod, kotoryj pri vorotah, i starejšiny: my svideteli; da sodelaet Gospodʹ ženu, vhodâŝuû v dom tvoj, kak Rahilʹ i kak Liû, kotorye obe ustroili dom Izrailev; priobretaj bogatstvo v Efrafe, i da slavitsâ imâ tvoe v Vifleeme;"],[4,12,"и да будет дом твой, как дом Фареса, которого родила Фамарь Иуде, от того семени, которое даст тебе Господь от этой молодой женщины.","i da budet dom tvoj, kak dom Faresa, kotorogo rodila Famarʹ Iude, ot togo semeni, kotoroe dast tebe Gospodʹ ot étoj molodoj ženŝiny."],[4,13,"И взял Вооз Руфь, и она сделалась его женою. И вошел он к ней, и Господь дал ей беременность, и она родила сына.","I vzâl Vooz Rufʹ, i ona sdelalasʹ ego ženoû. I vošel on k nej, i Gospodʹ dal ej beremennostʹ, i ona rodila syna."],[4,14,"И говорили женщины Ноемини: благословен Господь, что Он не оставил тебя ныне без наследника! И да будет славно имя его в Израиле!","I govorili ženŝiny Noemini: blagosloven Gospodʹ, čto On ne ostavil tebâ nyne bez naslednika! I da budet slavno imâ ego v Izraile!"],[4,15,"Он будет тебе отрадою и питателем в старости твоей, ибо его родила сноха твоя, которая любит тебя, которая для тебя лучше семи сыновей.","On budet tebe otradoû i pitatelem v starosti tvoej, ibo ego rodila snoha tvoâ, kotoraâ lûbit tebâ, kotoraâ dlâ tebâ lučše semi synovej."],[4,16,"И взяла Ноеминь дитя сие, и носила его в объятиях своих, и была ему нянькою.","I vzâla Noeminʹ ditâ sie, i nosila ego v obʺâtiâh svoih, i byla emu nânʹkoû."],[4,17,"Соседки нарекли ему имя и говорили: «у Ноемини родился сын», и нарекли ему имя: Овид. Он отец Иессея, отца Давидова.","Sosedki narekli emu imâ i govorili: «u Noemini rodilsâ syn», i narekli emu imâ: Ovid. On otec Iesseâ, otca Davidova."],[4,18,"И вот род Фаресов: Фарес родил Есрома;","I vot rod Faresov: Fares rodil Esroma;"],[4,19,"Есром родил Арама; Арам родил Аминадава;","Esrom rodil Arama; Aram rodil Aminadava;"],[4,20,"Аминадав родил Наассона; Наассон родил Салмона;","Aminadav rodil Naassona; Naasson rodil Salmona;"],[4,21,"Салмон родил Вооза; Вооз родил Овида;","Salmon rodil Vooza; Vooz rodil Ovida;"],[4,22,"Овид родил Иессея; Иессей родил Давида.","Ovid rodil Iesseâ; Iessej rodil Davida."]],"cmn-cuv-hant":[[1,1,"當士師秉政的時候，國中遭遇饑荒。在 猶大的 伯利恆，有一個人帶着妻子和兩個兒子往 摩押地去寄居。","dāng shì shī bǐng zhèng de shí hòu， guó zhōng zāo yù jī huāng. zài yóu dà de bó lì héng， yǒu yī gè rén dài zhe qī zǐ hé liǎng gè ér zǐ wǎng mó yā de qù jì jū."],[1,2,"這人名叫 以利米勒，他的妻名叫 拿俄米；他兩個兒子，一個名叫 瑪倫，一個名叫 基連，都是 猶大 伯利恆的 以法他人。他們到了 摩押地，就住在那裏。","zhè rén míng jiào yǐ lì mǐ lēi， tā de qī míng jiào ná é mǐ； tā liǎng gè ér zǐ， yī gè míng jiào mǎ lún， yī gè míng jiào jī lián， dōu shì yóu dà bó lì héng de yǐ fǎ tā rén. tā men dào le mó yā de， jiù zhù zài nà lǐ."],[1,3,"後來 拿俄米的丈夫 以利米勒死了，剩下婦人和她兩個兒子。","hòu lái ná é mǐ de zhàng fū yǐ lì mǐ lēi sǐ le， shèng xià fù rén hé tā liǎng gè ér zǐ."],[1,4,"這兩個兒子娶了 摩押女子為妻，一個名叫 俄珥巴，一個名叫 路得，在那裏住了約有十年。","zhè liǎng gè ér zǐ qǔ le mó yā nǚ zǐ wèi qī， yī gè míng jiào é ěr bā， yī gè míng jiào lù dé， zài nà lǐ zhù le yuē yǒu shí nián."],[1,5,"瑪倫和 基連二人也死了，剩下 拿俄米，沒有丈夫，也沒有兒子。","mǎ lún hé jī lián èr rén yě sǐ le， shèng xià ná é mǐ， méi yǒu zhàng fū， yě méi yǒu ér zǐ."],[1,6,"她就與兩個兒婦起身，要從 摩押地歸回；因為她在 摩押地聽見耶和華眷顧自己的百姓，賜糧食與他們。","tā jiù yǔ liǎng gè ér fù qǐ shēn， yào cóng mó yā de guī huí； yīn wèi tā zài mó yā de tīng jiàn yé hé huá juàn gù zì jǐ de bǎi xìng， cì liáng shí yǔ tā men."],[1,7,"於是她和兩個兒婦起行離開所住的地方，要回 猶大地去。","yú shì tā hé liǎng gè ér fù qǐ xíng lí kāi suǒ zhù de de fāng， yào huí yóu dà de qù."],[1,8,"拿俄米對兩個兒婦說：「你們各人回娘家去吧。願耶和華恩待你們，像你們恩待已死的人與我一樣！","ná é mǐ duì liǎng gè ér fù shuō：‘nǐ men gè rén huí niáng jiā qù ba. yuàn yé hé huá ēn dài nǐ men， xiàng nǐ men ēn dài yǐ sǐ de rén yǔ wǒ yī yàng！"],[1,9,"願耶和華使你們各在新夫家中得平安！」於是 拿俄米與她們親嘴。她們就放聲而哭，","yuàn yé hé huá shǐ nǐ men gè zài xīn fū jiā zhōng dé píng ān！’ yú shì ná é mǐ yǔ tā men qīn zuǐ. tā men jiù fàng shēng ér kū，"],[1,10,"說：「不然，我們必與你一同回你本國去。」","shuō：‘bù rán， wǒ men bì yǔ nǐ yī tóng huí nǐ běn guó qù.’"],[1,11,"拿俄米說：「我女兒們哪，回去吧！為何要跟我去呢？我還能生子作你們的丈夫嗎？","ná é mǐ shuō：‘wǒ nǚ ér men nǎ， huí qù ba！ wèi hé yào gēn wǒ qù ne？ wǒ hái néng shēng zǐ zuò nǐ men de zhàng fū ma？"],[1,12,"我女兒們哪，回去吧！我年紀老邁，不能再有丈夫；即或說，我還有指望，今夜有丈夫可以生子，","wǒ nǚ ér men nǎ， huí qù ba！ wǒ nián jì lǎo mài， bù néng zài yǒu zhàng fū； jí huò shuō， wǒ hái yǒu zhǐ wàng， jīn yè yǒu zhàng fū kě yǐ shēng zǐ，"],[1,13,"你們豈能等着他們長大呢？你們豈能等着他們不嫁別人呢？我女兒們哪，不要這樣。我為你們的緣故甚是愁苦，因為耶和華伸手攻擊我。」","nǐ men qǐ néng děng zhe tā men zhǎng dà ne？ nǐ men qǐ néng děng zhe tā men bù jià bié rén ne？ wǒ nǚ ér men nǎ， bù yào zhè yàng. wǒ wèi nǐ men de yuán gù shèn shì chóu kǔ， yīn wèi yé hé huá shēn shǒu gōng jī wǒ.’"],[1,14,"兩個兒婦又放聲而哭， 俄珥巴與婆婆親嘴 而別，只是 路得捨不得 拿俄米。","liǎng gè ér fù yòu fàng shēng ér kū， é ěr bā yǔ pó pó qīn zuǐ ér bié， zhǐ shì lù dé shě bù dé ná é mǐ."],[1,15,"拿俄米說：「看哪，你嫂子已經回她本國和她 所拜的神那裏去了，你也跟着你嫂子回去吧！」","ná é mǐ shuō：‘kàn nǎ， nǐ sǎo zǐ yǐ jīng huí tā běn guó hé tā suǒ bài de shén nà lǐ qù le， nǐ yě gēn zhe nǐ sǎo zǐ huí qù ba！’"],[1,16,"路得說：「不要催我回去不跟隨你。你往哪裏去，我也往那裏去；你在哪裏住宿，我也在那裏住宿；你的國就是我的國，你的神就是我的神。","lù dé shuō：‘bù yào cuī wǒ huí qù bù gēn suí nǐ. nǐ wǎng nǎ lǐ qù， wǒ yě wǎng nà lǐ qù； nǐ zài nǎ lǐ zhù sù， wǒ yě zài nà lǐ zhù sù； nǐ de guó jiù shì wǒ de guó， nǐ de shén jiù shì wǒ de shén."],[1,17,"你在哪裏死，我也在那裏死，也葬在那裏。除非死能使你我相離！不然，願耶和華重重地降罰與我。」","nǐ zài nǎ lǐ sǐ， wǒ yě zài nà lǐ sǐ， yě zàng zài nà lǐ. chú fēi sǐ néng shǐ nǐ wǒ xiāng lí！ bù rán， yuàn yé hé huá zhòng zhòng de jiàng fá yǔ wǒ.’"],[1,18,"拿俄米見 路得定意要跟隨自己去，就不再勸她了。","ná é mǐ jiàn lù dé dìng yì yào gēn suí zì jǐ qù， jiù bù zài quàn tā le."],[1,19,"於是二人同行，來到 伯利恆。她們到了 伯利恆，合城的人就都驚訝。婦女們說：「這是 拿俄米嗎？」","yú shì èr rén tóng xíng， lái dào bó lì héng. tā men dào le bó lì héng， hé chéng de rén jiù dōu jīng yà. fù nǚ men shuō：‘zhè shì ná é mǐ ma？’"],[1,20,"拿俄米對她們說：「不要叫我 拿俄米，要叫我 瑪拉，因為全能者使我受了大苦。","ná é mǐ duì tā men shuō：‘bù yào jiào wǒ ná é mǐ， yào jiào wǒ mǎ lā， yīn wèi quán néng zhě shǐ wǒ shòu le dà kǔ."],[1,21,"我滿滿地出去，耶和華使我空空地回來。耶和華降禍與我；全能者使我受苦。既是這樣，你們為何還叫我 拿俄米呢？」","wǒ mǎn mǎn de chū qù， yé hé huá shǐ wǒ kōng kōng de huí lái. yé hé huá jiàng huò yǔ wǒ； quán néng zhě shǐ wǒ shòu kǔ. jì shì zhè yàng， nǐ men wèi hé hái jiào wǒ ná é mǐ ne？’"],[1,22,"拿俄米和她兒婦 摩押女子 路得，從 摩押地回來到 伯利恆，正是動手割大麥的時候。","ná é mǐ hé tā ér fù mó yā nǚ zǐ lù dé， cóng mó yā de huí lái dào bó lì héng， zhèng shì dòng shǒu gē dà mài de shí hòu."],[2,1,"拿俄米的丈夫 以利米勒的親族中，有一個人名叫 波阿斯，是個大財主。","ná é mǐ de zhàng fū yǐ lì mǐ lēi de qīn zú zhōng， yǒu yī gè rén míng jiào bō ā sī， shì gè dà cái zhǔ."],[2,2,"摩押女子 路得對 拿俄米說：「容我往田間去，我蒙誰的恩，就在誰的身後拾取麥穗。」 拿俄米說：「女兒啊，你只管去。」","mó yā nǚ zǐ lù dé duì ná é mǐ shuō：‘róng wǒ wǎng tián jiān qù， wǒ méng shuí de ēn， jiù zài shuí de shēn hòu shí qǔ mài suì.’ ná é mǐ shuō：‘nǚ ér a， nǐ zhǐ guǎn qù.’"],[2,3,"路得就去了，來到田間，在收割的人身後拾取麥穗。她恰巧到了 以利米勒本族的人 波阿斯那塊田裏。","lù dé jiù qù le， lái dào tián jiān， zài shōu gē de rén shēn hòu shí qǔ mài suì. tā qià qiǎo dào le yǐ lì mǐ lēi běn zú de rén bō ā sī nà kuài tián lǐ."],[2,4,"波阿斯正從 伯利恆來，對收割的人說：「願耶和華與你們同在！」他們回答說：「願耶和華賜福與你！」","bō ā sī zhèng cóng bó lì héng lái， duì shōu gē de rén shuō：‘yuàn yé hé huá yǔ nǐ men tóng zài！’ tā men huí dá shuō：‘yuàn yé hé huá cì fú yǔ nǐ！’"],[2,5,"波阿斯問監管收割的僕人說：「那是誰家的女子？」","bō ā sī wèn jiān guǎn shōu gē de pú rén shuō：‘nà shì shuí jiā de nǚ zǐ？’"],[2,6,"監管收割的僕人回答說：「是那 摩押女子，跟隨 拿俄米從 摩押地回來的。","jiān guǎn shōu gē de pú rén huí dá shuō：‘shì nà mó yā nǚ zǐ， gēn suí ná é mǐ cóng mó yā de huí lái de."],[2,7,"她說：『請你容我跟着收割的人拾取打捆剩下的麥穗。』她從早晨直到如今，除了在屋子裏坐一會兒，常在這裏。」","tā shuō：“qǐng nǐ róng wǒ gēn zhe shōu gē de rén shí qǔ dǎ kǔn shèng xià de mài suì.” tā cóng zǎo chén zhí dào rú jīn， chú le zài wū zǐ lǐ zuò yī huì ér， cháng zài zhè lǐ.’"],[2,8,"波阿斯對 路得說：「女兒啊，聽我說，不要往別人田裏拾取麥穗，也不要離開這裏，要常與我使女們在一處。","bō ā sī duì lù dé shuō：‘nǚ ér a， tīng wǒ shuō， bù yào wǎng bié rén tián lǐ shí qǔ mài suì， yě bù yào lí kāi zhè lǐ， yào cháng yǔ wǒ shǐ nǚ men zài yī chù."],[2,9,"我的僕人在那塊田收割，你就跟着他們去。我已經吩咐僕人不可欺負你；你若渴了，就可以到器皿那裏喝僕人打來的水。」","wǒ de pú rén zài nà kuài tián shōu gē， nǐ jiù gēn zhe tā men qù. wǒ yǐ jīng fēn fù pú rén bù kě qī fù nǐ； nǐ ruò kě le， jiù kě yǐ dào qì mǐn nà lǐ hē pú rén dǎ lái de shuǐ.’"],[2,10,"路得就俯伏在地叩拜，對他說：「我既是外邦人，怎麼蒙你的恩，這樣顧恤我呢？」","lù dé jiù fǔ fú zài de kòu bài， duì tā shuō：‘wǒ jì shì wài bāng rén， zěn me méng nǐ de ēn， zhè yàng gù xù wǒ ne？’"],[2,11,"波阿斯回答說：「自從你丈夫死後，凡你向婆婆所行的，並你離開父母和本地，到素不認識的民中，這些事人全都告訴我了。","bō ā sī huí dá shuō：‘zì cóng nǐ zhàng fū sǐ hòu， fán nǐ xiàng pó pó suǒ xíng de， bìng nǐ lí kāi fù mǔ hé běn de， dào sù bù rèn shí de mín zhōng， zhè xiē shì rén quán dōu gào sù wǒ le."],[2,12,"願耶和華照你所行的賞賜你。你來投靠耶和華－ 以色列神的翅膀下，願你滿得他的賞賜。」","yuàn yé hé huá zhào nǐ suǒ xíng de shǎng cì nǐ. nǐ lái tóu kào yé hé huá－ yǐ sè liè shén de chì bǎng xià， yuàn nǐ mǎn dé tā de shǎng cì.’"],[2,13,"路得說：「我主啊，願在你眼前蒙恩。我雖然不及你的一個使女，你還用慈愛的話安慰我的心。」","lù dé shuō：‘wǒ zhǔ a， yuàn zài nǐ yǎn qián méng ēn. wǒ suī rán bù jí nǐ de yī gè shǐ nǚ， nǐ hái yòng cí ài de huà ān wèi wǒ de xīn.’"],[2,14,"到了吃飯的時候， 波阿斯對 路得說：「你到這裏來吃餅，將餅蘸在醋裏。」 路得就在收割的人旁邊坐下；他們把烘了的穗子遞給她。她吃飽了，還有餘剩的。","dào le chī fàn de shí hòu， bō ā sī duì lù dé shuō：‘nǐ dào zhè lǐ lái chī bǐng， jiāng bǐng zhàn zài cù lǐ.’ lù dé jiù zài shōu gē de rén páng biān zuò xià； tā men bǎ hōng le de suì zǐ dì gěi tā. tā chī bǎo le， hái yǒu yú shèng de."],[2,15,"她起來又拾取麥穗， 波阿斯吩咐僕人說：「她就是在捆中拾取麥穗，也可以容她，不可羞辱她；","tā qǐ lái yòu shí qǔ mài suì， bō ā sī fēn fù pú rén shuō：‘tā jiù shì zài kǔn zhōng shí qǔ mài suì， yě kě yǐ róng tā， bù kě xiū rǔ tā；"],[2,16,"並要從捆裏抽出些來，留在地下任她拾取，不可叱嚇她。」","bìng yào cóng kǔn lǐ chōu chū xiē lái， liú zài de xià rèn tā shí qǔ， bù kě chì xià tā.’"],[2,17,"這樣， 路得在田間拾取麥穗，直到晚上，將所拾取的打了，約有一伊法大麥。","zhè yàng， lù dé zài tián jiān shí qǔ mài suì， zhí dào wǎn shàng， jiāng suǒ shí qǔ de dǎ le， yuē yǒu yī yī fǎ dà mài."],[2,18,"她就把所拾取的帶進城去給婆婆看，又把她吃飽了所剩的給了婆婆。","tā jiù bǎ suǒ shí qǔ de dài jìn chéng qù gěi pó pó kàn， yòu bǎ tā chī bǎo le suǒ shèng de gěi le pó pó."],[2,19,"婆婆問她說：「你今日在哪裏拾取麥穗，在哪裏做工呢？願那顧恤你的得福。」 路得就告訴婆婆說：「我今日在一個名叫 波阿斯的人那裏做工。」","pó pó wèn tā shuō：‘nǐ jīn rì zài nǎ lǐ shí qǔ mài suì， zài nǎ lǐ zuò gōng ne？ yuàn nà gù xù nǐ de dé fú.’ lù dé jiù gào sù pó pó shuō：‘wǒ jīn rì zài yī gè míng jiào bō ā sī de rén nà lǐ zuò gōng.’"],[2,20,"拿俄米對兒婦說：「願那人蒙耶和華賜福，因為他不斷地恩待活人死人。」 拿俄米又說：「那是我們本族的人，是一個至近的親屬。」","ná é mǐ duì ér fù shuō：‘yuàn nà rén méng yé hé huá cì fú， yīn wèi tā bù duàn de ēn dài huó rén sǐ rén.’ ná é mǐ yòu shuō：‘nà shì wǒ men běn zú de rén， shì yī gè zhì jìn de qīn shǔ.’"],[2,21,"摩押女子 路得說：「他對我說：『你要緊隨我的僕人 拾取麥穗，直等他們收完了我的莊稼。』」","mó yā nǚ zǐ lù dé shuō：‘tā duì wǒ shuō：“nǐ yào jǐn suí wǒ de pú rén shí qǔ mài suì， zhí děng tā men shōu wán le wǒ de zhuāng jià.”’"],[2,22,"拿俄米對兒婦 路得說：「女兒啊，你跟着他的使女出去，不叫人遇見你在別人田間，這才為好。」","ná é mǐ duì ér fù lù dé shuō：‘nǚ ér a， nǐ gēn zhe tā de shǐ nǚ chū qù， bù jiào rén yù jiàn nǐ zài bié rén tián jiān， zhè cái wèi hǎo.’"],[2,23,"於是 路得與 波阿斯的使女常在一處拾取麥穗，直到收完了大麥和小麥。 路得仍與婆婆同住。","yú shì lù dé yǔ bō ā sī de shǐ nǚ cháng zài yī chù shí qǔ mài suì， zhí dào shōu wán le dà mài hé xiǎo mài. lù dé réng yǔ pó pó tóng zhù."],[3,1,"路得的婆婆 拿俄米對她說：「女兒啊，我不當為你找個安身之處，使你享福嗎？","lù dé de pó pó ná é mǐ duì tā shuō：‘nǚ ér a， wǒ bù dāng wèi nǐ zhǎo gè ān shēn zhī chù， shǐ nǐ xiǎng fú ma？"],[3,2,"你與 波阿斯的使女常在一處， 波阿斯不是我們的親族嗎？他今夜在場上簸大麥；","nǐ yǔ bō ā sī de shǐ nǚ cháng zài yī chù， bō ā sī bù shì wǒ men de qīn zú ma？ tā jīn yè zài chǎng shàng bǒ dà mài；"],[3,3,"你要沐浴抹膏，換上衣服，下到場上，卻不要使那人認出你來。你等他吃喝完了，","nǐ yào mù yù mǒ gāo， huàn shàng yī fú， xià dào chǎng shàng， què bù yào shǐ nà rén rèn chū nǐ lái. nǐ děng tā chī hē wán le，"],[3,4,"到他睡的時候，你看準他睡的地方，就進去掀開他腳上的被，躺臥在那裏，他必告訴你所當做的事。」","dào tā shuì de shí hòu， nǐ kàn zhǔn tā shuì de de fāng， jiù jìn qù xiān kāi tā jiǎo shàng de bèi， tǎng wò zài nà lǐ， tā bì gào sù nǐ suǒ dāng zuò de shì.’"],[3,5,"路得說：「凡你所吩咐的，我必遵行。」","lù dé shuō：‘fán nǐ suǒ fēn fù de， wǒ bì zūn xíng.’"],[3,6,"路得就下到場上，照她婆婆所吩咐她的而行。","lù dé jiù xià dào chǎng shàng， zhào tā pó pó suǒ fēn fù tā de ér xíng."],[3,7,"波阿斯吃喝完了，心裏歡暢，就去睡在麥堆旁邊。 路得便悄悄地來掀開他腳上的被，躺臥在那裏。","bō ā sī chī hē wán le， xīn lǐ huān chàng， jiù qù shuì zài mài duī páng biān. lù dé biàn qiāo qiāo de lái xiān kāi tā jiǎo shàng de bèi， tǎng wò zài nà lǐ."],[3,8,"到了夜半，那人忽然驚醒，翻過身來，不料有女子躺在他的腳下。","dào le yè bàn， nà rén hū rán jīng xǐng， fān guò shēn lái， bù liào yǒu nǚ zǐ tǎng zài tā de jiǎo xià."],[3,9,"他就說：「你是誰？」回答說：「我是你的婢女 路得。求你用你的衣襟遮蓋我，因為你是我一個至近的親屬。」","tā jiù shuō：‘nǐ shì shuí？’ huí dá shuō：‘wǒ shì nǐ de bì nǚ lù dé. qiú nǐ yòng nǐ de yī jīn zhē gài wǒ， yīn wèi nǐ shì wǒ yī gè zhì jìn de qīn shǔ.’"],[3,10,"波阿斯說：「女兒啊，願你蒙耶和華賜福。你末後的恩比先前更大；因為少年人無論貧富，你都沒有跟從。","bō ā sī shuō：‘nǚ ér a， yuàn nǐ méng yé hé huá cì fú. nǐ mò hòu de ēn bǐ xiān qián gèng dà； yīn wèi shǎo nián rén wú lùn pín fù， nǐ dōu méi yǒu gēn cóng."],[3,11,"女兒啊，現在不要懼怕，凡你所說的，我必照着行；我本城的人都知道你是個賢德的女子。","nǚ ér a， xiàn zài bù yào jù pà， fán nǐ suǒ shuō de， wǒ bì zhào zhe xíng； wǒ běn chéng de rén dōu zhī dào nǐ shì gè xián dé de nǚ zǐ."],[3,12,"我實在是你一個至近的親屬，只是還有一個人比我更近。","wǒ shí zài shì nǐ yī gè zhì jìn de qīn shǔ， zhǐ shì hái yǒu yī gè rén bǐ wǒ gèng jìn."],[3,13,"你今夜在這裏住宿，明早他若肯為你盡親屬的本分，就由他吧！倘若不肯，我指着永生的耶和華起誓，我必為你盡了本分，你只管躺到天亮。」","nǐ jīn yè zài zhè lǐ zhù sù， míng zǎo tā ruò kěn wèi nǐ jǐn qīn shǔ de běn fēn， jiù yóu tā ba！ tǎng ruò bù kěn， wǒ zhǐ zhe yǒng shēng de yé hé huá qǐ shì， wǒ bì wèi nǐ jǐn le běn fēn， nǐ zhǐ guǎn tǎng dào tiān liàng.’"],[3,14,"路得便在他腳下躺到天快亮，人彼此不能辨認的時候就起來了。 波阿斯說：「不可使人知道有女子到場上來」；","lù dé biàn zài tā jiǎo xià tǎng dào tiān kuài liàng， rén bǐ cǐ bù néng biàn rèn de shí hòu jiù qǐ lái le. bō ā sī shuō：‘bù kě shǐ rén zhī dào yǒu nǚ zǐ dào chǎng shàng lái’；"],[3,15,"又對 路得說：「打開你所披的外衣。」她打開了， 波阿斯就撮了六 簸箕大麥，幫她扛在肩上，她便進城去了。","yòu duì lù dé shuō：‘dǎ kāi nǐ suǒ pī de wài yī.’ tā dǎ kāi le， bō ā sī jiù cuō le liù bǒ jī dà mài， bāng tā káng zài jiān shàng， tā biàn jìn chéng qù le."],[3,16,"路得回到婆婆那裏，婆婆說：「女兒啊，怎麼樣了？」 路得就將那人向她所行的述說了一遍，","lù dé huí dào pó pó nà lǐ， pó pó shuō：‘nǚ ér a， zěn me yàng le？’ lù dé jiù jiāng nà rén xiàng tā suǒ xíng de shù shuō le yī biàn，"],[3,17,"又說：「那人給了我六 簸箕大麥，對我說：『你不可空手回去見你的婆婆。』」","yòu shuō：‘nà rén gěi le wǒ liù bǒ jī dà mài， duì wǒ shuō：“nǐ bù kě kōng shǒu huí qù jiàn nǐ de pó pó.”’"],[3,18,"婆婆說：「女兒啊，你只管安坐等候，看這事怎樣成就，因為那人今日不辦成這事必不休息。」","pó pó shuō：‘nǚ ér a， nǐ zhǐ guǎn ān zuò děng hòu， kàn zhè shì zěn yàng chéng jiù， yīn wèi nà rén jīn rì bù bàn chéng zhè shì bì bù xiū xī.’"],[4,1,"波阿斯到了城門，坐在那裏，恰巧 波阿斯所說的那至近的親屬經過。 波阿斯說：「某人哪，你來坐在這裏。」他就來坐下。","bō ā sī dào le chéng mén， zuò zài nà lǐ， qià qiǎo bō ā sī suǒ shuō de nà zhì jìn de qīn shǔ jīng guò. bō ā sī shuō：‘mǒu rén nǎ， nǐ lái zuò zài zhè lǐ.’ tā jiù lái zuò xià."],[4,2,"波阿斯又從本城的長老中揀選了十人，對他們說：「請你們坐在這裏。」他們就都坐下。","bō ā sī yòu cóng běn chéng de zhǎng lǎo zhōng jiǎn xuǎn le shí rén， duì tā men shuō：‘qǐng nǐ men zuò zài zhè lǐ.’ tā men jiù dōu zuò xià."],[4,3,"波阿斯對那至近的親屬說：「從 摩押地回來的 拿俄米，現在要賣我們族兄 以利米勒的那塊地；","bō ā sī duì nà zhì jìn de qīn shǔ shuō：‘cóng mó yā de huí lái de ná é mǐ， xiàn zài yào mài wǒ men zú xiōng yǐ lì mǐ lēi de nà kuài de；"],[4,4,"我想當贖那塊地的是你，其次是我，以外再沒有別人了。你可以在這裏的人面前和我本國的長老面前說明，你若肯贖就贖，若不肯贖就告訴我。」那人回答說：「我肯贖。」","wǒ xiǎng dāng shú nà kuài de de shì nǐ， qí cì shì wǒ， yǐ wài zài méi yǒu bié rén le. nǐ kě yǐ zài zhè lǐ de rén miàn qián hé wǒ běn guó de zhǎng lǎo miàn qián shuō míng， nǐ ruò kěn shú jiù shú， ruò bù kěn shú jiù gào sù wǒ.’ nà rén huí dá shuō：‘wǒ kěn shú.’"],[4,5,"波阿斯說：「你從 拿俄米手中買這地的時候，也當娶死人的妻 摩押女子 路得，使死人在產業上存留他的名。」","bō ā sī shuō：‘nǐ cóng ná é mǐ shǒu zhōng mǎi zhè de de shí hòu， yě dāng qǔ sǐ rén de qī mó yā nǚ zǐ lù dé， shǐ sǐ rén zài chǎn yè shàng cún liú tā de míng.’"],[4,6,"那人說：「這樣我就不能贖了，恐怕於我的產業有礙。你可以贖我所當贖的，我不能贖了。」","nà rén shuō：‘zhè yàng wǒ jiù bù néng shú le， kǒng pà yú wǒ de chǎn yè yǒu ài. nǐ kě yǐ shú wǒ suǒ dāng shú de， wǒ bù néng shú le.’"],[4,7,"從前，在 以色列中要定奪甚麼事，或贖回，或交易，這人就脫鞋給那人。 以色列人都以此為證據。","cóng qián， zài yǐ sè liè zhōng yào dìng duó shèn me shì， huò shú huí， huò jiāo yì， zhè rén jiù tuō xié gěi nà rén. yǐ sè liè rén dōu yǐ cǐ wèi zhèng jù."],[4,8,"那人對 波阿斯說：「你自己買吧！」於是將鞋脫下來了。","nà rén duì bō ā sī shuō：‘nǐ zì jǐ mǎi ba！’ yú shì jiāng xié tuō xià lái le."],[4,9,"波阿斯對長老和眾民說：「你們今日作見證，凡屬 以利米勒和 基連、 瑪倫的，我都從 拿俄米手中置買了；","bō ā sī duì zhǎng lǎo hé zhòng mín shuō：‘nǐ men jīn rì zuò jiàn zhèng， fán shǔ yǐ lì mǐ lēi hé jī lián, mǎ lún de， wǒ dōu cóng ná é mǐ shǒu zhōng zhì mǎi le；"],[4,10,"又娶了 瑪倫的妻 摩押女子 路得為妻，好在死人的產業上存留他的名，免得他的名在本族本鄉滅沒。你們今日可以作見證。」","yòu qǔ le mǎ lún de qī mó yā nǚ zǐ lù dé wèi qī， hǎo zài sǐ rén de chǎn yè shàng cún liú tā de míng， miǎn dé tā de míng zài běn zú běn xiāng miè méi. nǐ men jīn rì kě yǐ zuò jiàn zhèng.’"],[4,11,"在城門坐着的眾民和長老都說：「我們作見證。願耶和華使進你家的這女子，像建立 以色列家的 拉結、 利亞二人一樣。又願你在 以法他得亨通，在 伯利恆得名聲。","zài chéng mén zuò zhe de zhòng mín hé zhǎng lǎo dōu shuō：‘wǒ men zuò jiàn zhèng. yuàn yé hé huá shǐ jìn nǐ jiā de zhè nǚ zǐ， xiàng jiàn lì yǐ sè liè jiā de lā jié, lì yà èr rén yī yàng. yòu yuàn nǐ zài yǐ fǎ tā dé hēng tōng， zài bó lì héng dé míng shēng."],[4,12,"願耶和華從這少年女子賜你後裔，使你的家像 她瑪從 猶大所生 法勒斯的家一般。」","yuàn yé hé huá cóng zhè shǎo nián nǚ zǐ cì nǐ hòu yì， shǐ nǐ de jiā xiàng tā mǎ cóng yóu dà suǒ shēng fǎ lēi sī de jiā yī bān.’"],[4,13,"於是， 波阿斯娶了 路得為妻，與她同房。耶和華使她懷孕生了一個兒子。","yú shì， bō ā sī qǔ le lù dé wèi qī， yǔ tā tóng fáng. yé hé huá shǐ tā huái yùn shēng le yī gè ér zǐ."],[4,14,"婦人們對 拿俄米說：「耶和華是應當稱頌的！因為今日沒有撇下你，使你無至近的親屬。願這孩子在 以色列中得名聲。","fù rén men duì ná é mǐ shuō：‘yé hé huá shì yīng dāng chēng sòng de！ yīn wèi jīn rì méi yǒu piē xià nǐ， shǐ nǐ wú zhì jìn de qīn shǔ. yuàn zhè hái zǐ zài yǐ sè liè zhōng dé míng shēng."],[4,15,"他必提起你的精神，奉養你的老，因為是愛慕你的那兒婦所生的。有這兒婦比有七個兒子還好！」","tā bì tí qǐ nǐ de jīng shén， fèng yǎng nǐ de lǎo， yīn wèi shì ài mù nǐ de nà ér fù suǒ shēng de. yǒu zhè ér fù bǐ yǒu qī gè ér zǐ hái hǎo！’"],[4,16,"拿俄米就把孩子抱在懷中，作他的養母。","ná é mǐ jiù bǎ hái zǐ bào zài huái zhōng， zuò tā de yǎng mǔ."],[4,17,"鄰舍的婦人說：「 拿俄米得孩子了！」就給孩子起名叫 俄備得。這 俄備得是 耶西的父， 耶西是 大衛的父。","lín shě de fù rén shuō：‘ ná é mǐ dé hái zǐ le！’ jiù gěi hái zǐ qǐ míng jiào é bèi dé. zhè é bèi dé shì yé xī de fù， yé xī shì dà wèi de fù."],[4,18,"法勒斯的後代記在下面： 法勒斯生 希斯崙；","fǎ lēi sī de hòu dài jì zài xià miàn： fǎ lēi sī shēng xī sī lún；"],[4,19,"希斯崙生 蘭； 蘭生 亞米拿達；","xī sī lún shēng lán； lán shēng yà mǐ ná dá；"],[4,20,"亞米拿達生 拿順； 拿順生 撒門；","yà mǐ ná dá shēng ná shùn； ná shùn shēng sā mén；"],[4,21,"撒門生 波阿斯； 波阿斯生 俄備得；","sā mén shēng bō ā sī； bō ā sī shēng é bèi dé；"],[4,22,"俄備得生 耶西； 耶西生 大衛。","é bèi dé shēng yé xī； yé xī shēng dà wèi."]],"arb-vandyck":[[1,1,"حَدَثَ فِي أَيَّامِ حُكْمِ ٱلْقُضَاةِ أَنَّهُ صَارَ جُوعٌ فِي ٱلْأَرْضِ، فَذَهَبَ رَجُلٌ مِنْ بَيْتِ لَحْمِ يَهُوذَا لِيَتَغَرَّبَ فِي بِلَادِ مُوآبَ هُوَ وَٱمْرَأَتُهُ وَٱبْنَاهُ.","ḥadatẖa fī ạảyãạmi ḥuk̊mi ٱl̊quḍāẗi ạảnãhu ṣāra jūʿuⁿ fī ٱl̊ạảr̊ḍi, fadẖahaba rajuluⁿ min̊ baẙti laḥ̊mi yahūdẖā līatagẖarãba fī bilādi mūậba hūa waٱm̊rāảtuhu waٱb̊nāhu."],[1,2,"وَٱسْمُ ٱلرَّجُلِ أَلِيمَالِكُ، وَٱسْمُ ٱمْرَأَتِهِ نُعْمِي، وَٱسْمَا ٱبْنَيْهِ مَحْلُونُ وَكِلْيُونُ، أَفْرَاتِيُّونَ مِنْ بَيْتِ لَحْمِ يَهُوذَا. فَأَتَوْا إِلَى بِلَادِ مُوآبَ وَكَانُوا هُنَاكَ.","waٱs̊mu ٱlrãjuli ạảlīmāliku, waٱs̊mu ٱm̊rāảtihi nuʿ̊mī, waٱs̊mā ٱb̊naẙhi maḥ̊lūnu wakil̊yūnu, ạảf̊rātīũwna min̊ baẙti laḥ̊mi yahūdẖā. fāảtaẘạ ại̹lay̱ bilādi mūậba wakānūạ hunāka."],[1,3,"وَمَاتَ أَلِيمَالِكُ رَجُلُ نُعْمِي، وَبَقِيَتْ هِيَ وَٱبْنَاهَا.","wamāta ạảlīmāliku rajulu nuʿ̊mī, wabaqīat̊ hīa waٱb̊nāhā."],[1,4,"فَأَخَذَا لَهُمَا ٱمْرَأَتَيْنِ مُوآبِيَّتَيْنِ، ٱسْمُ إِحْدَاهُمَا عُرْفَةُ وَٱسْمُ ٱلْأُخْرَى رَاعُوثُ. وَأَقَامَا هُنَاكَ نَحْوَ عَشَرِ سِنِينٍ.","fāảkẖadẖā lahumā ٱm̊rāảtaẙni mūậbīãtaẙni, ٱs̊mu ại̹ḥ̊dāhumā ʿur̊faẗu waٱs̊mu ٱl̊ạủkẖ̊ray̱ rāʿūtẖu. wāảqāmā hunāka naḥ̊wa ʿasẖari sinīniⁿ."],[1,5,"ثُمَّ مَاتَا كِلَاهُمَا مَحْلُونُ وَكِلْيُونُ، فَتُرِكَتِ ٱلْمَرْأَةُ مِنِ ٱبْنَيْهَا وَمِنْ رَجُلِهَا.","tẖumã mātā kilāhumā maḥ̊lūnu wakil̊yūnu, faturikati ٱl̊mar̊ạảẗu mini ٱb̊naẙhā wamin̊ rajulihā."],[1,6,"فَقَامَتْ هِيَ وَكَنَّتَاهَا وَرَجَعَتْ مِنْ بِلَادِ مُوآبَ، لِأَنَّهَا سَمِعَتْ فِي بِلَادِ مُوآبَ أَنَّ ٱلرَّبَّ قَدِ ٱفْتَقَدَ شَعْبَهُ لِيُعْطِيَهُمْ خُبْزًا.","faqāmat̊ hīa wakanãtāhā warajaʿat̊ min̊ bilādi mūậba, liạảnãhā samiʿat̊ fī bilādi mūậba ạảnã ٱlrãbã qadi ٱf̊taqada sẖaʿ̊bahu līuʿ̊ṭīahum̊ kẖub̊zaⁿạ."],[1,7,"وَخَرَجَتْ مِنَ ٱلْمَكَانِ ٱلَّذِي كَانَتْ فِيهِ وَكَنَّتَاهَا مَعَهَا، وَسِرْنَ فِي ٱلطَّرِيقِ لِلرُّجُوعِ إِلَى أَرْضِ يَهُوذَا.","wakẖarajat̊ mina ٱl̊makāni ٱlãdẖī kānat̊ fīhi wakanãtāhā maʿahā, wasir̊na fī ٱlṭãrīqi lilrũjūʿi ại̹lay̱ ạảr̊ḍi yahūdẖā."],[1,8,"فَقَالَتْ نُعْمِي لِكَنَّتَيْهَا: «ٱذْهَبَا ٱرْجِعَا كُلُّ وَاحِدَةٍ إِلَى بَيْتِ أُمِّهَا. وَلْيَصْنَعِ ٱلرَّبُّ مَعَكُمَا إِحْسَانًا كَمَا صَنَعْتُمَا بِٱلْمَوْتَى وَبِي.","faqālat̊ nuʿ̊mī likanãtaẙhā: «ٱdẖ̊habā ٱr̊jiʿā kulũ wāḥidaẗiⁿ ại̹lay̱ baẙti ạủmĩhā. wal̊yaṣ̊naʿi ٱlrãbũ maʿakumā ại̹ḥ̊sānaⁿạ kamā ṣanaʿ̊tumā biٱl̊maẘtay̱ wabī."],[1,9,"وَلْيُعْطِكُمَا ٱلرَّبُّ أَنْ تَجِدَا رَاحَةً كُلُّ وَاحِدَةٍ فِي بَيْتِ رَجُلِهَا». فَقَبَّلَتْهُمَا، وَرَفَعْنَ أَصْوَاتَهُنَّ وَبَكَيْنَ.","wal̊yuʿ̊ṭikumā ٱlrãbũ ạản̊ tajidā rāḥaẗaⁿ kulũ wāḥidaẗiⁿ fī baẙti rajulihā». faqabãlat̊humā, warafaʿ̊na ạảṣ̊wātahunã wabakaẙna."],[1,10,"فَقَالَتَا لَهَا: «إِنَّنَا نَرْجِعُ مَعَكِ إِلَى شَعْبِكِ».","faqālatā lahā: «ại̹nãnā nar̊jiʿu maʿaki ại̹lay̱ sẖaʿ̊biki»."],[1,11,"فَقَالَتْ نُعْمِي: «ٱرْجِعَا يَا بِنْتَيَّ. لِمَاذَا تَذْهَبَانِ مَعِي؟ هَلْ فِي أَحْشَائِي بَنُونَ بَعْدُ حَتَّى يَكُونُوا لَكُمَا رِجَالًا؟","faqālat̊ nuʿ̊mī: «ٱr̊jiʿā yā bin̊tayã. limādẖā tadẖ̊habāni maʿī? hal̊ fī ạảḥ̊sẖāyỉy banūna baʿ̊du ḥatãy̱ yakūnūạ lakumā rijālaⁿạ?"],[1,12,"اِرْجِعَا يَا بِنْتَيَّ وَٱذْهَبَا لِأَنِّي قَدْ شِخْتُ عَنْ أَنْ أَكُونَ لِرَجُلٍ. وَإِنْ قُلْتُ لِي رَجَاءٌ أَيْضًا بِأَنِّي أَصِيرُ هَذِهِ ٱللَّيْلَةَ لِرَجُلٍ وَأَلِدُ بَنِينَ أَيْضًا،","ạir̊jiʿā yā bin̊tayã waٱdẖ̊habā liạảnĩy qad̊ sẖikẖ̊tu ʿan̊ ạản̊ ạảkūna lirajuliⁿ. wāi̹n̊ qul̊tu lī rajāʾuⁿ ạảẙḍaⁿạ biạảnĩy ạảṣīru hadẖihi ٱllãẙlaẗa lirajuliⁿ wāảlidu banīna ạảẙḍaⁿạ,"],[1,13,"هَلْ تَصْبِرَانِ لَهُمْ حَتَّى يَكْبُرُوا؟ هَلْ تَنْحَجِزَانِ مِنْ أَجْلِهِمْ عَنْ أَنْ تَكُونَا لِرَجُلٍ؟ لَا يَا بِنْتَيَّ. فَإِنِّي مَغْمُومَةٌ جِدًّا مِنْ أَجْلِكُمَا لِأَنَّ يَدَ ٱلرَّبِّ قَدْ خَرَجَتْ عَلَيَّ».","hal̊ taṣ̊birāni lahum̊ ḥatãy̱ yak̊burūạ? hal̊ tan̊ḥajizāni min̊ ạảj̊lihim̊ ʿan̊ ạản̊ takūnā lirajuliⁿ? lā yā bin̊tayã. fāi̹nĩy magẖ̊mūmaẗuⁿ jidaⁿ̃ạ min̊ ạảj̊likumā liạảnã yada ٱlrãbĩ qad̊ kẖarajat̊ ʿalayã»."],[1,14,"ثُمَّ رَفَعْنَ أَصْوَاتَهُنَّ وَبَكَيْنَ أَيْضًا. فَقَبَّلَتْ عُرْفَةُ حَمَاتَهَا، وَأَمَّا رَاعُوثُ فَلَصِقَتْ بِهَا.","tẖumã rafaʿ̊na ạảṣ̊wātahunã wabakaẙna ạảẙḍaⁿạ. faqabãlat̊ ʿur̊faẗu ḥamātahā, wāảmãạ rāʿūtẖu falaṣiqat̊ bihā."],[1,15,"فَقَالَتْ: «هُوَذَا قَدْ رَجَعَتْ سِلْفَتُكِ إِلَى شَعْبِهَا وَآلِهَتِهَا. اِرْجِعِي أَنْتِ وَرَاءَ سِلْفَتِكِ».","faqālat̊: «hūadẖā qad̊ rajaʿat̊ sil̊fatuki ại̹lay̱ sẖaʿ̊bihā wā̂lihatihā. ạir̊jiʿī ạản̊ti warāʾa sil̊fatiki»."],[1,16,"فَقَالَتْ رَاعُوثُ: «لَا تُلِحِّي عَلَيَّ أَنْ أَتْرُكَكِ وَأَرْجِعَ عَنْكِ، لِأَنَّهُ حَيْثُمَا ذَهَبْتِ أَذْهَبُ وَحَيْثُمَا بِتِّ أَبِيتُ. شَعْبُكِ شَعْبِي وَإِلَهُكِ إِلَهِي.","faqālat̊ rāʿūtẖu: «lā tuliḥĩy ʿalayã ạản̊ ạảt̊rukaki wāảr̊jiʿa ʿan̊ki, liạảnãhu ḥaẙtẖumā dẖahab̊ti ạảdẖ̊habu waḥaẙtẖumā bitĩ ạảbītu. sẖaʿ̊buki sẖaʿ̊bī wāi̹lahuki ại̹lahī."],[1,17,"حَيْثُمَا مُتِّ أَمُوتُ وَهُنَاكَ أَنْدَفِنُ. هَكَذَا يَفْعَلُ ٱلرَّبُّ بِي وَهَكَذَا يَزِيدُ. إِنَّمَا ٱلْمَوْتُ يَفْصِلُ بَيْنِي وَبَيْنَكِ».","ḥaẙtẖumā mutĩ ạảmūtu wahunāka ạản̊dafinu. hakadẖā yaf̊ʿalu ٱlrãbũ bī wahakadẖā yazīdu. ại̹nãmā ٱl̊maẘtu yaf̊ṣilu baẙnī wabaẙnaki»."],[1,18,"فَلَمَّا رَأَتْ أَنَّهَا مُشَدِّدَةٌ عَلَى ٱلذَّهَابِ مَعَهَا، كَفَّتْ عَنِ ٱلْكَلَامِ إِلَيْهَا.","falamãạ rāảt̊ ạảnãhā musẖadĩdaẗuⁿ ʿalay̱ ٱldẖãhābi maʿahā, kafãt̊ ʿani ٱl̊kalāmi ại̹laẙhā."],[1,19,"فَذَهَبَتَا كِلْتَاهُمَا حَتَّى دَخَلَتَا بَيْتَ لَحْمٍ. وَكَانَ عِنْدَ دُخُولِهِمَا بَيْتَ لَحْمٍ أَنَّ ٱلْمَدِينَةَ كُلَّهَا تَحَرَّكَتْ بِسَبَبِهِمَا، وَقَالُوا: «أَهَذِهِ نُعْمِي؟»","fadẖahabatā kil̊tāhumā ḥatãy̱ dakẖalatā baẙta laḥ̊miⁿ. wakāna ʿin̊da dukẖūlihimā baẙta laḥ̊miⁿ ạảnã ٱl̊madīnaẗa kulãhā taḥarãkat̊ bisababihimā, waqālūạ: «ạảhadẖihi nuʿ̊mī?»"],[1,20,"فَقَالَتْ لَهُمْ: «لَا تَدْعُونِي نُعْمِيَ بَلِ ٱدْعُونِي مُرَّةَ، لِأَنَّ ٱلْقَدِيرَ قَدْ أَمَرَّنِي جِدًّا.","faqālat̊ lahum̊: «lā tad̊ʿūnī nuʿ̊mīa bali ٱd̊ʿūnī murãẗa, liạảnã ٱl̊qadīra qad̊ ạảmarãnī jidaⁿ̃ạ."],[1,21,"إِنِّي ذَهَبْتُ مُمْتَلِئَةً وَأَرْجَعَنِيَ ٱلرَّبُّ فَارِغَةً. لِمَاذَا تَدْعُونَنِي نُعْمِي، وَٱلرَّبُّ قَدْ أَذَلَّنِي وَٱلْقَدِيرُ قَدْ كَسَّرَنِي؟»","ại̹nĩy dẖahab̊tu mum̊talīảẗaⁿ wāảr̊jaʿanīa ٱlrãbũ fārigẖaẗaⁿ. limādẖā tad̊ʿūnanī nuʿ̊mī, waٱlrãbũ qad̊ ạảdẖalãnī waٱl̊qadīru qad̊ kasãranī?»"],[1,22,"فَرَجَعَتْ نُعْمِيَ وَرَاعُوثُ ٱلْمُوآبِيَّةُ كَنَّتُهَا مَعَهَا، ٱلَّتِي رَجَعَتْ مِنْ بِلَادِ مُوآبَ، وَدَخَلَتَا بَيْتَ لَحْمٍ فِي ٱبْتِدَاءِ حَصَادِ ٱلشَّعِيرِ.","farajaʿat̊ nuʿ̊mīa warāʿūtẖu ٱl̊mūậbīãẗu kanãtuhā maʿahā, ٱlãtī rajaʿat̊ min̊ bilādi mūậba, wadakẖalatā baẙta laḥ̊miⁿ fī ٱb̊tidāʾi ḥaṣādi ٱlsẖãʿīri."],[2,1,"وَكَانَ لِنُعْمِي ذُو قَرَابَةٍ لِرَجُلِهَا، جَبَّارُ بَأْسٍ مِنْ عَشِيرَةِ أَلِيمَالِكَ، ٱسْمُهُ بُوعَزُ.","wakāna linuʿ̊mī dẖū qarābaẗiⁿ lirajulihā, jabãạru bā̊̉siⁿ min̊ ʿasẖīraẗi ạảlīmālika, ٱs̊muhu būʿazu."],[2,2,"فَقَالَتْ رَاعُوثُ ٱلْمُوآبِيَّةُ لِنُعْمِي: «دَعِينِي أَذْهَبْ إِلَى ٱلْحَقْلِ وَأَلْتَقِطْ سَنَابِلَ وَرَاءَ مَنْ أَجِدُ نِعْمَةً فِي عَيْنَيْهِ». فَقَالَتْ لَهَا: «ٱذْهَبِي يَابِنْتِي».","faqālat̊ rāʿūtẖu ٱl̊mūậbīãẗu linuʿ̊mī: «daʿīnī ạảdẖ̊hab̊ ại̹lay̱ ٱl̊ḥaq̊li wāảl̊taqiṭ̊ sanābila warāʾa man̊ ạảjidu niʿ̊maẗaⁿ fī ʿaẙnaẙhi». faqālat̊ lahā: «ٱdẖ̊habī yābin̊tī»."],[2,3,"فَذَهَبَتْ وَجَاءَتْ وَٱلْتَقَطَتْ فِي ٱلْحَقْلِ وَرَاءَ ٱلْحَصَّادِينَ. فَٱتَّفَقَ نَصِيبُهَا فِي قِطْعَةِ حَقْلٍ لِبُوعَزَ ٱلَّذِي مِنْ عَشِيرَةِ أَلِيمَالِكَ.","fadẖahabat̊ wajāʾat̊ waٱl̊taqaṭat̊ fī ٱl̊ḥaq̊li warāʾa ٱl̊ḥaṣãạdīna. faٱtãfaqa naṣībuhā fī qiṭ̊ʿaẗi ḥaq̊liⁿ libūʿaza ٱlãdẖī min̊ ʿasẖīraẗi ạảlīmālika."],[2,4,"وَإِذَا بِبُوعَزَ قَدْ جَاءَ مِنْ بَيْتِ لَحْمٍ وَقَالَ لِلْحَصَّادِينَ: «ٱلرَّبُّ مَعَكُمْ». فَقَالُوا لَهُ: «يُبَارِكُكَ ٱلرَّبُّ».","wāi̹dẖā bibūʿaza qad̊ jāʾa min̊ baẙti laḥ̊miⁿ waqāla lil̊ḥaṣãạdīna: «ٱlrãbũ maʿakum̊». faqālūạ lahu: «yubārikuka ٱlrãbũ»."],[2,5,"فَقَالَ بُوعَزُ لِغُلَامِهِ ٱلْمُوَكَّلِ عَلَى ٱلْحَصَّادِينَ: «لِمَنْ هَذِهِ ٱلْفَتَاةُ؟»","faqāla būʿazu ligẖulāmihi ٱl̊mūakãli ʿalay̱ ٱl̊ḥaṣãạdīna: «liman̊ hadẖihi ٱl̊fatāẗu?»"],[2,6,"فَأَجَابَ ألْغُلَامُ المُوَكَّلُ عَلَى ٱلحَصَّادِينَ وَقَالَ: «هِيَ فَتَاةٌ مُوآبِيَّةٌ قَدْ رَجَعَتْ مَعَ نُعْمِي مِنْ بِلَادِ مُوآبَ،","fāảjāba ạ̉l̊gẖulāmu ạlmūakãlu ʿalay̱ ٱlḥaṣãạdīna waqāla: «hīa fatāẗuⁿ mūậbīãẗuⁿ qad̊ rajaʿat̊ maʿa nuʿ̊mī min̊ bilādi mūậba,"],[2,7,"وَقَالَتْ: دَعُونِي أَلْتَقِطْ وَأَجْمَعْ بَيْنَ ٱلْحُزَمِ وَرَاءَ ٱلْحَصَّادِينَ. فَجَاءَتْ وَمَكَثَتْ مِنَ ٱلصَّبَاحِ إِلَى ٱلْآنَ. قَلِيلًا مَّا لَبِثَتْ فِي ٱلْبَيْتِ».","waqālat̊: daʿūnī ạảl̊taqiṭ̊ wāảj̊maʿ̊ baẙna ٱl̊ḥuzami warāʾa ٱl̊ḥaṣãạdīna. fajāʾat̊ wamakatẖat̊ mina ٱlṣãbāḥi ại̹lay̱ ٱl̊ậna. qalīlaⁿạ mãạ labitẖat̊ fī ٱl̊baẙti»."],[2,8,"فَقَالَ بُوعَزُ لِرَاعُوثَ: «أَلَا تَسْمَعِينَ يَابِنْتِي؟ لَا تَذْهَبِي لِتَلْتَقِطِي فِي حَقْلِ آخَرَ، وَأَيْضًا لَا تَبْرَحِي مِنْ هَهُنَا، بَلْ هُنَا لَازِمِي فَتَيَاتِي.","faqāla būʿazu lirāʿūtẖa: «ạảlā tas̊maʿīna yābin̊tī? lā tadẖ̊habī lital̊taqiṭī fī ḥaq̊li ậkẖara, wāảẙḍaⁿạ lā tab̊raḥī min̊ hahunā, bal̊ hunā lāzimī fatayātī."],[2,9,"عَيْنَاكِ عَلَى ٱلْحَقْلِ ٱلَّذِي يَحْصُدُونَ وَٱذْهَبِي وَرَاءَهُمْ. أَلَمْ أُوصِ ٱلْغِلْمَانَ أَنْ لَا يَمَسُّوكِ؟ وَإِذَا عَطِشْتِ فَٱذْهَبِي إِلَى ٱلْآنِيَةِ وَٱشْرَبِي مِمَّا ٱسْتَقَاهُ ٱلْغِلْمَانُ».","ʿaẙnāki ʿalay̱ ٱl̊ḥaq̊li ٱlãdẖī yaḥ̊ṣudūna waٱdẖ̊habī warāʾahum̊. ạảlam̊ ạủwṣi ٱl̊gẖil̊māna ạản̊ lā yamasũwki? wāi̹dẖā ʿaṭisẖ̊ti faٱdẖ̊habī ại̹lay̱ ٱl̊ậnīaẗi waٱsẖ̊rabī mimãạ ٱs̊taqāhu ٱl̊gẖil̊mānu»."],[2,10,"فَسَقَطَتْ عَلَى وَجْهِهَا وَسَجَدَتْ إِلَى ٱلْأَرْضِ وَقَالَتْ لَهُ: «كَيْفَ وَجَدْتُ نِعْمَةً فِي عَيْنَيْكَ حَتَّى تَنْظُرَ إِلَيَّ وَأَنَا غَرِيبَةٌ؟»","fasaqaṭat̊ ʿalay̱ waj̊hihā wasajadat̊ ại̹lay̱ ٱl̊ạảr̊ḍi waqālat̊ lahu: «kaẙfa wajad̊tu niʿ̊maẗaⁿ fī ʿaẙnaẙka ḥatãy̱ tan̊ẓura ại̹layã wāảnā gẖarībaẗuⁿ?»"],[2,11,"فَأَجَابَ بُوعَزُ وَقَالَ لَهَا: «إِنَّنِي قَدْ أُخْبِرْتُ بِكُلِّ مَا فَعَلْتِ بِحَمَاتِكِ بَعْدَ مَوْتِ رَجُلِكِ، حَتَّى تَرَكْتِ أَبَاكِ وَأُمَّكِ وَأَرْضَ مَوْلِدِكِ وَسِرْتِ إِلَى شَعْبٍ لَمْ تَعْرِفِيهِ مِنْ قَبْلُ.","fāảjāba būʿazu waqāla lahā: «ại̹nãnī qad̊ ạủkẖ̊bir̊tu bikulĩ mā faʿal̊ti biḥamātiki baʿ̊da maẘti rajuliki, ḥatãy̱ tarak̊ti ạảbāki wāủmãki wāảr̊ḍa maẘlidiki wasir̊ti ại̹lay̱ sẖaʿ̊biⁿ lam̊ taʿ̊rifīhi min̊ qab̊lu."],[2,12,"لِيُكَافِئِ ٱلرَّبُّ عَمَلَكِ، وَلْيَكُنْ أَجْرُكِ كَامِلًا مِنْ عِنْدِ ٱلرَّبِّ إِلَهِ إِسْرَائِيلَ ٱلَّذِي جِئْتِ لِكَيْ تَحْتَمِيَ تَحْتَ جَنَاحَيْهِ».","līukāfīỉ ٱlrãbũ ʿamalaki, wal̊yakun̊ ạảj̊ruki kāmilaⁿạ min̊ ʿin̊di ٱlrãbĩ ại̹lahi ại̹s̊rāyỉyla ٱlãdẖī jī̊̉ti likaẙ taḥ̊tamīa taḥ̊ta janāḥaẙhi»."],[2,13,"فَقَالَتْ: «لَيْتَنِي أَجِدُ نِعْمَةً فِي عَيْنَيْكَ يَا سَيِّدِي لِأَنَّكَ قَدْ عَزَّيْتَنِي وَطَيَّبْتَ قَلْبَ جَارِيَتِكَ، وَأَنَا لَسْتُ كَوَاحِدَةٍ مِنْ جَوَارِيكَ».","faqālat̊: «laẙtanī ạảjidu niʿ̊maẗaⁿ fī ʿaẙnaẙka yā sayĩdī liạảnãka qad̊ ʿazãẙtanī waṭayãb̊ta qal̊ba jārīatika, wāảnā las̊tu kawāḥidaẗiⁿ min̊ jawārīka»."],[2,14,"فَقَالَ لَهَا بُوعَزُ: «عِنْدَ وَقْتِ ٱلْأَكْلِ تَقَدَّمِي إِلَى هَهُنَا وَكُلِي مِنَ ٱلْخُبْزِ، وَٱغْمِسِي لُقْمَتَكِ فِي ٱلْخَلِّ». فَجَلَسَتْ بِجَانِبِ ٱلْحَصَّادِينَ فَنَاوَلَهَا فَرِيكًا، فَأَكَلَتْ وَشَبِعَتْ وَفَضَلَ عَنْهَا.","faqāla lahā būʿazu: «ʿin̊da waq̊ti ٱl̊ạảk̊li taqadãmī ại̹lay̱ hahunā wakulī mina ٱl̊kẖub̊zi, waٱgẖ̊misī luq̊mataki fī ٱl̊kẖalĩ». fajalasat̊ bijānibi ٱl̊ḥaṣãạdīna fanāwalahā farīkaⁿạ, fāảkalat̊ wasẖabiʿat̊ wafaḍala ʿan̊hā."],[2,15,"ثُمَّ قَامَتْ لِتَلْتَقِطَ. فَأَمَرَ بُوعَزُ غِلْمَانَهُ قَائِلًا: «دَعُوهَا تَلْتَقِطْ بَيْنَ ٱلْحُزَمِ أَيْضًا وَلَا تُؤْذُوهَا.","tẖumã qāmat̊ lital̊taqiṭa. fāảmara būʿazu gẖil̊mānahu qāyỉlaⁿạ: «daʿūhā tal̊taqiṭ̊ baẙna ٱl̊ḥuzami ạảẙḍaⁿạ walā tū̊̉dẖūhā."],[2,16,"وَأَنْسِلُوا أَيْضًا لَهَا مِنَ ٱلشَّمَائِلِ وَدَعُوهَا تَلْتَقِطْ وَلَا تَنْتَهِرُوهَا».","wāản̊silūạ ạảẙḍaⁿạ lahā mina ٱlsẖãmāyỉli wadaʿūhā tal̊taqiṭ̊ walā tan̊tahirūhā»."],[2,17,"فَٱلْتَقَطَتْ فِي ٱلْحَقْلِ إِلَى ٱلْمَسَاءِ، وَخَبَطَتْ مَا ٱلْتَقَطَتْهُ فَكَانَ نَحْوَ إِيفَةِ شَعِيرٍ.","faٱl̊taqaṭat̊ fī ٱl̊ḥaq̊li ại̹lay̱ ٱl̊masāʾi, wakẖabaṭat̊ mā ٱl̊taqaṭat̊hu fakāna naḥ̊wa ại̹yfaẗi sẖaʿīriⁿ."],[2,18,"فَحَمَلَتْهُ وَدَخَلَتِ ٱلْمَدِينَةَ. فَرَأَتْ حَمَاتُهَا مَا ٱلْتَقَطَتْهُ. وَأَخْرَجَتْ وَأَعْطَتْهَا مَا فَضَلَ عَنْهَا بَعْدَ شِبَعِهَا.","faḥamalat̊hu wadakẖalati ٱl̊madīnaẗa. farāảt̊ ḥamātuhā mā ٱl̊taqaṭat̊hu. wāảkẖ̊rajat̊ wāảʿ̊ṭat̊hā mā faḍala ʿan̊hā baʿ̊da sẖibaʿihā."],[2,19,"فَقَالَتْ لَهَا حَمَاتُهَا: «أَيْنَ ٱلْتَقَطْتِ ٱلْيَوْمَ؟ وَأَيْنَ ٱشْتَغَلْتِ؟ لِيَكُنِ ٱلنَّاظِرُ إِلَيْكِ مُبَارَكًا». فَأَخْبَرَتْ حَمَاتَهَا بِٱلَّذِي ٱشْتَغَلَتْ مَعَهُ وَقَالَتِ: «ٱسْمُ ٱلرَّجُلِ ٱلَّذِي ٱشْتَغَلْتُ مَعَهُ ٱلْيَوْمَ بُوعَزُ».","faqālat̊ lahā ḥamātuhā: «ạảẙna ٱl̊taqaṭ̊ti ٱl̊yaẘma? wāảẙna ٱsẖ̊tagẖal̊ti? līakuni ٱlnãạẓiru ại̹laẙki mubārakaⁿạ». fāảkẖ̊barat̊ ḥamātahā biٱlãdẖī ٱsẖ̊tagẖalat̊ maʿahu waqālati: «ٱs̊mu ٱlrãjuli ٱlãdẖī ٱsẖ̊tagẖal̊tu maʿahu ٱl̊yaẘma būʿazu»."],[2,20,"فَقَالَتْ نُعْمِي لِكَنَّتِهَا: «مُبَارَكٌ هُوَ مِنَ ٱلرَّبِّ لِأَنَّهُ لَمْ يَتْرُكِ ٱلْمَعْرُوفَ مَعَ ٱلْأَحْيَاءِ وَٱلْمَوْتَى». ثُمَّ قَالَتْ لَهَا نُعْمِي: «ٱلرَّجُلُ ذُو قَرَابَةٍ لَنَا. هُوَ ثَانِي وَلِيِّنَا».","faqālat̊ nuʿ̊mī likanãtihā: «mubārakuⁿ hūa mina ٱlrãbĩ liạảnãhu lam̊ yat̊ruki ٱl̊maʿ̊rūfa maʿa ٱl̊ạảḥ̊yāʾi waٱl̊maẘtay̱». tẖumã qālat̊ lahā nuʿ̊mī: «ٱlrãjulu dẖū qarābaẗiⁿ lanā. hūa tẖānī walīĩnā»."],[2,21,"فَقَالَتْ رَاعُوثُ ٱلْمُوآبِيَّةُ: «إِنَّهُ قَالَ لِي أَيْضًا: لَازِمِي فِتْيَانِي حَتَّى يُكَمِّلُوا جَمِيعَ حَصَادِي».","faqālat̊ rāʿūtẖu ٱl̊mūậbīãẗu: «ại̹nãhu qāla lī ạảẙḍaⁿạ: lāzimī fit̊yānī ḥatãy̱ yukamĩlūạ jamīʿa ḥaṣādī»."],[2,22,"فَقَالَتْ نُعْمِي لِرَاعُوثَ كَنَّتِهَا: «إِنَّهُ حَسَنٌ يَابِنْتِي أَنْ تَخْرُجِي مَعَ فَتَيَاتِهِ حَتَّى لَا يَقَعُوا بِكِ فِي حَقْلِ آخَرَ».","faqālat̊ nuʿ̊mī lirāʿūtẖa kanãtihā: «ại̹nãhu ḥasanuⁿ yābin̊tī ạản̊ takẖ̊rujī maʿa fatayātihi ḥatãy̱ lā yaqaʿūạ biki fī ḥaq̊li ậkẖara»."],[2,23,"فَلَازَمَتْ فَتَيَاتِ بُوعَزَ فِي ٱلِٱلْتِقَاطِ حَتَّى ٱنْتَهَى حَصَادُ ٱلشَّعِيرِ وَحَصَادُ ٱلْحِنْطَةِ. وَسَكَنَتْ مَعَ حَمَاتِهَا.","falāzamat̊ fatayāti būʿaza fī ٱliٱl̊tiqāṭi ḥatãy̱ ٱn̊tahay̱ ḥaṣādu ٱlsẖãʿīri waḥaṣādu ٱl̊ḥin̊ṭaẗi. wasakanat̊ maʿa ḥamātihā."],[3,1,"وَقَالَتْ لَهَا نُعْمِي حَمَاتُهَا: «يَابِنْتِي أَلَا أَلْتَمِسُ لَكِ رَاحَةً لِيَكُونَ لَكِ خَيْرٌ؟","waqālat̊ lahā nuʿ̊mī ḥamātuhā: «yābin̊tī ạảlā ạảl̊tamisu laki rāḥaẗaⁿ līakūna laki kẖaẙruⁿ?"],[3,2,"فَٱلْآنَ أَلَيْسَ بُوعَزُ ذَا قَرَابَةٍ لَنَا، ٱلَّذِي كُنْتِ مَعَ فَتَيَاتِهِ؟ هَا هُوَ يُذَرِّي بَيْدَرَ ٱلشَّعِيرِ ٱللَّيْلَةَ.","faٱl̊ậna ạảlaẙsa būʿazu dẖā qarābaẗiⁿ lanā, ٱlãdẖī kun̊ti maʿa fatayātihi? hā hūa yudẖarĩy baẙdara ٱlsẖãʿīri ٱllãẙlaẗa."],[3,3,"فَٱغْتَسِلِي وَتَدَهَّنِي وَٱلْبَسِي ثِيَابَكِ وَٱنْزِلِي إِلَى ٱلْبَيْدَرِ، وَلَكِنْ لَا تُعْرَفِي عِنْدَ ٱلرَّجُلِ حَتَّى يَفْرَغَ مِنَ ٱلْأَكْلِ وَٱلشُّرْبِ.","faٱgẖ̊tasilī watadahãnī waٱl̊basī tẖīābaki waٱn̊zilī ại̹lay̱ ٱl̊baẙdari, walakin̊ lā tuʿ̊rafī ʿin̊da ٱlrãjuli ḥatãy̱ yaf̊ragẖa mina ٱl̊ạảk̊li waٱlsẖũr̊bi."],[3,4,"وَمَتَى ٱضْطَجَعَ فَٱعْلَمِي ٱلْمَكَانَ ٱلَّذِي يَضْطَجِعُ فِيهِ، وَٱدْخُلِي وَٱكْشِفِي نَاحِيَةَ رِجْلَيْهِ وَٱضْطَجِعِي، وَهُوَ يُخْبِرُكِ بِمَا تَعْمَلِينَ».","wamatay̱ ٱḍ̊ṭajaʿa faٱʿ̊lamī ٱl̊makāna ٱlãdẖī yaḍ̊ṭajiʿu fīhi, waٱd̊kẖulī waٱk̊sẖifī nāḥīaẗa rij̊laẙhi waٱḍ̊ṭajiʿī, wahūa yukẖ̊biruki bimā taʿ̊malīna»."],[3,5,"فَقَالَتْ لَهَا: «كُلَّ مَا قُلْتِ أَصْنَعُ».","faqālat̊ lahā: «kulã mā qul̊ti ạảṣ̊naʿu»."],[3,6,"فَنَزَلَتْ إِلَى ٱلْبَيْدَرِ وَعَمِلَتْ حَسَبَ كُلِّ مَا أَمَرَتْهَا بِهِ حَمَاتُهَا.","fanazalat̊ ại̹lay̱ ٱl̊baẙdari waʿamilat̊ ḥasaba kulĩ mā ạảmarat̊hā bihi ḥamātuhā."],[3,7,"فَأَكَلَ بُوعَزُ وَشَرِبَ وَطَابَ قَلْبُهُ وَدَخَلَ لِيَضْطَجِعَ فِي طَرَفِ ٱلْعَرَمَةِ. فَدَخَلَتْ سِرًّا وَكَشَفَتْ نَاحِيَةَ رِجْلَيْهِ وَٱضْطَجَعَتْ.","fāảkala būʿazu wasẖariba waṭāba qal̊buhu wadakẖala līaḍ̊ṭajiʿa fī ṭarafi ٱl̊ʿaramaẗi. fadakẖalat̊ siraⁿ̃ạ wakasẖafat̊ nāḥīaẗa rij̊laẙhi waٱḍ̊ṭajaʿat̊."],[3,8,"وَكَانَ عِنْدَ ٱنْتِصَافِ ٱللَّيْلِ أَنَّ ٱلرَّجُلَ ٱضْطَرَبَ، وَٱلْتَفَتَ وَإِذَا بِٱمْرَأَةٍ مُضْطَجِعَةٍ عِنْدَ رِجْلَيْهِ.","wakāna ʿin̊da ٱn̊tiṣāfi ٱllãẙli ạảnã ٱlrãjula ٱḍ̊ṭaraba, waٱl̊tafata wāi̹dẖā biٱm̊rāảẗiⁿ muḍ̊ṭajiʿaẗiⁿ ʿin̊da rij̊laẙhi."],[3,9,"فَقَالَ: «مَنْ أَنْتِ؟» فَقَالَتْ: «أَنَا رَاعُوثُ أَمَتُكَ. فَٱبْسُطْ ذَيْلَ ثَوْبِكَ عَلَى أَمَتِكَ لِأَنَّكَ وَلِيٌّ».","faqāla: «man̊ ạản̊ti?» faqālat̊: «ạảnā rāʿūtẖu ạảmatuka. faٱb̊suṭ̊ dẖaẙla tẖaẘbika ʿalay̱ ạảmatika liạảnãka walīuⁿ̃»."],[3,10,"فَقَالَ: «إِنَّكِ مُبَارَكَةٌ مِنَ ٱلرَّبِّ يَابِنْتِي لِأَنَّكِ قَدْ أَحْسَنْتِ مَعْرُوفَكِ فِي ٱلْأَخِيرِ أَكْثَرَ مِنَ ٱلْأَوَّلِ، إِذْ لَمْ تَسْعَيْ وَرَاءَ ٱلشُّبَّانِ، فُقَرَاءَ كَانُوا أَوْ أَغْنِيَاءَ.","faqāla: «ại̹nãki mubārakaẗuⁿ mina ٱlrãbĩ yābin̊tī liạảnãki qad̊ ạảḥ̊san̊ti maʿ̊rūfaki fī ٱl̊ạảkẖīri ạảk̊tẖara mina ٱl̊ạảwãli, ại̹dẖ̊ lam̊ tas̊ʿaẙ warāʾa ٱlsẖũbãạni, fuqarāʾa kānūạ ạảẘ ạảgẖ̊nīāʾa."],[3,11,"وَٱلْآنَ يَابِنْتِي لَا تَخَافِي. كُلُّ مَا تَقُولِينَ أَفْعَلُ لَكِ، لِأَنَّ جَمِيعَ أَبْوَابِ شَعْبِي تَعْلَمُ أَنَّكِ ٱمْرَأَةٌ فَاضِلَةٌ.","waٱl̊ậna yābin̊tī lā takẖāfī. kulũ mā taqūlīna ạảf̊ʿalu laki, liạảnã jamīʿa ạảb̊wābi sẖaʿ̊bī taʿ̊lamu ạảnãki ٱm̊rāảẗuⁿ fāḍilaẗuⁿ."],[3,12,"وَٱلْآنَ صَحِيحٌ أَنِّي وَلِيٌّ، وَلَكِنْ يُوجَدُ وَلِيٌّ أَقْرَبُ مِنِّي.","waٱl̊ậna ṣaḥīḥuⁿ ạảnĩy walīuⁿ̃, walakin̊ yūjadu walīuⁿ̃ ạảq̊rabu minĩy."],[3,13,"بِيتِي ٱللَّيْلَةَ، وَيَكُونُ فِي ٱلصَّبَاحِ أَنَّهُ إِنْ قَضَى لَكِ حَقَّ ٱلْوَلِيِّ فَحَسَنًا. لِيَقْضِ. وَإِنْ لَمْ يَشَأْ أَنْ يَقْضِيَ لَكِ حَقَّ ٱلْوَلِيِّ، فَأَنَا أَقْضِي لَكِ. حَيٌّ هُوَ ٱلرَّبُّ. اِضْطَجِعِي إِلَى ٱلصَّبَاحِ».","bītī ٱllãẙlaẗa, wayakūnu fī ٱlṣãbāḥi ạảnãhu ại̹n̊ qaḍay̱ laki ḥaqã ٱl̊walīĩ faḥasanaⁿạ. līaq̊ḍi. wāi̹n̊ lam̊ yasẖā̊̉ ạản̊ yaq̊ḍīa laki ḥaqã ٱl̊walīĩ, fāảnā ạảq̊ḍī laki. ḥayuⁿ̃ hūa ٱlrãbũ. ạiḍ̊ṭajiʿī ại̹lay̱ ٱlṣãbāḥi»."],[3,14,"فَٱضْطَجَعَتْ عِنْدَ رِجْلَيْهِ إِلَى ٱلصَّبَاحِ. ثُمَّ قَامَتْ قَبْلَ أَنْ يَقْدِرَ ٱلْوَاحِدُ عَلَى مَعْرِفَةِ صَاحِبِهِ. وَقَالَ: «لَا يُعْلَمْ أَنَّ ٱلْمَرْأَةَ جَاءَتْ إِلَى ٱلْبَيْدَرِ».","faٱḍ̊ṭajaʿat̊ ʿin̊da rij̊laẙhi ại̹lay̱ ٱlṣãbāḥi. tẖumã qāmat̊ qab̊la ạản̊ yaq̊dira ٱl̊wāḥidu ʿalay̱ maʿ̊rifaẗi ṣāḥibihi. waqāla: «lā yuʿ̊lam̊ ạảnã ٱl̊mar̊ạảẗa jāʾat̊ ại̹lay̱ ٱl̊baẙdari»."],[3,15,"ثُمَّ قَالَ: «هَاتِي ٱلرِّدَاءَ ٱلَّذِي عَلَيْكِ وَأَمْسِكِيهِ». فَأَمْسَكَتْهُ، فَٱكْتَالَ سِتَّةً مِنَ ٱلشَّعِيرِ وَوَضَعَهَا عَلَيْهَا، ثُمَّ دَخَلَتَ ٱلْمَدِينَةَ.","tẖumã qāla: «hātī ٱlrĩdāʾa ٱlãdẖī ʿalaẙki wāảm̊sikīhi». fāảm̊sakat̊hu, faٱk̊tāla sitãẗaⁿ mina ٱlsẖãʿīri wawaḍaʿahā ʿalaẙhā, tẖumã dakẖalata ٱl̊madīnaẗa."],[3,16,"فَجَاءَتْ إِلَى حَمَاتِهَا فَقَالَتْ: «مَنْ أَنْتِ يَابِنْتِي؟». فَأَخْبَرَتْهَا بِكُلِّ مَا فَعَلَ لَهَا ٱلرَّجُلُ.","fajāʾat̊ ại̹lay̱ ḥamātihā faqālat̊: «man̊ ạản̊ti yābin̊tī?». fāảkẖ̊barat̊hā bikulĩ mā faʿala lahā ٱlrãjulu."],[3,17,"وَقَالَتْ: «هَذِهِ ٱلسِّتَّةَ مِنَ ٱلشَّعِيرِ أَعْطَانِي، لِأَنَّهُ قَالَ: لَا تَجِيئِي فَارِغَةً إِلَى حَمَاتِكِ».","waqālat̊: «hadẖihi ٱlsĩtãẗa mina ٱlsẖãʿīri ạảʿ̊ṭānī, liạảnãhu qāla: lā tajīyỉy fārigẖaẗaⁿ ại̹lay̱ ḥamātiki»."],[3,18,"فَقَالَتِ: «ٱجْلِسِي يَابِنْتِي حَتَّى تَعْلَمِي كَيْفَ يَقَعُ ٱلْأَمْرُ، لِأَنَّ ٱلرَّجُلَ لَا يَهْدَأُ حَتَّى يُتَمِّمَ ٱلْأَمْرَ ٱلْيَوْمَ».","faqālati: «ٱj̊lisī yābin̊tī ḥatãy̱ taʿ̊lamī kaẙfa yaqaʿu ٱl̊ạảm̊ru, liạảnã ٱlrãjula lā yah̊dāủ ḥatãy̱ yutamĩma ٱl̊ạảm̊ra ٱl̊yaẘma»."],[4,1,"فَصَعِدَ بُوعَزُ إِلَى ٱلْبَابِ وَجَلَسَ هُنَاكَ. وَإِذَا بِٱلْوَلِيِّ ٱلَّذِي تَكَلَّمَ عَنْهُ بُوعَزُ عَابِرٌ. فَقَالَ: «مِلْ وَٱجْلِسْ هُنَا أَنْتَ يَا فُلَانُ ٱلْفُلَانِيُّ». فَمَالَ وَجَلَسَ.","faṣaʿida būʿazu ại̹lay̱ ٱl̊bābi wajalasa hunāka. wāi̹dẖā biٱl̊walīĩ ٱlãdẖī takalãma ʿan̊hu būʿazu ʿābiruⁿ. faqāla: «mil̊ waٱj̊lis̊ hunā ạản̊ta yā fulānu ٱl̊fulānīũ». famāla wajalasa."],[4,2,"ثُمَّ أَخَذَ عَشَرَةَ رِجَالٍ مِنْ شُيُوخِ ٱلْمَدِينَةِ وَقَالَ لَهُمُ: «ٱجْلِسُوا هُنَا». فَجَلَسُوا.","tẖumã ạảkẖadẖa ʿasẖaraẗa rijāliⁿ min̊ sẖuyūkẖi ٱl̊madīnaẗi waqāla lahumu: «ٱj̊lisūạ hunā». fajalasūạ."],[4,3,"ثُمَّ قَالَ لِلْوَلِيِّ: «إِنَّ نُعْمِيَ ٱلَّتِي رَجَعَتْ مِنْ بِلَادِ مُوآبَ تَبِيعُ قِطْعَةَ ٱلْحَقْلِ ٱلَّتِي لِأَخِينَا أَلِيمَالِكَ.","tẖumã qāla lil̊walīĩ: «ại̹nã nuʿ̊mīa ٱlãtī rajaʿat̊ min̊ bilādi mūậba tabīʿu qiṭ̊ʿaẗa ٱl̊ḥaq̊li ٱlãtī liạảkẖīnā ạảlīmālika."],[4,4,"فَقُلْتُ إِنِّي أُخْبِرُكَ قَائِلًا: ٱشْتَرِ قُدَّامَ ٱلْجَالِسِينَ وَقُدَّامَ شُيُوخِ شَعْبِي. فَإِنْ كُنْتَ تَفُكُّ فَفُكَّ. وَإِنْ كُنْتَ لَا تَفُكُّ فَأَخْبِرْنِي لِأَعْلَمَ. لِأَنَّهُ لَيْسَ غَيْرُكَ يَفُكُّ وَأَنَا بَعْدَكَ». فَقَالَ: «إِنِّي أَفُكُّ».","faqul̊tu ại̹nĩy ạủkẖ̊biruka qāyỉlaⁿạ: ٱsẖ̊tari qudãạma ٱl̊jālisīna waqudãạma sẖuyūkẖi sẖaʿ̊bī. fāi̹n̊ kun̊ta tafukũ fafukã. wāi̹n̊ kun̊ta lā tafukũ fāảkẖ̊bir̊nī liạảʿ̊lama. liạảnãhu laẙsa gẖaẙruka yafukũ wāảnā baʿ̊daka». faqāla: «ại̹nĩy ạảfukũ»."],[4,5,"فَقَالَ بُوعَزُ: «يَوْمَ تَشْتَرِي ٱلْحَقْلَ مِنْ يَدِ نُعْمِي تَشْتَرِي أَيْضًا مِنْ يَدِ رَاعُوثَ ٱلْمُوآبِيَّةِ ٱمْرَأَةِ ٱلْمَيِّتِ لِتُقِيمَ ٱسْمَ ٱلْمَيِّتِ عَلَى مِيرَاثِهِ».","faqāla būʿazu: «yaẘma tasẖ̊tarī ٱl̊ḥaq̊la min̊ yadi nuʿ̊mī tasẖ̊tarī ạảẙḍaⁿạ min̊ yadi rāʿūtẖa ٱl̊mūậbīãẗi ٱm̊rāảẗi ٱl̊mayĩti lituqīma ٱs̊ma ٱl̊mayĩti ʿalay̱ mīrātẖihi»."],[4,6,"فَقَالَ ٱلْوَلِيُّ: «لَا أَقْدِرُ أَنْ أَفُكَّ لِنَفْسِي لِئَّلَا أُفْسِدَ مِيرَاثِي. فَفُكَّ أَنْتَ لِنَفْسِكَ فِكَاكِي لِأَنِّي لَا أَقْدِرُ أَنْ أَفُكَّ».","faqāla ٱl̊walīũ: «lā ạảq̊diru ạản̊ ạảfukã linaf̊sī līã̉lā ạủf̊sida mīrātẖī. fafukã ạản̊ta linaf̊sika fikākī liạảnĩy lā ạảq̊diru ạản̊ ạảfukã»."],[4,7,"وَهَذِهِ هِيَ ٱلْعَادَةُ سَابِقًا فِي إِسْرَائِيلَ فِي أَمْرِ ٱلْفِكَاكِ وَٱلْمُبَادَلَةِ، لِأَجْلِ إِثْبَاتِ كُلِّ أَمْرٍ. يَخْلَعُ ٱلرَّجُلُ نَعْلَهُ وَيُعْطِيهِ لِصَاحِبِهِ. فَهَذِهِ هِيَ ٱلْعَادَةُ فِي إِسْرَائِيلَ.","wahadẖihi hīa ٱl̊ʿādaẗu sābiqaⁿạ fī ại̹s̊rāyỉyla fī ạảm̊ri ٱl̊fikāki waٱl̊mubādalaẗi, liạảj̊li ại̹tẖ̊bāti kulĩ ạảm̊riⁿ. yakẖ̊laʿu ٱlrãjulu naʿ̊lahu wayuʿ̊ṭīhi liṣāḥibihi. fahadẖihi hīa ٱl̊ʿādaẗu fī ại̹s̊rāyỉyla."],[4,8,"فَقَالَ ٱلْوَلِيُّ لِبُوعَزَ: «ٱشْتَرِ لِنَفْسِكَ». وَخَلَعَ نَعْلَهُ.","faqāla ٱl̊walīũ libūʿaza: «ٱsẖ̊tari linaf̊sika». wakẖalaʿa naʿ̊lahu."],[4,9,"فَقَالَ بُوعَزُ لِلشُّيُوخِ وَلِجَمِيعِ ٱلشَّعْبِ: «أَنْتُمْ شُهُودٌ ٱلْيَوْمَ أَنِّي قَدِ ٱشْتَرَيْتُ كُلَّ مَا لِأَلِيمَالِكَ وَكُلَّ مَا لِكِلْيُونَ وَمَحْلُونَ مِنْ يَدِ نُعْمِي.","faqāla būʿazu lilsẖũyūkẖi walijamīʿi ٱlsẖãʿ̊bi: «ạản̊tum̊ sẖuhūduⁿ ٱl̊yaẘma ạảnĩy qadi ٱsẖ̊taraẙtu kulã mā liạảlīmālika wakulã mā likil̊yūna wamaḥ̊lūna min̊ yadi nuʿ̊mī."],[4,10,"وَكَذَا رَاعُوثُ ٱلْمُوآبِيَّةُ ٱمْرَأَةُ مَحْلُونَ قَدِ ٱشْتَرَيْتُهَا لِيَ ٱمْرَأَةً، لِأُقِيمَ ٱسْمَ ٱلْمَيِّتِ عَلَى مِيرَاثِهِ وَلَا يَنْقَرِضُ ٱسْمُ ٱلْمَيِّتِ مِنْ بَيْنِ إِخْوَتِهِ وَمِنْ بَابِ مَكَانِهِ. أَنْتُمْ شُهُودٌ ٱلْيَوْمَ».","wakadẖā rāʿūtẖu ٱl̊mūậbīãẗu ٱm̊rāảẗu maḥ̊lūna qadi ٱsẖ̊taraẙtuhā līa ٱm̊rāảẗaⁿ, liạủqīma ٱs̊ma ٱl̊mayĩti ʿalay̱ mīrātẖihi walā yan̊qariḍu ٱs̊mu ٱl̊mayĩti min̊ baẙni ại̹kẖ̊watihi wamin̊ bābi makānihi. ạản̊tum̊ sẖuhūduⁿ ٱl̊yaẘma»."],[4,11,"فَقَالَ جَمِيعُ ٱلشَّعْبِ ٱلَّذِينَ فِي ٱلْبَابِ وَٱلشُّيُوخُ: «نَحْنُ شُهُودٌ. فَلْيَجْعَلِ ٱلرَّبُّ ٱلْمَرْأَةَ ٱلدَّاخِلَةَ إِلَى بَيْتِكَ كَرَاحِيلَ وَكَلَيْئَةَ ٱللَّتَيْنِ بَنَتَا بَيْتَ إِسْرَائِيلَ. فَٱصْنَعْ بِبَأْسٍ فِي أَفْرَاتَةَ وَكُنْ ذَا ٱسْمٍ فِي بَيْتِ لَحْمٍ.","faqāla jamīʿu ٱlsẖãʿ̊bi ٱlãdẖīna fī ٱl̊bābi waٱlsẖũyūkẖu: «naḥ̊nu sẖuhūduⁿ. fal̊yaj̊ʿali ٱlrãbũ ٱl̊mar̊ạảẗa ٱldãạkẖilaẗa ại̹lay̱ baẙtika karāḥīla wakalaẙyảẗa ٱllãtaẙni banatā baẙta ại̹s̊rāyỉyla. faٱṣ̊naʿ̊ bibā̊̉siⁿ fī ạảf̊rātaẗa wakun̊ dẖā ٱs̊miⁿ fī baẙti laḥ̊miⁿ."],[4,12,"وَلْيَكُنْ بَيْتُكَ كَبَيْتِ فَارَصَ ٱلَّذِي وَلَدَتْهُ ثَامَارُ لِيَهُوذَا، مِنَ ٱلنَّسْلِ ٱلَّذِي يُعْطِيكَ ٱلرَّبُّ مِنْ هَذِهِ ٱلْفَتَاةِ».","wal̊yakun̊ baẙtuka kabaẙti fāraṣa ٱlãdẖī waladat̊hu tẖāmāru līahūdẖā, mina ٱlnãs̊li ٱlãdẖī yuʿ̊ṭīka ٱlrãbũ min̊ hadẖihi ٱl̊fatāẗi»."],[4,13,"فَأَخَذَ بُوعَزُ رَاعُوثَ ٱمْرَأَةً وَدَخَلَ عَلَيْهَا، فَأَعْطَاهَا ٱلرَّبُّ حَبَلًا فَوَلَدَتِ ٱبْنًا.","fāảkẖadẖa būʿazu rāʿūtẖa ٱm̊rāảẗaⁿ wadakẖala ʿalaẙhā, fāảʿ̊ṭāhā ٱlrãbũ ḥabalaⁿạ fawaladati ٱb̊naⁿạ."],[4,14,"فَقَالَتِ ٱلنِّسَاءُ لِنُعْمِي: «مُبَارَكٌ ٱلرَّبُّ ٱلَّذِي لَمْ يُعْدِمْكِ وَلِيًّا ٱلْيَوْمَ لِكَيْ يُدْعَى ٱسْمُهُ فِي إِسْرَائِيلَ.","faqālati ٱlnĩsāʾu linuʿ̊mī: «mubārakuⁿ ٱlrãbũ ٱlãdẖī lam̊ yuʿ̊dim̊ki walīaⁿ̃ạ ٱl̊yaẘma likaẙ yud̊ʿay̱ ٱs̊muhu fī ại̹s̊rāyỉyla."],[4,15,"وَيَكُونُ لَكِ لِإِرْجَاعِ نَفْسٍ وَإِعَالَةِ شَيْبَتِكِ. لِأَنَّ كَنَّتَكِ ٱلَّتِي أَحَبَّتْكِ قَدْ وَلَدَتْهُ، وَهِيَ خَيْرٌ لَكِ مِنْ سَبْعَةِ بَنِينَ».","wayakūnu laki liại̹r̊jāʿi naf̊siⁿ wāi̹ʿālaẗi sẖaẙbatiki. liạảnã kanãtaki ٱlãtī ạảḥabãt̊ki qad̊ waladat̊hu, wahīa kẖaẙruⁿ laki min̊ sab̊ʿaẗi banīna»."],[4,16,"فَأَخَذَتْ نُعْمِي ٱلْوَلَدَ وَوَضَعَتْهُ فِي حِضْنِهَا وَصَارَتْ لَهُ مُرَبِّيَةً.","fāảkẖadẖat̊ nuʿ̊mī ٱl̊walada wawaḍaʿat̊hu fī ḥiḍ̊nihā waṣārat̊ lahu murabĩyaẗaⁿ."],[4,17,"وَسَمَّتْهُ ٱلْجَارَاتُ ٱسْمًا قَائِلَاتٍ: «قَدْ وُلِدَ ٱبْنٌ لِنُعْمِي» وَدَعَوْنَ ٱسْمَهُ عُوبِيدَ. هُوَ أَبُو يَسَّى أَبِي دَاوُدَ.","wasamãt̊hu ٱl̊jārātu ٱs̊maⁿạ qāyỉlātiⁿ: «qad̊ wulida ٱb̊nuⁿ linuʿ̊mī» wadaʿaẘna ٱs̊mahu ʿūbīda. hūa ạảbū yasãy̱ ạảbī dāwuda."],[4,18,"وَهَذِهِ مَوَالِيدُ فَارَصَ: فَارَصُ وَلَدَ حَصْرُونَ،","wahadẖihi mawālīdu fāraṣa: fāraṣu walada ḥaṣ̊rūna,"],[4,19,"وَحَصْرُونُ وَلَدَ رَامَ، وَرَامُ وَلَدَ عَمِّينَادَابَ،","waḥaṣ̊rūnu walada rāma, warāmu walada ʿamĩynādāba,"],[4,20,"وَعَمِّينَادَابُ وَلَدَ نَحْشُونَ، وَنَحْشُونُ وَلَدَ سَلْمُونَ،","waʿamĩynādābu walada naḥ̊sẖūna, wanaḥ̊sẖūnu walada sal̊mūna,"],[4,21,"وَسَلْمُونُ وَلَدَ بُوعَزَ، وَبُوعَزُ وَلَدَ عُوبِيدَ،","wasal̊mūnu walada būʿaza, wabūʿazu walada ʿūbīda,"],[4,22,"وَعُوبِيدُ وَلَدَ يَسَّى، وَيَسَّى وَلَدَ دَاوُدَ.","waʿūbīdu walada yasãy̱, wayasãy̱ walada dāwuda."]],"bis-obbr":[[1,1,"Bifo, long taem ya we ol laen* blong Isrel* oli stap long han blong ol haeman blong olgeta nomo, i gat wan man long laen blong Juda* we hom blong hem long taon ya Betlehem. Man ya, nem blong hem Elimelek, mo woman blong hem, nem blong hem Nomi, mo tufala pikinini boe blong hem, nem blong tufala Malon mo Kilion. Nao i gat hadtaem i kasem olgeta, we oli no gat kakae nating long kantri ya, mo from samting ya, man ya wetem woman blong hem mo tufala pikinini blong tufala oli aot long ples ya, oli go stap long kantri ya Moab. Olgeta ya oli man Betlehem we olfala nem blong hem Efrata, be oli aot, oli go mekem ples blong olgeta long Moab. Oli stap long ples ya gogo,","Bifo, long taem ya we ol laen* blong Isrel* oli stap long han blong ol haeman blong olgeta nomo, i gat wan man long laen blong Juda* we hom blong hem long taon ya Betlehem. Man ya, nem blong hem Elimelek, mo woman blong hem, nem blong hem Nomi, mo tufala pikinini boe blong hem, nem blong tufala Malon mo Kilion. Nao i gat hadtaem i kasem olgeta, we oli no gat kakae nating long kantri ya, mo from samting ya, man ya wetem woman blong hem mo tufala pikinini blong tufala oli aot long ples ya, oli go stap long kantri ya Moab. Olgeta ya oli man Betlehem we olfala nem blong hem Efrata, be oli aot, oli go mekem ples blong olgeta long Moab. Oli stap long ples ya gogo,",2],[1,3,"Elimelek i ded, mo woman blong hem i stap hem wan, wetem tufala boe ya blong tufala.","Elimelek i ded, mo woman blong hem i stap hem wan, wetem tufala boe ya blong tufala."],[1,4,"Nao tufala boe ya i tekem tu gel Moab we nem blong tufala, Opa mo Rut, mo olgeta oli stap long kantri ya, gogo kasem samwe long ten yia,","Nao tufala boe ya i tekem tu gel Moab we nem blong tufala, Opa mo Rut, mo olgeta oli stap long kantri ya, gogo kasem samwe long ten yia,"],[1,5,"nao Malon mo Kilion tufala tu i ded, Nomi nomo i stap.","nao Malon mo Kilion tufala tu i ded, Nomi nomo i stap."],[1,6,"Nao Nomi i harem nius we Hae God i stap givhan gud long ol man ples blong hem, i stap givim plante kakae long olgeta bakegen. Nao hem i mekemrere blong i aot long Moab blong kambak long Juda,* mo tufala wido blong tufala pikinini blong hem, tufala i mekemrere blong kam wetem hem.","Nao Nomi i harem nius we Hae God i stap givhan gud long ol man ples blong hem, i stap givim plante kakae long olgeta bakegen. Nao hem i mekemrere blong i aot long Moab blong kambak long Juda,* mo tufala wido blong tufala pikinini blong hem, tufala i mekemrere blong kam wetem hem."],[1,7,"Ale, trifala i aot blong kam long Juda, nao taem trifala i stap long hafrod,","Ale, trifala i aot blong kam long Juda, nao taem trifala i stap long hafrod,"],[1,8,"hem i talem se, “Tufala. I moa gud yutufala i gobak long ples blong yutufala, yutufala i go stap wetem tufala mama blong yutufala. Prea blong mi we Hae God bambae i givhan long yutufala, olsem we bifo yutufala i stap givhan long mi, mo long tufala ya we i lus.","hem i talem se, “Tufala. I moa gud yutufala i gobak long ples blong yutufala, yutufala i go stap wetem tufala mama blong yutufala. Prea blong mi we Hae God bambae i givhan long yutufala, olsem we bifo yutufala i stap givhan long mi, mo long tufala ya we i lus."],[1,9,"Hem bambae i mekem rod, blong yutufala i mared bakegen, blong yutufala i save gat pikinini.” Nao hem i kis* long tufala blong talem tata long tufala. Be tufala i krae bigwan,","Hem bambae i mekem rod, blong yutufala i mared bakegen, blong yutufala i save gat pikinini.” Nao hem i kis* long tufala blong talem tata long tufala. Be tufala i krae bigwan,"],[1,10,"nao tufala i talem long hem se, “No, mitufala i mas kam wetem yu blong go stap wetem ol famle blong yu.”","nao tufala i talem long hem se, “No, mitufala i mas kam wetem yu blong go stap wetem ol famle blong yu.”"],[1,11,"Be hem i talem se, “Tufala dota blong mi. ?Blong wanem yutufala i wantem kam wetem mi? I gud yutufala i gobak, from we mi mi no moa save bonem tu pikinini boe bakegen, blong yutufala i mared long tufala.","Be hem i talem se, “Tufala dota blong mi. ?Blong wanem yutufala i wantem kam wetem mi? I gud yutufala i gobak, from we mi mi no moa save bonem tu pikinini boe bakegen, blong yutufala i mared long tufala."],[1,12,"Yutufala i gobak long ples blong yutufala. Mi mi olfala finis, mi no save mared bakegen. Sipos mi talem long yutufala se, ‘Yutufala i wet, bambae mi gat tu pikinini boe blong mi bakegen blong yutufala i mared long tufala,’","Yutufala i gobak long ples blong yutufala. Mi mi olfala finis, mi no save mared bakegen. Sipos mi talem long yutufala se, ‘Yutufala i wet, bambae mi gat tu pikinini boe blong mi bakegen blong yutufala i mared long tufala,’"],[1,13,"be tok ya i no save blokem yutufala, blong yutufala i no go mared long sam narafala man. ?Sipos mi mared long naet ya nomo, nao mi bonem tu pikinini boe blong mi, yutufala i ting se yutufala i save wet gogo tufala ya i kam bigwan, blong yutufala i mared long tufala? Tufala. Samting ya i no save kamtru. Hae God i tanem baksaed long mi finis, nao mi harem we mi sore tumas long yutufala.”","be tok ya i no save blokem yutufala, blong yutufala i no go mared long sam narafala man. ?Sipos mi mared long naet ya nomo, nao mi bonem tu pikinini boe blong mi, yutufala i ting se yutufala i save wet gogo tufala ya i kam bigwan, blong yutufala i mared long tufala? Tufala. Samting ya i no save kamtru. Hae God i tanem baksaed long mi finis, nao mi harem we mi sore tumas long yutufala.”"],[1,14,"Nao tufala i stat krae bigwan bakegen, nao Opa i kis long hem blong talem tata long hem, mo i gobak. Be Rut i no save lego hem nating.","Nao tufala i stat krae bigwan bakegen, nao Opa i kis long hem blong talem tata long hem, mo i gobak. Be Rut i no save lego hem nating."],[1,15,"Nao Nomi i talem long hem se, “Dota blong mi. Yu luk. Sista blong yu i gobak finis long ol man ples blong hem, mo long ol god blong hem. I gud yu tu, yu gobak wetem hem.”","Nao Nomi i talem long hem se, “Dota blong mi. Yu luk. Sista blong yu i gobak finis long ol man ples blong hem, mo long ol god blong hem. I gud yu tu, yu gobak wetem hem.”"],[1,16,"Be Rut i talem long hem se, “Plis yu no talem long mi blong mi lego yu. Mi wantem kam wetem yu. Plis yu no blokem mi. Ples we yu bambae yu go long hem, mi tu bambae mi go long hem. Ples we yu bambae yu stap long hem, mi tu bambae mi stap long hem. Ol man ples blong yu bambae oli man ples blong mi, mo God blong yu bambae i God blong mi.","Be Rut i talem long hem se, “Plis yu no talem long mi blong mi lego yu. Mi wantem kam wetem yu. Plis yu no blokem mi. Ples we yu bambae yu go long hem, mi tu bambae mi go long hem. Ples we yu bambae yu stap long hem, mi tu bambae mi stap long hem. Ol man ples blong yu bambae oli man ples blong mi, mo God blong yu bambae i God blong mi."],[1,17,"Ples we yu bambae yu ded long hem, mi bambae mi ded long hem, mo bambae oli berem mi tu long ples ya. Tru mi talem long yu, i no gat wan samting we bambae i save tekemaot mi long yu, ded nomo bambae i save tekemaot mi. Sipos mi brekem tok ya blong mi, i gud Hae God i givim panis long mi.”","Ples we yu bambae yu ded long hem, mi bambae mi ded long hem, mo bambae oli berem mi tu long ples ya. Tru mi talem long yu, i no gat wan samting we bambae i save tekemaot mi long yu, ded nomo bambae i save tekemaot mi. Sipos mi brekem tok ya blong mi, i gud Hae God i givim panis long mi.”"],[1,18,"Nao taem hem i luk we tingting blong Rut i strong tumas blong kam wetem hem, hem i no moa save tok bakegen.","Nao taem hem i luk we tingting blong Rut i strong tumas blong kam wetem hem, hem i no moa save tok bakegen."],[1,19,"Nao tufala i aot, mo taem tufala i kam kasem Betlehem, olgeta evriwan oli sek gud long tufala. Nao ol woman oli stap asaskem se, “?E, hu ya? ?Nomi ya, no hu?”","Nao tufala i aot, mo taem tufala i kam kasem Betlehem, olgeta evriwan oli sek gud long tufala. Nao ol woman oli stap asaskem se, “?E, hu ya? ?Nomi ya, no hu?”"],[1,20,"Be hem i talem se, “Mi Nomi, be yufala i no moa singaot mi se ‘Nomi’ we i min se ‘Harem gud’. I moa gud yufala i singaot mi se ‘Mara’ we i min se ‘Harem nogud’. Hae God i gat olgeta paoa, mo hem i mekem mi mi harem nogud tumas.","Be hem i talem se, “Mi Nomi, be yufala i no moa singaot mi se ‘Nomi’ we i min se ‘Harem gud’. I moa gud yufala i singaot mi se ‘Mara’ we i min se ‘Harem nogud’. Hae God i gat olgeta paoa, mo hem i mekem mi mi harem nogud tumas."],[1,21,"Taem mi mi aot long ples ya, mi gat plante samting, be naoia, hem i tekem mi mi kambak we mi no gat wan samting nating. I nogud yufala i stap singaot mi se ‘Nomi’, from we hem i tanem baksaed finis long mi, i mekem we bigfala trabol i kasem mi.”","Taem mi mi aot long ples ya, mi gat plante samting, be naoia, hem i tekem mi mi kambak we mi no gat wan samting nating. I nogud yufala i stap singaot mi se ‘Nomi’, from we hem i tanem baksaed finis long mi, i mekem we bigfala trabol i kasem mi.”"],[1,22,"Long fasin ya nao, Nomi i aot long Moab, i kambak long ples blong hem, mo woman Moab ya Rut, we i wido blong pikinini blong hem i biaen long hem, nao tufala i kam stap long Betlehem. Tufala i kamtru long ples ya, stret long taem we ol man oli stat blong tekemaot bale* long ol garen* blong olgeta.","Long fasin ya nao, Nomi i aot long Moab, i kambak long ples blong hem, mo woman Moab ya Rut, we i wido blong pikinini blong hem i biaen long hem, nao tufala i kam stap long Betlehem. Tufala i kamtru long ples ya, stret long taem we ol man oli stat blong tekemaot bale* long ol garen* blong olgeta."],[2,1,"Nao long ples ya, i gat wan famle blong Elimelek, man ya blong Nomi. Man ya, nem blong hem Boas, mo hem i rijman mo i haeman tu.","Nao long ples ya, i gat wan famle blong Elimelek, man ya blong Nomi. Man ya, nem blong hem Boas, mo hem i rijman mo i haeman tu."],[2,2,"Nao Rut i talem long Nomi se, “Plis yu letem mi mi go wok long garen* blong ol man, blong pikimap ol bale* we ol man blong wok oli mestem Bambae mi biaen long ol man we oli glad blong letem mi mi mekem olsem.” Nao Nomi i talem long hem se, “I oraet nomo, yu save go.”","Nao Rut i talem long Nomi se, “Plis yu letem mi mi go wok long garen* blong ol man, blong pikimap ol bale* we ol man blong wok oli mestem Bambae mi biaen long ol man we oli glad blong letem mi mi mekem olsem.” Nao Nomi i talem long hem se, “I oraet nomo, yu save go.”"],[2,3,"Nao hem i wokbaot i go, mo i gotru long garen blong wan man, nao i stap biaen long ol man blong wok, i stap pikimap ol bale we oli mestem. Garen ya i blong man ya we i famle blong Elimelek, be Rut i no save se garen ya i blong hu.","Nao hem i wokbaot i go, mo i gotru long garen blong wan man, nao i stap biaen long ol man blong wok, i stap pikimap ol bale we oli mestem. Garen ya i blong man ya we i famle blong Elimelek, be Rut i no save se garen ya i blong hu."],[2,4,"Nao long taem ya, Boas i aot long haos blong hem long taon, i kam long garen ya. Hem i talem halo long ol man blong hem we oli stap katemaot ol bale, i talem se, “Hae God bambae i stap wetem yufala.” Mo olgeta oli talem se, “Hae God bambae i blesem yu.”","Nao long taem ya, Boas i aot long haos blong hem long taon, i kam long garen ya. Hem i talem halo long ol man blong hem we oli stap katemaot ol bale, i talem se, “Hae God bambae i stap wetem yufala.” Mo olgeta oli talem se, “Hae God bambae i blesem yu.”"],[2,5,"Nao hem i askem long man we i bos blong ol man blong hem se, “?Yang woman ya i woman blong hu?”","Nao hem i askem long man we i bos blong ol man blong hem se, “?Yang woman ya i woman blong hu?”"],[2,6,"Mo bos ya i talem se, “Hemia woman Moab ya. Taem Nomi i aot long Moab i kambak, woman ya i biaen long hem.","Mo bos ya i talem se, “Hemia woman Moab ya. Taem Nomi i aot long Moab i kambak, woman ya i biaen long hem."],[2,7,"Hem i askem long mi blong i biaen long ol man blong mi, blong pikimap ol bale we oli stap mestem. Nao hem i stat wok long eli moning, i wok kam kasem naoia, nao i jes spel smol long wansaed haos ya.”","Hem i askem long mi blong i biaen long ol man blong mi, blong pikimap ol bale we oli stap mestem. Nao hem i stat wok long eli moning, i wok kam kasem naoia, nao i jes spel smol long wansaed haos ya.”"],[2,8,"Nao Boas i go talem long Rut se, “Dota blong mi. Mi wantem talem wan samting long yu. Bambae yu no go pikimap bale long garen blong narafala man. Bambae yu stap long ples ya, yu wok wetem ol woman ya we oli stap wok blong mi.","Nao Boas i go talem long Rut se, “Dota blong mi. Mi wantem talem wan samting long yu. Bambae yu no go pikimap bale long garen blong narafala man. Bambae yu stap long ples ya, yu wok wetem ol woman ya we oli stap wok blong mi."],[2,9,"Bambae yu stap lukluk long ol man ya blong luk weples oli stap katem bale, nao bambae yu biaen long olgeta. Mi mi talem long ol man blong mi finis blong oli no mekem i nogud long yu. Mo taem yu tosta, yu save go dring long ol botel wota ya we oli fulumap olgeta i stap.”","Bambae yu stap lukluk long ol man ya blong luk weples oli stap katem bale, nao bambae yu biaen long olgeta. Mi mi talem long ol man blong mi finis blong oli no mekem i nogud long yu. Mo taem yu tosta, yu save go dring long ol botel wota ya we oli fulumap olgeta i stap.”"],[2,10,"Nao Rut i bodaon long hem, we fes blong hem i godaon kasem graon, mo i talem se, “Masta. Mi mi wan strenja nomo long ples ya, be yu yu tingting tumas long mi.”","Nao Rut i bodaon long hem, we fes blong hem i godaon kasem graon, mo i talem se, “Masta. Mi mi wan strenja nomo long ples ya, be yu yu tingting tumas long mi.”"],[2,11,"Be Boas i talem long hem se, “No, be mi mi harem nius finis blong ol samting ya we yu mekem long mama blong man blong yu, i stat long taem ya we man blong yu i lus, i kam kasem tede. Mi save we yu lego stret papa mo mama blong yu, mo yu aot long ples blong yu, nao yu kam stap wetem mifala, we fastaem yu no save mifala nating.","Be Boas i talem long hem se, “No, be mi mi harem nius finis blong ol samting ya we yu mekem long mama blong man blong yu, i stat long taem ya we man blong yu i lus, i kam kasem tede. Mi save we yu lego stret papa mo mama blong yu, mo yu aot long ples blong yu, nao yu kam stap wetem mifala, we fastaem yu no save mifala nating."],[2,12,"Hae God i God blong mifala, mo prea blong mi we hem bambae i mekem i gud tumas long yu, from ol samting ya we yu yu mekem. Yu bambae yu kasem stret pei blong ol samting ya long hem, from we yu stap luk long hem, blong i lukaot gud long yu.”","Hae God i God blong mifala, mo prea blong mi we hem bambae i mekem i gud tumas long yu, from ol samting ya we yu yu mekem. Yu bambae yu kasem stret pei blong ol samting ya long hem, from we yu stap luk long hem, blong i lukaot gud long yu.”"],[2,13,"Nao hem i talem se, “Masta, yu yu mekem i gud tumas long mi. Mi mi no sem mak nating long ol gel blong wok blong yu, be from we yu toktok gud long mi olsem, yu leftemap tingting blong mi, nao mi mi harem gud.”","Nao hem i talem se, “Masta, yu yu mekem i gud tumas long mi. Mi mi no sem mak nating long ol gel blong wok blong yu, be from we yu toktok gud long mi olsem, yu leftemap tingting blong mi, nao mi mi harem gud.”"],[2,14,"Nao long taem blong kakae, Boas i talem long hem se, “Yu kam kakae. Yu tekem sam bisket* ya, yu pusum i go long waen ya, yu kakae.” Nao hem i kam sidaon wetem ol man blong wok, mo Boas i tekem sam bale we oli rusum finis, i givim long hem. Nao hem i kakae gogo i fulap, i no save finisim.","Nao long taem blong kakae, Boas i talem long hem se, “Yu kam kakae. Yu tekem sam bisket* ya, yu pusum i go long waen ya, yu kakae.” Nao hem i kam sidaon wetem ol man blong wok, mo Boas i tekem sam bale we oli rusum finis, i givim long hem. Nao hem i kakae gogo i fulap, i no save finisim."],[2,15,"Nao taem hem i girap blong go wok bakegen, Boas i talem long ol man blong hem se, “Bambae yufala i letem hem i pikimap sam bale long ol bandel tu, yufala i no blokem hem. Mo yufala i pulumaot sam bale long ol bandel ya, yufala i livim i stap, blong hem i save pikimap olgeta, mo bambae yufala i no tok long hem from.”","Nao taem hem i girap blong go wok bakegen, Boas i talem long ol man blong hem se, “Bambae yufala i letem hem i pikimap sam bale long ol bandel tu, yufala i no blokem hem. Mo yufala i pulumaot sam bale long ol bandel ya, yufala i livim i stap, blong hem i save pikimap olgeta, mo bambae yufala i no tok long hem from.”",16],[2,17,"Nao hem i stap pikimap bale gogo san i godaon. Mo biaen, hem i go kilim ol hed blong bale ya we i pikimap, blong kilimaot ol kakae blong hem. Mo ol kakae ya blong bale i plante we plante, we klosap i kasem ten kilo.","Nao hem i stap pikimap bale gogo san i godaon. Mo biaen, hem i go kilim ol hed blong bale ya we i pikimap, blong kilimaot ol kakae blong hem. Mo ol kakae ya blong bale i plante we plante, we klosap i kasem ten kilo."],[2,18,"Nao hem i girap, i karem bale ya, i gohom, mo i soem long Nomi we i tekem plante olsem. Mo hem i karem haf kakae ya blong hem blong medel dei, i givim long hem.","Nao hem i girap, i karem bale ya, i gohom, mo i soem long Nomi we i tekem plante olsem. Mo hem i karem haf kakae ya blong hem blong medel dei, i givim long hem."],[2,19,"Nao Nomi i askem long hem se, “?Tede yu go pikimap bale long weples? ?Yu tekem kakae ya long garen blong hu? Prea blong mi we Hae God bambae i blesem man ya we i luk yu, i kaen long yu olsem.” Nao hem i talem se, “Man ya we mi go pikimap bale long garen blong hem tede, nem blong hem Boas.”","Nao Nomi i askem long hem se, “?Tede yu go pikimap bale long weples? ?Yu tekem kakae ya long garen blong hu? Prea blong mi we Hae God bambae i blesem man ya we i luk yu, i kaen long yu olsem.” Nao hem i talem se, “Man ya we mi go pikimap bale long garen blong hem tede, nem blong hem Boas.”"],[2,20,"Nao Nomi i talem long hem se, “Prea blong mi we Hae God bambae i blesem hem. Oltaem Hae God i stap holem ol promes blong hem we i mekem long trifala ya we i lus, mo long yumi ya we yumi stap laef yet. Yu luk, man ya i wan famle blong man blong mi ya. Hem i wan long olgeta we oli mas lukaot gud long yumitufala, mo i stret blong hem i tekem yu.”","Nao Nomi i talem long hem se, “Prea blong mi we Hae God bambae i blesem hem. Oltaem Hae God i stap holem ol promes blong hem we i mekem long trifala ya we i lus, mo long yumi ya we yumi stap laef yet. Yu luk, man ya i wan famle blong man blong mi ya. Hem i wan long olgeta we oli mas lukaot gud long yumitufala, mo i stret blong hem i tekem yu.”"],[2,21,"Nao Rut i talem long hem se, “Mo hem i talem long mi tu se mi mas biaen long ol man blong wok blong hem, gogo kasem we oli tekemaot olgeta kakae long garen blong hem.”","Nao Rut i talem long hem se, “Mo hem i talem long mi tu se mi mas biaen long ol man blong wok blong hem, gogo kasem we oli tekemaot olgeta kakae long garen blong hem.”"],[2,22,"Nao Nomi i talem long hem se, “Dota blong mi. I moa gud yu stap wok wetem ol woman blong man ya nomo, from we sipos yu go wok long garen blong ol narafala man, maet sam man bambae oli mekem i nogud long yu.”","Nao Nomi i talem long hem se, “Dota blong mi. I moa gud yu stap wok wetem ol woman blong man ya nomo, from we sipos yu go wok long garen blong ol narafala man, maet sam man bambae oli mekem i nogud long yu.”"],[2,23,"Nao hem i stap wok wetem ol woman blong wok blong man ya, i stap pikimap bale mo wit,* gogo olgeta oli katem olgeta bale mo wit evriwan long ol garen blong hem. Be oltaem hem i stap kambak long haos blong tufala.","Nao hem i stap wok wetem ol woman blong wok blong man ya, i stap pikimap bale mo wit,* gogo olgeta oli katem olgeta bale mo wit evriwan long ol garen blong hem. Be oltaem hem i stap kambak long haos blong tufala."],[3,1,"Nao Nomi i talem long Rut se, “Dota blong mi. I gud mi lukaot wan man, blong i tekem yu, blong yu save gat ples blong yu we yu save stap gud long hem.","Nao Nomi i talem long Rut se, “Dota blong mi. I gud mi lukaot wan man, blong i tekem yu, blong yu save gat ples blong yu we yu save stap gud long hem."],[3,2,"Yu yu save, man ya Boas we yu stap wok wetem ol woman blong wok blong hem, hem i wan famle blong man blong mi, we i stret blong hem i tekem yu. Yu lesin. Long sapa ya, taem we win i blu, hem wetem ol man blong hem bambae oli go klinimaot ol skin blong bale,* blong tekem kakae blong hem.","Yu yu save, man ya Boas we yu stap wok wetem ol woman blong wok blong hem, hem i wan famle blong man blong mi, we i stret blong hem i tekem yu. Yu lesin. Long sapa ya, taem we win i blu, hem wetem ol man blong hem bambae oli go klinimaot ol skin blong bale,* blong tekem kakae blong hem."],[3,3,"I gud yu go swim, yu putum senta, mo yu putum gudfala klos blong yu mo kot blong yu, nao yu go long ples we bambae hem i stap wok long hem. Be yu no mas letem blong hem i save we yu yu stap long ples ya. Taem hem i kakae finis,","I gud yu go swim, yu putum senta, mo yu putum gudfala klos blong yu mo kot blong yu, nao yu go long ples we bambae hem i stap wok long hem. Be yu no mas letem blong hem i save we yu yu stap long ples ya. Taem hem i kakae finis,"],[3,4,"nao i go blong slip, bambae yu mas luklukgud ples ya, nao yu mas go tekemaot blangket long leg blong hem, mo yu mas slip klosap long leg blong hem. Nao hem bambae i talemaot long yu wanem samting we bambae yu mekem.”","nao i go blong slip, bambae yu mas luklukgud ples ya, nao yu mas go tekemaot blangket long leg blong hem, mo yu mas slip klosap long leg blong hem. Nao hem bambae i talemaot long yu wanem samting we bambae yu mekem.”"],[3,5,"Nao Rut i talem se, “I gud. Bambae mi mekem olgeta samting ya we yu yu talem.”","Nao Rut i talem se, “I gud. Bambae mi mekem olgeta samting ya we yu yu talem.”"],[3,6,"Nao hem i go swim, i putum senta, i putum klos blong hem, nao i go haed klosap long ples ya we oltaem oli stap klinimaot ol kakae blong bale long hem, olsem we Nomi i talem.","Nao hem i go swim, i putum senta, i putum klos blong hem, nao i go haed klosap long ples ya we oltaem oli stap klinimaot ol kakae blong bale long hem, olsem we Nomi i talem."],[3,7,"Taem Boas i kakae, mo i dring gogo i harem gud, hem i go slip klosap long hip blong bale. Nao Rut i wokbaot smosmol i go, i tekemaot blangket long leg blong Boas, nao i ledaon klosap long leg blong hem.","Taem Boas i kakae, mo i dring gogo i harem gud, hem i go slip klosap long hip blong bale. Nao Rut i wokbaot smosmol i go, i tekemaot blangket long leg blong Boas, nao i ledaon klosap long leg blong hem."],[3,8,"Long medel naet, man ya i sek, i wekap, i tanem hem, nao i sapraes blong luk we wan woman i stap ledaon klosap long leg blong hem,","Long medel naet, man ya i sek, i wekap, i tanem hem, nao i sapraes blong luk we wan woman i stap ledaon klosap long leg blong hem,"],[3,9,"nao hem i talem se, “!Ei! ?Hu ya?” Nao woman ya i talem se, “Mi Rut ya, woman blong wok blong yu. Yu yu wan famle blong man blong mi, mo i stret blong yu tekem mi. Plis yu tekem mi, mi woman blong yu.”","nao hem i talem se, “!Ei! ?Hu ya?” Nao woman ya i talem se, “Mi Rut ya, woman blong wok blong yu. Yu yu wan famle blong man blong mi, mo i stret blong yu tekem mi. Plis yu tekem mi, mi woman blong yu.”"],[3,10,"Nao hem i talem se, “Rut. Prea blong mi we Hae God bambae i blesem yu, from we fasin ya we yu mekem naoia, i gudfala moa, i winim ol samting we yu mekem long mama blong man blong yu. Yu yu no go blong faenem wan yang man we i rijman no i puaman, blong yu mared long hem, be yu ona long famle blong mifala.","Nao hem i talem se, “Rut. Prea blong mi we Hae God bambae i blesem yu, from we fasin ya we yu mekem naoia, i gudfala moa, i winim ol samting we yu mekem long mama blong man blong yu. Yu yu no go blong faenem wan yang man we i rijman no i puaman, blong yu mared long hem, be yu ona long famle blong mifala."],[3,11,"Yu no fraet. Olgeta man long ples ya oli save we yu yu wan gudfala woman. Bambae mi mekem olgeta samting ya we yu talem.","Yu no fraet. Olgeta man long ples ya oli save we yu yu wan gudfala woman. Bambae mi mekem olgeta samting ya we yu talem."],[3,12,"I tru we mi mi wan famle blong man blong yu, be i gat wan man i stap, we i klosap moa long man blong yu, i winim mi.","I tru we mi mi wan famle blong man blong yu, be i gat wan man i stap, we i klosap moa long man blong yu, i winim mi."],[3,13,"I gud yu stap long ples ya go kasem moning, nao long moning bambae mi traem askem long hem. Sipos hem i glad blong tekem yu blong lukaot long yu, bambae i olsem. Be sipos no, mi talem tru long yu long nem blong Hae God ya we i laef, i stap we i stap, se mi bambae mi tekem yu, mi lukaot long yu. Yu save stap long ples ya go kasem moning.”","I gud yu stap long ples ya go kasem moning, nao long moning bambae mi traem askem long hem. Sipos hem i glad blong tekem yu blong lukaot long yu, bambae i olsem. Be sipos no, mi talem tru long yu long nem blong Hae God ya we i laef, i stap we i stap, se mi bambae mi tekem yu, mi lukaot long yu. Yu save stap long ples ya go kasem moning.”"],[3,14,"Nao hem i slip long ples ya, klosap long leg blong man ya, go kasem moning. Be taem i haftudak yet, hem i girap, from we Boas i fraet se i nogud man i save we woman ya i kam stap long ples ya.","Nao hem i slip long ples ya, klosap long leg blong man ya, go kasem moning. Be taem i haftudak yet, hem i girap, from we Boas i fraet se i nogud man i save we woman ya i kam stap long ples ya."],[3,15,"Nao Boas i talem long hem se, “Yu tekemaot longfala kot ya blong yu, yu stretem long ples ya, blong mi kafsaedem sam bale i go long hem.” Nao hem i mekem olsem, mo Boas i kafsaedem bale i go long hem we klosap i kasem twanti kilo. Nao hem i givhan long Rut blong i leftemap kot ya we i fulap long bale, nao Rut i karem, i gobak long taon.","Nao Boas i talem long hem se, “Yu tekemaot longfala kot ya blong yu, yu stretem long ples ya, blong mi kafsaedem sam bale i go long hem.” Nao hem i mekem olsem, mo Boas i kafsaedem bale i go long hem we klosap i kasem twanti kilo. Nao hem i givhan long Rut blong i leftemap kot ya we i fulap long bale, nao Rut i karem, i gobak long taon."],[3,16,"Nao taem hem i kamtru long haos, Nomi i askem long hem se, “Dota blong mi. ?Olsem wanem?” Nao hem i talem long hem se, “O, man ya i kaen tumas long mi, mo hem i promes se bambae i stretem bisnes blong mared blong mi.","Nao taem hem i kamtru long haos, Nomi i askem long hem se, “Dota blong mi. ?Olsem wanem?” Nao hem i talem long hem se, “O, man ya i kaen tumas long mi, mo hem i promes se bambae i stretem bisnes blong mared blong mi."],[3,17,"Mo hem i givim bale ya long mi, from we i talem se, ‘I nogud yu gobak long mama blong man blong yu, we yu no gat samting long han blong yu.’ ”","Mo hem i givim bale ya long mi, from we i talem se, ‘I nogud yu gobak long mama blong man blong yu, we yu no gat samting long han blong yu.’ ”"],[3,18,"Nao Nomi i talem long hem se, “I gud yumi wet nomo blong luk ol samting we bambae i kamtru, from we man ya bambae i no save sidaon, gogo i stretem bisnes ya tede.”","Nao Nomi i talem long hem se, “I gud yumi wet nomo blong luk ol samting we bambae i kamtru, from we man ya bambae i no save sidaon, gogo i stretem bisnes ya tede.”"],[4,1,"Nao Boas i go long bigfala doa* blong stonwol blong taon ya, we i ples we ol man oli mekem miting long hem, nao i sidaon i wet. Nao i no longtaem, famle ya blong Elimelek we i klosap moa long Elimelek i winim hem, we hem i bin tokbaot finis long Rut, hem i pas long ples ya. Nao hem i talem long man ya se, “Ei, brata. Yu kam sidaon long ples ya.” Mo man ya i kam sidaon wetem hem.","Nao Boas i go long bigfala doa* blong stonwol blong taon ya, we i ples we ol man oli mekem miting long hem, nao i sidaon i wet. Nao i no longtaem, famle ya blong Elimelek we i klosap moa long Elimelek i winim hem, we hem i bin tokbaot finis long Rut, hem i pas long ples ya. Nao hem i talem long man ya se, “Ei, brata. Yu kam sidaon long ples ya.” Mo man ya i kam sidaon wetem hem."],[4,2,"Nao hem i singaot ten lida blong olgeta long taon ya, i talem long olgeta se, “Plis, yufala i kam sidaon long ples ya.” Nao olgeta oli kam sidaon,","Nao hem i singaot ten lida blong olgeta long taon ya, i talem long olgeta se, “Plis, yufala i kam sidaon long ples ya.” Nao olgeta oli kam sidaon,"],[4,3,"mo hem i talem long man ya se, “Nomi i aot long Moab, i kambak long ples ya finis, mo hem i wantem salem pis graon ya we i blong Elimelek ya we i famle blong yumi.","mo hem i talem long man ya se, “Nomi i aot long Moab, i kambak long ples ya finis, mo hem i wantem salem pis graon ya we i blong Elimelek ya we i famle blong yumi."],[4,4,"Nao mi mi wantem talemaot long yu, se sipos yu wantem pis graon ya, i gud yu pemaot long fes blong ol man ya we oli stap sidaon long ples ya, mo long fes blong ol lida ya blong yumi. Sipos yu wantem, i gud yu pemaot. Be sipos yu no wantem, i gud yu talemaot long mi blong mi save, from we yu yu fas man we yu gat raet blong pemaot, be sipos yu yu no pem, mi mi seken man we mi gat raet blong pemaot.” Nao man ya i talem se, “Mi bambae mi pemaot.”","Nao mi mi wantem talemaot long yu, se sipos yu wantem pis graon ya, i gud yu pemaot long fes blong ol man ya we oli stap sidaon long ples ya, mo long fes blong ol lida ya blong yumi. Sipos yu wantem, i gud yu pemaot. Be sipos yu no wantem, i gud yu talemaot long mi blong mi save, from we yu yu fas man we yu gat raet blong pemaot, be sipos yu yu no pem, mi mi seken man we mi gat raet blong pemaot.” Nao man ya i talem se, “Mi bambae mi pemaot.”"],[4,5,"Nao hem i talem se, “Oraet, sipos yu pemaot graon ya long Nomi, semtaem nomo bambae yu tekem woman Moab ya Rut, we i wido blong man ya we i ded. Long fasin ya, bambae i gat pikinini blong karem nem blong man ya bakegen, long graon blong hem.”","Nao hem i talem se, “Oraet, sipos yu pemaot graon ya long Nomi, semtaem nomo bambae yu tekem woman Moab ya Rut, we i wido blong man ya we i ded. Long fasin ya, bambae i gat pikinini blong karem nem blong man ya bakegen, long graon blong hem.”"],[4,6,"Nao man ya i talem se, “Sipos i olsem, mi mi no save yusum raet blong mi blong pemaot graon ya, from we bambae i spolem ol bisnes blong graon blong mi. I gud yu tekem ples blong mi, yu pemaot graon ya. Mi mi no save tekem.”","Nao man ya i talem se, “Sipos i olsem, mi mi no save yusum raet blong mi blong pemaot graon ya, from we bambae i spolem ol bisnes blong graon blong mi. I gud yu tekem ples blong mi, yu pemaot graon ya. Mi mi no save tekem.”"],[4,7,"Long kastom blong yumi bifo, taem we man i pemaot graon long narafala man, no tufala i jenjenisim graon blong tufala, i gat wan fasin i stap blong makem bisnes ya. Oltaem, man we i salem graon i mas tekemaot sandel blong hem, i givim long man we i pemaot graon ya, blong soemaot we ol bisnes blong graon ya i stret.","Long kastom blong yumi bifo, taem we man i pemaot graon long narafala man, no tufala i jenjenisim graon blong tufala, i gat wan fasin i stap blong makem bisnes ya. Oltaem, man we i salem graon i mas tekemaot sandel blong hem, i givim long man we i pemaot graon ya, blong soemaot we ol bisnes blong graon ya i stret."],[4,8,"Nao taem man ya i talem long Boas se, “I gud yu yu pemaot graon ya,” hem i tekemaot sandel blong hem, i givim long Boas.","Nao taem man ya i talem long Boas se, “I gud yu yu pemaot graon ya,” hem i tekemaot sandel blong hem, i givim long Boas."],[4,9,"Nao Boas i talem long ol lida blong olgeta mo long ol narafala man blong ples ya se, “Yufala evriwan i witnes blong mi. Tede, mi mi pemaot olgeta samting ya long Nomi. Naoia, olgeta samting we i blong Elimelek, mo blong Kilion, mo blong Malon oli blong mi.","Nao Boas i talem long ol lida blong olgeta mo long ol narafala man blong ples ya se, “Yufala evriwan i witnes blong mi. Tede, mi mi pemaot olgeta samting ya long Nomi. Naoia, olgeta samting we i blong Elimelek, mo blong Kilion, mo blong Malon oli blong mi."],[4,10,"Mo woman Moab ya Rut, we i wido blong Malon, mi pemaot hem blong i kam woman blong mi, blong bambae i gat pikinini blong karem nem blong man ya bakegen long graon ya blong hem. Nao nem blong dedman ya bambae i no save lus long fes blong ol brata blong hem, mo long fes blong yumi evriwan long ples ya blong hem. Tede, yufala evriwan i witnes blong mi long bisnes ya.”","Mo woman Moab ya Rut, we i wido blong Malon, mi pemaot hem blong i kam woman blong mi, blong bambae i gat pikinini blong karem nem blong man ya bakegen long graon ya blong hem. Nao nem blong dedman ya bambae i no save lus long fes blong ol brata blong hem, mo long fes blong yumi evriwan long ples ya blong hem. Tede, yufala evriwan i witnes blong mi long bisnes ya.”"],[4,11,"Mo ol lida wetem ol narafala man long ples ya oli talem se, “Yes, i gud. Mifala i witnes blong yu. Prea blong mifala we Hae God bambae i mekem we woman ya we i kam long haos blong yu, bambae i olsem Rejel mo Lea bifo, we tufala i bonem ol pikinini blong Jekob* ya bifo, we yumi kamaot biaen long hem. Nao bambae yu yu kam wan rijman, mo yu kam wan haeman long taon ya blong yumi.","Mo ol lida wetem ol narafala man long ples ya oli talem se, “Yes, i gud. Mifala i witnes blong yu. Prea blong mifala we Hae God bambae i mekem we woman ya we i kam long haos blong yu, bambae i olsem Rejel mo Lea bifo, we tufala i bonem ol pikinini blong Jekob* ya bifo, we yumi kamaot biaen long hem. Nao bambae yu yu kam wan rijman, mo yu kam wan haeman long taon ya blong yumi."],[4,12,"Ol pikinini we Hae God bambae i givim long yutufala, bambae oli mekem famle blong yu i olsem famle blong Peres, we papa blong hem Juda* ya bifo, mo mama blong hem Tamara.”","Ol pikinini we Hae God bambae i givim long yutufala, bambae oli mekem famle blong yu i olsem famle blong Peres, we papa blong hem Juda* ya bifo, mo mama blong hem Tamara.”"],[4,13,"Nao Boas i tekem Rut i go long ples blong hem, mo tufala i mared. Mo Hae God i blesem woman ya, nao hem i gat bel, mo i bonem wan boe.","Nao Boas i tekem Rut i go long ples blong hem, mo tufala i mared. Mo Hae God i blesem woman ya, nao hem i gat bel, mo i bonem wan boe."],[4,14,"Nao ol woman oli talem long Nomi se, “!Nomi! !Yumi presem Hae God! Tede hem i givim wan smol bubu blong yu long Rut, blong bambae i lukaot long yu. Pikinini ya bambae i kam wan haeman blong yumi ol laen* blong Isrel.*","Nao ol woman oli talem long Nomi se, “!Nomi! !Yumi presem Hae God! Tede hem i givim wan smol bubu blong yu long Rut, blong bambae i lukaot long yu. Pikinini ya bambae i kam wan haeman blong yumi ol laen* blong Isrel.*"],[4,15,"Hem bambae i mekem laef blong yu i kam niuwan bakegen, mo taem yu kam olfala, hem bambae i lukaot long yu. Woman ya we i bonem hem, hem i lavem yu tumas. Sipos yu gat seven pikinini boe blong yu blong givhan long yu, be bambae oli no save givhan gud long yu, olsem we woman ya i mekem.”","Hem bambae i mekem laef blong yu i kam niuwan bakegen, mo taem yu kam olfala, hem bambae i lukaot long yu. Woman ya we i bonem hem, hem i lavem yu tumas. Sipos yu gat seven pikinini boe blong yu blong givhan long yu, be bambae oli no save givhan gud long yu, olsem we woman ya i mekem.”"],[4,16,"Nao Nomi i tekem pikinini ya, i karem hem, nao i stap lukaot long hem.","Nao Nomi i tekem pikinini ya, i karem hem, nao i stap lukaot long hem."],[4,17,"Nao ol woman ples blong hem oli putum nem blong pikinini ya se Obed, mo oli stap talem se, “Naoia, Nomi i gat wan pikinini blong hem.” Obed ya, hem i papa blong Jese, mo Jese i papa blong King Deved.","Nao ol woman ples blong hem oli putum nem blong pikinini ya se Obed, mo oli stap talem se, “Naoia, Nomi i gat wan pikinini blong hem.” Obed ya, hem i papa blong Jese, mo Jese i papa blong King Deved."],[4,18,"Ol laen blong Peres ya bifo i olsem. Peres i bonem Hesron,","Ol laen blong Peres ya bifo i olsem. Peres i bonem Hesron,"],[4,19,"mo Hesron i bonem Ram, mo Ram i bonem Aminadab,","mo Hesron i bonem Ram, mo Ram i bonem Aminadab,"],[4,20,"mo Aminadab i bonem Nason, mo Nason i bonem Salmon,","mo Aminadab i bonem Nason, mo Nason i bonem Salmon,"],[4,21,"mo Salmon i bonem Boas, mo Boas i bonem Obed,","mo Salmon i bonem Boas, mo Boas i bonem Obed,"],[4,22,"mo Obed i bonem Jese, mo Jese i bonem Deved.","mo Obed i bonem Jese, mo Jese i bonem Deved."]],"hbo-wlc":[[1,1,"וַיְהִ֗י בִּימֵי֙ שְׁפֹ֣ט הַשֹּׁפְטִ֔ים וַיְהִ֥י רָעָ֖ב בָּאָ֑רֶץ וַיֵּ֨לֶךְ אִ֜ישׁ מִבֵּ֧ית לֶ֣חֶם יְהוּדָ֗ה לָגוּר֙ בִּשְׂדֵ֣י מוֹאָ֔ב ה֥וּא וְאִשְׁתּ֖וֹ וּשְׁנֵ֥י בָנָֽיו׃","wayĕhi֗y bi̇yméy֙ şĕ̌pò֣t haşò̇̌pĕti֔ym wayĕhi֥y ráʻá֖b bá̇ʼá֑reẕ wayé̇֨lekĕ ʼi֜yş̌ mibé֧̇yţ le֣ẖem yĕhẇdá֗h lágẇr֙ bi̇şĕ̂dé֣y mwòʼá֔b h֥ẇʼ wĕʼişĕ̌ţ֖̇wò ẇşĕ̌né֥y bánáֽyw׃"],[1,2,"וְשֵׁ֣ם הָאִ֣ישׁ אֱֽלִימֶ֡לֶךְ וְשֵׁם֩ אִשְׁתּ֨וֹ נָעֳמִ֜י וְשֵׁ֥ם שְׁנֵֽי־בָנָ֣יו ׀ מַחְל֤וֹן וְכִלְיוֹן֙ אֶפְרָתִ֔ים מִבֵּ֥ית לֶ֖חֶם יְהוּדָ֑ה וַיָּבֹ֥אוּ שְׂדֵי־מוֹאָ֖ב וַיִּֽהְיוּ־שָֽׁם׃","wĕşé֣̌m háʼi֣yş̌ ʼèֽliyme֡lekĕ wĕşé̌m֩ ʼişĕ̌ţ̇֨wò náʻomi֜y wĕşé֥̌m şĕ̌néֽy-báná֣yw ׀ maẖĕl֤wòn wĕkilĕywòn֙ ʼepĕráţi֔ym mibé֥̇yţ le֖ẖem yĕhẇdá֑h wayá̇bò֥ʼẇ şĕ̂déy-mwòʼá֖b wayiֽ̇hĕyẇ-şáֽ̌m׃"],[1,3,"וַיָּ֥מָת אֱלִימֶ֖לֶךְ אִ֣ישׁ נָעֳמִ֑י וַתִּשָּׁאֵ֥ר הִ֖יא וּשְׁנֵ֥י בָנֶֽיהָ׃","wayá֥̇máţ ʼèliyme֖lekĕ ʼi֣yş̌ náʻomi֑y waţi̇şá̇̌ʼé֥r hi֖yʼ ẇşĕ̌né֥y báneֽyhá׃"],[1,4,"וַיִּשְׂא֣וּ לָהֶ֗ם נָשִׁים֙ מֹֽאֲבִיּ֔וֹת שֵׁ֤ם הָֽאַחַת֙ עָרְפָּ֔ה וְשֵׁ֥ם הַשֵּׁנִ֖ית ר֑וּת וַיֵּ֥שְׁבוּ שָׁ֖ם כְּעֶ֥שֶׂר שָׁנִֽים׃","wayi̇şĕ̂ʼ֣ẇ láhe֗m náşǐym֙ mòֽʼàbiẏ֔wòţ şé֤̌m háֽʼaẖaţ֙ ʻárĕpá̇֔h wĕşé֥̌m haşé̇̌ni֖yţ r֑ẇţ wayé֥̇şĕ̌bẇ şá֖̌m kĕ̇ʻe֥şêr şá̌niֽym׃"],[1,5,"וַיָּמ֥וּתוּ גַם־שְׁנֵיהֶ֖ם מַחְל֣וֹן וְכִלְי֑וֹן וַתִּשָּׁאֵר֙ הָֽאִשָּׁ֔ה מִשְּׁנֵ֥י יְלָדֶ֖יהָ וּמֵאִישָֽׁהּ׃","wayá̇m֥ẇţẇ gam-şĕ̌néyhe֖m maẖĕl֣wòn wĕkilĕy֑wòn waţi̇şá̇̌ʼér֙ háֽʼişá̇̌֔h mişĕ̇̌né֥y yĕláde֖yhá ẇméʼiyşáֽ̌ḣ׃"],[1,6,"וַתָּ֤קָם הִיא֙ וְכַלֹּתֶ֔יהָ וַתָּ֖שָׁב מִשְּׂדֵ֣י מוֹאָ֑ב כִּ֤י שָֽׁמְעָה֙ בִּשְׂדֵ֣ה מוֹאָ֔ב כִּֽי־פָקַ֤ד יְהוָה֙ אֶת־עַמּ֔וֹ לָתֵ֥ת לָהֶ֖ם לָֽחֶם׃","waţá֤̇qám hiyʼ֙ wĕkalò̇ţe֔yhá waţá֖̇şá̌b mişĕ̇̂dé֣y mwòʼá֑b ki֤̇y şáֽ̌mĕʻáh֙ bi̇şĕ̂dé֣h mwòʼá֔b kiֽ̇y-páqa֤d yĕhwáh֙ ʼeţ-ʻaṁ֔wò láţé֥ţ láhe֖m láֽẖem׃"],[1,7,"וַתֵּצֵ֗א מִן־הַמָּקוֹם֙ אֲשֶׁ֣ר הָיְתָה־שָׁ֔מָּה וּשְׁתֵּ֥י כַלֹּתֶ֖יהָ עִמָּ֑הּ וַתֵּלַ֣כְנָה בַדֶּ֔רֶךְ לָשׁ֖וּב אֶל־אֶ֥רֶץ יְהוּדָֽה׃","waţé̇ẕé֗ʼ min-hamá̇qwòm֙ ʼàşě֣r háyĕţáh-şá̌֔má̇h ẇşĕ̌ţé֥̇y kalò̇ţe֖yhá ʻimá֑̇ḣ waţé̇la֣kĕnáh badė֔rekĕ láş֖̌ẇb ʼel-ʼe֥reẕ yĕhẇdáֽh׃"],[1,8,"וַתֹּ֤אמֶר נָעֳמִי֙ לִשְׁתֵּ֣י כַלֹּתֶ֔יהָ לֵ֣כְנָה שֹּׁ֔בְנָה אִשָּׁ֖ה לְבֵ֣ית אִמָּ֑הּ יעשה יְהוָ֤ה עִמָּכֶם֙ חֶ֔סֶד כַּאֲשֶׁ֧ר עֲשִׂיתֶ֛ם עִם־הַמֵּתִ֖ים וְעִמָּדִֽי׃","waţò֤̇ʼmer náʻomiy֙ lişĕ̌ţé֣̇y kalò̇ţe֔yhá lé֣kĕnáh şò̇̌֔bĕnáh ʼişá֖̇̌h lĕbé֣yţ ʼimá֑̇ḣ yʻşh yĕhwá֤h ʻimá̇kem֙ ẖe֔sed kȧʼàşě֧r ʻàşîyţe֛m ʻim-hamé̇ţi֖ym wĕʻimá̇diֽy׃"],[1,9,"יִתֵּ֤ן יְהוָה֙ לָכֶ֔ם וּמְצֶ֣אןָ מְנוּחָ֔ה אִשָּׁ֖ה בֵּ֣ית אִישָׁ֑הּ וַתִּשַּׁ֣ק לָהֶ֔ן וַתִּשֶּׂ֥אנָה קוֹלָ֖ן וַתִּבְכֶּֽינָה׃","yiţé֤̇n yĕhwáh֙ láke֔m ẇmĕẕe֣ʼná mĕnẇẖá֔h ʼişá֖̇̌h bé֣̇yţ ʼiyşá֑̌ḣ waţi̇şȧ֣̌q láhe֔n waţi̇şė֥̂ʼnáh qwòlá֖n waţi̇bĕkėֽynáh׃"],[1,10,"וַתֹּאמַ֖רְנָה־לָּ֑הּ כִּי־אִתָּ֥ךְ נָשׁ֖וּב לְעַמֵּֽךְ ׃","waţò̇ʼma֖rĕnáh-lá֑̇ḣ ki̇y-ʼiţá֥̇kĕ náş֖̌ẇb lĕʻaméֽ̇kĕ ׃"],[1,11,"וַתֹּ֤אמֶר נָעֳמִי֙ שֹׁ֣בְנָה בְנֹתַ֔י לָ֥מָּה תֵלַ֖כְנָה עִמִּ֑י הַֽעֽוֹד־לִ֤י בָנִים֙ בְּֽמֵעַ֔י וְהָי֥וּ לָכֶ֖ם לַאֲנָשִֽׁים׃","waţò֤̇ʼmer náʻomiy֙ şò֣̌bĕnáh bĕnòţa֔y lá֥má̇h ţéla֖kĕnáh ʻimi֑̇y haֽʻֽwòd-li֤y bániym֙ bĕֽ̇méʻa֔y wĕháy֥ẇ láke֖m laʼànáşǐֽym׃"],[1,12,"שֹׁ֤בְנָה בְנֹתַי֙ לֵ֔כְןָ כִּ֥י זָקַ֖נְתִּי מִהְי֣וֹת לְאִ֑ישׁ כִּ֤י אָמַ֙רְתִּי֙ יֶשׁ־לִ֣י תִקְוָ֔ה גַּ֣ם הָיִ֤יתִי הַלַּ֙יְלָה֙ לְאִ֔ישׁ וְגַ֖ם יָלַ֥דְתִּי בָנִֽים׃","şò֤̌bĕnáh bĕnòţay֙ lé֔kĕná ki֥̇y záqa֖nĕţi̇y mihĕy֣wòţ lĕʼi֑yş̌ ki֤̇y ʼáma֙rĕţi̇y֙ yeş̌-li֣y ţiqĕwá֔h gȧ֣m háyi֤yţiy halȧ֙yĕláh֙ lĕʼi֔yş̌ wĕga֖m yála֥dĕţi̇y bániֽym׃"],[1,13,"הֲלָהֵ֣ן ׀ תְּשַׂבֵּ֗רְנָה עַ֚ד אֲשֶׁ֣ר יִגְדָּ֔לוּ הֲלָהֵן֙ תֵּֽעָגֵ֔נָה לְבִלְתִּ֖י הֱי֣וֹת לְאִ֑ישׁ אַ֣ל בְּנֹתַ֗י כִּֽי־מַר־לִ֤י מְאֹד֙ מִכֶּ֔ם כִּֽי־יָצְאָ֥ה בִ֖י יַד־יְהוָֽה׃","hàláhé֣n ׀ ţĕ̇şâbé̇֗rĕnáh ʻa֚d ʼàşě֣r yigĕdá̇֔lẇ hàláhén֙ ţéֽ̇ʻágé֔náh lĕbilĕţi֖̇y hèy֣wòţ lĕʼi֑yş̌ ʼa֣l bĕ̇nòţa֗y kiֽ̇y-mar-li֤y mĕʼòd֙ mikė֔m kiֽ̇y-yáẕĕʼá֥h bi֖y yad-yĕhwáֽh׃"],[1,14,"וַתִּשֶּׂ֣נָה קוֹלָ֔ן וַתִּבְכֶּ֖ינָה ע֑וֹד וַתִּשַּׁ֤ק עָרְפָּה֙ לַחֲמוֹתָ֔הּ וְר֖וּת דָּ֥בְקָה בָּֽהּ׃","waţi̇şė֣̂náh qwòlá֔n waţi̇bĕkė֖ynáh ʻ֑wòd waţi̇şȧ֤̌q ʻárĕpá̇h֙ laẖàmwòţá֔ḣ wĕr֖ẇţ dá֥̇bĕqáh báֽ̇ḣ׃"],[1,15,"וַתֹּ֗אמֶר הִנֵּה֙ שָׁ֣בָה יְבִמְתֵּ֔ךְ אֶל־עַמָּ֖הּ וְאֶל־אֱלֹהֶ֑יהָ שׁ֖וּבִי אַחֲרֵ֥י יְבִמְתֵּֽךְ׃","waţò̇֗ʼmer hiné̇h֙ şá֣̌báh yĕbimĕţé̇֔kĕ ʼel-ʻamá֖̇ḣ wĕʼel-ʼèlòhe֑yhá ş֖̌ẇbiy ʼaẖàré֥y yĕbimĕţéֽ̇kĕ׃"],[1,16,"וַתֹּ֤אמֶר רוּת֙ אַל־תִּפְגְּעִי־בִ֔י לְעָזְבֵ֖ךְ לָשׁ֣וּב מֵאַחֲרָ֑יִךְ כִּ֠י אֶל־אֲשֶׁ֨ר תֵּלְכִ֜י אֵלֵ֗ךְ וּבַאֲשֶׁ֤ר תָּלִ֙ינִי֙ אָלִ֔ין עַמֵּ֣ךְ עַמִּ֔י וֵאלֹהַ֖יִךְ אֱלֹהָֽי׃","waţò֤̇ʼmer rẇţ֙ ʼal-ţi̇pĕgĕ̇ʻiy-bi֔y lĕʻázĕbé֖kĕ láş֣̌ẇb méʼaẖàrá֑yikĕ ki̇֠y ʼel-ʼàşě֨r ţé̇lĕki֜y ʼélé֗kĕ ẇbaʼàşě֤r ţá̇li֙yniy֙ ʼáli֔yn ʻamé֣̇kĕ ʻami̇֔y wéʼlòha֖yikĕ ʼèlòháֽy׃"],[1,17,"בַּאֲשֶׁ֤ר תָּמ֙וּתִי֙ אָמ֔וּת וְשָׁ֖ם אֶקָּבֵ֑ר כֹּה֩ יַעֲשֶׂ֨ה יְהוָ֥ה לִי֙ וְכֹ֣ה יֹסִ֔יף כִּ֣י הַמָּ֔וֶת יַפְרִ֖יד בֵּינִ֥י וּבֵינֵֽךְ׃","bȧʼàşě֤r ţá̇m֙ẇţiy֙ ʼám֔ẇţ wĕşá֖̌m ʼeqá̇bé֑r kò̇h֩ yaʻàşê֨h yĕhwá֥h liy֙ wĕkò֣h yòsi֔yp ki֣̇y hamá̇֔weţ yapĕri֖yd bé̇yni֥y ẇbéynéֽkĕ׃"],[1,18,"וַתֵּ֕רֶא כִּֽי־מִתְאַמֶּ֥צֶת הִ֖יא לָלֶ֣כֶת אִתָּ֑הּ וַתֶּחְדַּ֖ל לְדַבֵּ֥ר אֵלֶֽיהָ׃","waţé̇֕reʼ kiֽ̇y-miţĕʼamė֥ẕeţ hi֖yʼ lále֣keţ ʼiţá֑̇ḣ waţėẖĕdȧ֖l lĕdabé֥̇r ʼéleֽyhá׃"],[1,19,"וַתֵּלַ֣כְנָה שְׁתֵּיהֶ֔ם עַד־בֹּאָ֖נָה בֵּ֣ית לָ֑חֶם וַיְהִ֗י כְּבֹאָ֙נָה֙ בֵּ֣ית לֶ֔חֶם וַתֵּהֹ֤ם כָּל־הָעִיר֙ עֲלֵיהֶ֔ן וַתֹּאמַ֖רְנָה הֲזֹ֥את נָעֳמִֽי׃","waţé̇la֣kĕnáh şĕ̌ţé̇yhe֔m ʻad-bò̇ʼá֖náh bé֣̇yţ lá֑ẖem wayĕhi֗y kĕ̇bòʼá֙náh֙ bé֣̇yţ le֔ẖem waţé̇hò֤m ká̇l-háʻiyr֙ ʻàléyhe֔n waţò̇ʼma֖rĕnáh hàzò֥ʼţ náʻomiֽy׃"],[1,20,"וַתֹּ֣אמֶר אֲלֵיהֶ֔ן אַל־תִּקְרֶ֥אנָה לִ֖י נָעֳמִ֑י קְרֶ֤אןָ לִי֙ מָרָ֔א כִּי־הֵמַ֥ר שַׁדַּ֛י לִ֖י מְאֹֽד׃","waţò֣̇ʼmer ʼàléyhe֔n ʼal-ţi̇qĕre֥ʼnáh li֖y náʻomi֑y qĕre֤ʼná liy֙ márá֔ʼ ki̇y-héma֥r şǎdȧ֛y li֖y mĕʼòֽd׃"],[1,21,"אֲנִי֙ מְלֵאָ֣ה הָלַ֔כְתִּי וְרֵיקָ֖ם הֱשִׁיבַ֣נִי יְהוָ֑ה לָ֣מָּה תִקְרֶ֤אנָה לִי֙ נָעֳמִ֔י וַֽיהוָה֙ עָ֣נָה בִ֔י וְשַׁדַּ֖י הֵ֥רַֽע לִֽי׃","ʼàniy֙ mĕléʼá֣h hála֔kĕţi̇y wĕréyqá֖m hèşǐyba֣niy yĕhwá֑h lá֣má̇h ţiqĕre֤ʼnáh liy֙ náʻomi֔y waֽyhwáh֙ ʻá֣náh bi֔y wĕşǎdȧ֖y hé֥raֽʻ liֽy׃"],[1,22,"וַתָּ֣שָׁב נָעֳמִ֗י וְר֨וּת הַמּוֹאֲבִיָּ֤ה כַלָּתָהּ֙ עִמָּ֔הּ הַשָּׁ֖בָה מִשְּׂדֵ֣י מוֹאָ֑ב וְהֵ֗מָּה בָּ֚אוּ בֵּ֣ית לֶ֔חֶם בִּתְחִלַּ֖ת קְצִ֥יר שְׂעֹרִֽים׃","waţá֣̇şá̌b náʻomi֗y wĕr֨ẇţ haṁwòʼàbiyá֤̇h kalá̇ţáḣ֙ ʻimá̇֔ḣ haşá֖̇̌báh mişĕ̇̂dé֣y mwòʼá֑b wĕhé֗má̇h bá֚̇ʼẇ bé֣̇yţ le֔ẖem bi̇ţĕẖilȧ֖ţ qĕẕi֥yr şĕ̂ʻòriֽym׃"],[2,1,"וּֽלְנָעֳמִ֞י מידע לְאִישָׁ֗הּ אִ֚ישׁ גִּבּ֣וֹר חַ֔יִל מִמִּשְׁפַּ֖חַת אֱלִימֶ֑לֶךְ וּשְׁמ֖וֹ בֹּֽעַז׃","ẇֽlĕnáʻomi֞y mydʻ lĕʼiyşá̌֗ḣ ʼi֚yş̌ gi̇ḃ֣wòr ẖa֔yil mimi̇şĕ̌pȧ֖ẖaţ ʼèliyme֑lekĕ ẇşĕ̌m֖wò bòֽ̇ʻaz׃"],[2,2,"וַתֹּאמֶר֩ ר֨וּת הַמּוֹאֲבִיָּ֜ה אֶֽל־נָעֳמִ֗י אֵֽלְכָה־נָּ֤א הַשָּׂדֶה֙ וַאֲלַקֳטָּ֣ה בַשִׁבֳּלִ֔ים אַחַ֕ר אֲשֶׁ֥ר אֶמְצָא־חֵ֖ן בְּעֵינָ֑יו וַתֹּ֥אמֶר לָ֖הּ לְכִ֥י בִתִּֽי׃","waţò̇ʼmer֩ r֨ẇţ haṁwòʼàbiyá̇֜h ʼeֽl-náʻomi֗y ʼéֽlĕkáh-ná֤̇ʼ haşá̇̂deh֙ waʼàlaqotá֣̇h başǐbȯli֔ym ʼaẖa֕r ʼàşě֥r ʼemĕẕáʼ-ẖé֖n bĕ̇ʻéyná֑yw waţò֥̇ʼmer lá֖ḣ lĕki֥y biţiֽ̇y׃"],[2,3,"וַתֵּ֤לֶךְ וַתָּבוֹא֙ וַתְּלַקֵּ֣ט בַּשָּׂדֶ֔ה אַחֲרֵ֖י הַקֹּצְרִ֑ים וַיִּ֣קֶר מִקְרֶ֔הָ חֶלְקַ֤ת הַשָּׂדֶה֙ לְבֹ֔עַז אֲשֶׁ֖ר מִמִּשְׁפַּ֥חַת אֱלִימֶֽלֶךְ׃","waţé֤̇lekĕ waţá̇bwòʼ֙ waţĕ̇laqé֣̇t bȧşá̇̂de֔h ʼaẖàré֖y haqò̇ẕĕri֑ym wayi֣̇qer miqĕre֔há ẖelĕqa֤ţ haşá̇̂deh֙ lĕbò֔ʻaz ʼàşě֖r mimi̇şĕ̌pȧ֥ẖaţ ʼèliymeֽlekĕ׃"],[2,4,"וְהִנֵּה־בֹ֗עַז בָּ֚א מִבֵּ֣ית לֶ֔חֶם וַיֹּ֥אמֶר לַקּוֹצְרִ֖ים יְהוָ֣ה עִמָּכֶ֑ם וַיֹּ֥אמְרוּ ל֖וֹ יְבָרֶכְךָ֥ יְהוָֽה׃","wĕhiné̇h-bò֗ʻaz bá֚̇ʼ mibé֣̇yţ le֔ẖem wayò֥̇ʼmer laq̇wòẕĕri֖ym yĕhwá֣h ʻimá̇ke֑m wayò֥̇ʼmĕrẇ l֖wò yĕbárekĕká֥ yĕhwáֽh׃"],[2,5,"וַיֹּ֤אמֶר בֹּ֙עַז֙ לְנַעֲר֔וֹ הַנִּצָּ֖ב עַל־הַקּֽוֹצְרִ֑ים לְמִ֖י הַנַּעֲרָ֥ה הַזֹּֽאת׃","wayò֤̇ʼmer bò̇֙ʻaz֙ lĕnaʻàr֔wò hani̇ẕá֖̇b ʻal-haqֽ̇wòẕĕri֑ym lĕmi֖y hanȧʻàrá֥h hazòֽ̇ʼţ׃"],[2,6,"וַיַּ֗עַן הַנַּ֛עַר הַנִּצָּ֥ב עַל־הַקּוֹצְרִ֖ים וַיֹּאמַ֑ר נַעֲרָ֤ה מֽוֹאֲבִיָּה֙ הִ֔יא הַשָּׁ֥בָה עִֽם־נָעֳמִ֖י מִשְּׂדֵ֥ה מוֹאָֽב׃","wayȧ֗ʻan hanȧ֛ʻar hani̇ẕá֥̇b ʻal-haq̇wòẕĕri֖ym wayò̇ʼma֑r naʻàrá֤h mֽwòʼàbiyá̇h֙ hi֔yʼ haşá֥̇̌báh ʻiֽm-náʻomi֖y mişĕ̇̂dé֥h mwòʼáֽb׃"],[2,7,"וַתֹּ֗אמֶר אֲלַקֳטָה־נָּא֙ וְאָסַפְתִּ֣י בָֽעֳמָרִ֔ים אַחֲרֵ֖י הַקּוֹצְרִ֑ים וַתָּב֣וֹא וַֽתַּעֲמ֗וֹד מֵאָ֤ז הַבֹּ֙קֶר֙ וְעַד־עַ֔תָּה זֶ֛ה שִׁבְתָּ֥הּ הַבַּ֖יִת מְעָֽט׃","waţò̇֗ʼmer ʼàlaqotáh-ná̇ʼ֙ wĕʼásapĕţi֣̇y báֽʻomári֔ym ʼaẖàré֖y haq̇wòẕĕri֑ym waţá̇b֣wòʼ waֽţȧʻàm֗wòd méʼá֤z habò̇֙qer֙ wĕʻad-ʻa֔ţá̇h ze֛h şǐbĕţá֥̇ḣ habȧ֖yiţ mĕʻáֽt׃"],[2,8,"וַיֹּאמֶר֩ בֹּ֨עַז אֶל־ר֜וּת הֲל֧וֹא שָׁמַ֣עַתְּ בִּתִּ֗י אַל־תֵּלְכִי֙ לִלְקֹט֙ בְּשָׂדֶ֣ה אַחֵ֔ר וְגַ֛ם לֹ֥א תַעֲבוּרִ֖י מִזֶּ֑ה וְכֹ֥ה תִדְבָּקִ֖ין עִם־נַעֲרֹתָֽי׃","wayò̇ʼmer֩ bò̇֨ʻaz ʼel-r֜ẇţ hàl֧wòʼ şá̌ma֣ʻaţĕ̇ bi̇ţi̇֗y ʼal-ţé̇lĕkiy֙ lilĕqòt֙ bĕ̇şá̂de֣h ʼaẖé֔r wĕga֛m lò֥ʼ ţaʻàbẇri֖y mizė֑h wĕkò֥h ţidĕbá̇qi֖yn ʻim-naʻàròţáֽy׃"],[2,9,"עֵינַ֜יִךְ בַּשָּׂדֶ֤ה אֲשֶׁר־יִקְצֹרוּן֙ וְהָלַ֣כְתִּ אַחֲרֵיהֶ֔ן הֲל֥וֹא צִוִּ֛יתִי אֶת־הַנְּעָרִ֖ים לְבִלְתִּ֣י נָגְעֵ֑ךְ וְצָמִ֗ת וְהָלַכְתְּ֙ אֶל־הַכֵּלִ֔ים וְשָׁתִ֕ית מֵאֲשֶׁ֥ר יִשְׁאֲב֖וּן הַנְּעָרִֽים׃","ʻéyna֜yikĕ bȧşá̇̂de֤h ʼàşěr-yiqĕẕòrẇn֙ wĕhála֣kĕţi̇ ʼaẖàréyhe֔n hàl֥wòʼ ẕiwi֛̇yţiy ʼeţ-hanĕ̇ʻári֖ym lĕbilĕţi֣̇y nágĕʻé֑kĕ wĕẕámi֗ţ wĕhálakĕţĕ̇֙ ʼel-haké̇li֔ym wĕşá̌ţi֕yţ méʼàşě֥r yişĕ̌ʼàb֖ẇn hanĕ̇ʻáriֽym׃"],[2,10,"וַתִּפֹּל֙ עַל־פָּנֶ֔יהָ וַתִּשְׁתַּ֖חוּ אָ֑רְצָה וַתֹּ֣אמֶר אֵלָ֗יו מַדּוּעַ֩ מָצָ֨אתִי חֵ֤ן בְּעֵינֶ֙יךָ֙ לְהַכִּירֵ֔נִי וְאָּנֹכִ֖י נָכְרִיָּֽה׃","waţi̇pò̇l֙ ʻal-pá̇ne֔yhá waţi̇şĕ̌ţȧ֖ẖẇ ʼá֑rĕẕáh waţò֣̇ʼmer ʼélá֗yw maḋẇʻa֩ máẕá֨ʼţiy ẖé֤n bĕ̇ʻéyne֙yká֙ lĕhaki̇yré֔niy wĕʼá̇nòki֖y nákĕriyáֽ̇h׃"],[2,11,"וַיַּ֤עַן בֹּ֙עַז֙ וַיֹּ֣אמֶר לָ֔הּ הֻגֵּ֨ד הֻגַּ֜ד לִ֗י כֹּ֤ל אֲשֶׁר־עָשִׂית֙ אֶת־חֲמוֹתֵ֔ךְ אַחֲרֵ֖י מ֣וֹת אִישֵׁ֑ךְ וַתַּֽעַזְבִ֞י אָּבִ֣יךְ וְאִמֵּ֗ךְ וְאֶ֙רֶץ֙ מֽוֹלַדְתֵּ֔ךְ וַתֵּ֣לְכִ֔י אֶל־עַ֕ם אֲשֶׁ֥ר לֹא־יָדַ֖עַתְּ תְּמ֥וֹל שִׁלְשֽׁוֹם׃","wayȧ֤ʻan bò̇֙ʻaz֙ wayò֣̇ʼmer lá֔ḣ hugé̇֨d hugȧ֜d li֗y kò֤̇l ʼàşěr-ʻáşîyţ֙ ʼeţ-ẖàmwòţé֔kĕ ʼaẖàré֖y m֣wòţ ʼiyşé֑̌kĕ waţȧֽʻazĕbi֞y ʼá̇bi֣ykĕ wĕʼimé̇֗kĕ wĕʼe֙reẕ֙ mֽwòladĕţé̇֔kĕ waţé֣̇lĕki֔y ʼel-ʻa֕m ʼàşě֥r lòʼ-yáda֖ʻaţĕ̇ ţĕ̇m֥wòl şǐlĕşֽ̌wòm׃"],[2,12,"יְשַׁלֵּ֥ם יְהוָ֖ה פָּעֳלֵ֑ךְ וּתְהִ֨י מַשְׂכֻּרְתֵּ֜ךְ שְׁלֵמָ֗ה מֵעִ֤ם יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁר־בָּ֖את לַחֲס֥וֹת תַּֽחַת־כְּנָפָֽיו׃","yĕşǎlé֥̇m yĕhwá֖h pá̇ʻolé֑kĕ ẇţĕhi֨y maşĕ̂ku̇rĕţé̇֜kĕ şĕ̌lémá֗h méʻi֤m yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼàşěr-bá֖̇ʼţ laẖàs֥wòţ ţȧֽẖaţ-kĕ̇nápáֽyw׃"],[2,13,"וַ֠תֹּאמֶר אֶמְצָא־חֵ֨ן בְּעֵינֶ֤יךָ אֲדֹנִי֙ כִּ֣י נִֽחַמְתָּ֔נִי וְכִ֥י דִבַּ֖רְתָּ עַל־לֵ֣ב שִׁפְחָתֶ֑ךָ וְאָנֹכִי֙ לֹ֣א אֶֽהְיֶ֔ה כְּאַחַ֖ת שִׁפְחֹתֶֽיךָ ׃","wa֠ţò̇ʼmer ʼemĕẕáʼ-ẖé֨n bĕ̇ʻéyne֤yká ʼàdòniy֙ ki֣̇y niֽẖamĕţá̇֔niy wĕki֥y dibȧ֖rĕţá̇ ʻal-lé֣b şǐpĕẖáţe֑ká wĕʼánòkiy֙ lò֣ʼ ʼeֽhĕye֔h kĕ̇ʼaẖa֖ţ şǐpĕẖòţeֽyká ׃"],[2,14,"וַיֹּאמֶר֩ לָ֨ה בֹ֜עַז לְעֵ֣ת הָאֹ֗כֶל גֹּ֤שִֽׁי הֲלֹם֙ וְאָכַ֣לְתְּ מִן־הַלֶּ֔חֶם וְטָבַ֥לְתְּ פִּתֵּ֖ךְ בַּחֹ֑מֶץ וַתֵּ֙שֶׁב֙ מִצַּ֣ד הַקּֽוֹצְרִ֔ים וַיִּצְבָּט־לָ֣הּ קָלִ֔י וַתֹּ֥אכַל וַתִּשְׂבַּ֖ע וַתֹּתַֽר׃","wayò̇ʼmer֩ lá֨h bò֜ʻaz lĕʻé֣ţ háʼò֗kel gò֤̇şǐֽy hàlòm֙ wĕʼáka֣lĕţĕ̇ min-halė֔ẖem wĕtába֥lĕţĕ̇ pi̇ţé֖̇kĕ bȧẖò֑meẕ waţé̇֙şěb֙ miẕȧ֣d haqֽ̇wòẕĕri֔ym wayi̇ẕĕbá̇t-lá֣ḣ qáli֔y waţò֥̇ʼkal waţi̇şĕ̂bȧ֖ʻ waţò̇ţaֽr׃"],[2,15,"וַתָּ֖קָם לְלַקֵּ֑ט וַיְצַו֩ בֹּ֨עַז אֶת־נְעָרָ֜יו לֵאמֹ֗ר גַּ֣ם בֵּ֧ין הָֽעֳמָרִ֛ים תְּלַקֵּ֖ט וְלֹ֥א תַכְלִימֽוּהָ ׃","waţá֖̇qám lĕlaqé֑̇t wayĕẕaw֩ bò̇֨ʻaz ʼeţ-nĕʻárá֜yw léʼmò֗r gȧ֣m bé֧̇yn háֽʻomári֛ym ţĕ̇laqé֖̇t wĕlò֥ʼ ţakĕliymֽẇhá ׃"],[2,16,"וְגַ֛ם שֹׁל־תָּשֹׁ֥לּוּ לָ֖הּ מִן־הַצְּבָתִ֑ים וַעֲזַבְתֶּ֥ם וְלִקְּטָ֖ה וְלֹ֥א תִגְעֲרוּ־בָֽהּ׃","wĕga֛m şò̌l-ţá̇şò֥̌l̇ẇ lá֖ḣ min-haẕĕ̇báţi֑ym waʻàzabĕţė֥m wĕliqĕ̇tá֖h wĕlò֥ʼ ţigĕʻàrẇ-báֽḣ׃"],[2,17,"וַתְּלַקֵּ֥ט בַּשָּׂדֶ֖ה עַד־הָעָ֑רֶב וַתַּחְבֹּט֙ אֵ֣ת אֲשֶׁר־לִקֵּ֔טָה וַיְהִ֖י כְּאֵיפָ֥ה שְׂעֹרִֽים׃","waţĕ̇laqé֥̇t bȧşá̇̂de֖h ʻad-háʻá֑reb waţȧẖĕbò̇t֙ ʼé֣ţ ʼàşěr-liqé̇֔táh wayĕhi֖y kĕ̇ʼéypá֥h şĕ̂ʻòriֽym׃"],[2,18,"וַתִּשָּׂא֙ וַתָּב֣וֹא הָעִ֔יר וַתֵּ֥רֶא חֲמוֹתָ֖הּ אֵ֣ת אֲשֶׁר־לִקֵּ֑טָה וַתּוֹצֵא֙ וַתִּתֶּן־לָ֔הּ אֵ֥ת אֲשֶׁר־הוֹתִ֖רָה מִשָּׂבְעָֽהּ׃","waţi̇şá̇̂ʼ֙ waţá̇b֣wòʼ háʻi֔yr waţé֥̇reʼ ẖàmwòţá֖ḣ ʼé֣ţ ʼàşěr-liqé֑̇táh waţ̇wòẕéʼ֙ waţi̇ţėn-lá֔ḣ ʼé֥ţ ʼàşěr-hwòţi֖ráh mişá̇̂bĕʻáֽḣ׃"],[2,19,"וַתֹּאמֶר֩ לָ֨הּ חֲמוֹתָ֜הּ אֵיפֹ֨ה לִקַּ֤טְתְּ הַיּוֹם֙ וְאָ֣נָה עָשִׂ֔ית יְהִ֥י מַכִּירֵ֖ךְ בָּר֑וּךְ וַתַּגֵּ֣ד לַחֲמוֹתָ֗הּ אֵ֤ת אֲשֶׁר־עָשְׂתָה֙ עִמּ֔וֹ וַתֹּ֗אמֶר שֵׁ֤ם הָאִישׁ֙ אֲשֶׁ֨ר עָשִׂ֧יתִי עִמּ֛וֹ הַיּ֖וֹם בֹּֽעַז׃","waţò̇ʼmer֩ lá֨ḣ ẖàmwòţá֜ḣ ʼéypò֨h liqȧ֤tĕţĕ̇ haẏwòm֙ wĕʼá֣náh ʻáşî֔yţ yĕhi֥y maki̇yré֖kĕ bá̇r֑ẇkĕ waţȧgé֣̇d laẖàmwòţá֗ḣ ʼé֤ţ ʼàşěr-ʻáşĕ̂ţáh֙ ʻiṁ֔wò waţò̇֗ʼmer şé֤̌m háʼiyş̌֙ ʼàşě֨r ʻáşî֧yţiy ʻiṁ֛wò haẏ֖wòm bòֽ̇ʻaz׃"],[2,20,"וַתֹּ֨אמֶר נָעֳמִ֜י לְכַלָּתָ֗הּ בָּר֥וּךְ הוּא֙ לַיהוָ֔ה אֲשֶׁר֙ לֹא־עָזַ֣ב חַסְדּ֔וֹ אֶת־הַחַיִּ֖ים וְאֶת־הַמֵּתִ֑ים וַתֹּ֧אמֶר לָ֣הּ נָעֳמִ֗י קָר֥וֹב לָ֙נוּ֙ הָאִ֔ישׁ מִֽגֹּאֲלֵ֖נוּ הֽוּא׃","waţò̇֨ʼmer náʻomi֜y lĕkalá̇ţá֗ḣ bá̇r֥ẇkĕ hẇʼ֙ layhwá֔h ʼàşěr֙ lòʼ-ʻáza֣b ẖasĕḋ֔wò ʼeţ-haẖayi֖̇ym wĕʼeţ-hamé̇ţi֑ym waţò֧̇ʼmer lá֣ḣ náʻomi֗y qár֥wòb lá֙nẇ֙ háʼi֔yş̌ miֽgò̇ʼàlé֖nẇ hֽẇʼ׃"],[2,21,"וַתֹּ֖אמֶר ר֣וּת הַמּוֹאֲבִיָּ֑ה גַּ֣ם ׀ כִּי־אָמַ֣ר אֵלַ֗י עִם־הַנְּעָרִ֤ים אֲשֶׁר־לִי֙ תִּדְבָּקִ֔ין עַ֣ד אִם־כִּלּ֔וּ אֵ֥ת כָּל־הַקָּצִ֖יר אֲשֶׁר־לִֽי׃","waţò֖̇ʼmer r֣ẇţ haṁwòʼàbiyá֑̇h gȧ֣m ׀ ki̇y-ʼáma֣r ʼéla֗y ʻim-hanĕ̇ʻári֤ym ʼàşěr-liy֙ ţi̇dĕbá̇qi֔yn ʻa֣d ʼim-ki̇l̇֔ẇ ʼé֥ţ ká̇l-haqá̇ẕi֖yr ʼàşěr-liֽy׃"],[2,22,"וַתֹּ֥אמֶר נָעֳמִ֖י אֶל־ר֣וּת כַּלָּתָ֑הּ ט֣וֹב בִּתִּ֗י כִּ֤י תֵֽצְאִי֙ עִם־נַ֣עֲרוֹתָ֔יו וְלֹ֥א יִפְגְּעוּ־בָ֖ךְ בְּשָׂדֶ֥ה אַחֵֽר׃","waţò֥̇ʼmer náʻomi֖y ʼel-r֣ẇţ kȧlá̇ţá֑ḣ t֣wòb bi̇ţi̇֗y ki֤̇y ţéֽẕĕʼiy֙ ʻim-na֣ʻàrwòţá֔yw wĕlò֥ʼ yipĕgĕ̇ʻẇ-bá֖kĕ bĕ̇şá̂de֥h ʼaẖéֽr׃"],[2,23,"וַתִּדְבַּ֞ק בְּנַעֲר֥וֹת בֹּ֙עַז֙ לְלַקֵּ֔ט עַד־כְּל֥וֹת קְצִֽיר־הַשְּׂעֹרִ֖ים וּקְצִ֣יר הַֽחִטִּ֑ים וַתֵּ֖שֶׁב אֶת־חֲמוֹתָֽהּ׃","waţi̇dĕbȧ֞q bĕ̇naʻàr֥wòţ bò̇֙ʻaz֙ lĕlaqé̇֔t ʻad-kĕ̇l֥wòţ qĕẕiֽyr-haşĕ̇̂ʻòri֖ym ẇqĕẕi֣yr haֽẖiti֑̇ym waţé֖̇şěb ʼeţ-ẖàmwòţáֽḣ׃"],[3,1,"וַתֹּ֥אמֶר לָ֖הּ נָעֳמִ֣י חֲמוֹתָ֑הּ בִּתִּ֞י הֲלֹ֧א אֲבַקֶּשׁ־לָ֛ךְ מָנ֖וֹחַ אֲשֶׁ֥ר יִֽיטַב־לָֽךְ׃","waţò֥̇ʼmer lá֖ḣ náʻomi֣y ẖàmwòţá֑ḣ bi̇ţi̇֞y hàlò֧ʼ ʼàbaqėş̌-lá֛kĕ mán֖wòẖa ʼàşě֥r yiֽytab-láֽkĕ׃"],[3,2,"וְעַתָּ֗ה הֲלֹ֥א בֹ֙עַז֙ מֹֽדַעְתָּ֔נוּ אֲשֶׁ֥ר הָיִ֖ית אֶת־נַעֲרוֹתָ֑יו הִנֵּה־ה֗וּא זֹרֶ֛ה אֶת־גֹּ֥רֶן הַשְּׂעֹרִ֖ים הַלָּֽיְלָה׃","wĕʻaţá̇֗h hàlò֥ʼ bò֙ʻaz֙ mòֽdaʻĕţá̇֔nẇ ʼàşě֥r háyi֖yţ ʼeţ-naʻàrwòţá֑yw hiné̇h-h֗ẇʼ zòre֛h ʼeţ-gò֥̇ren haşĕ̇̂ʻòri֖ym haláֽ̇yĕláh׃"],[3,3,"וְרָחַ֣צְתְּ ׀ וָסַ֗כְתְּ וְשַׂ֧מְתְּ שמלתך עָלַ֖יִךְ וירדתי הַגֹּ֑רֶן אַל־תִּוָּדְעִ֣י לָאִ֔ישׁ עַ֥ד כַּלֹּת֖וֹ לֶאֱכֹ֥ל וְלִשְׁתּֽוֹת׃","wĕráẖa֣ẕĕţĕ̇ ׀ wása֗kĕţĕ̇ wĕşâ֧mĕţĕ̇ şmlţk ʻála֖yikĕ wyrdţy hagò֑̇ren ʼal-ţi̇wá̇dĕʻi֣y láʼi֔yş̌ ʻa֥d kȧlò̇ţ֖wò leʼèkò֥l wĕlişĕ̌ţֽ̇wòţ׃"],[3,4,"וִיהִ֣י בְשָׁכְב֗וֹ וְיָדַ֙עַתְּ֙ אֶת־הַמָּקוֹם֙ אֲשֶׁ֣ר יִשְׁכַּב־שָׁ֔ם וּבָ֛את וְגִלִּ֥ית מַרְגְּלֹתָ֖יו ושכבתי וְהוּא֙ יַגִּ֣יד לָ֔ךְ אֵ֖ת אֲשֶׁ֥ר תַּעַשִֽׂין׃","wiyhi֣y bĕşá̌kĕb֗wò wĕyáda֙ʻaţĕ̇֙ ʼeţ-hamá̇qwòm֙ ʼàşě֣r yişĕ̌kȧb-şá̌֔m ẇbá֛ʼţ wĕgili֥̇yţ marĕgĕ̇lòţá֖yw wşkbţy wĕhẇʼ֙ yagi֣̇yd lá֔kĕ ʼé֖ţ ʼàşě֥r ţȧʻaşîֽyn׃"],[3,5,"וַתֹּ֖אמֶר אֵלֶ֑יהָ כֹּ֛ל אֲשֶׁר־תֹּאמְרִ֥י אֶֽעֱשֶֽׂה׃","waţò֖̇ʼmer ʼéle֑yhá kò֛̇l ʼàşěr-ţò̇ʼmĕri֥y ʼeֽʻèşêֽh׃"],[3,6,"וַתֵּ֖רֶד הַגֹּ֑רֶן וַתַּ֕עַשׂ כְּכֹ֥ל אֲשֶׁר־צִוַּ֖תָּה חֲמוֹתָֽהּ׃","waţé֖̇red hagò֑̇ren waţȧ֕ʻaş̂ kĕ̇kò֥l ʼàşěr-ẕiwȧ֖ţá̇h ẖàmwòţáֽḣ׃"],[3,7,"וַיֹּ֨אכַל בֹּ֤עַז וַיֵּשְׁתְּ֙ וַיִּיטַ֣ב לִבּ֔וֹ וַיָּבֹ֕א לִשְׁכַּ֖ב בִּקְצֵ֣ה הָעֲרֵמָ֑ה וַתָּבֹ֣א בַלָּ֔ט וַתְּגַ֥ל מַרְגְּלֹתָ֖יו וַתִּשְׁכָּֽב׃","wayò̇֨ʼkal bò֤̇ʻaz wayé̇şĕ̌ţĕ̇֙ wayi̇yta֣b liḃ֔wò wayá̇bò֕ʼ lişĕ̌kȧ֖b bi̇qĕẕé֣h háʻàrémá֑h waţá̇bò֣ʼ balá̇֔t waţĕ̇ga֥l marĕgĕ̇lòţá֖yw waţi̇şĕ̌káֽ̇b׃"],[3,8,"וַיְהִי֙ בַּחֲצִ֣י הַלַּ֔יְלָה וַיֶּחֱרַ֥ד הָאִ֖ישׁ וַיִּלָּפֵ֑ת וְהִנֵּ֣ה אִשָּׁ֔ה שֹׁכֶ֖בֶת מַרְגְּלֹתָֽיו׃","wayĕhiy֙ bȧẖàẕi֣y halȧ֔yĕláh wayėẖèra֥d háʼi֖yş̌ wayi̇lá̇pé֑ţ wĕhiné֣̇h ʼişá̇̌֔h şò̌ke֖beţ marĕgĕ̇lòţáֽyw׃"],[3,9,"וַיֹּ֖אמֶר מִי־אָ֑תּ וַתֹּ֗אמֶר אָנֹכִי֙ ר֣וּת אֲמָתֶ֔ךָ וּפָרַשְׂתָּ֤ כְנָפֶ֙ךָ֙ עַל־אֲמָ֣תְךָ֔ כִּ֥י גֹאֵ֖ל אָֽתָּה׃","wayò֖̇ʼmer miy-ʼá֑ţ̇ waţò̇֗ʼmer ʼánòkiy֙ r֣ẇţ ʼàmáţe֔ká ẇpáraşĕ̂ţá֤̇ kĕnápe֙ká֙ ʻal-ʼàmá֣ţĕká֔ ki֥̇y gòʼé֖l ʼáֽţá̇h׃"],[3,10,"וַיֹּ֗אמֶר בְּרוּכָ֨ה אַ֤תְּ לַֽיהוָה֙ בִּתִּ֔י הֵיטַ֛בְתְּ חַסְדֵּ֥ךְ הָאַחֲר֖וֹן מִן־הָרִאשׁ֑וֹן לְבִלְתִּי־לֶ֗כֶת אַחֲרֵי֙ הַבַּ֣חוּרִ֔ים אִם־דַּ֖ל וְאִם־עָשִֽׁיר׃","wayò̇֗ʼmer bĕ̇rẇká֨h ʼa֤ţĕ̇ laֽyhwáh֙ bi̇ţi̇֔y héyta֛bĕţĕ̇ ẖasĕdé֥̇kĕ háʼaẖàr֖wòn min-háriʼş֑̌wòn lĕbilĕţi̇y-le֗keţ ʼaẖàréy֙ habȧ֣ẖẇri֔ym ʼim-dȧ֖l wĕʼim-ʻáşǐֽyr׃"],[3,11,"וְעַתָּ֗ה בִּתִּי֙ אַל־תִּ֣ירְאִ֔י כֹּ֥ל אֲשֶׁר־תֹּאמְרִ֖י אֶֽעֱשֶׂה־לָּ֑ךְ כִּ֤י יוֹדֵ֙עַ֙ כָּל־שַׁ֣עַר עַמִּ֔י כִּ֛י אֵ֥שֶׁת חַ֖יִל אָֽתְּ׃","wĕʻaţá̇֗h bi̇ţi̇y֙ ʼal-ţi֣̇yrĕʼi֔y kò֥̇l ʼàşěr-ţò̇ʼmĕri֖y ʼeֽʻèşêh-lá֑̇kĕ ki֤̇y ywòdé֙ʻa֙ ká̇l-şǎ֣ʻar ʻami̇֔y ki֛̇y ʼé֥şěţ ẖa֖yil ʼáֽţĕ̇׃"],[3,12,"וְעַתָּה֙ כִּ֣י אָמְנָ֔ם כִּ֥י אם גֹאֵ֖ל אָנֹ֑כִי וְגַ֛ם יֵ֥שׁ גֹּאֵ֖ל קָר֥וֹב מִמֶּֽנִּי׃","wĕʻaţá̇h֙ ki֣̇y ʼámĕná֔m ki֥̇y ʼm gòʼé֖l ʼánò֑kiy wĕga֛m yé֥ş̌ gò̇ʼé֖l qár֥wòb mimėֽni̇y׃"],[3,13,"לִ֣ינִי ׀ הַלַּ֗יְלָה וְהָיָ֤ה בַבֹּ֙קֶר֙ אִם־יִגְאָלֵ֥ךְ טוֹב֙ יִגְאָ֔ל וְאִם־לֹ֨א יַחְפֹּ֧ץ לְגָֽאֳלֵ֛ךְ וּגְאַלְתִּ֥יךְ אָנֹ֖כִי חַי־יְהוָ֑ה שִׁכְבִ֖י עַד־הַבֹּֽקֶר׃","li֣yniy ׀ halȧ֗yĕláh wĕháyá֤h babò̇֙qer֙ ʼim-yigĕʼálé֥kĕ twòb֙ yigĕʼá֔l wĕʼim-lò֨ʼ yaẖĕpò֧̇ẕ lĕgáֽʼolé֛kĕ ẇgĕʼalĕţi֥̇ykĕ ʼánò֖kiy ẖay-yĕhwá֑h şǐkĕbi֖y ʻad-habòֽ̇qer׃"],[3,14,"וַתִּשְׁכַּ֤ב מרגלתו עַד־הַבֹּ֔קֶר וַתָּ֕קָם בטרום יַכִּ֥יר אִ֖ישׁ אֶת־רֵעֵ֑הוּ וַיֹּ֙אמֶר֙ אַל־יִוָּדַ֔ע כִּי־בָ֥אָה הָאִשָּׁ֖ה הַגֹּֽרֶן׃","waţi̇şĕ̌kȧ֤b mrglţw ʻad-habò̇֔qer waţá̇֕qám btrwm yaki֥̇yr ʼi֖yş̌ ʼeţ-réʻé֑hẇ wayò̇֙ʼmer֙ ʼal-yiwá̇da֔ʻ ki̇y-bá֥ʼáh háʼişá֖̇̌h hagòֽ̇ren׃"],[3,15,"וַיֹּ֗אמֶר הָ֠בִי הַמִּטְפַּ֧חַת אֲשֶׁר־עָלַ֛יִךְ וְאֶֽחֳזִי־בָ֖הּ וַתֹּ֣אחֶז בָּ֑הּ וַיָּ֤מָד שֵׁשׁ־שְׂעֹרִים֙ וַיָּ֣שֶׁת עָלֶ֔יהָ וַיָּבֹ֖א הָעִֽיר׃","wayò̇֗ʼmer há֠biy hami̇tĕpȧ֧ẖaţ ʼàşěr-ʻála֛yikĕ wĕʼeֽẖoziy-bá֖ḣ waţò֣̇ʼẖez bá֑̇ḣ wayá֤̇mád şé̌ş̌-şĕ̂ʻòriym֙ wayá֣̇şěţ ʻále֔yhá wayá̇bò֖ʼ háʻiֽyr׃"],[3,16,"וַתָּבוֹא֙ אֶל־חֲמוֹתָ֔הּ וַתֹּ֖אמֶר מִי־אַ֣תְּ בִּתִּ֑י וַתַּ֨גֶּד־לָ֔הּ אֵ֛ת כָּל־אֲשֶׁ֥ר עָֽשָׂה־לָ֖הּ הָאִֽישׁ׃","waţá̇bwòʼ֙ ʼel-ẖàmwòţá֔ḣ waţò֖̇ʼmer miy-ʼa֣ţĕ̇ bi̇ţi֑̇y waţȧ֨gėd-lá֔ḣ ʼé֛ţ ká̇l-ʼàşě֥r ʻáֽşá̂h-lá֖ḣ háʼiֽyş̌׃"],[3,17,"וַתֹּ֕אמֶר שֵׁשׁ־הַשְּׂעֹרִ֥ים הָאֵ֖לֶּה נָ֣תַן לִ֑י כִּ֚י אָמַ֣ר אַל־תָּב֥וֹאִי רֵיקָ֖ם אֶל־חֲמוֹתֵֽךְ׃","waţò̇֕ʼmer şé̌ş̌-haşĕ̇̂ʻòri֥ym háʼé֖lėh ná֣ţan li֑y ki֚̇y ʼáma֣r ʼal-ţá̇b֥wòʼiy réyqá֖m ʼel-ẖàmwòţéֽkĕ׃"],[3,18,"וַתֹּ֙אמֶר֙ שְׁבִ֣י בִתִּ֔י עַ֚ד אֲשֶׁ֣ר תֵּֽדְעִ֔ין אֵ֖יךְ יִפֹּ֣ל דָּבָ֑ר כִּ֣י לֹ֤א יִשְׁקֹט֙ הָאִ֔ישׁ כִּֽי־אִם־כִּלָּ֥ה הַדָּבָ֖ר הַיּֽוֹם׃","waţò̇֙ʼmer֙ şĕ̌bi֣y biţi̇֔y ʻa֚d ʼàşě֣r ţéֽ̇dĕʻi֔yn ʼé֖ykĕ yipò֣̇l dá̇bá֑r ki֣̇y lò֤ʼ yişĕ̌qòt֙ háʼi֔yş̌ kiֽ̇y-ʼim-ki̇lá֥̇h hadá̇bá֖r haẏֽwòm׃"],[4,1,"וּבֹ֨עַז עָלָ֣ה הַשַּׁעַר֮ וַיֵּ֣שֶׁב שָׁם֒ וְהִנֵּ֨ה הַגֹּאֵ֤ל עֹבֵר֙ אֲשֶׁ֣ר דִּבֶּר־בֹּ֔עַז וַיֹּ֛אמֶר ס֥וּרָה שְׁבָה־פֹּ֖ה פְּלֹנִ֣י אַלְמֹנִ֑י וַיָּ֖סַר וַיֵּשֵֽׁב׃","ẇbò֨ʻaz ʻálá֣h haşȧ̌ʻar֮ wayé֣̇şěb şá̌m֒ wĕhiné̇֨h hagò̇ʼé֤l ʻòbér֙ ʼàşě֣r di̇bėr-bò̇֔ʻaz wayò֛̇ʼmer s֥ẇráh şĕ̌báh-pò֖̇h pĕ̇lòni֣y ʼalĕmòni֑y wayá֖̇sar wayé̇şéֽ̌b׃"],[4,2,"וַיִּקַּ֞ח עֲשָׂרָ֧ה אֲנָשִׁ֛ים מִזִּקְנֵ֥י הָעִ֖יר וַיֹּ֣אמֶר שְׁבוּ־פֹ֑ה וַיֵּשֵֽׁבוּ׃","wayi̇qȧ֞ẖ ʻàşá̂rá֧h ʼànáşǐ֛ym mizi̇qĕné֥y háʻi֖yr wayò֣̇ʼmer şĕ̌bẇ-pò֑h wayé̇şéֽ̌bẇ׃"],[4,3,"וַיֹּ֙אמֶר֙ לַגֹּאֵ֔ל חֶלְקַת֙ הַשָּׂדֶ֔ה אֲשֶׁ֥ר לְאָחִ֖ינוּ לֶאֱלִימֶ֑לֶךְ מָכְרָ֣ה נָעֳמִ֔י הַשָּׁ֖בָה מִשְּׂדֵ֥ה מוֹאָֽב׃","wayò̇֙ʼmer֙ lagò̇ʼé֔l ẖelĕqaţ֙ haşá̇̂de֔h ʼàşě֥r lĕʼáẖi֖ynẇ leʼèliyme֑lekĕ mákĕrá֣h náʻomi֔y haşá֖̇̌báh mişĕ̇̂dé֥h mwòʼáֽb׃"],[4,4,"וַאֲנִ֨י אָמַ֜רְתִּי אֶגְלֶ֧ה אָזְנְךָ֣ לֵאמֹ֗ר קְ֠נֵה נֶ֥גֶד הַֽיֹּשְׁבִים֮ וְנֶ֣גֶד זִקְנֵ֣י עַמִּי֒ אִם־תִּגְאַל֙ גְּאָ֔ל וְאִם־לֹ֨א יִגְאַ֜ל הַגִּ֣ידָה לִּ֗י ואדע כִּ֣י אֵ֤ין זוּלָֽתְךָ֙ לִגְא֔וֹל וְאָנֹכִ֖י אַחֲרֶ֑יךָ וַיֹּ֖אמֶר אָנֹכִ֥י אֶגְאָֽל׃","waʼàni֨y ʼáma֜rĕţi̇y ʼegĕle֧h ʼázĕnĕká֣ léʼmò֗r qĕ֠néh ne֥ged haֽyò̇şĕ̌biym֮ wĕne֣ged ziqĕné֣y ʻami̇y֒ ʼim-ţi̇gĕʼal֙ gĕ̇ʼá֔l wĕʼim-lò֨ʼ yigĕʼa֜l hagi֣̇ydáh li̇֗y wʼdʻ ki֣̇y ʼé֤yn zẇláֽţĕká֙ ligĕʼ֔wòl wĕʼánòki֖y ʼaẖàre֑yká wayò֖̇ʼmer ʼánòki֥y ʼegĕʼáֽl׃"],[4,5,"וַיֹּ֣אמֶר בֹּ֔עַז בְּיוֹם־קְנוֹתְךָ֥ הַשָּׂדֶ֖ה מִיַּ֣ד נָעֳמִ֑י וּ֠מֵאֵת ר֣וּת הַמּוֹאֲבִיָּ֤ה אֵֽשֶׁת־הַמֵּת֙ קניתי לְהָקִ֥ים שֵׁם־הַמֵּ֖ת עַל־נַחֲלָתֽוֹ׃","wayò֣̇ʼmer bò̇֔ʻaz bĕ̇ywòm-qĕnwòţĕká֥ haşá̇̂de֖h miyȧ֣d náʻomi֑y ẇ֠méʼéţ r֣ẇţ haṁwòʼàbiyá֤̇h ʼéֽşěţ-hamé̇ţ֙ qnyţy lĕháqi֥ym şé̌m-hamé֖̇ţ ʻal-naẖàláţֽwò׃"],[4,6,"וַיֹּ֣אמֶר הַגֹּאֵ֗ל לֹ֤א אוּכַל֙ לגאול ־לִ֔י פֶּן־אַשְׁחִ֖ית אֶת־נַחֲלָתִ֑י גְּאַל־לְךָ֤ אַתָּה֙ אֶת־גְּאֻלָּתִ֔י כִּ֥י לֹא־אוּכַ֖ל לִגְאֹֽל׃","wayò֣̇ʼmer hagò̇ʼé֗l lò֤ʼ ʼẇkal֙ lgʼwl -li֔y pėn-ʼaşĕ̌ẖi֖yţ ʼeţ-naẖàláţi֑y gĕ̇ʼal-lĕká֤ ʼaţá̇h֙ ʼeţ-gĕ̇ʼulá̇ţi֔y ki֥̇y lòʼ-ʼẇka֖l ligĕʼòֽl׃"],[4,7,"וְזֹאת֩ לְפָנִ֨ים בְּיִשְׂרָאֵ֜ל עַל־הַגְּאוּלָּ֤ה וְעַל־הַתְּמוּרָה֙ לְקַיֵּ֣ם כָּל־דָּבָ֔ר שָׁלַ֥ף אִ֛ישׁ נַעֲל֖וֹ וְנָתַ֣ן לְרֵעֵ֑הוּ וְזֹ֥את הַתְּעוּדָ֖ה בְּיִשְׂרָאֵֽל׃","wĕzòʼţ֩ lĕpáni֨ym bĕ̇yişĕ̂ráʼé֜l ʻal-hagĕ̇ʼẇlá֤̇h wĕʻal-haţĕ̇mẇráh֙ lĕqayé֣̇m ká̇l-dá̇bá֔r şá̌la֥p ʼi֛yş̌ naʻàl֖wò wĕnáţa֣n lĕréʻé֑hẇ wĕzò֥ʼţ haţĕ̇ʻẇdá֖h bĕ̇yişĕ̂ráʼéֽl׃"],[4,8,"וַיֹּ֧אמֶר הַגֹּאֵ֛ל לְבֹ֖עַז קְנֵה־לָ֑ךְ וַיִּשְׁלֹ֖ף נַעֲלֽוֹ׃","wayò֧̇ʼmer hagò̇ʼé֛l lĕbò֖ʻaz qĕnéh-lá֑kĕ wayi̇şĕ̌lò֖p naʻàlֽwò׃"],[4,9,"וַיֹּאמֶר֩ בֹּ֨עַז לַזְּקֵנִ֜ים וְכָל־הָעָ֗ם עֵדִ֤ים אַתֶּם֙ הַיּ֔וֹם כִּ֤י קָנִ֙יתִי֙ אֶת־כָּל־אֲשֶׁ֣ר לֶֽאֱלִימֶ֔לֶךְ וְאֵ֛ת כָּל־אֲשֶׁ֥ר לְכִלְי֖וֹן וּמַחְל֑וֹן מִיַּ֖ד נָעֳמִֽי׃","wayò̇ʼmer֩ bò̇֨ʻaz lazĕ̇qéni֜ym wĕkál-háʻá֗m ʻédi֤ym ʼaţėm֙ haẏ֔wòm ki֤̇y qáni֙yţiy֙ ʼeţ-ká̇l-ʼàşě֣r leֽʼèliyme֔lekĕ wĕʼé֛ţ ká̇l-ʼàşě֥r lĕkilĕy֖wòn ẇmaẖĕl֑wòn miyȧ֖d náʻomiֽy׃"],[4,10,"וְגַ֣ם אֶת־ר֣וּת הַמֹּאֲבִיָּה֩ אֵ֨שֶׁת מַחְל֜וֹן קָנִ֧יתִי לִ֣י לְאִשָּׁ֗ה לְהָקִ֤ים שֵׁם־הַמֵּת֙ עַל־נַ֣חֲלָת֔וֹ וְלֹא־יִכָּרֵ֧ת שֵׁם־הַמֵּ֛ת מֵעִ֥ם אֶחָ֖יו וּמִשַּׁ֣עַר מְקוֹמ֑וֹ עֵדִ֥ים אַתֶּ֖ם הַיּֽוֹם׃","wĕga֣m ʼeţ-r֣ẇţ hamò̇ʼàbiyá̇h֩ ʼé֨şěţ maẖĕl֜wòn qáni֧yţiy li֣y lĕʼişá̇̌֗h lĕháqi֤ym şé̌m-hamé̇ţ֙ ʻal-na֣ẖàláţ֔wò wĕlòʼ-yiká̇ré֧ţ şé̌m-hamé֛̇ţ méʻi֥m ʼeẖá֖yw ẇmişȧ֣̌ʻar mĕqwòm֑wò ʻédi֥ym ʼaţė֖m haẏֽwòm׃"],[4,11,"וַיֹּ֨אמְר֜וּ כָּל־הָעָ֧ם אֲשֶׁר־בַּשַּׁ֛עַר וְהַזְּקֵנִ֖ים עֵדִ֑ים יִתֵּן֩ יְהוָ֨ה אֶֽת־הָאִשָּׁ֜ה הַבָּאָ֣ה אֶל־בֵּיתֶ֗ךָ כְּרָחֵ֤ל ׀ וּכְלֵאָה֙ אֲשֶׁ֨ר בָּנ֤וּ שְׁתֵּיהֶם֙ אֶת־בֵּ֣ית יִשְׂרָאֵ֔ל וַעֲשֵׂה־ חַ֣יִל בְּאֶפְרָ֔תָה וּקְרָא־שֵׁ֖ם בְּבֵ֥ית לָֽחֶם׃","wayò̇֨ʼmĕr֜ẇ ká̇l-háʻá֧m ʼàşěr-bȧşȧ֛̌ʻar wĕhazĕ̇qéni֖ym ʻédi֑ym yiţé̇n֩ yĕhwá֨h ʼeֽţ-háʼişá̇̌֜h habá̇ʼá֣h ʼel-bé̇yţe֗ká kĕ̇ráẖé֤l ׀ ẇkĕléʼáh֙ ʼàşě֨r bá̇n֤ẇ şĕ̌ţé̇yhem֙ ʼeţ-bé֣̇yţ yişĕ̂ráʼé֔l waʻàşé̂h- ẖa֣yil bĕ̇ʼepĕrá֔ţáh ẇqĕráʼ-şé֖̌m bĕ̇bé֥yţ láֽẖem׃"],[4,12,"וִיהִ֤י בֵֽיתְךָ֙ כְּבֵ֣ית פֶּ֔רֶץ אֲשֶׁר־יָלְדָ֥ה תָמָ֖ר לִֽיהוּדָ֑ה מִן־הַזֶּ֗רַע אֲשֶׁ֨ר יִתֵּ֤ן יְהוָה֙ לְךָ֔ מִן־הַֽנַּעֲרָ֖ה הַזֹּֽאת׃","wiyhi֤y béֽyţĕká֙ kĕ̇bé֣yţ pė֔reẕ ʼàşěr-yálĕdá֥h ţámá֖r liֽyhẇdá֑h min-hazė֗raʻ ʼàşě֨r yiţé֤̇n yĕhwáh֙ lĕká֔ min-haֽnȧʻàrá֖h hazòֽ̇ʼţ׃"],[4,13,"וַיִּקַּ֨ח בֹּ֤עַז אֶת־רוּת֙ וַתְּהִי־ל֣וֹ לְאִשָּׁ֔ה וַיָּבֹ֖א אֵלֶ֑יהָ וַיִּתֵּ֨ן יְהוָ֥ה לָ֛הּ הֵרָי֖וֹן וַתֵּ֥לֶד בֵּֽן׃","wayi̇qȧ֨ẖ bò֤̇ʻaz ʼeţ-rẇţ֙ waţĕ̇hiy-l֣wò lĕʼişá̇̌֔h wayá̇bò֖ʼ ʼéle֑yhá wayi̇ţé̇֨n yĕhwá֥h lá֛ḣ héráy֖wòn waţé֥̇led béֽ̇n׃"],[4,14,"וַתֹּאמַ֤רְנָה הַנָּשִׁים֙ אֶֽל־נָעֳמִ֔י בָּר֣וּךְ יְהוָ֔ה אֲ֠שֶׁר לֹ֣א הִשְׁבִּ֥ית לָ֛ךְ גֹּאֵ֖ל הַיּ֑וֹם וְיִקָּרֵ֥א שְׁמ֖וֹ בְּיִשְׂרָאֵֽל׃","waţò̇ʼma֤rĕnáh haná̇şǐym֙ ʼeֽl-náʻomi֔y bá̇r֣ẇkĕ yĕhwá֔h ʼà֠şěr lò֣ʼ hişĕ̌bi֥̇yţ lá֛kĕ gò̇ʼé֖l haẏ֑wòm wĕyiqá̇ré֥ʼ şĕ̌m֖wò bĕ̇yişĕ̂ráʼéֽl׃"],[4,15,"וְהָ֤יָה לָךְ֙ לְמֵשִׁ֣יב נֶ֔פֶשׁ וּלְכַלְכֵּ֖ל אֶת־שֵׂיבָתֵ֑ךְ כִּ֣י כַלָּתֵ֤ךְ אֲֽשֶׁר־אֲהֵבַ֙תֶךְ֙ יְלָדַ֔תּוּ אֲשֶׁר־הִיא֙ ט֣וֹבָה לָ֔ךְ מִשִּׁבְעָ֖ה בָּנִֽים׃","wĕhá֤yáh lákĕ֙ lĕméşǐ֣yb ne֔peş̌ ẇlĕkalĕké֖̇l ʼeţ-şé̂ybáţé֑kĕ ki֣̇y kalá̇ţé֤kĕ ʼàֽşěr-ʼàhéba֙ţekĕ֙ yĕláda֔ţ̇ẇ ʼàşěr-hiyʼ֙ t֣wòbáh lá֔kĕ mişi̇̌bĕʻá֖h bá̇niֽym׃"],[4,16,"וַתִּקַּ֨ח נָעֳמִ֤י אֶת־הַיֶּ֙לֶד֙ וַתְּשִׁתֵ֣הוּ בְחֵיקָ֔הּ וַתְּהִי־ל֖וֹ לְאֹמֶֽנֶת׃","waţi̇qȧ֨ẖ náʻomi֤y ʼeţ-hayė֙led֙ waţĕ̇şǐţé֣hẇ bĕẖéyqá֔ḣ waţĕ̇hiy-l֖wò lĕʼòmeֽneţ׃"],[4,17,"וַתִּקְרֶאנָה֩ ל֨וֹ הַשְּׁכֵנ֥וֹת שֵׁם֙ לֵאמֹ֔ר יֻלַּד־בֵּ֖ן לְנָעֳמִ֑י וַתִּקְרֶ֤אנָֽה שְׁמוֹ֙ עוֹבֵ֔ד ה֥וּא אֲבִי־יִשַׁ֖י אֲבִ֥י דָוִֽד׃ פ","waţi̇qĕreʼnáh֩ l֨wò haşĕ̇̌kén֥wòţ şé̌m֙ léʼmò֔r yulȧd-bé֖̇n lĕnáʻomi֑y waţi̇qĕre֤ʼnáֽh şĕ̌mwò֙ ʻwòbé֔d h֥ẇʼ ʼàbiy-yişǎ֖y ʼàbi֥y dáwiֽd׃ p"],[4,18,"וְאֵ֙לֶּה֙ תּוֹלְד֣וֹת פָּ֔רֶץ פֶּ֖רֶץ הוֹלִ֥יד אֶת־חֶצְרֽוֹן׃","wĕʼé֙lėh֙ ţ̇wòlĕd֣wòţ pá̇֔reẕ pė֖reẕ hwòli֥yd ʼeţ-ẖeẕĕrֽwòn׃"],[4,19,"וְחֶצְרוֹן֙ הוֹלִ֣יד אֶת־רָ֔ם וְרָ֖ם הוֹלִ֥יד אֶת־עַמִּֽינָדָֽב׃","wĕẖeẕĕrwòn֙ hwòli֣yd ʼeţ-rá֔m wĕrá֖m hwòli֥yd ʼeţ-ʻamiֽ̇ynádáֽb׃"],[4,20,"וְעַמִּֽינָדָב֙ הוֹלִ֣יד אֶת־נַחְשׁ֔וֹן וְנַחְשׁ֖וֹן הוֹלִ֥יד אֶת־שַׂלְמָֽה׃","wĕʻamiֽ̇ynádáb֙ hwòli֣yd ʼeţ-naẖĕş̌֔wòn wĕnaẖĕş֖̌wòn hwòli֥yd ʼeţ-şâlĕmáֽh׃"],[4,21,"וְשַׂלְמוֹן֙ הוֹלִ֣יד אֶת־בֹּ֔עַז וּבֹ֖עַז הוֹלִ֥יד אֶת־עוֹבֵֽד׃","wĕşâlĕmwòn֙ hwòli֣yd ʼeţ-bò̇֔ʻaz ẇbò֖ʻaz hwòli֥yd ʼeţ-ʻwòbéֽd׃"],[4,22,"וְעֹבֵד֙ הוֹלִ֣יד אֶת־יִשָׁ֔י וְיִשַׁ֖י הוֹלִ֥יד אֶת־דָּוִֽד׃","wĕʻòbéd֙ hwòli֣yd ʼeţ-yişá̌֔y wĕyişǎ֖y hwòli֥yd ʼeţ-dá̇wiֽd׃"]],"fra-giguet-lxx":[[1,1,"Du temps des juges, il y eut une famine sur la terre; et un homme partit de Bethleem en Juda, pour aller aux champs de Moab, lui, et sa femme et ses deux fils.","Du temps des juges, il y eut une famine sur la terre; et un homme partit de Bethleem en Juda, pour aller aux champs de Moab, lui, et sa femme et ses deux fils."],[1,2,"Le nom de l’homme était Elimelech, et le nom de sa femme Noémi, et les noms de ses deux fils, Maalon et Chélaïon, Ephrathéens de Bethléem en Juda. Ainsi, ils allèrent aux champs de Moab et ils y demeurèrent.","Le nom de l’homme était Elimelech, et le nom de sa femme Noémi, et les noms de ses deux fils, Maalon et Chélaïon, Ephrathéens de Bethléem en Juda. Ainsi, ils allèrent aux champs de Moab et ils y demeurèrent."],[1,3,"Or, Elimelech, le mari de Noémi, mourut, et elle resta veuve avec deux fils.","Or, Elimelech, le mari de Noémi, mourut, et elle resta veuve avec deux fils."],[1,4,"Et ils épousèrent des femmes moabites: l’une se nommait Orpha, la seconde se nommait Ruth, et ils passèrent là dix années.","Et ils épousèrent des femmes moabites: l’une se nommait Orpha, la seconde se nommait Ruth, et ils passèrent là dix années."],[1,5,"Et tous les deux moururent aussi: Maalon et Chélaïon, la femme resta ainsi privée de son mari et de ses deux fils.","Et tous les deux moururent aussi: Maalon et Chélaïon, la femme resta ainsi privée de son mari et de ses deux fils."],[1,6,"Alors, elle se leva avec ses deux brus, et elles s’en allèrent des champs de Moab, parce qu’elles y avaient appris que le Seigneur avait visité son peuple pour lui donner du pain.","Alors, elle se leva avec ses deux brus, et elles s’en allèrent des champs de Moab, parce qu’elles y avaient appris que le Seigneur avait visité son peuple pour lui donner du pain."],[1,7,"Elle quitta donc le lieu où elle était, et ses deux brus avec elle; elles se mirent en route pour retourner en la terre de Juda.","Elle quitta donc le lieu où elle était, et ses deux brus avec elle; elles se mirent en route pour retourner en la terre de Juda."],[1,8,"Et Noémi dit à ses deux brus: Allez, retournez chacune en la maison de votre mère; que le Seigneur soit miséricordieux envers vous comme vous l’avez été pour nos morts et pour moi.","Et Noémi dit à ses deux brus: Allez, retournez chacune en la maison de votre mère; que le Seigneur soit miséricordieux envers vous comme vous l’avez été pour nos morts et pour moi."],[1,9,"Que le Seigneur vous l’accorde, et vous retrouverez l’une et l’autre la maison d’un époux. Puis, elle les baisa, et elles élevèrent la voix, et elles se prirent à pleurer.","Que le Seigneur vous l’accorde, et vous retrouverez l’une et l’autre la maison d’un époux. Puis, elle les baisa, et elles élevèrent la voix, et elles se prirent à pleurer."],[1,10,"Et elles lui dirent: Nous irons avec toi chez ton peuple.","Et elles lui dirent: Nous irons avec toi chez ton peuple."],[1,11,"Mais Noémi dit: Allez-vous-en, mes filles. Pourquoi viendriez-vous avec moi? Ai-je encore en mes entrailles des fils qui puissent être vos époux?","Mais Noémi dit: Allez-vous-en, mes filles. Pourquoi viendriez-vous avec moi? Ai-je encore en mes entrailles des fils qui puissent être vos époux?"],[1,12,"Allez-vous-en, mes filles, parce que je suis trop vieille pour être avec un mari, et que du reste j’ai dit: Quand même je pourrais prendre un mari et enfanter des fils,","Allez-vous-en, mes filles, parce que je suis trop vieille pour être avec un mari, et que du reste j’ai dit: Quand même je pourrais prendre un mari et enfanter des fils,"],[1,13,"Les attendriez-vous jusqu’à qu’ils soient devenus hommes; et, poux eux, vous abstiendriez-vous d’être avec des maris? Ne venez point, mes filles; car j’ai bien de la peine à votre sujet, parce que la main du Seigneur s’est appesantie sur moi.","Les attendriez-vous jusqu’à qu’ils soient devenus hommes; et, poux eux, vous abstiendriez-vous d’être avec des maris? Ne venez point, mes filles; car j’ai bien de la peine à votre sujet, parce que la main du Seigneur s’est appesantie sur moi."],[1,14,"Et elles élevèrent la voix et elles pleurèrent encore; Orpha baisa sa belle-mère, et elle s’en retourna chez son peuple; mais Ruth suivit Noémi.","Et elles élevèrent la voix et elles pleurèrent encore; Orpha baisa sa belle-mère, et elle s’en retourna chez son peuple; mais Ruth suivit Noémi."],[1,15,"Et Noémi dit à Ruth: Vois, ta sœur retourne à son peuple et à ses dieux; fais comme elle, et accompagne ta sœur.","Et Noémi dit à Ruth: Vois, ta sœur retourne à son peuple et à ses dieux; fais comme elle, et accompagne ta sœur."],[1,16,"Et Ruth dit: Ne me parle plus de m’éloigner de toi et de t’abandonner, parce qu’où tu iras, j’irai; où tu demeureras, je demeurerai; ton peuple est mon peuple, ton Dieu est mon Dieu;","Et Ruth dit: Ne me parle plus de m’éloigner de toi et de t’abandonner, parce qu’où tu iras, j’irai; où tu demeureras, je demeurerai; ton peuple est mon peuple, ton Dieu est mon Dieu;"],[1,17,"Où tu mourras, je mourrai, et c’est là que je serai ensevelie; que le Seigneur me punisse, et qu’il me punisse encore si je te quitte; car la mort seule nous séparera.","Où tu mourras, je mourrai, et c’est là que je serai ensevelie; que le Seigneur me punisse, et qu’il me punisse encore si je te quitte; car la mort seule nous séparera."],[1,18,"Voyant donc sa ferme volonté de partir avec elle, Noémi cessa de lui parler.","Voyant donc sa ferme volonté de partir avec elle, Noémi cessa de lui parler."],[1,19,"Elles marchèrent toutes deux jusqu’à ce qu’elles arrivassent à Bethléem; et, dès qu’elles furent entrées à Bethleem, toute la ville fut en rumeur à leur sujet, et les femmes dirent: N’est-ce point Noémi?","Elles marchèrent toutes deux jusqu’à ce qu’elles arrivassent à Bethléem; et, dès qu’elles furent entrées à Bethleem, toute la ville fut en rumeur à leur sujet, et les femmes dirent: N’est-ce point Noémi?"],[1,20,"Et elle leur dit: Ne m’appelez point Noémi (belle); appelez-moi Mara (amère), parce que le Tout-Puissant m’a remplie d’amertume.","Et elle leur dit: Ne m’appelez point Noémi (belle); appelez-moi Mara (amère), parce que le Tout-Puissant m’a remplie d’amertume."],[1,21,"Pleine je suis partie, et vide me renvoie le Seigneur. Pourquoi m’appelleriez-vous Noémi, puisque le Seigneur m’a humiliée et que le Tout-Puissant m’a accablée de maux?","Pleine je suis partie, et vide me renvoie le Seigneur. Pourquoi m’appelleriez-vous Noémi, puisque le Seigneur m’a humiliée et que le Tout-Puissant m’a accablée de maux?"],[1,22,"Noémi et sa bru Ruth la Moabite étaient donc revenues des champs de Moab, et elles étaient entrées à Bethleem comme on commençait à moissonner les orges.","Noémi et sa bru Ruth la Moabite étaient donc revenues des champs de Moab, et elles étaient entrées à Bethleem comme on commençait à moissonner les orges."],[2,1,"Il y avait un homme connu de Noémi et de son époux; cet homme, parent d’Elimelech, était riche, et il se nommait Booz.","Il y avait un homme connu de Noémi et de son époux; cet homme, parent d’Elimelech, était riche, et il se nommait Booz."],[2,2,"Et Ruth la Moabite dit à Noémi: Je m’en vais aux champs, et je ramasserai des épis à la suite des moissonneurs, chez celui aux yeux de qui je trouverai grâce; et Noémi répondit: Va, ma fille.","Et Ruth la Moabite dit à Noémi: Je m’en vais aux champs, et je ramasserai des épis à la suite des moissonneurs, chez celui aux yeux de qui je trouverai grâce; et Noémi répondit: Va, ma fille."],[2,3,"Elle partit done, et, étant arrivée, elle glana dans un champ, derrière les moissonneurs; elle était tombée par aventure sur un endroit du champ de Booz, le parent d’Elimélech.","Elle partit done, et, étant arrivée, elle glana dans un champ, derrière les moissonneurs; elle était tombée par aventure sur un endroit du champ de Booz, le parent d’Elimélech."],[2,4,"Et voilà que Booz vint de Bethléem, et il dit aux moissonneurs Le Seigneur soit avec vous; et ils lui dirent Que le Seigneur te bénisse.","Et voilà que Booz vint de Bethléem, et il dit aux moissonneurs Le Seigneur soit avec vous; et ils lui dirent Que le Seigneur te bénisse."],[2,5,"Et Booz dit à son serviteur, qui était placé au-dessus des moissonneurs: Qui est cette jeune fille?","Et Booz dit à son serviteur, qui était placé au-dessus des moissonneurs: Qui est cette jeune fille?"],[2,6,"Son serviteur, qui était placé au-dessus des moissonneurs, répondit: C’est la jeune Moabite, qui est revenue avec Noémi du champ de Moab.","Son serviteur, qui était placé au-dessus des moissonneurs, répondit: C’est la jeune Moabite, qui est revenue avec Noémi du champ de Moab."],[2,7,"Elle m’a dit: Je glanerai et je recueillerai des épis derrière les moissonneurs; et elle a glané depuis le matin jusqu’au soir, et elle n’a pas pris dans le champ un moment de repos.","Elle m’a dit: Je glanerai et je recueillerai des épis derrière les moissonneurs; et elle a glané depuis le matin jusqu’au soir, et elle n’a pas pris dans le champ un moment de repos."],[2,8,"Alors, Booz dit à Ruth: N’as-tu pas entendu, ma fille? Ne va pas glaner dans un autre champ; ne t’éloigne pas d’ici, et attache-toi aux pas de mes filles.","Alors, Booz dit à Ruth: N’as-tu pas entendu, ma fille? Ne va pas glaner dans un autre champ; ne t’éloigne pas d’ici, et attache-toi aux pas de mes filles."],[2,9,"Les yeux fixés sur le champ où elles moissonnent, tu iras après elles; voilà que j’ai commandé à mes serviteurs de te respecter. Et quand tu auras soif, tu iras aux vaisseaux, et tu boiras où boivent mes serviteurs.","Les yeux fixés sur le champ où elles moissonnent, tu iras après elles; voilà que j’ai commandé à mes serviteurs de te respecter. Et quand tu auras soif, tu iras aux vaisseaux, et tu boiras où boivent mes serviteurs."],[2,10,"Et, pour témoigner son respect, elle tomba la face contre terre, et elle lui dit: Comment ai-je trouvé grâce devant tes yeux pour que tu m’honores, moi qui suis une étrangère?","Et, pour témoigner son respect, elle tomba la face contre terre, et elle lui dit: Comment ai-je trouvé grâce devant tes yeux pour que tu m’honores, moi qui suis une étrangère?"],[2,11,"Et il répondit: On m’a raconté tout ce que tu as fait pour ta belle-mère après la mort de son mari, et comment tu as quitté ton père et ta mère et le lieu de ta naissance, et comment tu es venue chez un peuple qu’auparavant tu ne connaissais pas.","Et il répondit: On m’a raconté tout ce que tu as fait pour ta belle-mère après la mort de son mari, et comment tu as quitté ton père et ta mère et le lieu de ta naissance, et comment tu es venue chez un peuple qu’auparavant tu ne connaissais pas."],[2,12,"Que le Seigneur rémunère ta bonne action; que le Seigneur Dieu d’Israël, à qui tu es venue pour t’abriter sous ses ailes, t’accorde un salaire abondant.","Que le Seigneur rémunère ta bonne action; que le Seigneur Dieu d’Israël, à qui tu es venue pour t’abriter sous ses ailes, t’accorde un salaire abondant."],[2,13,"Et elle reprit: Que je trouve, seigneur, grâce devant tes yeux, puisque tu m’as consolée, et que tu as parlé au cœur de ta servante, et je serai comme l’une de tes servantes.","Et elle reprit: Que je trouve, seigneur, grâce devant tes yeux, puisque tu m’as consolée, et que tu as parlé au cœur de ta servante, et je serai comme l’une de tes servantes."],[2,14,"Et Booz lui dit: Voici le moment de manger, viens ici; tu mangeras du pain et tu tremperas ta bouchée dans le vinaigre. Ruth s’assit donc auprès des moissonneurs, et Booz lui présenta des gâteaux de farine; elle mangea et elle fut rassasiée, et il lui en resta.","Et Booz lui dit: Voici le moment de manger, viens ici; tu mangeras du pain et tu tremperas ta bouchée dans le vinaigre. Ruth s’assit donc auprès des moissonneurs, et Booz lui présenta des gâteaux de farine; elle mangea et elle fut rassasiée, et il lui en resta."],[2,15,"Ensuite, elle se leva pour glaner, et Booz donna ses ordres à ses serviteurs, disant: Laissez-la glaner au milieu des javelles et gardez-vous de la molester.","Ensuite, elle se leva pour glaner, et Booz donna ses ordres à ses serviteurs, disant: Laissez-la glaner au milieu des javelles et gardez-vous de la molester."],[2,16,"En apportant les épis, apportez-en pour elle, et en les jetant à terre, jetez pour elle une part de ce que vous recueillez; elle glanera, elle mangera, et vous ne lui ferez aucun reproche.","En apportant les épis, apportez-en pour elle, et en les jetant à terre, jetez pour elle une part de ce que vous recueillez; elle glanera, elle mangera, et vous ne lui ferez aucun reproche."],[2,17,"Et elle glana jusqu’à la nuit, puis elle battit les épis qu’elle avait ramassés, et elle en tira près d’une me-sure d’orge.","Et elle glana jusqu’à la nuit, puis elle battit les épis qu’elle avait ramassés, et elle en tira près d’une me-sure d’orge."],[2,18,"Elle l’emporta et elle rentra dans la ville; sa bellemère vit ce qu’elle avait recueilli, et Ruth lui donna les restes qu’elle avait rapportés des mets dont elle s’était rassasiée.","Elle l’emporta et elle rentra dans la ville; sa bellemère vit ce qu’elle avait recueilli, et Ruth lui donna les restes qu’elle avait rapportés des mets dont elle s’était rassasiée."],[2,19,"Et sa belle-mère lui dit: Où as-tu glané aujourd’hui, où as-tu travaillé? Béni soit celui qui t’a accueillie. Et Ruth apprit à sa belle-mère où elle avait travaillé, et elle lui dit L’homme chez qui j’ai glané aujourd’hui se nomme Booz.","Et sa belle-mère lui dit: Où as-tu glané aujourd’hui, où as-tu travaillé? Béni soit celui qui t’a accueillie. Et Ruth apprit à sa belle-mère où elle avait travaillé, et elle lui dit L’homme chez qui j’ai glané aujourd’hui se nomme Booz."],[2,20,"Et Noémi dit à sa bru: Béni soit-il, au nom du Seigneur, parce que sa miséricorde n’a manqué ni aux vivants, ni aux morts. Et Noémi ajouta: L’homme nous est proche, c’est un de nos parents.","Et Noémi dit à sa bru: Béni soit-il, au nom du Seigneur, parce que sa miséricorde n’a manqué ni aux vivants, ni aux morts. Et Noémi ajouta: L’homme nous est proche, c’est un de nos parents."],[2,21,"Et Ruth reprit: C’est sans doute pour cela qu’il m’a dit: Attache-toi aux pas de mes filles jusqu’à ce qu’elles aient achevé toute ma moisson.","Et Ruth reprit: C’est sans doute pour cela qu’il m’a dit: Attache-toi aux pas de mes filles jusqu’à ce qu’elles aient achevé toute ma moisson."],[2,22,"Et Noémi dit à Ruth, sa bru: Bon, mon enfant, si tu marches avec ses filles, on ne te contrariera pas dans un autre champ.","Et Noémi dit à Ruth, sa bru: Bon, mon enfant, si tu marches avec ses filles, on ne te contrariera pas dans un autre champ."],[2,23,"Ruth s’attacha donc aux pas des filles de Booz pour glaner jusqu’à la fin de la moisson des orges et des froments.","Ruth s’attacha donc aux pas des filles de Booz pour glaner jusqu’à la fin de la moisson des orges et des froments."],[3,1,"Or, comme elle était assise auprès de sa belle-mère, Noémi sa belle-mère lui dit: Fille, ne chercherai-je point pour toi le repos afin que tu sois heureuse?","Or, comme elle était assise auprès de sa belle-mère, Noémi sa belle-mère lui dit: Fille, ne chercherai-je point pour toi le repos afin que tu sois heureuse?"],[3,2,"Maintenant, Booz, dont tu as fréquenté les filles, ne nous est-il pas connu? Écoute: Il doit vanner cette nuit de l’orge dans son aire.","Maintenant, Booz, dont tu as fréquenté les filles, ne nous est-il pas connu? Écoute: Il doit vanner cette nuit de l’orge dans son aire."],[3,3,"Lave-toi donc et te parfume, revêts-toi de ton bel habillement et monte à son aire. Ne te montre pas à l’homme qu’il n’ait fini de manger et de boire.","Lave-toi donc et te parfume, revêts-toi de ton bel habillement et monte à son aire. Ne te montre pas à l’homme qu’il n’ait fini de manger et de boire."],[3,4,"Lorsqu’il sera couché, et que tu sauras le lieu où il sera couché, tu iras, tu lèveras ce qui couvre ses pieds, tu te coucheras, et lui-même t’apprendra ce que tu auras à faire.","Lorsqu’il sera couché, et que tu sauras le lieu où il sera couché, tu iras, tu lèveras ce qui couvre ses pieds, tu te coucheras, et lui-même t’apprendra ce que tu auras à faire."],[3,5,"Et Ruth répondit: Je ferai tout ce que tu viens de dire.","Et Ruth répondit: Je ferai tout ce que tu viens de dire."],[3,6,"Et elle se rendit à l’aire, et elle fit tout ce que sa belle-mère lui avait recommandé.","Et elle se rendit à l’aire, et elle fit tout ce que sa belle-mère lui avait recommandé."],[3,7,"Et Booz mangea et il but; son cœur fut réjoui et il alla se coucher au coin d’un tas de blé; elle le suivit en silence et elle leva ce qui couvrait ses pieds.","Et Booz mangea et il but; son cœur fut réjoui et il alla se coucher au coin d’un tas de blé; elle le suivit en silence et elle leva ce qui couvrait ses pieds."],[3,8,"Or, à minuit l’homme s’éveilla, et il fut saisi d’étonnement et de trouble en voyant une femme couchée à ses pieds.","Or, à minuit l’homme s’éveilla, et il fut saisi d’étonnement et de trouble en voyant une femme couchée à ses pieds."],[3,9,"Et il dit? Qui es-tu? Elle répondit: Je suis Ruth ta servante, et tu étendras ton aile sur ta servante, parce que tu es rédempteur.","Et il dit? Qui es-tu? Elle répondit: Je suis Ruth ta servante, et tu étendras ton aile sur ta servante, parce que tu es rédempteur."],[3,10,"Et Booz reprit: Bénie sois-tu au nom du Seigneur, ma fille, parce que tu as été bonne et miséricordieuse à la fin plus encore qu’au commencement, et que tu n’as point recherché les jeunes gens pauvres ou riches.","Et Booz reprit: Bénie sois-tu au nom du Seigneur, ma fille, parce que tu as été bonne et miséricordieuse à la fin plus encore qu’au commencement, et que tu n’as point recherché les jeunes gens pauvres ou riches."],[3,11,"Maintenant, ma fille, n’aie point de crainte: tout ce que tu demanderas, je te l’accorderai; car toute la tribu de mon peuple sait que tu es une femme forte.","Maintenant, ma fille, n’aie point de crainte: tout ce que tu demanderas, je te l’accorderai; car toute la tribu de mon peuple sait que tu es une femme forte."],[3,12,"Il est vrai que je suis ton parent, mais il en est un plus proche que moi.","Il est vrai que je suis ton parent, mais il en est un plus proche que moi."],[3,13,"Demeure ici la nuit et demain: s’il veut t’épouser, qu’il t’épouse; mais s’il ne veut t’épouser, je t’épouserai, moi, vive le Seigneur. Couche-toi donc jusqu’à l’aurore.","Demeure ici la nuit et demain: s’il veut t’épouser, qu’il t’épouse; mais s’il ne veut t’épouser, je t’épouserai, moi, vive le Seigneur. Couche-toi donc jusqu’à l’aurore."],[3,14,"Elle resta couchée à ses pieds jusqu’au lendemain; puis, elle se leva avant que l’on pût se reconnaître de près, et Booz lui dit: Que personne ne sache qu’une femme est venue à mon aire.","Elle resta couchée à ses pieds jusqu’au lendemain; puis, elle se leva avant que l’on pût se reconnaître de près, et Booz lui dit: Que personne ne sache qu’une femme est venue à mon aire."],[3,15,"Il ajouta: Soulève le manteau que tu portes; elle le soutint, et il y versa six mesures d’orge; il l’en chargea, et elle rentra dans la ville.","Il ajouta: Soulève le manteau que tu portes; elle le soutint, et il y versa six mesures d’orge; il l’en chargea, et elle rentra dans la ville."],[3,16,"Et Ruth alla retrouver sa belle-mère, et celle-ci lui dit: Ma fille! et l’autre lui raconta tout ce que l’homme avait fait pour elle.","Et Ruth alla retrouver sa belle-mère, et celle-ci lui dit: Ma fille! et l’autre lui raconta tout ce que l’homme avait fait pour elle."],[3,17,"Elle ajouta: Il m’a donné ces dix mesures d’orge, et il m’a dit: Tu ne rentreras pas les mains vides chez ta belle-mère.","Elle ajouta: Il m’a donné ces dix mesures d’orge, et il m’a dit: Tu ne rentreras pas les mains vides chez ta belle-mère."],[3,18,"Or, celle-ci dit: Ne bouge pas, fille, jusqu’à ce que tu apprennes que la chose a réussi, car l’homme n’aura pas de repos qu’il ne l’ait terminée aujourd’hui même.","Or, celle-ci dit: Ne bouge pas, fille, jusqu’à ce que tu apprennes que la chose a réussi, car l’homme n’aura pas de repos qu’il ne l’ait terminée aujourd’hui même."],[4,1,"Booz alla vers la porte de la ville, et après s’y être assis, il vit venir le parent dont il avait parlé; et Booz lui dit: Approche, assieds-toi ici, homme dissimulé. Et l’autre approcha et il s’assit.","Booz alla vers la porte de la ville, et après s’y être assis, il vit venir le parent dont il avait parlé; et Booz lui dit: Approche, assieds-toi ici, homme dissimulé. Et l’autre approcha et il s’assit."],[4,2,"Et Booz prit dix des anciens de la ville, et il leur dit: Asseyez-vous là. Et ils s’assirent.","Et Booz prit dix des anciens de la ville, et il leur dit: Asseyez-vous là. Et ils s’assirent."],[4,3,"Et Booz dit au parent le plus proche: Il y a un champ de notre frère Elimelech qui a été donné à Noémi, laquelle est revenue de Moab.","Et Booz dit au parent le plus proche: Il y a un champ de notre frère Elimelech qui a été donné à Noémi, laquelle est revenue de Moab."],[4,4,"Et moi j’ai dit que je t’en informerais et te dirais: Prends-en possession devant ceux qui sont assis, tous anciens de notre peuple. Si tu veux racheter, rachète; si tu ne le veux, déclare-le-moi; je saurai qu’il n’y a plus personne qui doive racheter, et je viens après toi. Et l’autre répondit: Je rachèterai.","Et moi j’ai dit que je t’en informerais et te dirais: Prends-en possession devant ceux qui sont assis, tous anciens de notre peuple. Si tu veux racheter, rachète; si tu ne le veux, déclare-le-moi; je saurai qu’il n’y a plus personne qui doive racheter, et je viens après toi. Et l’autre répondit: Je rachèterai."],[4,5,"Et Booz lui dit: Le jour où tu acquerras le champ des mains de Noémi, et du consentement de Ruth la Moabite, femme du défunt, il faudra que tu la prennes aussi afin de faire revivre le nom de son mari sur son héritage.","Et Booz lui dit: Le jour où tu acquerras le champ des mains de Noémi, et du consentement de Ruth la Moabite, femme du défunt, il faudra que tu la prennes aussi afin de faire revivre le nom de son mari sur son héritage."],[4,6,"Et le parent le plus proche dit: Je ne suis point capable de le racheter pour moi-même, sinon au détriment de mon propre héritage; rachète pour toi-même ce que j’ai le droit de racheter, parce que je ne puis le racheter.","Et le parent le plus proche dit: Je ne suis point capable de le racheter pour moi-même, sinon au détriment de mon propre héritage; rachète pour toi-même ce que j’ai le droit de racheter, parce que je ne puis le racheter."],[4,7,"Or, dès longtemps en Israël cette règle existait concernant les rachats et les marchés: pour confirmer toute parole, l’homme détachait sa chaussure et la donnait à son proche, qui reprenait son droit de rachat. Tel était le témoignage en Israël.","Or, dès longtemps en Israël cette règle existait concernant les rachats et les marchés: pour confirmer toute parole, l’homme détachait sa chaussure et la donnait à son proche, qui reprenait son droit de rachat. Tel était le témoignage en Israël."],[4,8,"Le parent le plus proche dit donc à Booz: Acquiers pour toi tous mes droits de rachat. Et il dénoua sa chaussure, et il la lui donna.","Le parent le plus proche dit donc à Booz: Acquiers pour toi tous mes droits de rachat. Et il dénoua sa chaussure, et il la lui donna."],[4,9,"Et Booz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd’hui que j’ai acheté de Noémi tous les biens d’Elimelech et tout ce qui appartenait à Chélaïon et à Maalon,","Et Booz dit aux anciens et à tout le peuple: Vous êtes témoins aujourd’hui que j’ai acheté de Noémi tous les biens d’Elimelech et tout ce qui appartenait à Chélaïon et à Maalon,"],[4,10,"Et que de plus, je prends pour ma femme Ruth la Moabite, femme de Maalon, afin de faire revivre le nom du défunt sur son héritage; et le nom du défunt ne sera effacé ni parmi ses frères, ni dans sa tribu. Vous en êtes témoins aujourd’hui.","Et que de plus, je prends pour ma femme Ruth la Moabite, femme de Maalon, afin de faire revivre le nom du défunt sur son héritage; et le nom du défunt ne sera effacé ni parmi ses frères, ni dans sa tribu. Vous en êtes témoins aujourd’hui."],[4,11,"Et tout le peuple qui était près de la porte s’écria: Témoins! Et les anciens dirent: Fasse le Seigneur que la femme qui entre dans ta maison soit comme Rachel et comme Lia, qui l’une et l’autre ont fondé la maison d’Israël, et ont été des femmes fortes en Ephratha; que son nom demeure en Bethléem.","Et tout le peuple qui était près de la porte s’écria: Témoins! Et les anciens dirent: Fasse le Seigneur que la femme qui entre dans ta maison soit comme Rachel et comme Lia, qui l’une et l’autre ont fondé la maison d’Israël, et ont été des femmes fortes en Ephratha; que son nom demeure en Bethléem."],[4,12,"Et que ta maison ressemble à la maison de Pharès que Thamar enfanta à Juda, par la postérité que le Seigneur fera naître pour toi de cette jeune servante.","Et que ta maison ressemble à la maison de Pharès que Thamar enfanta à Juda, par la postérité que le Seigneur fera naître pour toi de cette jeune servante."],[4,13,"Booz prit donc Ruth pour sa femme et il eut commerce avec elle; le Seigneur lui accorda de concevoir, et elle enfanta un fils.","Booz prit donc Ruth pour sa femme et il eut commerce avec elle; le Seigneur lui accorda de concevoir, et elle enfanta un fils."],[4,14,"Et les femmes dirent à Noémi: Béni soit le Seigneur qui ne t’a point laissé manquer d’un rédempteur, et qui veut aujourd’hui que ton nom vive en Israël.","Et les femmes dirent à Noémi: Béni soit le Seigneur qui ne t’a point laissé manquer d’un rédempteur, et qui veut aujourd’hui que ton nom vive en Israël."],[4,15,"Tu auras un soutien qui ranimera ton âme, qui nourrira ta vieillesse: ta belle-fille qui t’aime, et qui vaut mieux pour toi que sept fils, l’a enfanté.","Tu auras un soutien qui ranimera ton âme, qui nourrira ta vieillesse: ta belle-fille qui t’aime, et qui vaut mieux pour toi que sept fils, l’a enfanté."],[4,16,"Et Noémi prit l’enfant et elle le mit dans son sein, et elle fut pour lui comme une nourrice.","Et Noémi prit l’enfant et elle le mit dans son sein, et elle fut pour lui comme une nourrice."],[4,17,"Et les voisins lui donnèrent un nom, disant: Un fils est né à Noémi, et ils le nommèrent Obed; c’est lui qui fut le père de Jessé, père de David.","Et les voisins lui donnèrent un nom, disant: Un fils est né à Noémi, et ils le nommèrent Obed; c’est lui qui fut le père de Jessé, père de David."],[4,18,"Et voici la postérité de Pharès: Pharès engendra Esron;","Et voici la postérité de Pharès: Pharès engendra Esron;"],[4,19,"Et Esron engendra Aram, et Aram engendra Aminadab;","Et Esron engendra Aram, et Aram engendra Aminadab;"],[4,20,"Et Aminadah engendra Naasson, et Naasson engendra Salmon;","Et Aminadah engendra Naasson, et Naasson engendra Salmon;"],[4,21,"Et Salmon engendra Booz, et Booz engendra Obed;","Et Salmon engendra Booz, et Booz engendra Obed;"],[4,22,"Et Obed engendra Jessé, et Jessé engendra David.","Et Obed engendra Jessé, et Jessé engendra David."]],"ell-vamvas1850":[[1,1,"Και εν ταις ημέραις καθ' ας οι κριταί έκρινον, έγεινε πείνα εν τη γη. Και υπήγεν άνθρωπός τις από Βηθλεέμ Ιούδα να παροικήση εν γη Μωάβ, αυτός και η γυνή αυτού και οι δύο υιοί αυτού.","Kai en tais ēmérais kath' as oi kritaí ékrinon, égeine peína en tē gē. Kai ypḗgen ánthrōpós tis apó Bēthleém Ioúda na paroikḗsē en gē Mōáb, autós kai ē gynḗ autoú kai oi dýo yioí autoú."],[1,2,"Το δε όνομα του ανθρώπου ήτο Ελιμέλεχ, και το όνομα της γυναικός αυτού Ναομί, και το όνομα των δύο υιών αυτού Μααλών και Χελαιών, Εφραθαίοι εκ Βηθλεέμ Ιούδα. Και ήλθον εις γην Μωάβ και ήσαν εκεί.","To de ónoma tou anthrṓpou ḗto Elimélech, kai to ónoma tēs gynaikós autoú Naomí, kai to ónoma tōn dýo yiṓn autoú Maalṓn kai Chelaiṓn, Ephrathaíoi ek Bēthleém Ioúda. Kai ḗlthon eis gēn Mōáb kai ḗsan ekeí."],[1,3,"Και απέθανεν Ελιμέλεχ ο ανήρ της Ναομί· και έμεινεν αυτή και οι δύο υιοί αυτής.","Kai apéthanen Elimélech o anḗr tēs Naomí: kai émeinen autḗ kai oi dýo yioí autḗs."],[1,4,"Και ούτοι έλαβον εις εαυτούς γυναίκας Μωαβίτιδας· το όνομα της μιας Ορφά και το όνομα της άλλης Ρούθ· και κατώκησαν εκεί έως δέκα έτη.","Kai oútoi élabon eis eautoús gynaíkas Mōabítidas: to ónoma tēs mias Orphá kai to ónoma tēs állēs Roúth: kai katṓkēsan ekeí éōs déka étē."],[1,5,"Απέθανον δε αμφότεροι, ο Μααλών και ο Χελαιών· και εστερήθη η γυνή των δύο υιών αυτής και του ανδρός αυτής.","Apéthanon de amphóteroi, o Maalṓn kai o Chelaiṓn: kai esterḗthē ē gynḗ tōn dýo yiṓn autḗs kai tou andrós autḗs."],[1,6,"Τότε εσηκώθη αυτή και αι νύμφαι αυτής και επέστρεψαν εκ της γης Μωάβ· διότι ήκουσεν εν γη Μωάβ, ότι επεσκέφθη ο Κύριος τον λαόν αυτού δίδων εις αυτούς άρτον.","Tóte esēkṓthē autḗ kai ai nýmphai autḗs kai epéstrepsan ek tēs gēs Mōáb: dióti ḗkousen en gē Mōáb, óti epesképhthē o Kýrios ton laón autoú dídōn eis autoús árton."],[1,7,"Και εξήλθεν εκ του τόπου όπου ήτο, και αι δύο νύμφαι αυτής μετ' αυτής και επορεύοντο την οδόν διά να επιστρέψωσιν εις γην Ιούδα.","Kai exḗlthen ek tou tópou ópou ḗto, kai ai dýo nýmphai autḗs met' autḗs kai eporeúonto tēn odón diá na epistrépsōsin eis gēn Ioúda."],[1,8,"Είπε δε η Ναομί προς τας δύο νύμφας αυτής, Υπάγετε, επιστρέψατε εκάστη εις τον οίκον της μητρός αυτής. Ο Κύριος να κάμη έλεος εις εσάς, καθώς σεις εκάμετε εις τους αποθανόντας και εις εμέ·","Eípe de ē Naomí pros tas dýo nýmphas autḗs, Ypágete, epistrépsate ekástē eis ton oíkon tēs mētrós autḗs. O Kýrios na kámē éleos eis esás, kathṓs seis ekámete eis tous apothanóntas kai eis emé:"],[1,9,"ο Κύριος να σας δώση να εύρητε ανάπαυσιν, εκάστη εν τω οίκω του ανδρός αυτής. Και εφίλησεν αυτάς· και αυταί ύψωσαν την φωνήν αυτών και έκλαυσαν.","o Kýrios na sas dṓsē na eúrēte anápausin, ekástē en tō oíkō tou andrós autḗs. Kai ephílēsen autás: kai autaí ýpsōsan tēn phōnḗn autṓn kai éklausan."],[1,10,"Και είπον προς αυτήν, Ουχί· αλλά μετά σου θέλομεν επιστρέψει εις τον λαόν σου.","Kai eípon pros autḗn, Ouchí: allá metá sou thélomen epistrépsei eis ton laón sou."],[1,11,"Και είπεν η Ναομί, Επιστρέψατε, θυγατέρες μου· διά τι να έλθητε μετ' εμού; μήπως έχω έτι υιούς εν τη κοιλία μου, διά να γείνωσιν άνδρες σας;","Kai eípen ē Naomí, Epistrépsate, thygatéres mou: diá ti na élthēte met' emoú? mḗpōs échō éti yioús en tē koilía mou, diá na geínōsin ándres sas?"],[1,12,"επιστρέψατε, θυγατέρες μου, υπάγετε· διότι εγήρασα και δεν είμαι διά άνδρα· εάν έλεγον, Έχω ελπίδα, εάν μάλιστα υπανδρευόμην ταύτην την νύκτα και εγέννων έτι υιούς,","epistrépsate, thygatéres mou, ypágete: dióti egḗrasa kai den eímai diá ándra: eán élegon, Échō elpída, eán málista ypandreuómēn taútēn tēn nýkta kai egénnōn éti yioús,"],[1,13,"σεις ηθέλετε προσμένει αυτούς εωσού μεγαλώσωσιν; ηθέλετε δι' αυτούς αναβάλει το να υπανδρευθήτε; μη, θυγατέρες μου· επειδή επικράνθην πολύ πλέον παρά σεις, ότι η χειρ του Κυρίου εξήλθε κατ' εμού.","seis ēthélete prosménei autoús eōsoú megalṓsōsin? ēthélete di' autoús anabálei to na ypandreuthḗte? mē, thygatéres mou: epeidḗ epikránthēn polý pléon pará seis, óti ē cheir tou Kyríou exḗlthe kat' emoú."],[1,14,"Εκείναι δε ύψωσαν την φωνήν αυτών και έκλαυσαν πάλιν· και κατεφίλησεν η Ορφά την πενθεράν αυτής· η δε Ρούθ επροσκολλήθη εις αυτήν.","Ekeínai de ýpsōsan tēn phōnḗn autṓn kai éklausan pálin: kai katephílēsen ē Orphá tēn pentherán autḗs: ē de Roúth eproskollḗthē eis autḗn."],[1,15,"Και είπεν η Ναομί, Ιδού, η σύννυμφός σου επέστρεψε προς τον λαόν αυτής και προς τους θεούς αυτής· επίστρεψον και συ κατόπιν της συννύμφου σου.","Kai eípen ē Naomí, Idoú, ē sýnnymphós sou epéstrepse pros ton laón autḗs kai pros tous theoús autḗs: epístrepson kai sy katópin tēs synnýmphou sou."],[1,16,"Αλλ' η Ρούθ είπε, Μη με ανάγκαζε να σε αφήσω, διά να αναχωρήσω απ' όπισθέν σου· διότι όπου αν συ υπάγης, και εγώ θέλω υπάγει· και όπου αν συ παραμείνης, και εγώ θέλω παραμείνει· ο λαός σου, λαός μου, και ο Θεός σου, Θεός μου·","All' ē Roúth eípe, Mē me anánkaze na se aphḗsō, diá na anachōrḗsō ap' ópisthén sou: dióti ópou an sy ypágēs, kai egṓ thélō ypágei: kai ópou an sy parameínēs, kai egṓ thélō parameínei: o laós sou, laós mou, kai o Theós sou, Theós mou:"],[1,17,"όπου αν αποθάνης, θέλω αποθάνει και εκεί θέλω ταφή· ούτω να κάμη ο Κύριος εις εμέ και ούτω να προσθέση, εάν άλλο τι παρά τον θάνατον χωρίση εμέ από σου.","ópou an apothánēs, thélō apothánei kai ekeí thélō taphḗ: oútō na kámē o Kýrios eis emé kai oútō na prosthésē, eán állo ti pará ton thánaton chōrísē emé apó sou."],[1,18,"Ιδούσα δε η Ναομί ότι αυτή διϊσχυρίζετο να υπάγη μετ' αυτής, έπαυσε να λαλή προς αυτήν.","Idoúsa de ē Naomí óti autḗ diïschyrízeto na ypágē met' autḗs, épause na lalḗ pros autḗn."],[1,19,"Περιεπάτησαν δε αμφότεραι, εωσού έφθασαν εις Βηθλεέμ. Και ότε έφθασαν εις Βηθλεέμ, πάσα η πόλις συνεκινήθη δι' αυτάς, και αι γυναίκες έλεγον, Αύτη είναι η Ναομί;","Periepátēsan de amphóterai, eōsoú éphthasan eis Bēthleém. Kai óte éphthasan eis Bēthleém, pása ē pólis synekinḗthē di' autás, kai ai gynaíkes élegon, Aútē eínai ē Naomí?"],[1,20,"Και αυτή είπε προς αυτάς, Μη με ονομάζετε Ναομί· ονομάζετέ με Μαρά· διότι ο Παντοδύναμος με επίκρανε σφόδρα·","Kai autḗ eípe pros autás, Mē me onomázete Naomí: onomázeté me Mará: dióti o Pantodýnamos me epíkrane sphódra:"],[1,21,"εγώ πλήρης ανεχώρησα, και κενήν επανήγαγέ με ο Κύριος· διά τι με ονομάζετε Ναομί, αφού ο Κύριος εμαρτύρησε κατ' εμού και ο Παντοδύναμος με κατέθλιψεν;","egṓ plḗrēs anechṓrēsa, kai kenḗn epanḗgagé me o Kýrios: diá ti me onomázete Naomí, aphoú o Kýrios emartýrēse kat' emoú kai o Pantodýnamos me katéthlipsen?"],[1,22,"Επέστρεψε λοιπόν η Ναομί, και μετ' αυτής Ρούθ η Μωαβίτις η νύμφη αυτής ελθούσα εκ γης Μωάβ· και αύται έφθασαν εις Βηθλεέμ εν τη αρχή του θερισμού των κριθών.","Epéstrepse loipón ē Naomí, kai met' autḗs Roúth ē Mōabítis ē nýmphē autḗs elthoúsa ek gēs Mōáb: kai aútai éphthasan eis Bēthleém en tē archḗ tou therismoú tōn krithṓn."],[2,1,"Είχε δε η Ναομί συγγενή τινά του ανδρός αυτής, άνθρωπον δυνατόν εν ισχύϊ, εκ της συγγενείας του Ελιμέλεχ· και το όνομα αυτού Βοόζ.","Eíche de ē Naomí syngenḗ tiná tou andrós autḗs, ánthrōpon dynatón en ischýï, ek tēs syngeneías tou Elimélech: kai to ónoma autoú Boóz."],[2,2,"Και είπεν η Ρούθ η Μωαβίτις προς την Ναομί, Ας υπάγω, παρακαλώ, εις τον αγρόν διά να συνάξω αστάχυα κατόπιν ούτινος εύρω χάριν εις τους οφθαλμούς· και είπε προς αυτήν, Ύπαγε, θυγάτηρ μου.","Kai eípen ē Roúth ē Mōabítis pros tēn Naomí, As ypágō, parakalṓ, eis ton agrón diá na synáxō astáchya katópin oútinos eúrō chárin eis tous ophthalmoús: kai eípe pros autḗn, Ýpage, thygátēr mou."],[2,3,"Και υπήγε και ελθούσα εσταχυολόγει εν τω αγρώ κατόπιν των θεριστών· και έτυχεν εν μέρει του αγρού του Βοόζ, όστις ήτο εκ της συγγενείας του Ελιμέλεχ.","Kai ypḗge kai elthoúsa estachyológei en tō agrṓ katópin tōn theristṓn: kai étychen en mérei tou agroú tou Boóz, óstis ḗto ek tēs syngeneías tou Elimélech."],[2,4,"Και ιδού, ο Βοόζ ήλθεν εκ Βηθλεέμ και είπε προς τους θεριστάς, Κύριος μεθ' υμών. Και απεκρίθησαν προς αυτόν, Κύριος να σε ευλογήση.","Kai idoú, o Boóz ḗlthen ek Bēthleém kai eípe pros tous theristás, Kýrios meth' ymṓn. Kai apekríthēsan pros autón, Kýrios na se eulogḗsē."],[2,5,"Τότε είπεν ο Βοόζ προς τον υπηρέτην αυτού, τον επιστάτην των θεριστών, Τίνος είναι η νέα αύτη;","Tóte eípen o Boóz pros ton ypērétēn autoú, ton epistátēn tōn theristṓn, Tínos eínai ē néa aútē?"],[2,6,"Και ο υπηρέτης ο επιστάτης των θεριστών απεκρίθη και είπεν, είναι η νέα η Μωαβίτις, η επιστρέψασα μετά της Ναομί εκ γης Μωάβ·","Kai o ypērétēs o epistátēs tōn theristṓn apekríthē kai eípen, eínai ē néa ē Mōabítis, ē epistrépsasa metá tēs Naomí ek gēs Mōáb:"],[2,7,"και είπεν, Ας σταχυολογήσω, παρακαλώ, και ας συνάξω τι μεταξύ των δεματίων κατόπιν των θεριστών· και ήλθε και εστάθη από πρωΐας έως ταύτης της ώρας· ολίγον μόνον ανεπαύθη εν τη οικία.","kai eípen, As stachyologḗsō, parakalṓ, kai as synáxō ti metaxý tōn dematíōn katópin tōn theristṓn: kai ḗlthe kai estáthē apó prōḯas éōs taútēs tēs ṓras: olígon mónon anepaúthē en tē oikía."],[2,8,"Και είπεν ο Βοόζ προς την Ρούθ, Δεν ακούεις, θυγάτηρ μου; μη υπάγης να σταχυολογήσης εν άλλω αγρώ, μηδέ να αναχωρήσης εντεύθεν, αλλά μένε ενταύθα μετά των κορασίων μου·","Kai eípen o Boóz pros tēn Roúth, Den akoúeis, thygátēr mou? mē ypágēs na stachyologḗsēs en állō agrṓ, mēdé na anachōrḗsēs enteúthen, allá méne entaútha metá tōn korasíōn mou:"],[2,9,"ας ήναι οι οφθαλμοί σου επί τον αγρόν όπου θερίζουσι, και ύπαγε κατόπιν αυτών· δεν προσέταξα εγώ εις τους νέους να μη σε εγγίσωσι; και όταν διψήσης ύπαγε εις τα αγγεία και πίνε από ό,τι αντλήσωσιν οι νέοι.","as ḗnai oi ophthalmoí sou epí ton agrón ópou therízousi, kai ýpage katópin autṓn: den prosétaxa egṓ eis tous néous na mē se engísōsi? kai ótan dipsḗsēs ýpage eis ta angeía kai píne apó ó,ti antlḗsōsin oi néoi."],[2,10,"Η δε έπεσε κατά πρόσωπον και προσεκύνησεν έως εδάφους και είπε προς αυτόν, Πως εγώ εύρηκα χάριν εις τους οφθαλμούς σου, ώστε να λάβης πρόνοιαν περί εμού, ενώ είμαι ξένη;","Ē de épese katá prósōpon kai prosekýnēsen éōs edáphous kai eípe pros autón, Pōs egṓ eúrēka chárin eis tous ophthalmoús sou, ṓste na lábēs prónoian perí emoú, enṓ eímai xénē?"],[2,11,"Και ο Βοόζ απεκρίθη και είπε προς αυτήν, Ανηγγέλθησαν προς εμέ ακριβώς πάντα όσα έκαμες εις την πενθεράν σου μετά τον θάνατον του ανδρός σου· και ότι αφήκας τον πατέρα σου και την μητέρα σου και την γην της γεννήσεώς σου, και ήλθες προς λαόν, τον οποίον δεν εγνώριζες πρότερον·","Kai o Boóz apekríthē kai eípe pros autḗn, Anēngélthēsan pros emé akribṓs pánta ósa ékames eis tēn pentherán sou metá ton thánaton tou andrós sou: kai óti aphḗkas ton patéra sou kai tēn mētéra sou kai tēn gēn tēs gennḗseṓs sou, kai ḗlthes pros laón, ton opoíon den egnṓrizes próteron:"],[2,12,"ο Κύριος να ανταμείψη το έργον σου, και ο μισθός σου να ήναι πλήρης παρά Κυρίου του Θεού του Ισραήλ, υπό τας πτέρυγας του οποίου ήλθες να σκεπασθής.","o Kýrios na antameípsē to érgon sou, kai o misthós sou na ḗnai plḗrēs pará Kyríou tou Theoú tou Israḗl, ypó tas ptérygas tou opoíou ḗlthes na skepasthḗs."],[2,13,"Η δε είπεν, Ας εύρω χάριν εις τους οφθαλμούς σου, κύριέ μου· επειδή με παρηγόρησας και επειδή ελάλησας ευμενώς προς την δούλην σου, αν και εγώ δεν είμαι ουδέ ως μία των θεραπαινίδων σου.","Ē de eípen, As eúrō chárin eis tous ophthalmoús sou, kýrié mou: epeidḗ me parēgórēsas kai epeidḗ elálēsas eumenṓs pros tēn doúlēn sou, an kai egṓ den eímai oudé ōs mía tōn therapainídōn sou."],[2,14,"Και είπε προς αυτήν ο Βοόζ την ώραν του φαγητού, Ελθέ και φάγε εκ του άρτου και βρέξον το ψωμίον σου εις το όξος. Και αυτή εκάθισεν εις τα πλάγια των θεριστών· εκείνος δε έδωκεν εις αυτήν σίτον πεφρυγανισμένον, και έφαγε και εχορτάσθη και επερίσσευσε.","Kai eípe pros autḗn o Boóz tēn ṓran tou phagētoú, Elthé kai pháge ek tou ártou kai bréxon to psōmíon sou eis to óxos. Kai autḗ ekáthisen eis ta plágia tōn theristṓn: ekeínos de édōken eis autḗn síton pephryganisménon, kai éphage kai echortásthē kai eperísseuse."],[2,15,"Και εσηκώθη να σταχυολογήση, και προσέταξεν ο Βοόζ εις τους νέους αυτού, λέγων, Και μεταξύ των δεματίων ας σταχυολογή, και μη επιπλήττετε αυτήν·","Kai esēkṓthē na stachyologḗsē, kai prosétaxen o Boóz eis tous néous autoú, légōn, Kai metaxý tōn dematíōn as stachyologḗ, kai mē epiplḗttete autḗn:"],[2,16,"και μάλιστα αφίνετε να πίπτη τι από των χειροβόλων διά αυτήν και αφίνετε να συλλέγη και μη ελέγχετε αυτήν.","kai málista aphínete na píptē ti apó tōn cheirobólōn diá autḗn kai aphínete na syllégē kai mē elénchete autḗn."],[2,17,"Και εσταχυολόγησεν εν τω αγρώ έως εσπέρας και εκοπάνισεν όσον εσταχυολόγησε· και ήτο έως εν εφά κριθής.","Kai estachyológēsen en tō agrṓ éōs espéras kai ekopánisen óson estachyológēse: kai ḗto éōs en ephá krithḗs."],[2,18,"Και εσήκωσεν αυτό και εισήλθεν εις την πόλιν· και είδεν η πενθερά αυτής όσον εσταχυολόγησε· και εκβαλούσα η Ρούθ, έδωκεν εις αυτήν ό,τι είχε περισσεύσει αφού εχορτάσθη.","Kai esḗkōsen autó kai eisḗlthen eis tēn pólin: kai eíden ē pentherá autḗs óson estachyológēse: kai ekbaloúsa ē Roúth, édōken eis autḗn ó,ti eíche perisseúsei aphoú echortásthē."],[2,19,"Και είπε προς αυτήν η πενθερά αυτής, Που εσταχυολόγησας σήμερον; και που εδούλευσας; ευλογημένος να ήναι εκείνος όστις έλαβε πρόνοιαν περί σου. Και εκείνη εφανέρωσε προς την πενθεράν αυτής εις τίνος αγρόν εδούλευσε και είπε, το όνομα του ανθρώπου, εις τον οποίον εδούλευσα σήμερον, είναι Βοόζ.","Kai eípe pros autḗn ē pentherá autḗs, Pou estachyológēsas sḗmeron? kai pou edoúleusas? eulogēménos na ḗnai ekeínos óstis élabe prónoian perí sou. Kai ekeínē ephanérōse pros tēn pentherán autḗs eis tínos agrón edoúleuse kai eípe, to ónoma tou anthrṓpou, eis ton opoíon edoúleusa sḗmeron, eínai Boóz."],[2,20,"Και είπεν η Ναομί προς την νύμφην αυτής, Ευλογημένος παρά Κυρίου εκείνος όστις δεν αφήκε το έλεος αυτού προς τους ζώντας και προς τους τεθνεώτας. Και είπε προς αυτήν η Ναομί, Συγγενής ημών είναι ο άνθρωπος ούτος εκ των πλησίον συγγενών ημών.","Kai eípen ē Naomí pros tēn nýmphēn autḗs, Eulogēménos pará Kyríou ekeínos óstis den aphḗke to éleos autoú pros tous zṓntas kai pros tous tethneṓtas. Kai eípe pros autḗn ē Naomí, Syngenḗs ēmṓn eínai o ánthrōpos oútos ek tōn plēsíon syngenṓn ēmṓn."],[2,21,"Και είπεν η Ρούθ η Μωαβίτις, Αυτός με είπε προσέτι, Συ θέλεις μένει μετά των ανθρώπων μου, εωσού τελειώσωσιν όλον τον θερισμόν μου.","Kai eípen ē Roúth ē Mōabítis, Autós me eípe proséti, Sy théleis ménei metá tōn anthrṓpōn mou, eōsoú teleiṓsōsin ólon ton therismón mou."],[2,22,"Και είπεν η Ναομί προς την Ρούθ την νύμφην αυτής, Είναι καλόν, θυγάτηρ μου, να εκβαίνης μετά των κορασίων αυτού, και να μη σε απαντήσωσιν εν άλλω αγρώ.","Kai eípen ē Naomí pros tēn Roúth tēn nýmphēn autḗs, Eínai kalón, thygátēr mou, na ekbaínēs metá tōn korasíōn autoú, kai na mē se apantḗsōsin en állō agrṓ."],[2,23,"Και προσεκολλήθη εις τα κοράσια του Βοόζ διά να σταχυολογή, εωσού τελειώση ο θερισμός των κριθών και ο θερισμός του σίτου· και εκάθητο μετά της πενθεράς αυτής.","Kai prosekollḗthē eis ta korásia tou Boóz diá na stachyologḗ, eōsoú teleiṓsē o therismós tōn krithṓn kai o therismós tou sítou: kai ekáthēto metá tēs pentherás autḗs."],[3,1,"Και είπε προς αυτήν η Ναομί η πενθερά αυτής, Θυγάτηρ μου, να μη ζητήσω ανάπαυσιν εις σε διά να ευημερήσης;","Kai eípe pros autḗn ē Naomí ē pentherá autḗs, Thygátēr mou, na mē zētḗsō anápausin eis se diá na euēmerḗsēs?"],[3,2,"και τώρα, μήπως δεν είναι Βοόζ εκ της συγγενείας ημών, μετά των κορασίων του οποίου ήσο; ιδού, αυτός λικμίζει ταύτην την νύκτα το αλώνιον των κριθών·","kai tṓra, mḗpōs den eínai Boóz ek tēs syngeneías ēmṓn, metá tōn korasíōn tou opoíou ḗso? idoú, autós likmízei taútēn tēn nýkta to alṓnion tōn krithṓn:"],[3,3,"λούσθητι λοιπόν και αλείφθητι και ενδύθητι την στολήν σου και κατάβα εις το αλώνιον· μη γνωρισθής εις τον άνθρωπον, εωσού τελειώση από του να φάγη και να πίη·","loústhēti loipón kai aleíphthēti kai endýthēti tēn stolḗn sou kai katába eis to alṓnion: mē gnōristhḗs eis ton ánthrōpon, eōsoú teleiṓsē apó tou na phágē kai na píē:"],[3,4,"και ενώ πλαγιάζει, παρατήρησον τον τόπον όπου πλαγιάζει, και ελθούσα σήκωσον το σκέπασμα από των ποδών αυτού, και πλαγίασον· και εκείνος θέλει σοι ειπεί τι να κάμης.","kai enṓ plagiázei, paratḗrēson ton tópon ópou plagiázei, kai elthoúsa sḗkōson to sképasma apó tōn podṓn autoú, kai plagíason: kai ekeínos thélei soi eipeí ti na kámēs."],[3,5,"Η δε είπε προς αυτήν, Πάντα όσα λέγεις εις εμέ, θέλω κάμει.","Ē de eípe pros autḗn, Pánta ósa légeis eis emé, thélō kámei."],[3,6,"Και κατέβη εις το αλώνιον και έκαμε πάντα όσα προσέταξεν εις αυτήν η πενθερά αυτής.","Kai katébē eis to alṓnion kai ékame pánta ósa prosétaxen eis autḗn ē pentherá autḗs."],[3,7,"Και αφού ο Βοόζ έφαγε και έπιε, και ευφράνη η καρδία αυτού, υπήγε να πλαγιάση εις την άκραν του σωρού του σίτου· εκείνη δε ήλθε κρυφίως και εσήκωσε ο σκέπασμα από των ποδών αυτού και επλαγίασε.","Kai aphoú o Boóz éphage kai épie, kai euphránē ē kardía autoú, ypḗge na plagiásē eis tēn ákran tou sōroú tou sítou: ekeínē de ḗlthe kryphíōs kai esḗkōse o sképasma apó tōn podṓn autoú kai eplagíase."],[3,8,"Και προς το μεσονύκτιον εξέστη ο άνθρωπος και συνεταράχθη· και ιδού, γυνή εκοιμάτο παρά τους πόδας αυτού.","Kai pros to mesonýktion exéstē o ánthrōpos kai synetaráchthē: kai idoú, gynḗ ekoimáto pará tous pódas autoú."],[3,9,"Και είπε, Ποία είσαι συ; Εκείνη δε απεκρίθη, Εγώ η Ρούθ η δούλη σου· άπλωσον λοιπόν την πτέρυγά σου επί την δούλην σου· διότι είσαι ο πλησιέστερος συγγενής μου.","Kai eípe, Poía eísai sy? Ekeínē de apekríthē, Egṓ ē Roúth ē doúlē sou: áplōson loipón tēn ptérygá sou epí tēn doúlēn sou: dióti eísai o plēsiésteros syngenḗs mou."],[3,10,"Ο δε είπεν, Ευλογημένη να ήσαι παρά Κυρίου, θύγατερ· διότι έδειξας περισσοτέραν αγαθωσύνην εσχάτως παρά πρότερον, μη υπάγουσα κατόπιν νέων, είτε πτωχών είτε πλουσίων·","O de eípen, Eulogēménē na ḗsai pará Kyríou, thýgater: dióti édeixas perissotéran agathōsýnēn eschátōs pará próteron, mē ypágousa katópin néōn, eíte ptōchṓn eíte plousíōn:"],[3,11,"και τώρα, θύγατερ, μη φοβού· θέλω κάμει εις σε παν ό,τι είπης· διότι πάσα η πόλις του λαού μου εξεύρει ότι είσαι γυνή ενάρετος·","kai tṓra, thýgater, mē phoboú: thélō kámei eis se pan ó,ti eípēs: dióti pása ē pólis tou laoú mou exeúrei óti eísai gynḗ enáretos:"],[3,12,"και τώρα είναι αληθές ότι εγώ είμαι στενός συγγενής· είναι όμως άλλος συγγενής πλησιέστερος εμού·","kai tṓra eínai alēthés óti egṓ eímai stenós syngenḗs: eínai ómōs állos syngenḗs plēsiésteros emoú:"],[3,13,"μείνον ταύτην την νύκτα· και το πρωΐ εάν αυτός θέλη να εκπληρώση προς σε το χρέος το συγγενικόν, καλόν· ας το εκπληρώση· αλλ' εάν δεν θέλη να εκπληρώση προς σε το χρέος το συγγενικόν, τότε εγώ θέλω εκπληρώσει τούτο προς σε, ζη Κύριος· κοιμήθητι έως πρωΐ.","meínon taútēn tēn nýkta: kai to prōḯ eán autós thélē na ekplērṓsē pros se to chréos to syngenikón, kalón: as to ekplērṓsē: all' eán den thélē na ekplērṓsē pros se to chréos to syngenikón, tóte egṓ thélō ekplērṓsei toúto pros se, zē Kýrios: koimḗthēti éōs prōḯ."],[3,14,"Και εκοιμήθη παρά τους πόδας αυτού έως πρωΐ· και εσηκώθη πριν διακρίνη άνθρωπος άνθρωπον. Και εκείνος είπεν, Ας μη γνωρισθή ότι ήλθεν η γυνή εις το αλώνιον.","Kai ekoimḗthē pará tous pódas autoú éōs prōḯ: kai esēkṓthē prin diakrínē ánthrōpos ánthrōpon. Kai ekeínos eípen, As mē gnōristhḗ óti ḗlthen ē gynḗ eis to alṓnion."],[3,15,"Είπε προσέτι, Φέρε το περικάλυμμα το επάνω σου και κράτει αυτό. Και εκείνη εκράτει αυτό, και αυτός εμέτρησεν εξ μέτρα κριθής και έβαλεν επ' αυτήν· και υπήγεν εις την πόλιν.","Eípe proséti, Phére to perikálymma to epánō sou kai krátei autó. Kai ekeínē ekrátei autó, kai autós emétrēsen ex métra krithḗs kai ébalen ep' autḗn: kai ypḗgen eis tēn pólin."],[3,16,"Και ότε ήλθε προς την πενθεράν αυτής, εκείνη είπε, Τι έγεινεν εις σε, θυγάτηρ μου; Και αυτή ανήγγειλε προς αυτήν πάντα όσα έκαμεν εις αυτήν ο άνθρωπος·","Kai óte ḗlthe pros tēn pentherán autḗs, ekeínē eípe, Ti égeinen eis se, thygátēr mou? Kai autḗ anḗngeile pros autḗn pánta ósa ékamen eis autḗn o ánthrōpos:"],[3,17,"και είπεν, Έδωκεν εις εμέ ταύτα τα εξ μέτρα της κριθής· διότι, Δεν θέλεις υπάγει, μοι είπε, κενή προς την πενθεράν σου.","kai eípen, Édōken eis emé taúta ta ex métra tēs krithḗs: dióti, Den théleis ypágei, moi eípe, kenḗ pros tēn pentherán sou."],[3,18,"Η δε είπε, Κάθου, θυγάτηρ μου, εωσού ίδης πως θέλει τελειώσει το πράγμα· διότι ο άνθρωπος δεν θέλει ησυχάσει, εωσού τελειώση το πράγμα σήμερον.","Ē de eípe, Káthou, thygátēr mou, eōsoú ídēs pōs thélei teleiṓsei to prágma: dióti o ánthrōpos den thélei ēsychásei, eōsoú teleiṓsē to prágma sḗmeron."],[4,1,"Και ανέβη ο Βοόζ εις την πύλην και εκάθισεν εκεί· και ιδού, διέβαινεν ο συγγενής, περί του οποίου ώμίλησεν ο Βοόζ. Και είπεν, Ω συ, στρέψον, κάθισον ενταύθα. Και εστράφη και εκάθισε.","Kai anébē o Boóz eis tēn pýlēn kai ekáthisen ekeí: kai idoú, diébainen o syngenḗs, perí tou opoíou ṓmílēsen o Boóz. Kai eípen, Ō sy, strépson, káthison entaútha. Kai estráphē kai ekáthise."],[4,2,"Και έλαβεν ο Βοόζ δέκα άνδρας εκ των πρεσβυτέρων της πόλεως, και είπε, Καθίσατε ενταύθα. Και εκάθισαν.","Kai élaben o Boóz déka ándras ek tōn presbytérōn tēs póleōs, kai eípe, Kathísate entaútha. Kai ekáthisan."],[4,3,"Και είπε προς τον συγγενή, Η Ναομί, η επιστρέψασα εκ γης Μωάβ, πωλεί το μερίδιον του αγρού, το οποίον ήτο του αδελφού ημών Ελιμέλεχ·","Kai eípe pros ton syngenḗ, Ē Naomí, ē epistrépsasa ek gēs Mōáb, pōleí to merídion tou agroú, to opoíon ḗto tou adelphoú ēmṓn Elimélech:"],[4,4,"και εγώ είπα να σε ειδοποιήσω, λέγων, Αγόρασον αυτό έμπροσθεν των κατοίκων και έμπροσθεν των πρεσβυτέρων του λαού μου· εάν θέλης να εξαγοράσης αυτό ως συγγενής, εξαγόρασον· αλλ' εάν δεν θέλης να εξαγοράσης αυτό, ειπέ προς εμέ, διά να εξεύρω· διότι δεν είναι άλλος να εξαγοράση αυτό ως συγγενής παρά σύ· και εγώ είμαι μετά σε. Ο δε είπεν, Εγώ θέλω εξαγοράσει αυτό.","kai egṓ eípa na se eidopoiḗsō, légōn, Agórason autó émprosthen tōn katoíkōn kai émprosthen tōn presbytérōn tou laoú mou: eán thélēs na exagorásēs autó ōs syngenḗs, exagórason: all' eán den thélēs na exagorásēs autó, eipé pros emé, diá na exeúrō: dióti den eínai állos na exagorásē autó ōs syngenḗs pará sý: kai egṓ eímai metá se. O de eípen, Egṓ thélō exagorásei autó."],[4,5,"Και είπεν ο Βοόζ, Καθ' ην ημέραν αγοράσης τον αγρόν εκ της χειρός της Ναομί, πρέπει να λάβης και την Ρούθ την Μωαβίτιν, γυναίκα του αποθανόντος, διά να αναστήσης το όνομα του αποθανόντος επί της κληρονομίας αυτού.","Kai eípen o Boóz, Kath' ēn ēméran agorásēs ton agrón ek tēs cheirós tēs Naomí, prépei na lábēs kai tēn Roúth tēn Mōabítin, gynaíka tou apothanóntos, diá na anastḗsēs to ónoma tou apothanóntos epí tēs klēronomías autoú."],[4,6,"Και είπεν ο συγγενής, Δεν δύναμαι να εκπληρώσω το χρέος το συγγενικόν, μήποτε φθείρω την κληρονομίαν μου· εκπλήρωσον συ το χρέος μου το συγγενικόν, διότι δεν δύναμαι εγώ να εκπληρώσω αυτό.","Kai eípen o syngenḗs, Den dýnamai na ekplērṓsō to chréos to syngenikón, mḗpote phtheírō tēn klēronomían mou: ekplḗrōson sy to chréos mou to syngenikón, dióti den dýnamai egṓ na ekplērṓsō autó."],[4,7,"Ούτος δε ήτο ο τρόπος το πάλαι εν τω Ισραήλ περί του δικαιώματος της συγγενείας και περί της απαλλοτριώσεως, διά να βεβαιούται πας λόγος· ο άνθρωπος λύων το υπόδημα αυτού, έδιδεν εις τον πλησίον αυτού· και τούτο ήτο μαρτυρία εν τω Ισραήλ.","Oútos de ḗto o trópos to pálai en tō Israḗl perí tou dikaiṓmatos tēs syngeneías kai perí tēs apallotriṓseōs, diá na bebaioútai pas lógos: o ánthrōpos lýōn to ypódēma autoú, édiden eis ton plēsíon autoú: kai toúto ḗto martyría en tō Israḗl."],[4,8,"Διά τούτο είπεν ο συγγενής προς τον Βοόζ, Αγόρασον αυτό εις σεαυτόν. Και έλυσε το υπόδημα αυτού.","Diá toúto eípen o syngenḗs pros ton Boóz, Agórason autó eis seautón. Kai élyse to ypódēma autoú."],[4,9,"Τότε είπεν ο Βοόζ προς τους πρεσβυτέρους και πάντα τον λαόν, Μάρτυρες είσθε σήμερον, ότι ηγόρασα πάντα τα του Ελιμέλεχ και πάντα τα του Χελαιών και Μααλών, εκ της χειρός της Ναομί·","Tóte eípen o Boóz pros tous presbytérous kai pánta ton laón, Mártyres eísthe sḗmeron, óti ēgórasa pánta ta tou Elimélech kai pánta ta tou Chelaiṓn kai Maalṓn, ek tēs cheirós tēs Naomí:"],[4,10,"και προσέτι, την Ρούθ την Μωαβίτιν την γυναίκα του Μααλών, έλαβον εις εμαυτόν διά γυναίκα, διά να αναστήσω το όνομα του αποθανόντος επί της κληρονομίας αυτού, διά να μη εξαλειφθή το όνομα του αποθανόντος εκ των αδελφών αυτού και εκ της πόλεως της κατοικίας αυτού· μάρτυρες είσθε σήμερον.","kai proséti, tēn Roúth tēn Mōabítin tēn gynaíka tou Maalṓn, élabon eis emautón diá gynaíka, diá na anastḗsō to ónoma tou apothanóntos epí tēs klēronomías autoú, diá na mē exaleiphthḗ to ónoma tou apothanóntos ek tōn adelphṓn autoú kai ek tēs póleōs tēs katoikías autoú: mártyres eísthe sḗmeron."],[4,11,"Και πας ο λαός ο εν τη πύλη και οι πρεσβύτεροι είπαν, Μάρτυρες· ο Κύριος να κάμη την γυναίκα, ήτις εισέρχεται εις τον οίκόν σου, ως την Ραχήλ και ως την Λείαν, αίτινες ωκοδόμησαν αμφότεραι τον οίκον Ισραήλ· και ίσχυε εν Εφραθά και έσο περίφημος εν Βηθλεέμ·","Kai pas o laós o en tē pýlē kai oi presbýteroi eípan, Mártyres: o Kýrios na kámē tēn gynaíka, ḗtis eisérchetai eis ton oíkón sou, ōs tēn Rachḗl kai ōs tēn Leían, aítines ōkodómēsan amphóterai ton oíkon Israḗl: kai íschye en Ephrathá kai éso períphēmos en Bēthleém:"],[4,12,"και ας γείνη ο οίκός σου ως ο οίκος του Φαρές, τον οποίον εγέννησεν η Θάμαρ εις τον Ιούδαν, εκ του σπέρματος το οποίον ο Κύριος θέλει δώσει εις σε εκ της νέας ταύτης.","kai as geínē o oíkós sou ōs o oíkos tou Pharés, ton opoíon egénnēsen ē Thámar eis ton Ioúdan, ek tou spérmatos to opoíon o Kýrios thélei dṓsei eis se ek tēs néas taútēs."],[4,13,"Και έλαβεν ο Βοόζ την Ρούθ, και έγεινε γυνή αυτού· και ότε εισήλθε προς αυτήν, ο Κύριος έδωκεν εις αυτήν σύλληψιν, και εγέννησεν υιόν.","Kai élaben o Boóz tēn Roúth, kai égeine gynḗ autoú: kai óte eisḗlthe pros autḗn, o Kýrios édōken eis autḗn sýllēpsin, kai egénnēsen yión."],[4,14,"Και είπαν αι γυναίκες προς την Ναομί, Ευλογητός ο Κύριος, όστις σήμερον δεν σε απεστέρησε συγγενούς, ώστε το όνομα αυτού να καλήται εν τω Ισραήλ·","Kai eípan ai gynaíkes pros tēn Naomí, Eulogētós o Kýrios, óstis sḗmeron den se apestérēse syngenoús, ṓste to ónoma autoú na kalḗtai en tō Israḗl:"],[4,15,"και ούτος θέλει είσθαι εις σε αναψυχωτής της ζωής και θέλει θρέψει την πολιάν σου· διότι εγέννησεν αυτόν η νύμφη σου, ήτις σε αγαπά, ήτις είναι εις σε καλητέρα παρά επτά υιούς.","kai oútos thélei eísthai eis se anapsychōtḗs tēs zōḗs kai thélei thrépsei tēn polián sou: dióti egénnēsen autón ē nýmphē sou, ḗtis se agapá, ḗtis eínai eis se kalētéra pará eptá yioús."],[4,16,"Τότε έλαβεν η Ναομί το παιδίον και έθεσεν αυτό εις τον κόλπον αυτής και έγεινεν εις αυτό τροφός.","Tóte élaben ē Naomí to paidíon kai éthesen autó eis ton kólpon autḗs kai égeinen eis autó trophós."],[4,17,"Και αι γείτονες έδωκαν εις αυτό όνομα, λέγουσαι, Υιός εγεννήθη εις την Ναομί· και εκάλεσαν το όνομα αυτού Ωβήδ· ούτος είναι ο πατήρ του Ιεσσαί πατρός του Δαβίδ.","Kai ai geítones édōkan eis autó ónoma, légousai, Yiós egennḗthē eis tēn Naomí: kai ekálesan to ónoma autoú Ōbḗd: oútos eínai o patḗr tou Iessaí patrós tou Dabíd."],[4,18,"Και αύτη είναι η γενεαλογία του Φαρές· ο Φαρές εγέννησε τον Εσρών,","Kai aútē eínai ē genealogía tou Pharés: o Pharés egénnēse ton Esrṓn,"],[4,19,"Εσρών δε εγέννησε τον Αράμ, Αράμ δε εγέννησε τον Αμιναδάβ,","Esrṓn de egénnēse ton Arám, Arám de egénnēse ton Aminadáb,"],[4,20,"Αμιναδάβ δε εγέννησε τον Ναασσών, Ναασσών δε εγέννησε τον Σαλμών,","Aminadáb de egénnēse ton Naassṓn, Naassṓn de egénnēse ton Salmṓn,"],[4,21,"Σαλμών δε εγέννησε τον Βοόζ, Βοόζ δε εγέννησε τον Ωβήδ,","Salmṓn de egénnēse ton Boóz, Boóz de egénnēse ton Ōbḗd,"],[4,22,"Ωβήδ δε εγέννησε τον Ιεσσαί, και ο Ιεσσαί εγέννησε τον Δαβίδ.","Ōbḗd de egénnēse ton Iessaí, kai o Iessaí egénnēse ton Dabíd."]],"grc-swete":[[1,1,"ΚΑΙ ἐγένετο ἐν τῷ κρίνειν τοὺς κριτὰς καὶ ἐγένετο λιμὸς ἐν τῆ γῆ· καὶ ἐπορεύθη ἀνὴρ ἀπὸ Βαιθλέεμ τῆς ᾿Ιούδα τοῦ παροικῆσαι ἐν ἀγρῷ Μωάβ, αὐτὸς καὶ ἡ γυνὴ αὐτοῦ καὶ οἱ υἱοὶ αὐτοῦ.","KAI egéneto en tō̂i krínein toùs kritàs kaì egéneto limòs en tē̂ gē̂: kaì eporeúthē anḕr apò Baithléem tē̂s ᾿Ioúda toû paroikē̂sai en agrō̂i Mōáb, autòs kaì hē gynḕ autoû kaì hoi hyioì autoû."],[1,2,"καὶ ὄνομα τῷ ἀνδρὶ ᾿Αβειμέλεχ, καὶ ὄνομα τοῖς δυσὶν υἱοῖς αὐτοῦ Μααλὼν καὶ ών, ᾿Εφραθαῖοι ἐκ Βαιθλέεμ τῆς Ἰούδα· καὶ ἥλθοσαν εἰς ἀγρὸν καὶ ἦσαν ἐκεῖ.","kaì ónoma tō̂i andrì ᾿Abeimélech, kaì ónoma toîs dysìn hyioîs autoû Maalṑn kaì ṓn, ᾿Ephrathaîoi ek Baithléem tē̂s Ioúda: kaì hḗlthosan eis agròn kaì ē̂san ekeî."],[1,3,"καὶ ἀπέθανεν ᾿Αβειμέλεχ ὁ ἀνὴρ τῆς Νωεμείν, καὶ κατελείφθη αὕτη καὶ οἱ δύο υἱοὶ αὐτῆς.","kaì apéthanen ᾿Abeimélech ho anḕr tē̂s Nōemeín, kaì kateleíphthē haútē kaì hoi dýo hyioì autē̂s."],[1,4,"καὶ ἐλάβοσαν ἑαυτοῖς γυναῖκας Μωαβείτιδας· ὄνομα τῇ μιᾷ ᾿Ορφά, καὶ ὄνομα τῇ δευτέρᾳ ῾Ρούθ· καὶ κατῴκησαν ἐκεῖ ὡς δέκα ἔτη.","kaì elábosan heautoîs gynaîkas Mōabeítidas: ónoma tē̂i miā̂i ᾿Orphá, kaì ónoma tē̂i deutérāi ῾Roúth: kaì katṓikēsan ekeî hōs déka étē."],[1,5,"καὶ ἀπέθανον καί γε ἀμφότεροι, Μααλὼν καὶ Χελαιών· καὶ κατελείφθη ἡ γυνὴ ἀπὸ τοῦ ἀνδρὸς αὐτῆς καὶ ἀπὸ τῶν δύο υἱῶν αὐτῆς.","kaì apéthanon kaí ge amphóteroi, Maalṑn kaì Chelaiṓn: kaì kateleíphthē hē gynḕ apò toû andròs autē̂s kaì apò tō̂n dýo hyiō̂n autē̂s."],[1,6,"Καὶ ἀνέστη αὕτη καὶ αἱ δύο νύμφαι αὐτῆς καὶ ἀπέστρεψαν ἐξ ἀγροῦ Μωάβ, ὅτι ἤκουσαν ἐν ἀγρῷ Μωὰβ ὅτι ᾿Επέσκεπται Κύριος τὸν λαὸν αὐτοῦ, δοῦναι αὐτοῖς ἄρτους.","Kaì anéstē haútē kaì hai dýo nýmphai autē̂s kaì apéstrepsan ex agroû Mōáb, hóti ḗkousan en agrō̂i Mōàb hóti ᾿Epéskeptai Kýrios tòn laòn autoû, doûnai autoîs ártous."],[1,7,"καὶ ἐξῆλθεν ἐκ τοῦ τόπου οὗ ἦν ἐκεῖ, καὶ αἱ δύο νύμφαι αὐτῆς μετ᾿ αὐτῆς· καὶ ἐπορεύοντο ἐν τῇ ὁδῷ τοῦ ἐπιστρέψαι εἰς τὴν γῆν Ἰούδα.","kaì exē̂lthen ek toû tópou hoû ē̂n ekeî, kaì hai dýo nýmphai autē̂s met᾿ autē̂s: kaì eporeúonto en tē̂i hodō̂i toû epistrépsai eis tḕn gē̂n Ioúda."],[1,8,"καὶ εἶπεν Νωεμεὶν ταῖς νύμφαις αὐτῆς Πορεύεσθε δή, ἀποστράφητε ἑκάστη εἰς οἶκον μητρὸς αὐτῆς· ποιήσαι κύριος μεθ’ ὑμῶν ἔλεος, καθὼς ἐποιήσατε μετὰ τῶν τεθνηκότων καὶ μετ’ ἐμοῦ·","kaì eîpen Nōemeìn taîs nýmphais autē̂s Poreúesthe dḗ, apostráphēte hekástē eis oîkon mētròs autē̂s: poiḗsai kýrios meth’ hymō̂n éleos, kathṑs epoiḗsate metà tō̂n tethnēkótōn kaì met’ emoû:"],[1,9,"δῴη κύριος ὑμῖν καὶ εὕροιτε ἀνάπαυσιν, ἑκάστη ἐν οἴκῳ ἀνδρὸς αὐτῆς. καὶ κατεφίλησεν αὐτάς· καὶ ἐπῆραν τὴν φωνὴν αὐτῶν καὶ ἔκλαυσαν.","dṓiē kýrios hymîn kaì heúroite anápausin, hekástē en oíkōi andròs autē̂s. kaì katephílēsen autás: kaì epē̂ran tḕn phōnḕn autō̂n kaì éklausan."],[1,10,"καὶ εἶπαν αὐτῇ Μετὰ σοῦ ἐπιστρέφομεν εἰς τὸν λαόν σου.","kaì eîpan autē̂i Metà soû epistréphomen eis tòn laón sou."],[1,11,"καὶ εἶπεν Νωεμείν ᾿Επιστράφητε δή, θυγατέρες μου· καὶ ἵνα τί πορεύεσθε μετ’ ἑ μοῦ ; μὴ ἔτι μοι υἱοὶ ἐν τῇ κοιλίᾳ μου, καὶ ἔσονται ὑμίν εἰς ἄνδρας;","kaì eîpen Nōemeín ᾿Epistráphēte dḗ, thygatéres mou: kaì hína tí poreúesthe met’ he moû ? mḕ éti moi hyioì en tē̂i koilíāi mou, kaì ésontai hymín eis ándras?"],[1,12,"ἐπιστράφητε δή, θυγατέρες μου, διότι γεγήρακα τοῦ μὴ εἶναι ἀνδρί· ὅτι εἶπα ὅτι ἔστιν μοι ὑπόστασις τοῦ γενηθῆναί με ἀνδρὶ καὶ τέξομαι υἱούς,","epistráphēte dḗ, thygatéres mou, dióti gegḗraka toû mḕ eînai andrí: hóti eîpa hóti éstin moi hypóstasis toû genēthē̂naí me andrì kaì téxomai hyioús,"],[1,13,"μὴ αὐτοὺς προσδέξεσθε ἕως οὗ ἁδρυνθῶσιν ; ἢ αὐτοῖς κατασχεθήσεσθε τοῦ μὴ γενέσθαι ἀνδρί; μὴ δὴ θυγατέρες μου, ὅτι ἐπικράνθη μοι ὑπὲρ ὑμᾶς, ὅτι ἐξῆλθεν ἐν ἐμοὶ χεὶρ Κυρίου.","mḕ autoùs prosdéxesthe héōs hoû hadrynthō̂sin ? ḕ autoîs kataschethḗsesthe toû mḕ genésthai andrí? mḕ dḕ thygatéres mou, hóti epikránthē moi hypèr hymâs, hóti exē̂lthen en emoì cheìr Kyríou."],[1,14,"καὶ ἐπῆραν τὴν φωνὴν αὐτῶν καὶ ἔκλαυσαν ἔτι· καὶ κατεφίλησεν Ορφὰ τὴν πενθερὰν αὐτῆς καὶ ἐπέστρεψεν εἰς τὸν λαὸν αὐτῆς, ῾Ροὺθ δὲ ἠκολούθησεν αὐτῇ.","kaì epē̂ran tḕn phōnḕn autō̂n kaì éklausan éti: kaì katephílēsen Orphà tḕn pentheràn autē̂s kaì epéstrepsen eis tòn laòn autē̂s, ῾Roùth dè ēkoloúthēsen autē̂i."],[1,15,"καὶ εἶπεν Νωεμεὶν πρός ῾Ρούθ ἰδοὺ ἀνέστρεψεν σύννυμφός σου πρὸς λαὸν αὐτῆς καὶ πρὸς τοὺς θεοὺς αὐτῆς. ἐπιστράφητι δὴ καὶ σὺ ὀπίσω τῆς συννύμφου σου.","kaì eîpen Nōemeìn prós ῾Roúth idoù anéstrepsen sýnnymphós sou pròs laòn autē̂s kaì pròs toùs theoùs autē̂s. epistráphēti dḕ kaì sỳ opísō tē̂s synnýmphou sou."],[1,16,"εἶπεν δὲ ῾Ρούθ Μὴ ἀπαντήσαι ἐμοὶ τοῦ καταλιπεῖν σε ἡ ἀποστρέψαι ὄπισθέν σου, ὅτι σὺ ὅπου ἐὰν πορευθῇς πορεύσομαι, καἰ οὗ ἐὰν αὐλισθῇς αὐλισθήσομαι. ὁ λαός σου λαός μου, καὶ ὁ θεός σου θεός μου·","eîpen dè ῾Roúth Mḕ apantḗsai emoì toû katalipeîn se hē apostrépsai ópisthén sou, hóti sỳ hópou eàn poreuthē̂is poreúsomai, kai hoû eàn aulisthē̂is aulisthḗsomai. ho laós sou laós mou, kaì ho theós sou theós mou:"],[1,17,"καὶ οὗ ἐὰν ἀποθάνῃς ἀποθανοῦμαι, κἀκεῖ ταφήσομαι. τάδε ποιήσαι μοι Κύριος καὶ τάδε προσθείη, ὅτι θάνατος διαστελεῖ ἀνὰ μέσον ἐμοῦ καὶ σοῦ.","kaì hoû eàn apothánēis apothanoûmai, kakeî taphḗsomai. táde poiḗsai moi Kýrios kaì táde prostheíē, hóti thánatos diasteleî anà méson emoû kaì soû."],[1,18,"ἰδοῦσα δὲ Νωεμεὶν ὅτι κραταιοῦται αὐτὴ τοῦ πορεύεσθαι μετ’ αὐτῆς, ἐκόπασεν τοῦ λαλῆσαι πρὸς αὐτὴν ἔτι","idoûsa dè Nōemeìn hóti krataioûtai autḕ toû poreúesthai met’ autē̂s, ekópasen toû lalē̂sai pròs autḕn éti"],[1,19,"᾿Επορεύθησαν δὲ ἀμφότεραι ἕως τοῦ παραγενέσθαι αὐτὰς εἰς Βαιθλέεμ. καὶ ἤχησεν πᾶσα ἡ πόλις ἐπ’ αὐτῆς, κοὶ εἶπον Αὕτη ἐστὶν Νωεμείν ;","᾿Eporeúthēsan dè amphóterai héōs toû paragenésthai autàs eis Baithléem. kaì ḗchēsen pâsa hē pólis ep’ autē̂s, koì eîpon Haútē estìn Nōemeín ?"],[1,20,"καὶ εἶπεν πρὸς αὐτάς Μὴ δὴ καλεῖτέ με Νωεμείν, καλέσατέ με πικράν, ὅτι ἐπικράνθη ἐν ἐμοὶ ὁ ἱκανὸς σφόδρα.","kaì eîpen pròs autás Mḕ dḕ kaleîté me Nōemeín, kalésaté me pikrán, hóti epikránthē en emoì ho hikanòs sphódra."],[1,21,"ἐγὼ πλήρης ἐπορεύθην, κοὶ κενὴν ἀπέστρεψέν με ὁ κύριος· καὶ ἵνα τί καλεῖτέ με Νωεμείν, καὶ ἐταπείνωσέν με, καὶ ὁ ἱκανὸς ἐκάκωσέν με,.","egṑ plḗrēs eporeúthēn, koì kenḕn apéstrepsén me ho kýrios: kaì hína tí kaleîté me Nōemeín, kaì etapeínōsén me, kaì ho hikanòs ekákōsén me,."],[1,22,"καὶ ἐπέ Νωεμεὶν καὶ ῾Ροὺθ ἡ Μωαβεῖτις ἡ νύμφη αὐτῆς ἐπιστρέφουσα ἀγροῦ Μωάβ· αὗται δὲ παρεγενήθησαν εἰς Βαιθλέεμ ἐν ἁρχῇ θερισμοῦ κριθῶν.","kaì epé Nōemeìn kaì ῾Roùth hē Mōabeîtis hē nýmphē autē̂s epistréphousa agroû Mōáb: haûtai dè paregenḗthēsan eis Baithléem en harchē̂i therismoû krithō̂n."],[2,1,"Καὶ τῇ Νωεμεὶν ἀνὴρ γνώριμος τῷ ἀνδρὶ αὐτῆς· ὁ δὲ ἀνὴρ δυνατὸς ἐκ τῆς συγγενίας ᾿Αβειμέλεχ, καὶ ὄνομα αὐτῶ Βόος.","Kaì tē̂i Nōemeìn anḕr gnṓrimos tō̂i andrì autē̂s: ho dè anḕr dynatòs ek tē̂s syngenías ᾿Abeimélech, kaì ónoma autō̂ Bóos."],[2,2,"καὶ ἡ Μωαβεῖτις τοῖς στάχυσιν κατόπισθεν οὗ ἐὰν εὕρω χάριν ἐν ὀφθαλμοῖς αὐτοῦ. εἶπεν δὲ αὐτῇ Πορεύου, θυγάτηρ.","kaì hē Mōabeîtis toîs stáchysin katópisthen hoû eàn heúrō chárin en ophthalmoîs autoû. eîpen dè autē̂i Poreúou, thygátēr."],[2,3,"καὶ ἐπορεύθη, καὶ συνέλεξεν ἐν τῷ ἀγρῷ κατόπισθεν τῶν τῶν θεριζόντων· καὶ περιέπεσεν περιπτώματι τῇ μερίδι τοῦ ἀγροῦ Βόος, τοῦ ἐκ συγγενείας ᾿Αβειμέλεχ·","kaì eporeúthē, kaì synélexen en tō̂i agrō̂i katópisthen tō̂n tō̂n therizóntōn: kaì periépesen periptṓmati tē̂i merídi toû agroû Bóos, toû ek syngeneías ᾿Abeimélech:"],[2,4,"Καὶ ἰδοὺ Βόος ἦλθεν ἐκ Βαιθλέεμ καὶ εἶπεν τοῖς θερίζουσιν Κύριος μεθ’ ὑμῶν· κοὶ εἶπον αὐτῷ Εὐλογήσαι σε Κύριος.","Kaì idoù Bóos ē̂lthen ek Baithléem kaì eîpen toîs therízousin Kýrios meth’ hymō̂n: koì eîpon autō̂i Eulogḗsai se Kýrios."],[2,5,"καὶ εἶπεν Βόος τῷ παιδαρίῳ αὐτοῦ τῷ ἐφεστῶτι ἐπὶ τοὺς θερίζοντας τίνος ἡ νεᾶνις αὕτη ;","kaì eîpen Bóos tō̂i paidaríōi autoû tō̂i ephestō̂ti epì toùs therízontas tínos hē neânis haútē ?"],[2,6,"καὶ ἀπεκρίθη τὸ παιδάριον τὸ ἐφεστὸς ἐπὶ τούς θερίζοντας καὶ εἶπεν Ἡ παῖς ἡ Μωαβεῖτίς ἐστιν, ἡ ἀποστραφεῖσα μετὰ Νωεμεὶν ἐξ ἀγροῦ Μωάβ·","kaì apekríthē tò paidárion tò ephestòs epì toús therízontas kaì eîpen HĒ paîs hē Mōabeîtís estin, hē apostrapheîsa metà Nōemeìn ex agroû Mōáb:"],[2,7,"καὶ εἶπεν Συλλέξω δὴ καὶ συνάξω ἐν τοῖς δράγμασιν ὄπισθεν τῶν θεριζόντων· καὶ ἦλθεν καὶ ἔστη ἀπὸ πρωίθεν καὶ ἕως ἑσπέρας, οὐ κατέπαυσεν ἐν τῷ ἀγρῷ μικρόν.","kaì eîpen Sylléxō dḕ kaì synáxō en toîs drágmasin ópisthen tō̂n therizóntōn: kaì ē̂lthen kaì éstē apò prōíthen kaì héōs hespéras, ou katépausen en tō̂i agrō̂i mikrón."],[2,8,"καὶ εἶπεν Βόος πρὸς ῾Ρούθ οὐκ ἤκουσας, θυγάτηρ; μὴ πορευθῇς ἐν ἀγρῷ συλλέξαι ἑτέρῳ· καὶ σὺ οὐ πορεύσῃ ἐντεῦθεν, ὧδε κολλήθητι μετὰ τῶν κορασίων μου.","kaì eîpen Bóos pròs ῾Roúth ouk ḗkousas, thygátēr? mḕ poreuthē̂is en agrō̂i sylléxai hetérōi: kaì sỳ ou poreúsēi enteûthen, hō̂de kollḗthēti metà tō̂n korasíōn mou."],[2,9,"οἱ ὀφθαλμοί σου εἰς τὸν ἀγρὸν οὗ ἐὰν θερίζωσιν, καὶ πορεύση κατόπισθεν αὐτῶν. ἰδοὺ ἐνετειλάμην τοῖς παιδαρίοις τοῦ μὴ ἅψασθαὶ σου· καὶ ὅ τι διψήσεις, καὶ πορευθήσῃ εἰς τὰ σκεύη καὶ πίεσαι ὅθεν ἀν’ ὑδρεύωνται τὰ παιδάρια.","hoi ophthalmoí sou eis tòn agròn hoû eàn therízōsin, kaì poreúsē katópisthen autō̂n. idoù eneteilámēn toîs paidaríois toû mḕ hápsasthaì sou: kaì hó ti dipsḗseis, kaì poreuthḗsēi eis tà skeúē kaì píesai hóthen an’ hydreúōntai tà paidária."],[2,10,"καὶ ἔπεσεν ἐπὶ πρόσωπον αὐτῆς καὶ προσεκύνησεν ἑ ’πὶ τὴν γῆν, καὶ εἶπεν πρὸς αὐτόν Τί ὅτι εὗρον χάριν ἐν ὀφθαλμοῖς σου τοῦ ἐπιγνῶναί με, καὶ ἐγώ εἰμι ξένη ;","kaì épesen epì prósōpon autē̂s kaì prosekýnēsen he ’pì tḕn gē̂n, kaì eîpen pròs autón Tí hóti heûron chárin en ophthalmoîs sou toû epignō̂naí me, kaì egṓ eimi xénē ?"],[2,11,"καὶ ἀπεκρίθη Βόοσ καὶ εἶπεν αὐτῇ ᾿Απαγγελίᾳ ἀπηγγέλη μοι ὅσα πεποίηκας μετὰ τῆς πενθερᾶς σου μετὰ τὸ ἀποθανεῖν τὸν ἄνδρα σου, καὶ πῶς κατέλιπες τὸν πατέρα σου καὶ τὴν μητέρα σου καὶ τὴν γῆν γενέσεως σου, καὶ ἐπορεύθης πρὸς λαὸν ὃν οὐκ ᾔδεις ἐχθὲς καὶ τρίτης.","kaì apekríthē Bóos̱ kaì eîpen autē̂i ᾿Apangelíāi apēngélē moi hósa pepoíēkas metà tē̂s pentherâs sou metà tò apothaneîn tòn ándra sou, kaì pō̂s katélipes tòn patéra sou kaì tḕn mētéra sou kaì tḕn gē̂n genéseōs sou, kaì eporeúthēs pròs laòn hòn ouk ḗideis echthès kaì trítēs."],[2,12,"ἀποτίσαι κύριος τὴν ἐργασίαν σου· γένοιτο ὁ μισθός σου πλήρης παρὰ κυρίου θεοῦ ᾿Ισραήλ, πρὸς ὅν ἦλθες πεποιθέναι ὑπὸ τὰς πτέρυγας αὐτοῦ","apotísai kýrios tḕn ergasían sou: génoito ho misthós sou plḗrēs parà kyríou theoû ᾿Israḗl, pròs hón ē̂lthes pepoithénai hypò tàs ptérygas autoû"],[2,13,"ἡ δὲ εἶπεν Εὔροιμι χάριν ἐν ὀφθαλμοῖς σου, κύριε, ὅτι παρεκάλεσάς με, καὶ ὅτι ἐλάλησας ἐπὶ καρδίαν τῆς δούλης σου, καὶ ἰδοὺ ἐγὼ ἔσομαι ὡς μία τῶν παιδισκῶν σου.","hē dè eîpen Eúroimi chárin en ophthalmoîs sou, kýrie, hóti parekálesás me, kaì hóti elálēsas epì kardían tē̂s doúlēs sou, kaì idoù egṑ ésomai hōs mía tō̂n paidiskō̂n sou."],[2,14,"καὶ εἶπεν αὐτῇ Βόος Ἤδη ὥρα τοῦ Φαγεῖν, πρόσελθε ὧδε καὶ φάγεσαι τῶν ἄρτων, καὶ βάψεις τὸν ψωμόν σου τῷ ὄξει. καὶ ἐκάθισεν ῾Ροὺθ ἐκ πλαγίων τῶν θεριζόντων· καὶ ἐβούνισεν αὐτῇ Βόος ἄλφιτον, κα ἔφαγεν καὶ ἐνεπλήσθη καὶ κατέλιπεν,","kaì eîpen autē̂i Bóos Ḗdē hṓra toû Phageîn, próselthe hō̂de kaì phágesai tō̂n ártōn, kaì bápseis tòn psōmón sou tō̂i óxei. kaì ekáthisen ῾Roùth ek plagíōn tō̂n therizóntōn: kaì eboúnisen autē̂i Bóos álphiton, ka éphagen kaì eneplḗsthē kaì katélipen,"],[2,15,"καὶ ἀνέστη τοῦ συλλέγειν . καὶ ἐνετείλατο βοὸς τοῖς παιδαρίοις αὐτοῦ λέγων καί γε ἀνὰ μέσον τῶν δραγμάτων συλλεγέτω, καὶ μὴ καταισχύνητε αὐτήν·","kaì anéstē toû syllégein . kaì eneteílato boòs toîs paidaríois autoû légōn kaí ge anà méson tō̂n dragmátōn syllegétō, kaì mḕ kataischýnēte autḗn:"],[2,16,"καὶ βαστάζοντες βαστάξατε αὐτῇ, καί γε παραβάλλοντες παραβαλεῖτε ἐκ τῶν βεβουνισμένων· καὶ φάγεται καὶ συλλέξει, καὶ οὐκ ἐπ’ μήσετε αὐτῇ.","kaì bastázontes bastáxate autē̂i, kaí ge parabállontes parabaleîte ek tō̂n bebounisménōn: kaì phágetai kaì sylléxei, kaì ouk ep’ mḗsete autē̂i."],[2,17,"καὶ συνέλεξεν ἐν τῷ ἀγρῷ ἕως ἑσπέρας, καὶ ἐράβδισεν ἃ συνέλεξεν, καὶ ἐγενήθη ὡς οἰφὶ κριθῶν.","kaì synélexen en tō̂i agrō̂i héōs hespéras, kaì erábdisen hà synélexen, kaì egenḗthē hōs oiphì krithō̂n."],[2,18,"Καὶ καὶ εἰσῆλθεν εἰς τὴν πόλιν· καὶ εἶδεν ἡ πενθερὰ αὐτῆς ἁ καὶ ἐξενέγκασα ῾Ροὺθ ἔδωκεν αὐτῇ ἃ κατέλιπεν ἐξ ὧν ἐνεπλήσθη.","Kaì kaì eisē̂lthen eis tḕn pólin: kaì eîden hē pentherà autē̂s ha kaì exenénkasa ῾Roùth édōken autē̂i hà katélipen ex hō̂n eneplḗsthē."],[2,19,"καὶ εἶπεν αὐτῇ ἡ πενθερὰ αὐτῆς Ποῦ συνέλεξας σήμερον καὶ ποῦ ἐποίησας; εἴη ὁ ἐπιγνούς σε εὐλογημένος. καὶ ἀνήγγειλεν ῾Ροὺθ τῆ πενθερᾷ αὐτῆς ποῦ ἐποίησεν, καὶ εἶπεν Τὸ ὄνομα τοῦ ἀνδρὸς μεθ’ οὗ ἐποίησα σήμερον Βόος.","kaì eîpen autē̂i hē pentherà autē̂s Poû synélexas sḗmeron kaì poû epoíēsas? eíē ho epignoús se eulogēménos. kaì anḗngeilen ῾Roùth tē̂ pentherā̂i autē̂s poû epoíēsen, kaì eîpen Tò ónoma toû andròs meth’ hoû epoíēsa sḗmeron Bóos."],[2,20,"καὶ εἶπεν Νωεμεὶν τῇ νύμφη αὐτῆς Εὐλογητός ἐστιν τῷ κυρίῳ, ὅτι οὐκ ἐνκατέλιπεν τὸ ἕλεος αὐτοῦ μετὰ τῶν ζώντων καὶ μετὰ τῶν καὶ εἶπεν αὐτῇ Νωεμείν ᾿Εγγίζει ἡμῖν ὁ ἀνήρ, ἐκ τῶν ἡμᾶς ἐστιν.","kaì eîpen Nōemeìn tē̂i nýmphē autē̂s Eulogētós estin tō̂i kyríōi, hóti ouk en'katélipen tò héleos autoû metà tō̂n zṓntōn kaì metà tō̂n kaì eîpen autē̂i Nōemeín ᾿Engízei hēmîn ho anḗr, ek tō̂n hēmâs estin."],[2,21,"καὶ εἶπεν ῾Ροὺθ πρὸς τὴν πενθερὰν αὐτῆς καἰ γε ὅτι εἶπεν πρὸς μέ Μετὰ τῶν παιδαρίων μου κολλήθητι ἕως ἂν τελέσωσιν ὅλον τὸν ἀμητὸν ὃς ὑπάρχει μοι.","kaì eîpen ῾Roùth pròs tḕn pentheràn autē̂s kai ge hóti eîpen pròs mé Metà tō̂n paidaríōn mou kollḗthēti héōs àn telésōsin hólon tòn amētòn hòs hypárchei moi."],[2,22,"καὶ εἶπεν πρὸς ῾Ροὺθ τὴν νύμφην αὐτῆς ᾿Αγαθόν, θυγάτηρ, ὅτι ἑ μετά τῶν κορασίων αὐτοῦ, καὶ οὐκ ἀπαντήσονταί σοι ἐν ἀγρῷ ἑτέρῳ.","kaì eîpen pròs ῾Roùth tḕn nýmphēn autē̂s ᾿Agathón, thygátēr, hóti he metá tō̂n korasíōn autoû, kaì ouk apantḗsontaí soi en agrō̂i hetérōi."],[2,23,"καὶ προσεκολλήθη ῾Ροὺθ τοῖς κορασίοις βοὸς συλλέγειν ἕως οὗ συνετέλεσεν τὸν θερισμὸν τῶν κριθῶν καὶ τῶν πυρῶν. * κοὶ ἐκάθισεν μετὰ τῆς πενθερᾶς αὐτῆς.","kaì prosekollḗthē ῾Roùth toîs korasíois boòs syllégein héōs hoû synetélesen tòn therismòn tō̂n krithō̂n kaì tō̂n pyrō̂n. * koì ekáthisen metà tē̂s pentherâs autē̂s."],[3,1,"Ειπεν δὲ αὐτῇ Νωεμεὶν ἡ πενθερὰ αὐτῆς Θυγάτηρ, οὐ μὴ σοι ἀνάπαυσιν ἵνα εὖ γένηται σοι ;","Eipen dè autē̂i Nōemeìn hē pentherà autē̂s Thygátēr, ou mḕ soi anápausin hína eû génētai soi ?"],[3,2,"καὶ νῦν οὐχὶ Βόος γνώριμος ἡ οὗ ἦς μετὰ τῶν κορασίων αὐτοῦ ; ἰδοὺ αὐτὸς λικμᾷ τὸν ἅλωνα τῶν κριθῶν ταύτῃ τῇ νυκτί.","kaì nŷn ouchì Bóos gnṓrimos hē hoû ē̂s metà tō̂n korasíōn autoû ? idoù autòs likmā̂i tòn hálōna tō̂n krithō̂n taútēi tē̂i nyktí."],[3,3,"σὺ δὲ λούσῃ καὶ ἀλείψῃ καὶ περιθησεις τὸν ἱματισμόν σου ἐπὶ σέ, καὶ ἀναβήσῃ ἐπὶ τὸν ἅλω· μὴ γνωρισθῇς τῷ ὶ ἕως οὗ συντελέσαι αὐτὸν πιεῖν καὶ φαγεῖν·","sỳ dè loúsēi kaì aleípsēi kaì perithēseis tòn himatismón sou epì sé, kaì anabḗsēi epì tòn hálō: mḕ gnōristhē̂is tō̂i ì héōs hoû syntelésai autòn pieîn kaì phageîn:"],[3,4,"καὶ ἱστᾶι ἐν τὼ ι αὐτὸν καὶ γνώσῃ τὸν τόπον ὅπου κοιμᾶται ἐκεῖ, καὶ ἐλεύσῃ καὶ ἀποκαλύψεις τὰ πρὸς ποδῶν αὐτοῦ καὶ κοιμηθήσῃ, καὶ αὐτὸς ἀπαγγελεῖ σοι αἰ ποιήσεις.","kaì histâi en tṑ i autòn kaì gnṓsēi tòn tópon hópou koimâtai ekeî, kaì eleúsēi kaì apokalýpseis tà pròs podō̂n autoû kaì koimēthḗsēi, kaì autòs apangeleî soi ai poiḗseis."],[3,5,"εἶπεν δὲ ῾Ροὺθ πρὸς αὐτήν αὐτήν Πάντα ἐὰν εἴπῃς ποιήσω.","eîpen dè ῾Roùth pròs autḗn autḗn Pánta eàn eípēis poiḗsō."],[3,6,"καὶ κατέβη εἰς τὸν ἅλω, καὶ ἐποίησεν κατὰ πάντα ὅσα ἐνετείλατο αὐτῇ ἡ πενθερὰ αὐτῆς.","kaì katébē eis tòn hálō, kaì epoíēsen katà pánta hósa eneteílato autē̂i hē pentherà autē̂s."],[3,7,"καὶ ἔφαγεν Βόος καὶ ἠγαθύνθη ἡ καρδία αὐτοῦ, καὶ ἦλθεν κοιμηθῆναι ἐν μερίδι τῆς στοιβῆς· ἡ δὲ ἦλθεν κρυφῆ καὶ ἀπεκάλυψεν τὰ πρὸς ποδῶν αὐτοῦ.","kaì éphagen Bóos kaì ēgathýnthē hē kardía autoû, kaì ē̂lthen koimēthē̂nai en merídi tē̂s stoibē̂s: hē dè ē̂lthen kryphē̂ kaì apekálypsen tà pròs podō̂n autoû."],[3,8,"ἐγένετο δὲ ἐν τῷ μεσονυκτίῳ καὶ ἐξέστη ὁ ἀνὴρ καὶ ἐταράχθη, καὶ ἰδοὺ γυνὴ κοιμᾶται πρὸς ποδῶν αὐτοῦ.","egéneto dè en tō̂i mesonyktíōi kaì exéstē ho anḕr kaì etaráchthē, kaì idoù gynḕ koimâtai pròs podō̂n autoû."],[3,9,"εἰπεν δέ τίς εἰ σύ ; ἡ δὲ εἶπεν ᾿Εγώ εἰμι ῾Ρούθ ἡ δούλη σου, καὶ περιβαλεῖς τὸ πτερύγιόν σου ἐπὶ τὴν δούλην σου, ὅτι ἀγχιστεὺς εἶ σύ.","eipen dé tís ei sý ? hē dè eîpen ᾿Egṓ eimi ῾Roúth hē doúlē sou, kaì peribaleîs tò pterýgión sou epì tḕn doúlēn sou, hóti anchisteùs eî sý."],[3,10,"καὶ εἶπεν Βόος Εὐλογημένη σὺ τῷ κυρίῳ θεῷ, θύγατερ, ὅτι ἠγάθυνας τὸ ἐλεός σου τὸ ἔσχατον ὑπὲρ τὸ πρῶτον τὸ μή πορευθῆναι νεανιῶν, εἴτοι πτωχὸς εἴτοι πλούσιος.","kaì eîpen Bóos Eulogēménē sỳ tō̂i kyríōi theō̂i, thýgater, hóti ēgáthynas tò eleós sou tò éschaton hypèr tò prō̂ton tò mḗ poreuthē̂nai neaniō̂n, eítoi ptōchòs eítoi ploúsios."],[3,11,"καὶ νῦν, θύγατερ, πάντα ὅσα ἐὰν εἴπῃς ποιήσω σοι· οἶδεν γὰρ πᾶσα φυλή λαοῦ μου ὅτι γυνὴ δυνάμεως εἰ σύ.","kaì nŷn, thýgater, pánta hósa eàn eípēis poiḗsō soi: oîden gàr pâsa phylḗ laoû mou hóti gynḕ dynámeōs ei sý."],[3,12,"καὶ ὅτι ἀληθῶς ἀγχιστεὺς ἐγώ εἰμι· καί γέ ἐστιν ἀγχιστεὺς ἐγγίων ὑπὲρ ἐμέ.","kaì hóti alēthō̂s anchisteùs egṓ eimi: kaí gé estin anchisteùs engíōn hypèr emé."],[3,13,"αὐλίσθητι τὴν νύκτα, καὶ ὦσται τὸ πρωὶ ἐὰν ἀγχιστε΄πυσῃ σε, ἀγαθόν, ἀγχιστευέτω· ἐὰν δὲ μὴ βούληται ἀγχιστεῦσαί σε, ἀγχιστεύσω σε ἐγώ, ζῇ Κύριος, σὺ εἶ κύριος· κοιμήθητι ἕως πρωί.","aulísthēti tḕn nýkta, kaì ō̂stai tò prōì eàn anchiste´pysēi se, agathón, anchisteuétō: eàn dè mḕ boúlētai anchisteûsaí se, anchisteúsō se egṓ, zē̂i Kýrios, sỳ eî kýrios: koimḗthēti héōs prōí."],[3,14,"καὶ ἐκοιμήθη πρὸς ποδῶν αὐτοῦ ἕως πρωί· ἡ δὲ ἐνέστη πρὸ τοῦ ἐπιγνῶναι ἄνδρα τὸν πλησίον αὐτοῦ· καὶ εἶπεν Βόος Μὴ γνωσθήτω ὅτι ἦλθεν γυνή εἰς τὴν ἅλωνα.","kaì ekoimḗthē pròs podō̂n autoû héōs prōí: hē dè enéstē prò toû epignō̂nai ándra tòn plēsíon autoû: kaì eîpen Bóos Mḕ gnōsthḗtō hóti ē̂lthen gynḗ eis tḕn hálōna."],[3,15,"καὶ εἶπεν αὐτῇ Φέρε τὸ περίζωμα τὸ ἐπάνω σου. καὶ ἐκρότησεν αὐτό, καὶ ἐμέτρησεν ἕξ κριθῶν καὶ ἐπέθηκεν ἐπ’ αὐτήν· καὶ εἰσῆλθεν εἰς τὴν πόλιν.","kaì eîpen autē̂i Phére tò perízōma tò epánō sou. kaì ekrótēsen autó, kaì emétrēsen héx krithō̂n kaì epéthēken ep’ autḗn: kaì eisē̂lthen eis tḕn pólin."],[3,16,"καὶ ῾Ροὺθ εἰσῆλθεν πρὸς τὴν πενθερὰν αὐτῆς· ἡ δὲ εἶπεν αὐτῇ Θύγατερ· καὶ εἶπεν αὐτὴ πάντα ὅσα ἐποίησεν αὐτῇ ὁ ἀνήρ.","kaì ῾Roùth eisē̂lthen pròs tḕn pentheràn autē̂s: hē dè eîpen autē̂i Thýgater: kaì eîpen autḕ pánta hósa epoíēsen autē̂i ho anḗr."],[3,17,"καὶ εἶπεν οὐτῇ Τὰ ἕξ τῶν κριθῶν ταῦτα ἔδωκέν μοι, ὅτι εἶπεν πρὸς μέ Μὴ εἰσέλθῃς κενὴ πρὸς τὴν πενθεράν σου.","kaì eîpen outē̂i Tà héx tō̂n krithō̂n taûta édōkén moi, hóti eîpen pròs mé Mḕ eisélthēis kenḕ pròs tḕn pentherán sou."],[3,18,"ἡ δὲ εἶπεν Κάθου, θύγατερ, ἕως τοῦ ἐπιγνῶναί σε πῶς οὐ πεσεῖται ῥῆμα· οὐ γὰρ μὴ ἡσυχάσῃ ὁ ἀνὴρ ἕως ἀν’ τελέσῃ τὸ ῥῆμα σήμερον.","hē dè eîpen Káthou, thýgater, héōs toû epignō̂naí se pō̂s ou peseîtai rhē̂ma: ou gàr mḕ hēsychásēi ho anḕr héōs an’ telésēi tò rhē̂ma sḗmeron."],[4,1,"Καὶ Βόος ἀνέβη ἐπὶ τὴν πύλην καὶ ἐκάθισεν ἐκεῖ, καὶ ἰδοὺ ὁ ἀγχιστευτὴς παρεπορεύετο ὅν εἶπεν Βόος. καὶ εἶπεν πρὸς αὐτὸν Βόος ᾿Εκκλίνας κάθισον ὧδε, κρύφιε· κοὶ ἐξέκλινεν καὶ ἐκάθισεν.","Kaì Bóos anébē epì tḕn pýlēn kaì ekáthisen ekeî, kaì idoù ho anchisteutḕs pareporeúeto hón eîpen Bóos. kaì eîpen pròs autòn Bóos ᾿Ekklínas káthison hō̂de, krýphie: koì exéklinen kaì ekáthisen."],[4,2,"καὶ ἔλαβεν Βόος δέκα ἄνδρας ἀπὸ τῶν πρεσβυτέρων τῆς πόλεως καὶ εἶπεν Καθίσατε ὧδε· καὶ ἐκάθισαν.","kaì élaben Bóos déka ándras apò tō̂n presbytérōn tē̂s póleōs kaì eîpen Kathísate hō̂de: kaì ekáthisan."],[4,3,"καὶ εἶπεν Βόοε τῶ τὴν μερίδα τοῦ ἀγροῦ ἥ ἐστιν τοῦ ἀδελφοῦ ἡμῶν τοῦ ἣ δέδοται Νωεμεὶν τῇ ἐπιστρεφούσῃ ἐξ ἀγροῦ Μωάβ,","kaì eîpen Bóoe tō̂ tḕn merída toû agroû hḗ estin toû adelphoû hēmō̂n toû hḕ dédotai Nōemeìn tē̂i epistrephoúsēi ex agroû Mōáb,"],[4,4,"κἀγὼ εἶπα ᾿Αποκαλύψω τὸ οὖς σου λέγων κτῆσαι ἐναντίον τῶν καθημένων καὶ ἐναντίον τῶν πρεσβυτέρων τοῦ λαοῦ μου· εἰ ἀγχιστεύεις, ἀγχίστευε· εἰ δὲ μὴ ἀγχιστεύεις, ἀνάγγειλόν μοι, καὶ γνώσομαι ὅτι οὐκ ἔστιν παρὲξ σοῦ τοῦ ἀγχιστεῦσαι, κἀγώ εἰμι μετὰ σε. ὁ δὲ εἶπεν ᾿Εγώ εἰμι ἀγχιστεύσω.","kagṑ eîpa ᾿Apokalýpsō tò oûs sou légōn ktē̂sai enantíon tō̂n kathēménōn kaì enantíon tō̂n presbytérōn toû laoû mou: ei anchisteúeis, anchísteue: ei dè mḕ anchisteúeis, anángeilón moi, kaì gnṓsomai hóti ouk éstin parèx soû toû anchisteûsai, kagṓ eimi metà se. ho dè eîpen ᾿Egṓ eimi anchisteúsō."],[4,5,"καὶ εἶπεν Βόος Ἐν ἡμέρᾳ τοῦ κτήσασθαί σε τὸν ἀγρὸν ἐκ χειρὸς Νωεμεὶν καὶ παρὰ ῾Ροὺθ τῆς Μωαβείτιδος γυναικὸς τοῦ τεθνηκότος, καὶ αὐτὴν κτήσασθαί σε δεῖ, ὥστε τὸ ὄνομα τοῦ τεθνηκότος ἐπὶ τῆς κληρονομίας αὐτοῦ.","kaì eîpen Bóos En hēmérāi toû ktḗsasthaí se tòn agròn ek cheiròs Nōemeìn kaì parà ῾Roùth tē̂s Mōabeítidos gynaikòs toû tethnēkótos, kaì autḕn ktḗsasthaí se deî, hṓste tò ónoma toû tethnēkótos epì tē̂s klēronomías autoû."],[4,6,"καὶ εἶπεν ὁ ἀγχιστεύς Οὐ δυνήσομαι ἀγχιστεῦσαι ἐμαυτῷ, μή ποτε διαφείρω τὴν κληρονομίαν μου· ἀγχίστευσον σεαυτῷ τὴν ἀχγιστείαν μου, ὅτι οὐ δυνήσομαι ἀγχιστεῦσαι.","kaì eîpen ho anchisteús Ou dynḗsomai anchisteûsai emautō̂i, mḗ pote diapheírō tḕn klēronomían mou: anchísteuson seautō̂i tḕn achgisteían mou, hóti ou dynḗsomai anchisteûsai."],[4,7,"καὶ τοῦτο τὸ δικαίωμα ἔμπροσθεν ἐν τῷ Ἰσραὴλ ἐπὶ τὴν ἀγχιστείαν καὶ ἐπὶ τὸ ἀντάλλαγμα, τοῦ στῆσαι πάντα λόγον· καὶ ὑπελύετο ὁ ἀνὴρ τὸ ὑπόδημα αὐτοῦ καὶ ἐδίδου τῷ πλησίον αὐτοῦ τῷ ἀγχιστεύοντι τὴν ἀγχιστείαν αὐτοῦ· κοὶ τοῦτο ἦν μαρτύριον ἐν ᾿Ισραήλ.","kaì toûto tò dikaíōma émprosthen en tō̂i Israḕl epì tḕn anchisteían kaì epì tò antállagma, toû stē̂sai pánta lógon: kaì hypelýeto ho anḕr tò hypódēma autoû kaì edídou tō̂i plēsíon autoû tō̂i anchisteúonti tḕn anchisteían autoû: koì toûto ē̂n martýrion en ᾿Israḗl."],[4,8,"καὶ εἶπεν ὁ ἀγχιστεὺς τῷ Βόος Κτῆσαι σεαυτῷ τὴν ἀγχιστείαν μου· καὶ ὑπελύσατο τὸ ὑπόδημα αὐτοῦ κοὶ ἔδωκεν αὐτῷ.","kaì eîpen ho anchisteùs tō̂i Bóos Ktē̂sai seautō̂i tḕn anchisteían mou: kaì hypelýsato tò hypódēma autoû koì édōken autō̂i."],[4,9,"Καὶ εἶπεν Βόος τοῖς πρεσβυτέροις καὶ παντὶ τῷ λαῷ Μάρτυρρς ὑμεῖς σήμερον ὅτι κέκτημαι πάντα τὰ τοῦ ᾿Αβειμέλεχ καὶ πάντα ὅσα ὑπάρχει τῷ Χελαιὼν καὶ τῷ Μααλὼν ἐκ ωεμείν·","Kaì eîpen Bóos toîs presbytérois kaì pantì tō̂i laō̂i Mártyrrs hymeîs sḗmeron hóti kéktēmai pánta tà toû ᾿Abeimélech kaì pánta hósa hypárchei tō̂i Chelaiṑn kaì tō̂i Maalṑn ek ōemeín:"],[4,10,"καί γε ῾Ροὐθ τὴν Μωαβεῖτιν τὴν γυναῖκα Μααλὼν αὐτῷ εἰς γυναῖκα τοῦ ἀναστῆσαι τὸ ὄνομα τοῦ τεθνηκότος ἐπὶ τῆς κληρονομίας αὐτοῦ, καὶ οὐκ ἐξολεθρευθήσεται τὸ ὄνομα τοῦ τεθνηκότος ἐκ τῶν ἀδελφῶν αὐτοῦ καὶ ἐκ τῆς φυλῆς λαοῦ αὐτοῦ. μάρτυρες ὑμεῖς σήμερον.","kaí ge ῾Routh tḕn Mōabeîtin tḕn gynaîka Maalṑn autō̂i eis gynaîka toû anastē̂sai tò ónoma toû tethnēkótos epì tē̂s klēronomías autoû, kaì ouk exolethreuthḗsetai tò ónoma toû tethnēkótos ek tō̂n adelphō̂n autoû kaì ek tē̂s phylē̂s laoû autoû. mártyres hymeîs sḗmeron."],[4,11,"καὶ εἴποσαν πᾶς ὁ λαὸς οἱ ἐν τῇ πύλῃ Μάρτθρες. καὶ οἱ πρεσβύτεροι εἴποσαν Δῴη κύριος τὴν γυναῖκά σου τήν εἰσπορευομένην εἰς τὸν οἶκόν σου ὡς ῾Ραχὴλ καὶ ὡς λείαν, αἳ ᾠκοδόμησαν ἀμφότεραι τὸν οἶκον τοῦ ᾿Ισραὴλ καὶ ἐποίησαν δύναμιν ἐν Ἐφράθα· καὶ ἔσται ὄνομα ἐν Βαιθλέεμ.","kaì eíposan pâs ho laòs hoi en tē̂i pýlēi Mártthres. kaì hoi presbýteroi eíposan Dṓiē kýrios tḕn gynaîká sou tḗn eisporeuoménēn eis tòn oîkón sou hōs ῾Rachḕl kaì hōs leían, haì ōikodómēsan amphóterai tòn oîkon toû ᾿Israḕl kaì epoíēsan dýnamin en Ephrátha: kaì éstai ónoma en Baithléem."],[4,12,"καὶ γένοιτο ὁ οἰκός σου ὡς ὁ οἶκος Φάρες, ὃν ἔτεκεν Θαμὰρ τῷ ᾿Ιούδᾳ, ἐκ τοῦ σπέρματος οὗ δώσει Κύριός σοι ἐκ τῆς παιδίσκης ταύτης.","kaì génoito ho oikós sou hōs ho oîkos Pháres, hòn éteken Thamàr tō̂i ᾿Ioúdāi, ek toû spérmatos hoû dṓsei Kýriós soi ek tē̂s paidískēs taútēs."],[4,13,"Καὶ ἔλαβεν Βόος τὴν ῾Ρούθ, καὶ ἔδωκεν αὐτὴ Κύριος κύησιν, κα ἔτεκεν υἱόν.","Kaì élaben Bóos tḕn ῾Roúth, kaì édōken autḕ Kýrios kýēsin, ka éteken hyión."],[4,14,"καὶ εἶπαν αἱ γυναῖκες πρὸς Νωεμείν Εὐλογητὸς κύριος ὅς οὐ κατέλυσέ σοι σήμερον τὸν ἀγχιστέα, καὶ καλέσαι τὸ ὄνομάσου ἐν ᾿Ισραήλ·","kaì eîpan hai gynaîkes pròs Nōemeín Eulogētòs kýrios hós ou katélysé soi sḗmeron tòn anchistéa, kaì kalésai tò ónomásou en ᾿Israḗl:"],[4,15,"καὶ ἱστᾶι σοι εἰς ἐπιστρέφοντα ψυχὴν καὶ τοῦ διαθρέψαι τὴν πολιάν σου, ὅτι ἡ νύμφη ἡ ἀγαπήσασά σε ἔτεκεν αὐτὸν, ἥ ἐστιν ἀγαθή σοι ὑπὲρ ἑπτὰ υἱούς.","kaì histâi soi eis epistréphonta psychḕn kaì toû diathrépsai tḕn polián sou, hóti hē nýmphē hē agapḗsasá se éteken autòn, hḗ estin agathḗ soi hypèr heptà hyioús."],[4,16,"καὶ ἔλαβεν Νωεμεὶν τὸ παιδίον καὶ ἔθηκεν εἰς τὸν κόλπον αὐτῆς, καὶ ἐγενήθη αὐτῷ εἰς τιθηνόν.","kaì élaben Nōemeìn tò paidíon kaì éthēken eis tòn kólpon autē̂s, kaì egenḗthē autō̂i eis tithēnón."],[4,17,"καὶ ἐκάλεσαν αὐτοῦ αἱ γείτονες ὄνομα λέγουσαι ᾿Ετέχθη υἱὸς τῆ Νωεμείν, καὶ ἐκάλεσαν τὸ ὄνομα αὐτοῦ Ὤβήδ· οὗτος πατὴρ ᾿Ιεσσαὶ πατρὸς Δαυείδ.","kaì ekálesan autoû hai geítones ónoma légousai ᾿Etéchthē hyiòs tē̂ Nōemeín, kaì ekálesan tò ónoma autoû Ṓbḗd: hoûtos patḕr ᾿Iessaì patròs Daueíd."],[4,18,"Καὶ αὗται αἱ γενέσεις Φάρες· Φάρες ἐγέννησεν τὸν ῾Εσρών,","Kaì haûtai hai genéseis Pháres: Pháres egénnēsen tòn ῾Esrṓn,"],[4,19,"῾Εσρὼν δὲ ἐγέννησεν τὸν ᾿Αρράν, καὶ ᾿Αρρὰν ἐγέννησεν τὸν ᾿Αμειναδάβ,","῾Esrṑn dè egénnēsen tòn ᾿Arrán, kaì ᾿Arràn egénnēsen tòn ᾿Ameinadáb,"],[4,20,"καὶ ᾿Αμειναδὰβ ἐγέννησεν τὸν Ναασσών, καὶ Ναασσὼν ἐγέννησεν τὸν Σαλμάν,","kaì ᾿Ameinadàb egénnēsen tòn Naassṓn, kaì Naassṑn egénnēsen tòn Salmán,"],[4,21,"καὶ Σαλμὰν ἐγέννησεν τὸν Βόος, καὶ βοὸς ἐγέννησεν τὸν ᾿Ωβήδ,","kaì Salmàn egénnēsen tòn Bóos, kaì boòs egénnēsen tòn ᾿Ōbḗd,"],[4,22,"καὶ Ὀβὴδ ἐγέννησεν τὸν ᾿Ιεσσαί, καὶ ᾿Ιεσσαὶ","kaì Obḕd egénnēsen tòn ᾿Iessaí, kaì ᾿Iessaì"]],"chu-elizabeth":[[1,1,"И бысть внегда судяху судии, бысть глад на земли. И иде муж от Вифлеема Иудина обитати в селе Моавли, сам и жена его, и два сыны его:","I bystʹ vnegda sudâhu sudii, bystʹ glad na zemli. I ide muž ot Vifleema Iudina obitati v sele Moavli, sam i žena ego, i dva syny ego:"],[1,2,"имя же мужеви Елимелех, имя же жене его Ноемминь и имя двема сынома его Маалон и Хелеон, Ефрафейстии от Вифлеема Иудина. И приидоша в село Моавле, и беша тамо.","imâ že muževi Elimeleh, imâ že žene ego Noemminʹ i imâ dvema synoma ego Maalon i Heleon, Efrafejstii ot Vifleema Iudina. I priidoša v selo Moavle, i beša tamo."],[1,3,"И умре Елимелех муж Ноемминин, и остася она и оба сыны ея:","I umre Elimeleh muž Noemminin, i ostasâ ona i oba syny eâ:"],[1,4,"и пояста себе жены Моавитския: имя единей Орфа и имя вторей Руфь: и жиша тамо до десяти лет.","i poâsta sebe ženy Moavitskiâ: imâ edinej Orfa i imâ vtorej Rufʹ: i žiša tamo do desâti let."],[1,5,"И умроста оба сыны ея, Маалон и Хелеон, и остася жена от мужа своего и от обоих сынов ея.","I umrosta oba syny eâ, Maalon i Heleon, i ostasâ žena ot muža svoego i ot oboih synov eâ."],[1,6,"И воста она и обе снохи ея, и возвратишася с села Моавля: зане услыша на селе Моавли, яко присети Господь людий Своих дати им хлебы.","I vosta ona i obe snohi eâ, i vozvratišasâ s sela Moavlâ: zane uslyša na sele Moavli, âko priseti Gospodʹ lûdij Svoih dati im hleby."],[1,7,"И отиде от места, идеже бе, она и обе снохи ея с нею, и идяху в путь возвратитися в землю Иудину.","I otide ot mesta, ideže be, ona i obe snohi eâ s neû, i idâhu v putʹ vozvratitisâ v zemlû Iudinu."],[1,8,"И рече Ноемминь обема снохама своима: идите убо, возвратитеся каяждо в дом отца своего: да сотворит Господь с вами милость, якоже сотвористе со умершими и со мною:","I reče Noemminʹ obema snohama svoima: idite ubo, vozvratitesâ kaâždo v dom otca svoego: da sotvorit Gospodʹ s vami milostʹ, âkože sotvoriste so umeršimi i so mnoû:"],[1,9,"да даст Господь Бог вам обрести покой коейждо в дому мужа своего. И целова я: они же воздвигоша гласы своя и плакашася,","da dast Gospodʹ Bog vam obresti pokoj koejždo v domu muža svoego. I celova â: oni že vozdvigoša glasy svoâ i plakašasâ,"],[1,10,"и рекоша ей: ни, но идем с тобою в люди твоя.","i rekoša ej: ni, no idem s toboû v lûdi tvoâ."],[1,11,"И рече Ноемминь: обратитеся убо, дщери мои, вскую идете со мною? Или еще мне сынове во утробе моей, и будут вам мужи?","I reče Noemminʹ: obratitesâ ubo, dŝeri moi, vskuû idete so mnoû? Ili eŝe mne synove vo utrobe moej, i budut vam muži?"],[1,12,"Возвратитеся убо, дщери мои и отидите, яко состарехся, и не буду мужу: аще же бых и рекла, яко у мене есть надежда, да буду мужу и рожду сыны,","Vozvratitesâ ubo, dŝeri moi i otidite, âko sostarehsâ, i ne budu mužu: aŝe že byh i rekla, âko u mene estʹ nadežda, da budu mužu i roždu syny,"],[1,13,"вы ли пождете их, дондеже возрастут? И вы ли удержитеся, да не будете иному мужу? Ни, дщери мои, яко горько бысть мне паче вас, яко изыде на мя рука Господня.","vy li poždete ih, dondeže vozrastut? I vy li uderžitesâ, da ne budete inomu mužu? Ni, dŝeri moi, âko gorʹko bystʹ mne pače vas, âko izyde na mâ ruka Gospodnâ."],[1,14,"И воздвигоша гласы своя, и плакаша паки. И целова Орфа свекровь свою, и возвратися в люди своя, Руфь же последова ей.","I vozdvigoša glasy svoâ, i plakaša paki. I celova Orfa svekrovʹ svoû, i vozvratisâ v lûdi svoâ, Rufʹ že posledova ej."],[1,15,"И рече Ноемминь к Руфе: се, возвратися ятровь твоя к людем своим и к богом своим, возвратися убо и ты вслед ятрове своея.","I reče Noemminʹ k Rufe: se, vozvratisâ âtrovʹ tvoâ k lûdem svoim i k bogom svoim, vozvratisâ ubo i ty vsled âtrove svoeâ."],[1,16,"И рече Руфь: не срящи мене то, еже оставити тебе или обратитися мне от тебе, но идеже идеши ты, и аз пойду, и идеже водворишися ты, водворюся и аз: людие твои людие мои, и Бог твой Бог мой:","I reče Rufʹ: ne srâŝi mene to, eže ostaviti tebe ili obratitisâ mne ot tebe, no ideže ideši ty, i az pojdu, i ideže vodvorišisâ ty, vodvorûsâ i az: lûdie tvoi lûdie moi, i Bog tvoj Bog moj:"],[1,17,"и идеже аще умреши, умру и тамо погребуся: тако да сотворит мне Господь, и сия да приложит, яко смерть разлучит между мною и тобою.","i ideže aŝe umreši, umru i tamo pogrebusâ: tako da sotvorit mne Gospodʹ, i siâ da priložit, âko smertʹ razlučit meždu mnoû i toboû."],[1,18,"Видевши же Ноемминь, яко укрепися она ити с нею, умолче глаголати к ней ктому.","Videvši že Noemminʹ, âko ukrepisâ ona iti s neû, umolče glagolati k nej ktomu."],[1,19,"Идосте же обе, дондеже приидосте в Вифлеем. И бысть егда приидосте они в Вифлеем, и возгласи весь град о них, и рекоша: еда сия есть Ноемминь?","Idoste že obe, dondeže priidoste v Vifleem. I bystʹ egda priidoste oni v Vifleem, i vozglasi vesʹ grad o nih, i rekoša: eda siâ estʹ Noemminʹ?"],[1,20,"И рече к ним: не зовите убо мене Ноемминь, но зовите мене Горька: яко исполни мя горести Вседержитель зело:","I reče k nim: ne zovite ubo mene Noemminʹ, no zovite mene Gorʹka: âko ispolni mâ goresti Vsederžitelʹ zelo:"],[1,21,"аз исполнь отидох, и ныне тщу мя возврати Господь: и вскую мя нарицаете Ноемминь, Господь смири мя и Вседержитель озлоби мя?","az ispolnʹ otidoh, i nyne tŝu mâ vozvrati Gospodʹ: i vskuû mâ naricaete Noemminʹ, Gospodʹ smiri mâ i Vsederžitelʹ ozlobi mâ?"],[1,22,"И возвратися Ноемминь и Руфь Моавитиня сноха ея с нею, обращающыяся с села Моавля: и приидосте в Вифлеем в начале жатвы ячменя.","I vozvratisâ Noemminʹ i Rufʹ Moavitinâ snoha eâ s neû, obraŝaûŝyâsâ s sela Moavlâ: i priidoste v Vifleem v načale žatvy âčmenâ."],[2,1,"И бе муж знаемый мужу Ноемминю: муж же силен от рода Елимелехова, имя же ему Вооз.","I be muž znaemyj mužu Noemminû: muž že silen ot roda Elimelehova, imâ že emu Vooz."],[2,2,"И рече Руфь Моавитиня к Ноеммини: да иду убо на ниву и соберу класы вследствующи, идеже аще обрящу благодать пред очима его. Рече же ей: иди, дщи (моя).","I reče Rufʹ Moavitinâ k Noemmini: da idu ubo na nivu i soberu klasy vsledstvuûŝi, ideže aŝe obrâŝu blagodatʹ pred očima ego. Reče že ej: idi, dŝi (moâ)."],[2,3,"И иде, и пришедши собираше на ниве вследствующи жателем: и прииде по случаю в часть нивы Воозовы, иже от сродства Елимелехова.","I ide, i prišedši sobiraše na nive vsledstvuûŝi žatelem: i priide po slučaû v častʹ nivy Voozovy, iže ot srodstva Elimelehova."],[2,4,"И се, Вооз прииде от Вифлеема и рече жнущым: Господь с вами. И реша ему: да благословит тя Господь.","I se, Vooz priide ot Vifleema i reče žnuŝym: Gospodʹ s vami. I reša emu: da blagoslovit tâ Gospodʹ."],[2,5,"И рече Вооз отроку своему стоящему над жатели: чия отроковица сия?","I reče Vooz otroku svoemu stoâŝemu nad žateli: čiâ otrokovica siâ?"],[2,6,"И отвеща отрок стояй над жнущими, и рече: отроковица Моавитиня есть, пришедшая с Ноемминою от села Моавля:","I otveŝa otrok stoâj nad žnuŝimi, i reče: otrokovica Moavitinâ estʹ, prišedšaâ s Noemminoû ot sela Moavlâ:"],[2,7,"и рече: да соберу ныне и сложу в снопех по следу жнущих: и прииде, и ста от утра даже и до вечера, и ни мало почи на ниве.","i reče: da soberu nyne i složu v snopeh po sledu žnuŝih: i priide, i sta ot utra daže i do večera, i ni malo poči na nive."],[2,8,"И рече Вооз к Руфе: слыши, дщи, не ходи собирати на ниву ину, и ты да не отидеши отсюду: но зде прилепися ко отроковицам моим,","I reče Vooz k Rufe: slyši, dŝi, ne hodi sobirati na nivu inu, i ty da ne otideši otsûdu: no zde prilepisâ ko otrokovicam moim,"],[2,9,"и очи твои да будут на ниве, идеже жнут, и да ходиши вслед их: се, заповедах отроком не коснутися тебе: и егда возжаждеши, и да идеши к сосудом, и пиеши отнюдуже черплют отроцы.","i oči tvoi da budut na nive, ideže žnut, i da hodiši vsled ih: se, zapovedah otrokom ne kosnutisâ tebe: i egda vozžaždeši, i da ideši k sosudom, i pieši otnûduže čerplût otrocy."],[2,10,"И паде (отроковица) ниц и поклонися до земли, и рече ему: что яко обретох благодать пред очима твоима, еже познати мя, аз же есмь странна?","I pade (otrokovica) nic i poklonisâ do zemli, i reče emu: čto âko obretoh blagodatʹ pred očima tvoima, eže poznati mâ, az že esmʹ stranna?"],[2,11,"И отвеща Вооз и рече к ней: возвещением возвестися мне, елика сотворила еси со свекровию твоею по умертвии мужа твоего, и како оставила еси отца твоего и матерь твою и землю рождения твоего, и пришла еси в люди, ихже не ведала от вчера и третияго дне:","I otveŝa Vooz i reče k nej: vozveŝeniem vozvestisâ mne, elika sotvorila esi so svekroviû tvoeû po umertvii muža tvoego, i kako ostavila esi otca tvoego i materʹ tvoû i zemlû roždeniâ tvoego, i prišla esi v lûdi, ihže ne vedala ot včera i tretiâgo dne:"],[2,12,"да воздаст Господь дело твое, и да будет мзда твоя исполнь от Господа Бога Израилева, к Немуже пришла еси уповати под крилома Его.","da vozdast Gospodʹ delo tvoe, i da budet mzda tvoâ ispolnʹ ot Gospoda Boga Izraileva, k Nemuže prišla esi upovati pod kriloma Ego."],[2,13,"Она же рече: обретох благодать пред очима твоима, господине мой, яко утешил мя еси, и яко глаголал еси в сердце рабы твоея, и се, аз буду яко едина от рабынь твоих.","Ona že reče: obretoh blagodatʹ pred očima tvoima, gospodine moj, âko utešil mâ esi, i âko glagolal esi v serdce raby tvoeâ, i se, az budu âko edina ot rabynʹ tvoih."],[2,14,"И рече ей Вооз: уже час ясти, приближися убо семо, да яси хлеб мой, и омочи укрух твой во оцет. И сяде Руфь от страны жателей: и подаде ей Вооз пряжмо, и яде и насытися, и оста:","I reče ej Vooz: uže čas âsti, približisâ ubo semo, da âsi hleb moj, i omoči ukruh tvoj vo ocet. I sâde Rufʹ ot strany žatelej: i podade ej Vooz prâžmo, i âde i nasytisâ, i osta:"],[2,15,"и воста собирати. И заповеда Вооз отроком своим, глаголя: среде снопов да собирает, и не посрамите ю:","i vosta sobirati. I zapoveda Vooz otrokom svoim, glagolâ: srede snopov da sobiraet, i ne posramite û:"],[2,16,"и носяще носите ей, и отлагающе отлагайте ей от снопов, и оставите ю собирати и ясти, и не возбраните ей.","i nosâŝe nosite ej, i otlagaûŝe otlagajte ej ot snopov, i ostavite û sobirati i âsti, i ne vozbranite ej."],[2,17,"И собира до вечера на ниве, и измлати еже собра, и бысть яко ифи мера ячменя:","I sobira do večera na nive, i izmlati eže sobra, i bystʹ âko ifi mera âčmenâ:"],[2,18,"и взя, и прииде во град. И виде свекровь ея еже собра: и иземши Руфь от недр своих, даде свекрови своей, еже оставила, от нихже насытися.","i vzâ, i priide vo grad. I vide svekrovʹ eâ eže sobra: i izemši Rufʹ ot nedr svoih, dade svekrovi svoej, eže ostavila, ot nihže nasytisâ."],[2,19,"И рече к ней свекровь ея: где еси собирала днесь, и где работала? Да будет благословен познавый тя. И поведа Руфь свекрови своей, где работала, и рече: имя мужу Вооз, у негоже работах днесь.","I reče k nej svekrovʹ eâ: gde esi sobirala dnesʹ, i gde rabotala? Da budet blagosloven poznavyj tâ. I poveda Rufʹ svekrovi svoej, gde rabotala, i reče: imâ mužu Vooz, u negože rabotah dnesʹ."],[2,20,"Рече же Ноемминь снохе своей: благословен есть Господем, яко не остави милости своея с живыми и со умершими. И рече ей Ноемминь: ужик есть нам муж той, и есть от ужик наших.","Reče že Noemminʹ snohe svoej: blagosloven estʹ Gospodem, âko ne ostavi milosti svoeâ s živymi i so umeršimi. I reče ej Noemminʹ: užik estʹ nam muž toj, i estʹ ot užik naših."],[2,21,"И рече Руфь ко свекрови своей: и мне убо рече: ко отроковицам моим пристани, дондеже скончают всю жатву, яже есть мне.","I reče Rufʹ ko svekrovi svoej: i mne ubo reče: ko otrokovicam moim pristani, dondeže skončaût vsû žatvu, âže estʹ mne."],[2,22,"И рече Ноемминь к Руфе снохе своей: благо, дщи, яко ходила еси со отроковицами его, и не сопротивятся тебе на иней ниве.","I reče Noemminʹ k Rufe snohe svoej: blago, dŝi, âko hodila esi so otrokovicami ego, i ne soprotivâtsâ tebe na inej nive."],[2,23,"И приста Руфь ко отроковицам Воозовым собирати (класы), дондеже скончася жатва ячменя и пшеницы: и седе со свекровию своею.","I prista Rufʹ ko otrokovicam Voozovym sobirati (klasy), dondeže skončasâ žatva âčmenâ i pšenicy: i sede so svekroviû svoeû."],[3,1,"Рече же ей Ноемминь свекровь ея: дщи (моя), не поищу ли тебе покоя, да благо ти будет?","Reče že ej Noemminʹ svekrovʹ eâ: dŝi (moâ), ne poiŝu li tebe pokoâ, da blago ti budet?"],[3,2,"И ныне Вооз не ужик ли нам, идеже со отроковицами его была еси? Се, той веет на гумне ячмень сея нощи:","I nyne Vooz ne užik li nam, ideže so otrokovicami ego byla esi? Se, toj veet na gumne âčmenʹ seâ noŝi:"],[3,3,"ты же измыйся, и помасти лице твое, и облецыся в ризы твоя (светлыя), и изыди на гумно: не явися мужу, дондеже скончает ясти и пити:","ty že izmyjsâ, i pomasti lice tvoe, i oblecysâ v rizy tvoâ (svetlyâ), i izydi na gumno: ne âvisâ mužu, dondeže skončaet âsti i piti:"],[3,4,"и будет внегда уснути ему, и познаеши место, где ляжет, тамо да внидеши, и открыеши у ног его, и ляжеши: и той повесть тебе, яже имаши творити.","i budet vnegda usnuti emu, i poznaeši mesto, gde lâžet, tamo da vnideši, i otkryeši u nog ego, i lâžeši: i toj povestʹ tebe, âže imaši tvoriti."],[3,5,"И рече Руфь к ней: вся елика речеши мне, сотворю.","I reče Rufʹ k nej: vsâ elika rečeši mne, sotvorû."],[3,6,"И иде на гумно, и сотвори по всему, елика заповеда ей свекровь ея.","I ide na gumno, i sotvori po vsemu, elika zapoveda ej svekrovʹ eâ."],[3,7,"И яде Вооз и пи, и возблажа сердце его, и иде спати со страны стога: она же прииде втай, и откры яже у ног его, и ляже.","I âde Vooz i pi, i vozblaža serdce ego, i ide spati so strany stoga: ona že priide vtaj, i otkry âže u nog ego, i lâže."],[3,8,"И бысть в полунощи, ужасеся муж и возмятеся, и се, жена лежит у ног его:","I bystʹ v polunoŝi, užasesâ muž i vozmâtesâ, i se, žena ležit u nog ego:"],[3,9,"и рече (ей Вооз): кто еси ты? Она же рече: аз есмь Руфь раба твоя, да возложиши крило твое на рабу твою, яко ужик ты еси.","i reče (ej Vooz): kto esi ty? Ona že reče: az esmʹ Rufʹ raba tvoâ, da vozložiši krilo tvoe na rabu tvoû, âko užik ty esi."],[3,10,"И рече Вооз: благословена ты Господем Богом, дщи, яко разблажила еси милость твою последнюю паче первыя, еже не ити тебе вслед юнот, аще убог, аще богат:","I reče Vooz: blagoslovena ty Gospodem Bogom, dŝi, âko razblažila esi milostʹ tvoû poslednûû pače pervyâ, eže ne iti tebe vsled ûnot, aŝe ubog, aŝe bogat:"],[3,11,"и ныне, дщи, не бойся: вся елика речеши, сотворю тебе: весть бо все племя людий моих, яко жена силы ты еси:","i nyne, dŝi, ne bojsâ: vsâ elika rečeši, sotvorû tebe: vestʹ bo vse plemâ lûdij moih, âko žena sily ty esi:"],[3,12,"и ныне поистинне ужик есмь аз: но еще есть ужик ближший мене:","i nyne poistinne užik esmʹ az: no eŝe estʹ užik bližšij mene:"],[3,13,"прележи сию нощь, и будет заутра аще приимет тя, то благо: да поймет: аще ли не восхощет пояти тебе, то поиму тя аз, жив Господь: прележи до заутрия.","preleži siû noŝʹ, i budet zautra aŝe priimet tâ, to blago: da pojmet: aŝe li ne voshoŝet poâti tebe, to poimu tâ az, živ Gospodʹ: preleži do zautriâ."],[3,14,"И лежа у ног его до заутрия: она же воста, прежде неже познати мужу подруга своего. И рече Вооз: да не увестся, яко приходила жена на гумно.","I leža u nog ego do zautriâ: ona že vosta, prežde neže poznati mužu podruga svoego. I reče Vooz: da ne uvestsâ, âko prihodila žena na gumno."],[3,15,"И рече ей: принеси покрывало еже на тебе, и держи е. Она же держа е, и намери ей шесть мер ячменя, и заде ей: и иде во град.","I reče ej: prinesi pokryvalo eže na tebe, i derži e. Ona že derža e, i nameri ej šestʹ mer âčmenâ, i zade ej: i ide vo grad."],[3,16,"И прииде Руфь ко свекрови своей. Она же рече ей: что есть, дщи? И поведа ей вся, елика сотвори ей муж.","I priide Rufʹ ko svekrovi svoej. Ona že reče ej: čto estʹ, dŝi? I poveda ej vsâ, elika sotvori ej muž."],[3,17,"И рече ей: шесть мер сих ячменя даде ми, глагола бо ко мне: да не идеши тща ко свекрови своей.","I reče ej: šestʹ mer sih âčmenâ dade mi, glagola bo ko mne: da ne ideši tŝa ko svekrovi svoej."],[3,18,"Она же рече: седи, дщи, дондеже увеси, како падет слово: не умолчит бо муж, дондеже совершится слово днесь.","Ona že reče: sedi, dŝi, dondeže uvesi, kako padet slovo: ne umolčit bo muž, dondeže soveršitsâ slovo dnesʹ."],[4,1,"И Вооз прииде ко вратом и седе тамо: и се, ужик мимоидяше, о немже глагола Вооз. И рече ему Вооз: уклонився сяди зде. Он же уклонися и седе.","I Vooz priide ko vratom i sede tamo: i se, užik mimoidâše, o nemže glagola Vooz. I reče emu Vooz: uklonivsâ sâdi zde. On že uklonisâ i sede."],[4,2,"И поя Вооз десять мужей от старейшин града, и рече: сядите зде. И седоша.","I poâ Vooz desâtʹ mužej ot starejšin grada, i reče: sâdite zde. I sedoša."],[4,3,"И рече Вооз ужику: часть села, яже есть брата нашего Елимелеха, яже дадеся Ноеммине возвратившейся от села Моавля:","I reče Vooz užiku: častʹ sela, âže estʹ brata našego Elimeleha, âže dadesâ Noemmine vozvrativšejsâ ot sela Moavlâ:"],[4,4,"аз же рекох: явлю тебе сие во ухо твое, глаголя, пристяжи пред седящими и пред старейшины людий моих: и аще ужичествуеши, ужичествуй: аще же не ужичествуеши, повеждь ми, да ведаю: яко несть разве тебе еже ужичествовати ближший, и аз есмь по тебе. Он же рече: аз есмь, ужичествую.","az že rekoh: âvlû tebe sie vo uho tvoe, glagolâ, pristâži pred sedâŝimi i pred starejšiny lûdij moih: i aŝe užičestvueši, užičestvuj: aŝe že ne užičestvueši, poveždʹ mi, da vedaû: âko nestʹ razve tebe eže užičestvovati bližšij, i az esmʹ po tebe. On že reče: az esmʹ, užičestvuû."],[4,5,"И рече Вооз: в день в оньже пристяжеши село от руки Ноеммини, и от Руфы Моавитяныни жены умершаго, и сию достоит ти пояти, да возставиши имя умершаго в наследие его.","I reče Vooz: v denʹ v onʹže pristâžeši selo ot ruki Noemmini, i ot Rufy Moavitânyni ženy umeršago, i siû dostoit ti poâti, da vozstaviši imâ umeršago v nasledie ego."],[4,6,"И рече ужик: не возмогу ужичествовати себе, да не разсыплю наследия моего: ужичествуй себе ты ужичество мое, аз бо не возмогу ужичествовати.","I reče užik: ne vozmogu užičestvovati sebe, da ne razsyplû naslediâ moego: užičestvuj sebe ty užičestvo moe, az bo ne vozmogu užičestvovati."],[4,7,"И сие управление бысть прежде во Израили о ужичествовании и о пременении, еже укрепити всякое слово: и иззуваше муж сапог свой, и даяше подругу своему ужичествующу ужичество его: и сие бяше свидетелство во Израили.","I sie upravlenie bystʹ prežde vo Izraili o užičestvovanii i o premenenii, eže ukrepiti vsâkoe slovo: i izzuvaše muž sapog svoj, i daâše podrugu svoemu užičestvuûŝu užičestvo ego: i sie bâše svidetelstvo vo Izraili."],[4,8,"И рече ужик Воозу: пристяжи себе ужичество мое. И иззув сапог свой, даде ему.","I reče užik Voozu: pristâži sebe užičestvo moe. I izzuv sapog svoj, dade emu."],[4,9,"И рече Вооз старейшинам и всем людем: свидетеле вы днесь, яко пристяжах днесь вся, яже Елимелехова, и вся елика суть Хелеонова и Маалонова, от руки Ноеммини:","I reče Vooz starejšinam i vsem lûdem: svidetele vy dnesʹ, âko pristâžah dnesʹ vsâ, âže Elimelehova, i vsâ elika sutʹ Heleonova i Maalonova, ot ruki Noemmini:"],[4,10,"ксему же Руфь Моавитяныню жену Маалоню поемлю себе в жену возставити имя умершаго в наследие его, да не погибнет имя умершаго от братии его и от племене людий его: свидетеле вы днесь.","ksemu že Rufʹ Moavitânynû ženu Maalonû poemlû sebe v ženu vozstaviti imâ umeršago v nasledie ego, da ne pogibnet imâ umeršago ot bratii ego i ot plemene lûdij ego: svidetele vy dnesʹ."],[4,11,"И отвещаша вси людие иже у врат: свидетеле есмы. И старейшины реша: да даст Господь жене твоей, входящей в дом твой, якоже Рахили и яко Лии, яже создаша обе дом Израилев, и сотвориша силу во Ефрафе, и будет имя в Вифлееме:","I otveŝaša vsi lûdie iže u vrat: svidetele esmy. I starejšiny reša: da dast Gospodʹ žene tvoej, vhodâŝej v dom tvoj, âkože Rahili i âko Lii, âže sozdaša obe dom Izrailev, i sotvoriša silu vo Efrafe, i budet imâ v Vifleeme:"],[4,12,"и буди дом твой якоже дом Фаресов, егоже роди Фамарь Иуде, от семене твоего даст тебе Господь от рабы сея чада.","i budi dom tvoj âkože dom Faresov, egože rodi Famarʹ Iude, ot semene tvoego dast tebe Gospodʹ ot raby seâ čada."],[4,13,"И поя Вооз Руфь, и бысть ему жена, и вниде к ней: и даде ей Господь зачати, и роди сына.","I poâ Vooz Rufʹ, i bystʹ emu žena, i vnide k nej: i dade ej Gospodʹ začati, i rodi syna."],[4,14,"И рекоша жены к Ноеммине: благословен Господь, Иже не разсыпа ужика твоего днесь, и прозовется имя твое во Израили,","I rekoša ženy k Noemmine: blagosloven Gospodʹ, Iže ne razsypa užika tvoego dnesʹ, i prozovetsâ imâ tvoe vo Izraili,"],[4,15,"и будет тебе во обращающаго душу и в прекормление старости твоея, яко сноха твоя, возлюбившая тебе, роди сына, яже есть блага тебе паче седми сынов.","i budet tebe vo obraŝaûŝago dušu i v prekormlenie starosti tvoeâ, âko snoha tvoâ, vozlûbivšaâ tebe, rodi syna, âže estʹ blaga tebe pače sedmi synov."],[4,16,"И взя Ноемминь отроча, и положи е на лоне своем, и бысть ему кормилица.","I vzâ Noemminʹ otroča, i položi e na lone svoem, i bystʹ emu kormilica."],[4,17,"И прозваша соседи имя его, глаголюще: родися сын Ноеммине. И нарекоша имя ему Овид: сей есть отец Иессеа, отца Давидова.","I prozvaša sosedi imâ ego, glagolûŝe: rodisâ syn Noemmine. I narekoša imâ emu Ovid: sej estʹ otec Iessea, otca Davidova."],[4,18,"И сия родства Фаресова: Фарес роди Есрома:","I siâ rodstva Faresova: Fares rodi Esroma:"],[4,19,"Есром же роди Арама: Арам же роди Аминадава:","Esrom že rodi Arama: Aram že rodi Aminadava:"],[4,20,"Аминадав же роди Наассона: Наассон же роди Салмона:","Aminadav že rodi Naassona: Naasson že rodi Salmona:"],[4,21,"Салмон же роди Вооза: Вооз же роди Овида:","Salmon že rodi Vooza: Vooz že rodi Ovida:"],[4,22,"Овид же роди Иессеа: Иессей же роди Давида.","Ovid že rodi Iessea: Iessej že rodi Davida."]],"eng-thomson-partial":[[1,1,"Now when the Judges ruled, there was a famine in the land, and a man went from Bethlehem Juda to sojourn in the country of Moab, he and his wife and his two sons.","Now when the Judges ruled, there was a famine in the land, and a man went from Bethlehem Juda to sojourn in the country of Moab, he and his wife and his two sons."],[1,2,"The man's name was Elimelech, and his wife's name was Noemin, and the names of his two sons, Maalon and Chelaion. They were Ephrathites of Bethlehem Juda.","The man's name was Elimelech, and his wife's name was Noemin, and the names of his two sons, Maalon and Chelaion. They were Ephrathites of Bethlehem Juda."],[1,3,"They went to the country of Moab, and while they were there, Elimelech, the husband of Noemin, died, and she was left with her two sons.","They went to the country of Moab, and while they were there, Elimelech, the husband of Noemin, died, and she was left with her two sons."],[1,4,"And they took for themselves wives of the daughters of Moab, the name of the one was Orpha, and the name of the other Ruth.","And they took for themselves wives of the daughters of Moab, the name of the one was Orpha, and the name of the other Ruth."],[1,5,"And when they had dwelt there about ten years, both Maalon and Chelaion died, so that the woman was bereaved of her husband, and her two sons.","And when they had dwelt there about ten years, both Maalon and Chelaion died, so that the woman was bereaved of her husband, and her two sons."],[1,6,"Whereupon she arose with her two daughters in law, and set out on her return from the country of Moab; for she had heard, in the country of Moab, that the Lord had visited his people in giving them bread.","Whereupon she arose with her two daughters in law, and set out on her return from the country of Moab; for she had heard, in the country of Moab, that the Lord had visited his people in giving them bread."],[1,7,"So she set out from the place where she was with her two daughters in law.","So she set out from the place where she was with her two daughters in law."],[1,8,"And when they had travelled some part of the way on their return to the land of Juda, Noemin said to her two daughters in law, Go, I pray you, return each to her mother's house.","And when they had travelled some part of the way on their return to the land of Juda, Noemin said to her two daughters in law, Go, I pray you, return each to her mother's house."],[1,9,"May the Lord deal kindly with you, as you have done with the dead, and with me. The Lord grant, that you may find rest, each in the house of her husband.","May the Lord deal kindly with you, as you have done with the dead, and with me. The Lord grant, that you may find rest, each in the house of her husband."],[1,10,"So she kissed them, and they wept aloud, and said to her, We will go back with thee to thy people.","So she kissed them, and they wept aloud, and said to her, We will go back with thee to thy people."],[1,11,"But Noemin said, Return, I pray you, my daughters! for why should you go with me? Have I yet any more sons in my womb to be husbands for you?","But Noemin said, Return, I pray you, my daughters! for why should you go with me? Have I yet any more sons in my womb to be husbands for you?"],[1,12,"Return, I pray you, my daughters! For I am too old to have a husband—for should I say, I am in condition to marry, and should I bear sons, would you wait for them till they grow up;","Return, I pray you, my daughters! For I am too old to have a husband—for should I say, I am in condition to marry, and should I bear sons, would you wait for them till they grow up;"],[1,13,"or should you be restrained by them from having husbands? No, my daughters. Indeed it grieveth me much for your sakes, that the hand of the Lord hath gone forth against me.","or should you be restrained by them from having husbands? No, my daughters. Indeed it grieveth me much for your sakes, that the hand of the Lord hath gone forth against me."],[1,14,"And when they had raised their voice, and wept again, Orpha kissed her mother in law, and returned to her people; but Ruth followed her.","And when they had raised their voice, and wept again, Orpha kissed her mother in law, and returned to her people; but Ruth followed her."],[1,15,"Then Noemin said to Ruth; Behold thy sister in law is gone back to her people, and to her gods, return thou also, I pray thee, after thy sister in law.","Then Noemin said to Ruth; Behold thy sister in law is gone back to her people, and to her gods, return thou also, I pray thee, after thy sister in law."],[1,16,"Whereupon Ruth said, Force me not to leave thee, nor to return from following thee; for whither soever thou goest, I will go and wherever thou lodgest, I will lodge. Thy people shall be my people; and thy God, my God; and wherever thou diest, I will die, and there will I be buried.","Whereupon Ruth said, Force me not to leave thee, nor to return from following thee; for whither soever thou goest, I will go and wherever thou lodgest, I will lodge. Thy people shall be my people; and thy God, my God; and wherever thou diest, I will die, and there will I be buried."],[1,17,"The Lord do so to me and more also, if any thing but death shall part me and thee.","The Lord do so to me and more also, if any thing but death shall part me and thee."],[1,18,"And when Noemin saw that she was steadfastly determined to go with her, she refrained from speaking to her any more.","And when Noemin saw that she was steadfastly determined to go with her, she refrained from speaking to her any more."],[1,19,"So they both proceeded on till they came to Bethlehem. And when they arrived at Bethlehem, all the city was moved about them, and they said, Is this Noemin?","So they both proceeded on till they came to Bethlehem. And when they arrived at Bethlehem, all the city was moved about them, and they said, Is this Noemin?"],[1,20,"But she said to them, Call me not, I pray you, Noemin. Call me, Bitter: for the Almighty hath dealt very bitterly with me.","But she said to them, Call me not, I pray you, Noemin. Call me, Bitter: for the Almighty hath dealt very bitterly with me."],[1,21,"I went out full but the Lord hath brought me back empty. Why therefore do you call me Noemin, seeing the Lord hath brought me low, and the Almighty hath afflicted me?","I went out full but the Lord hath brought me back empty. Why therefore do you call me Noemin, seeing the Lord hath brought me low, and the Almighty hath afflicted me?"],[1,22,"Thus Noemin returned, with Ruth the Moabitess, her daughter in law; and having returned from the country of Moab, they came to Bethlehem, at the beginning of the barley harvest.","Thus Noemin returned, with Ruth the Moabitess, her daughter in law; and having returned from the country of Moab, they came to Bethlehem, at the beginning of the barley harvest."],[2,1,"Now Noemin had a kinsman of her husband's; a mighty man of wealth, of the family of Elimelech, and his name was Boaz.","Now Noemin had a kinsman of her husband's; a mighty man of wealth, of the family of Elimelech, and his name was Boaz."],[2,2,"And Ruth the Moabitess said to Noemin, Let me go, I pray thee, into the field, and glean among the stubble after him in whose eyes I shall find favour. And she said to her, Go, my daughter.","And Ruth the Moabitess said to Noemin, Let me go, I pray thee, into the field, and glean among the stubble after him in whose eyes I shall find favour. And she said to her, Go, my daughter."],[2,3,"So she went, and coming into a field, gleaned after the reapers. Now she happened to light upon the part of the field which belonged to Boaz, who was of the kindred of Elimelech.","So she went, and coming into a field, gleaned after the reapers. Now she happened to light upon the part of the field which belonged to Boaz, who was of the kindred of Elimelech."],[2,4,"And behold Boaz came from Bethlehem, and said to the reapers, The Lord be with you! And they said to him, The Lord bless thee.","And behold Boaz came from Bethlehem, and said to the reapers, The Lord be with you! And they said to him, The Lord bless thee."],[2,5,"Then Boaz said to his servant, who was set over the reapers, Whose damsel is that?","Then Boaz said to his servant, who was set over the reapers, Whose damsel is that?"],[2,6,"And the servant who was over the reapers said in reply, It is the Moabitess girl, who came with Noemin from the country of Moab.","And the servant who was over the reapers said in reply, It is the Moabitess girl, who came with Noemin from the country of Moab."],[2,7,"She said, Let me, I pray thee, glean, and gather among the sheaves after the reapers. So she came, and hath been on her feet from early in the morning, and is continuing on till evening. She hath not rested a moment in the field.","She said, Let me, I pray thee, glean, and gather among the sheaves after the reapers. So she came, and hath been on her feet from early in the morning, and is continuing on till evening. She hath not rested a moment in the field."],[2,8,"Then Boaz said to Ruth, Hearest thou not, my daughter? Thou must not go to glean in any other field, nor must thou go hence, but abide here fast by my maids,","Then Boaz said to Ruth, Hearest thou not, my daughter? Thou must not go to glean in any other field, nor must thou go hence, but abide here fast by my maids,"],[2,9,"let thy eyes be on the field where they reap and go after them. Behold I have given a charge to my servants not to touch thee, and when thou art thirsty, go to the vessels, and drink of what the servants have drawn.","let thy eyes be on the field where they reap and go after them. Behold I have given a charge to my servants not to touch thee, and when thou art thirsty, go to the vessels, and drink of what the servants have drawn."],[2,10,"Upon which she fell on her face, and made an obeisance to the ground, and said to him, How have I found favour in thy sight, that thou shouldst take notice of me, seeing I am a stranger?","Upon which she fell on her face, and made an obeisance to the ground, and said to him, How have I found favour in thy sight, that thou shouldst take notice of me, seeing I am a stranger?"],[2,11,"And Boaz in reply said to her, I have been fully informed of all that thou hast done to thy mother in law after the death of thy husband; and how thou hast left thy father, and thy mother, and the land of thy nativity, to come to a people whom thou knewest not heretofore.","And Boaz in reply said to her, I have been fully informed of all that thou hast done to thy mother in law after the death of thy husband; and how thou hast left thy father, and thy mother, and the land of thy nativity, to come to a people whom thou knewest not heretofore."],[2,12,"The Lord recompense thy work, and may a full reward be given thee by the Lord God of Israel, to whom thou art come, to put thy trust under his wings.","The Lord recompense thy work, and may a full reward be given thee by the Lord God of Israel, to whom thou art come, to put thy trust under his wings."],[2,13,"And she said, Let me find favour in thy sight, my Lord, for thou hast comforted me. Now because thou hast spoken affectionately to thy servant, behold let me therefore be like one of thy maid servants.","And she said, Let me find favour in thy sight, my Lord, for thou hast comforted me. Now because thou hast spoken affectionately to thy servant, behold let me therefore be like one of thy maid servants."],[2,14,"Then Boaz said to her, It is now meal time, draw near, and eat of the bread, and dip thy morsel in the vinegar. So Ruth sat down by the side of the reapers. And Boaz helped her to a large piece of barley bread, so that she eat, and was satisfied, and had some left.","Then Boaz said to her, It is now meal time, draw near, and eat of the bread, and dip thy morsel in the vinegar. So Ruth sat down by the side of the reapers. And Boaz helped her to a large piece of barley bread, so that she eat, and was satisfied, and had some left."],[2,15,"And when she arose to glean, Boaz gave a charge to his servants, saying, Let her glean among the sheaves, and put her not to the blush.","And when she arose to glean, Boaz gave a charge to his servants, saying, Let her glean among the sheaves, and put her not to the blush."],[2,16,"And when you carry out, carry out for her. Leave also for her some out of the bundles, and let her eat, and glean, and rebuke her not.","And when you carry out, carry out for her. Leave also for her some out of the bundles, and let her eat, and glean, and rebuke her not."],[2,17,"So she gleaned in the field till evening, and beat out what she had gathered, and it was about an epha of barley. And she took it up, and went to the city.","So she gleaned in the field till evening, and beat out what she had gathered, and it was about an epha of barley. And she took it up, and went to the city."],[2,18,"And when her mother in law saw what she had gathered, and Ruth had taken out, and given her some of the bread that was left after she had been satisfied,","And when her mother in law saw what she had gathered, and Ruth had taken out, and given her some of the bread that was left after she had been satisfied,"],[2,19,"her mother in law said to her, Where hast thou gleaned to day? And where hast thou been at work? Blessed be he who hath taken notice of thee. And when Ruth told her mother in law where she had been at work, and said, The man's name is Boaz, with whom I worked to day.","her mother in law said to her, Where hast thou gleaned to day? And where hast thou been at work? Blessed be he who hath taken notice of thee. And when Ruth told her mother in law where she had been at work, and said, The man's name is Boaz, with whom I worked to day."],[2,20,"Noemin said to her daughter in law, Blessed is he of the Lord, because he hath not dropped his kindness to the living, nor to the dead. Then Noemin said to her, The man is near of kin to us. He is one of our nearest relations.","Noemin said to her daughter in law, Blessed is he of the Lord, because he hath not dropped his kindness to the living, nor to the dead. Then Noemin said to her, The man is near of kin to us. He is one of our nearest relations."],[2,21,"And Ruth said to her mother in law, Indeed he also said to me, Thou must keep close by my maids till they finish my whole harvest.","And Ruth said to her mother in law, Indeed he also said to me, Thou must keep close by my maids till they finish my whole harvest."],[2,22,"And Noemin said to her daughter in law Ruth, it is good my daughter that thou hast gone out with his maids, therefore let them not meet thee in another field.","And Noemin said to her daughter in law Ruth, it is good my daughter that thou hast gone out with his maids, therefore let them not meet thee in another field."],[2,23,"So Ruth kept fast by the maids of Boaz, to glean till they finished the barley and wheat harvest.","So Ruth kept fast by the maids of Boaz, to glean till they finished the barley and wheat harvest."],[3,1,"Then she abode at home with her mother in law. And Noemin her mother in law said to her, My daughter, shall I not seek a rest for thee, that it may be well with thee?","Then she abode at home with her mother in law. And Noemin her mother in law said to her, My daughter, shall I not seek a rest for thee, that it may be well with thee?"],[3,2,"Now is not Boaz our relation, with whose girls thou hast been? Behold he is winnowing barley in the threshing floor.","Now is not Boaz our relation, with whose girls thou hast been? Behold he is winnowing barley in the threshing floor."],[3,3,"This very night therefore thou shalt wash, and anoint thyself, and put on thy raiment, and go up to the threshing floor. But make not thyself known to the man till he hath done eating and drinking.","This very night therefore thou shalt wash, and anoint thyself, and put on thy raiment, and go up to the threshing floor. But make not thyself known to the man till he hath done eating and drinking."],[3,4,"And when he goeth to rest, mark the place where he lieth down, and go and uncover his feet, and lie down, and he will tell thee what thou shalt do.","And when he goeth to rest, mark the place where he lieth down, and go and uncover his feet, and lie down, and he will tell thee what thou shalt do."],[3,5,"And Ruth said to her, All that thou hast ordered me I will do.","And Ruth said to her, All that thou hast ordered me I will do."],[3,6,"So she went up to the threshing floor, and did all that her mother in law commanded her.","So she went up to the threshing floor, and did all that her mother in law commanded her."],[3,7,"And when Boaz had eaten, and drunk, and his heart was cheered, he went and lay down at the side of a heap of corn. Then she went in softly and uncovered his feet.","And when Boaz had eaten, and drunk, and his heart was cheered, he went and lay down at the side of a heap of corn. Then she went in softly and uncovered his feet."],[3,8,"And in the middle of the night the man was astonished, and troubled, for lo! a woman was lying at his feet.","And in the middle of the night the man was astonished, and troubled, for lo! a woman was lying at his feet."],[3,9,"And he said, Who art thou? And she said, I am Ruth thy handmaid; therefore spread thy skirt over thy handmaid, for thou art near a kinsman.","And he said, Who art thou? And she said, I am Ruth thy handmaid; therefore spread thy skirt over thy handmaid, for thou art near a kinsman."],[3,10,"And Boaz said, Blessed art thou of the Lord God, my daughter; for thou hast shewn more kindness in this last act than in the former, in not going after young men either poor or rich.","And Boaz said, Blessed art thou of the Lord God, my daughter; for thou hast shewn more kindness in this last act than in the former, in not going after young men either poor or rich."],[3,11,"Now therefore, my daughter, be not afraid, I will do for thee all thou hast said; for all the tribe of my people know that thou art a virtuous woman.","Now therefore, my daughter, be not afraid, I will do for thee all thou hast said; for all the tribe of my people know that thou art a virtuous woman."],[3,12,"Now indeed it is true that I am a near relation; but there is a relation nearer of kin than I.","Now indeed it is true that I am a near relation; but there is a relation nearer of kin than I."],[3,13,"Tarry this night, and it shall be, in the morning, that if he perform to thee the part of a kinsman, well: let him do so. But if he decline to perform to thee the part of a kinsman, I myself will do the kinsman's part for thee, as the Lord liveth. Go to sleep till the morning.","Tarry this night, and it shall be, in the morning, that if he perform to thee the part of a kinsman, well: let him do so. But if he decline to perform to thee the part of a kinsman, I myself will do the kinsman's part for thee, as the Lord liveth. Go to sleep till the morning."],[3,14,"So she lay at his feet till the morning, and arose before one could know another. And Boaz said, Let it not be known that a woman came to the threshing floor.","So she lay at his feet till the morning, and arose before one could know another. And Boaz said, Let it not be known that a woman came to the threshing floor."],[3,15,"Then he said to her, Bring the sash which is girt about thee. So she held it, and he measured six measures of barley, and laid it on her, and went to the city.","Then he said to her, Bring the sash which is girt about thee. So she held it, and he measured six measures of barley, and laid it on her, and went to the city."],[3,16,"And Ruth went to her mother in law. And her mother in law said to her, My daughter! And when Ruth had told her all that the man had done to her;","And Ruth went to her mother in law. And her mother in law said to her, My daughter! And when Ruth had told her all that the man had done to her;"],[3,17,"and said to her, He gave me also these six measures of barley; for said he to me, Thou must not go empty to thy mother in law;","and said to her, He gave me also these six measures of barley; for said he to me, Thou must not go empty to thy mother in law;"],[3,18,"she said, Sit still my daughter till thou know the issue of this matter; for the man will not rest till the affair is now brought to a conclusion.","she said, Sit still my daughter till thou know the issue of this matter; for the man will not rest till the affair is now brought to a conclusion."],[4,1,"And Boaz went up to the gate and sat down there. And behold when the kinsman of whom Boaz had spoken was passing by, Boaz said to him, Turn aside and sit down here thou hidden man.","And Boaz went up to the gate and sat down there. And behold when the kinsman of whom Boaz had spoken was passing by, Boaz said to him, Turn aside and sit down here thou hidden man."],[4,2,"So he turned aside, and sat down. Then Boaz took ten men of the elders of the city, and said, Sit down here.","So he turned aside, and sat down. Then Boaz took ten men of the elders of the city, and said, Sit down here."],[4,3,"And when they had taken their seats, Boaz said to the kinsman, With respect to that portion of the field which belonged to our brother Elimelech, and which is given to Noemin, who is returned from the country of Moab,","And when they had taken their seats, Boaz said to the kinsman, With respect to that portion of the field which belonged to our brother Elimelech, and which is given to Noemin, who is returned from the country of Moab,"],[4,4,"I have promised to open thine ear, saying, Purchase it in the presence of these men who are sitting here, even in the presence of the elders of my people. If thou wilt do the kinsman's part, do it; but if thou wilt not perform the office of a kinsman, tell me, that I may know for there is none besides thee to perform the office of a kinsman, except myself, who am next after thee. And he said, I will do the kinsman's part.","I have promised to open thine ear, saying, Purchase it in the presence of these men who are sitting here, even in the presence of the elders of my people. If thou wilt do the kinsman's part, do it; but if thou wilt not perform the office of a kinsman, tell me, that I may know for there is none besides thee to perform the office of a kinsman, except myself, who am next after thee. And he said, I will do the kinsman's part."],[4,5,"Then Boaz said, On the day thou purchasest the field of Noemin, thou must purchase it with Ruth, the Moabitess, the wife of the dead, to raise up the name of the dead on his inheritance.","Then Boaz said, On the day thou purchasest the field of Noemin, thou must purchase it with Ruth, the Moabitess, the wife of the dead, to raise up the name of the dead on his inheritance."],[4,6,"Thereupon the relation said, I cannot take upon me the office of a kinsman, lest I mar my own inheritance. Take thou upon thyself that office of a kinsman which is my right; for I cannot perform it.","Thereupon the relation said, I cannot take upon me the office of a kinsman, lest I mar my own inheritance. Take thou upon thyself that office of a kinsman which is my right; for I cannot perform it."],[4,7,"Now it was the custom heretofore in Israel, in regard to the transfer of the right of consanguinity, in order to give it validity, that the man loosed his sandal, and gave it to his neighbour, who took upon him his right of consanguinity, and this was the evidence in Israel.","Now it was the custom heretofore in Israel, in regard to the transfer of the right of consanguinity, in order to give it validity, that the man loosed his sandal, and gave it to his neighbour, who took upon him his right of consanguinity, and this was the evidence in Israel."],[4,8,"So when the relation said to Boaz, Purchase thou for thyself, what by the law of consanguinity it was my right to purchase, he loosed his sandal, and gave it to him.","So when the relation said to Boaz, Purchase thou for thyself, what by the law of consanguinity it was my right to purchase, he loosed his sandal, and gave it to him."],[4,9,"Thereupon Boaz said to the elders, and to all the people, You are this day witnesses that I have purchased all that belonged to Elimelech, and all that belonged to Chelaion and Maalon, at the hand of Noemin;","Thereupon Boaz said to the elders, and to all the people, You are this day witnesses that I have purchased all that belonged to Elimelech, and all that belonged to Chelaion and Maalon, at the hand of Noemin;"],[4,10,"and that I have purchased Ruth, the Moabitess, the wife of Maalon, to be a wife to myself, to raise up the name of the deceased on his inheritance; that the name of the deceased may not be blotted out from among his brethren, and from the tribe of his people. You are this day witnesses.","and that I have purchased Ruth, the Moabitess, the wife of Maalon, to be a wife to myself, to raise up the name of the deceased on his inheritance; that the name of the deceased may not be blotted out from among his brethren, and from the tribe of his people. You are this day witnesses."],[4,11,"And all the people who were in the gate said, We are witnesses. Then the elders said, The Lord make this thy wife who is coming to thy house, like Rachel and like Leia, who both built up the house of Israel, and laid the foundation of power in Ephratha, that there may be a name in Bethlehem:","And all the people who were in the gate said, We are witnesses. Then the elders said, The Lord make this thy wife who is coming to thy house, like Rachel and like Leia, who both built up the house of Israel, and laid the foundation of power in Ephratha, that there may be a name in Bethlehem:"],[4,12,"And may thy house be like the house of Phares, whom Thamar bore to Juda, from the seed which the Lord will give thee from this young woman.","And may thy house be like the house of Phares, whom Thamar bore to Juda, from the seed which the Lord will give thee from this young woman."],[4,13,"So Boaz took Ruth, and she became his wife, and he went in unto her, and the Lord gave her conception, and she bore a son.","So Boaz took Ruth, and she became his wife, and he went in unto her, and the Lord gave her conception, and she bore a son."],[4,14,"Whereupon the women said to Noemin, Blessed be the Lord who hath not left thee this day without a kinsman to make thy name famous in Israel.","Whereupon the women said to Noemin, Blessed be the Lord who hath not left thee this day without a kinsman to make thy name famous in Israel."],[4,15,"He shall be to thee a restorer of life, and a nourisher of thine old age. For thy daughter in law, who loved thee, hath brought forth a son. She is better to thee than seven sons.","He shall be to thee a restorer of life, and a nourisher of thine old age. For thy daughter in law, who loved thee, hath brought forth a son. She is better to thee than seven sons."],[4,16,"And Noemin took the child, and laid it in her bosom, and became its nurse,","And Noemin took the child, and laid it in her bosom, and became its nurse,"],[4,17,"and the neighbours gave it a name, saying, A son is born to Noemin, and called its name Obed. He was the father of Jessai, the father of David.","and the neighbours gave it a name, saying, A son is born to Noemin, and called its name Obed. He was the father of Jessai, the father of David."],[4,18,"Now this is the genealogy of Phares. Phares begot Esrom,","Now this is the genealogy of Phares. Phares begot Esrom,"],[4,19,"and Esrom begot Aram; and Aram begot Aminadab;","and Esrom begot Aram; and Aram begot Aminadab;"],[4,20,"and Aminadab, Naasson; and Naasson, Salmon;","and Aminadab, Naasson; and Naasson, Salmon;"],[4,21,"and Salmon, Boaz; and Boaz, Obed;","and Salmon, Boaz; and Boaz, Obed;"],[4,22,"and Obed, Jessai; and Jessai, David.","and Obed, Jessai; and Jessai, David."]]}};